$function$;

--
-- Name: delete_workflow_definition; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.delete_workflow_definition(p_definition_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_is_platform_super boolean := (select app_private.is_platform_super());
  v_definition public.wf_definition;
begin
  if (select auth.uid()) is null or not v_is_platform_super then
    raise exception '当前账号没有流程删除权限' using errcode = '42501';
  end if;

  select *
  into v_definition
  from public.wf_definition d
  where d.id = p_definition_id
    
  for update;

  if not found then
    raise exception '流程不存在或无权删除';
  end if;

  if exists (
    select 1
    from public.wf_instance i
    where i.definition_id = p_definition_id
  ) then
    raise exception '流程已有审批记录，不能删除，只能停用';
  end if;

  if not v_is_platform_super and v_definition.current_version_id is not null then
    raise exception '普通管理员只能删除未发布流程';
  end if;

  delete from public.wf_definition
  where id = p_definition_id;
end;
$function$;

--
-- Name: document_number_period_key; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.document_number_period_key(p_reset_cycle text, p_now timestamp with time zone, p_timezone text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select case p_reset_cycle
    when 'year' then to_char(p_now at time zone p_timezone, 'YYYY')
    when 'month' then to_char(p_now at time zone p_timezone, 'YYYYMM')
    when 'day' then to_char(p_now at time zone p_timezone, 'YYYYMMDD')
    else ''
  end
$function$;

--
-- Name: enforce_enabled_dictionary_fields; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.enforce_enabled_dictionary_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_index integer;
  v_column_name text;
  v_type_code text;
  v_field_label text;
  v_raw_value text;
  v_normalized_value text;
  v_old_value text;
begin
  if tg_nargs = 0 or tg_nargs % 3 <> 0 then
    raise exception '字典字段守卫配置无效' using errcode = '22023';
  end if;

  v_index := 0;
  while v_index < tg_nargs loop
    v_column_name := tg_argv[v_index];
    v_type_code := tg_argv[v_index + 1];
    v_field_label := tg_argv[v_index + 2];
    v_raw_value := to_jsonb(new)->>v_column_name;

    if v_raw_value is not null then
      v_normalized_value := btrim(v_raw_value);
      if v_normalized_value = '' then
        raise exception '%不能为空', v_field_label using errcode = '22023';
      end if;

      v_old_value := case
        when tg_op = 'UPDATE' then btrim(to_jsonb(old)->>v_column_name)
        else null
      end;

      if not app_private.is_enabled_dictionary_value(v_type_code, v_normalized_value)
        and not (tg_op = 'UPDATE' and v_old_value = v_normalized_value) then
        raise exception '%无效或已停用', v_field_label using errcode = '22023';
      end if;

      new := jsonb_populate_record(
        new,
        jsonb_build_object(v_column_name, v_normalized_value)
      );
    end if;

    v_index := v_index + 3;
  end loop;

  return new;
end;
$function$;

--
-- Name: enforce_platform_super_user; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.enforce_platform_super_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  return case when tg_op='DELETE' then old else new end;
end;
$function$;

--
-- Name: enforce_system_organization_rules; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.enforce_system_organization_rules()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
begin

  if tg_op = 'DELETE' then
    return old;
  end if;

  if old.is_system is true and true then
    if new.is_system is not true
      
      or new.parent_id is distinct from old.parent_id
      or new.organization_code is distinct from old.organization_code
      or new.organization_type is distinct from old.organization_type
      or new.status is distinct from '1'
    then
      raise exception '正式组织根节点的身份、父级、编码、类型和启用状态不可修改';
    end if;
  elsif new.is_system is true and true then
    raise exception '不能将普通组织改为正式组织根节点';
  end if;

  return new;
end;
$function$;

--
-- Name: enforce_system_role_rules; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.enforce_system_role_rules()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_is_service_role boolean := current_user in ('postgres', 'service_role')
    or coalesce(auth.jwt() ->> 'role', '') = 'service_role';
  v_is_platform_super_role boolean := old.role_code = 'R_SUPER';
begin
  if v_is_service_role then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if v_is_platform_super_role then
    if tg_op = 'DELETE' then
      raise exception '平台超管角色不可删除';
    end if;
    if new.role_code is distinct from old.role_code then
      raise exception '平台超管角色编码不可修改，请改用其他角色编码';
    end if;
    if new.enabled is not true then
      raise exception '平台超管角色不可停用';
    end if;
  end if;

  if tg_op = 'DELETE' then
    if old.builtin_type is not null
       and old.builtin_type not in ('default_register', 'platform_super') then
      raise exception '系统预置角色“%”不可删除', old.role_name;
    end if;
    return old;
  end if;

  if old.builtin_type is not null
     and old.builtin_type not in ('default_register', 'platform_super')
     and (new.builtin_type is distinct from old.builtin_type
       or new.role_code is distinct from old.role_code
       or new.enabled is false) then
    raise exception '系统预置角色身份不可修改或停用';
  end if;

  if new.builtin_type is not null
     and new.builtin_type not in ('default_register', 'platform_super')
     and new.builtin_type is distinct from old.builtin_type then
    raise exception '不能将普通角色改为系统预置角色';
  end if;

  return new;
end;
$function$;

--
-- Name: enqueue_fms_posting_event; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.enqueue_fms_posting_event(p_source_type text, p_event_code text, p_source_id uuid, p_source_no text, p_event_date date, p_summary text, p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event_id uuid;
  v_account_set_id uuid;
  v_actor text := coalesce(auth.jwt() ->> 'email', auth.uid()::text, 'system');
begin
  v_account_set_id := app_private.resolve_fms_posting_account_set();
  insert into public.fms_posting_event ( account_set_id, source_type, event_code, source_id, source_no,
    event_date, summary, payload, status, create_by, update_by
  ) values ( v_account_set_id, p_source_type, p_event_code, p_source_id,
    nullif(btrim(p_source_no), ''), p_event_date, btrim(p_summary),
    coalesce(p_payload, '{}'::jsonb),
    case when v_account_set_id is null then 'pending_configuration' else 'pending' end,
    v_actor, v_actor
  )
  on conflict (source_type, event_code, source_id) do update set
    account_set_id = coalesce(public.fms_posting_event.account_set_id, excluded.account_set_id),
    source_no = excluded.source_no,
    event_date = excluded.event_date,
    summary = excluded.summary,
    payload = excluded.payload,
    status = case
      when public.fms_posting_event.status in ('generated', 'reversed', 'ignored')
        then public.fms_posting_event.status
      when coalesce(public.fms_posting_event.account_set_id, excluded.account_set_id) is null
        then 'pending_configuration'
      else 'pending'
    end,
    update_by = excluded.update_by,
    update_time = now()
  returning id into v_event_id;
  perform app_private.process_fms_posting_event(v_event_id, false);
  return v_event_id;
end;
$function$;

--
-- Name: enqueue_user_notification; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.enqueue_user_notification(p_recipient_user_id uuid, p_category text, p_title text, p_content text, p_severity text, p_source_type text, p_source_id uuid, p_business_type text DEFAULT NULL::text, p_business_id uuid DEFAULT NULL::uuid, p_instance_id uuid DEFAULT NULL::uuid, p_route_path text DEFAULT '/workflow/workbench'::text, p_route_query jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_notification_id uuid;
begin
  if p_category not in ('notice', 'message', 'todo') then
    raise exception '不支持的通知分类';
  end if;
  if p_severity not in ('info', 'success', 'warning', 'danger') then
    raise exception '不支持的通知级别';
  end if;
  if btrim(coalesce(p_title, '')) = '' or btrim(coalesce(p_source_type, '')) = '' then
    raise exception '通知标题和来源不能为空';
  end if;
  if coalesce(jsonb_typeof(p_route_query), 'null') <> 'object' then
    raise exception '通知路由参数必须是对象';
  end if;
  if not exists (
    select 1
    from public.sys_user u
    where u.id = p_recipient_user_id
      
      and u.status = '1'
  ) then
    raise exception '通知接收人不存在、已停用或不可用';
  end if;

  insert into public.sys_notification(
    recipient_user_id,
    category,
    title,
    content,
    severity,
    source_type,
    source_id,
    business_type,
    business_id,
    instance_id,
    route_path,
    route_query) values (
    p_recipient_user_id,
    p_category,
    btrim(p_title),
    nullif(btrim(coalesce(p_content, '')), ''),
    p_severity,
    btrim(p_source_type),
    p_source_id,
    nullif(btrim(coalesce(p_business_type, '')), ''),
    p_business_id,
    p_instance_id,
    coalesce(nullif(btrim(coalesce(p_route_path, '')), ''), '/workflow/workbench'),
    coalesce(p_route_query, '{}'::jsonb))
  on conflict (recipient_user_id, category, source_type, source_id) do nothing
  returning id into v_notification_id;

  if v_notification_id is null then
    select n.id into v_notification_id
    from public.sys_notification n
    where n.recipient_user_id = p_recipient_user_id
      and n.category = p_category
      and n.source_type = p_source_type
      and n.source_id = p_source_id;
  end if;

  return v_notification_id;
end;
$function$;

--
-- Name: execute_carrier_payment_application_workflow_callback; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.execute_carrier_payment_application_workflow_callback(p_business_id uuid, p_status text, p_actor text, p_comment text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_app record;
begin
  select * into v_app from public.tms_carrier_payment_application
  where id=p_business_id for update;
  if not found then raise exception '付款申请不存在或已被删除'; end if;
  perform pg_catalog.set_config('app.workflow_engine','on',true);
  if p_status='running' then
    perform public.validate_tms_carrier_payment_application_submission(p_business_id);
    update public.tms_carrier_payment_application set
      status='pending_review',submitted_at=now(),submitted_by=p_actor,
      reviewed_at=null,reviewed_by=null,review_remark=null
    where id=p_business_id;
  elsif p_status='approved' then
    update public.tms_carrier_payment_application set
      status='approved',reviewed_at=now(),reviewed_by=p_actor,
      review_remark=nullif(btrim(coalesce(p_comment,'')),'')
    where id=p_business_id;
  elsif p_status='rejected' then
    update public.tms_carrier_payment_application set
      status='rejected',reviewed_at=now(),reviewed_by=p_actor,
      review_remark=nullif(btrim(coalesce(p_comment,'')),'')
    where id=p_business_id;
  elsif p_status in ('withdrawn','cancelled') then
    update public.tms_carrier_payment_application set
      status='draft',reviewed_at=now(),reviewed_by=p_actor,
      review_remark=nullif(btrim(coalesce(p_comment,'')),'')
    where id=p_business_id;
  end if;
end; $function$;

--
-- Name: execute_expense_reimbursement_workflow_callback; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.execute_expense_reimbursement_workflow_callback(p_business_id uuid, p_status text, p_actor text, p_comment text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform set_config('app.workflow_engine', 'on', true);
  update public.tms_expense_reimbursement
  set status = case p_status
        when 'running' then 'pending_review'
        when 'approved' then 'approved'
        when 'rejected' then 'rejected'
        when 'withdrawn' then 'draft'
        when 'cancelled' then 'draft'
        else status end,
      submitted_at = case when p_status = 'running' then now() else submitted_at end,
      submitted_by = case when p_status = 'running' then p_actor else submitted_by end,
      reviewed_at = case when p_status in ('approved', 'rejected') then now()
                         when p_status = 'running' then null else reviewed_at end,
      reviewed_by = case when p_status in ('approved', 'rejected') then p_actor
                         when p_status = 'running' then null else reviewed_by end,
      review_remark = case when p_status in ('approved', 'rejected', 'cancelled')
                           then nullif(btrim(coalesce(p_comment, '')), '')
                           when p_status = 'running' then null else review_remark end
  where id = p_business_id;
  if not found then raise exception '费用报销单不存在或已被删除'; end if;
end;
$function$;

--
-- Name: execute_hr_self_service_workflow_callback; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.execute_hr_self_service_workflow_callback(p_business_id uuid, p_status text, p_actor text, p_comment text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform pg_catalog.set_config('app.workflow_engine','on',true);
  update public.hr_self_service_request
  set status=case p_status when 'running' then 'pending' when 'approved' then 'approved'
      when 'rejected' then 'rejected' when 'withdrawn' then 'draft'
      when 'cancelled' then 'cancelled' else status end,
    workflow_instance_id=coalesce(workflow_instance_id,(
      select i.id from public.wf_instance i where true
        and i.business_type='hr_self_service_request' and i.business_id=p_business_id
      order by i.started_at desc limit 1)),
    reviewed_at=case when p_status in ('approved','rejected') then now() else reviewed_at end,
    reviewed_by=case when p_status in ('approved','rejected') then p_actor else reviewed_by end,
    review_comment=case when p_status in ('approved','rejected','cancelled')
      then nullif(btrim(coalesce(p_comment,'')),'') else review_comment end
  where id=p_business_id;
  if not found then raise exception '员工自助申请不存在或已删除'; end if;
end $function$;

--
-- Name: execute_hr_workflow_business_callback; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.execute_hr_workflow_business_callback(p_business_type text, p_business_id uuid, p_status text, p_actor text, p_comment text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_case public.hr_lifecycle_case;
begin
  perform pg_catalog.set_config('app.workflow_engine', 'on', true);
  if p_business_type = 'hr_personnel_change' then
    update public.hr_personnel_change
    set status = case p_status
          when 'running' then 'pending' when 'approved' then 'approved'
          when 'rejected' then 'rejected' when 'withdrawn' then 'draft'
          when 'cancelled' then 'cancelled' else status end,
        workflow_instance_id = coalesce(workflow_instance_id, (
          select i.id from public.wf_instance i
          where true
            and i.business_type = p_business_type and i.business_id = p_business_id
          order by i.started_at desc limit 1
        )),
        approved_at = case when p_status = 'approved' then now() else approved_at end,
        approved_by = case when p_status = 'approved' then p_actor else approved_by end,
        remark = case when p_status in ('rejected','cancelled')
          then concat_ws(E'\n', remark, nullif(btrim(coalesce(p_comment,'')),'')) else remark end
    where id = p_business_id;
    if not found then raise exception '人事异动单不存在或已被删除'; end if;
  elsif p_business_type = 'hr_lifecycle_case' then
    update public.hr_lifecycle_case
    set status = case p_status
          when 'running' then 'pending' when 'approved' then 'approved'
          when 'rejected' then 'rejected' when 'withdrawn' then 'draft'
          when 'cancelled' then 'cancelled' else status end,
        workflow_instance_id = coalesce(workflow_instance_id, (
          select i.id from public.wf_instance i
          where true
            and i.business_type = p_business_type and i.business_id = p_business_id
          order by i.started_at desc limit 1
        )),
        approved_at = case when p_status = 'approved' then now() else approved_at end,
        approved_by = case when p_status = 'approved' then p_actor else approved_by end,
        remark = case when p_status in ('rejected','cancelled')
          then concat_ws(E'\n', remark, nullif(btrim(coalesce(p_comment,'')),'')) else remark end
    where id = p_business_id
    returning * into v_case;
    if not found then raise exception '入转调离事项不存在或已被删除'; end if;

    -- Approval materializes a reusable checklist. Existing manually-created tasks are preserved,
    -- and only missing defaults are inserted so workflow retries remain idempotent.
    if p_status = 'approved' then
      insert into public.hr_lifecycle_task(
        lifecycle_case_id,task_type,task_name,responsible_user_id,due_date,status,sort,
        create_by,update_by
      )
      select v_case.id,task.task_type,task.task_name,v_case.owner_user_id,
        v_case.planned_effective_date,'pending',task.sort,p_actor,p_actor
      from (values
        ('onboarding','organization','确认组织与岗位',10),
        ('onboarding','account','开通系统账号与权限',20),
        ('onboarding','document','归档入职资料',30),
        ('regularization','document','归档转正审批资料',10),
        ('transfer','organization','更新组织与岗位关系',10),
        ('transfer','account','调整系统角色与数据权限',20),
        ('offboarding','asset','完成资产与工作交接',10),
        ('offboarding','account','回收系统账号与权限',20),
        ('offboarding','document','归档离职资料',30)
      ) as task(case_type,task_type,task_name,sort)
      where task.case_type=v_case.case_type
        and not exists (
          select 1 from public.hr_lifecycle_task existing
          where existing.lifecycle_case_id=v_case.id
            and existing.task_type=task.task_type and existing.task_name=task.task_name
        );
    end if;
  end if;
end;
$function$;

--
-- Name: execute_tool_return_workflow_callback; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.execute_tool_return_workflow_callback(p_business_id uuid, p_status text, p_actor text, p_comment text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update public.smis_tool_return
  set status = case p_status
        when 'running' then 'pending_approval'
        when 'approved' then 'approved'
        when 'rejected' then 'rejected'
        when 'draft' then 'draft'
        when 'cancelled' then 'rejected'
        else status
      end,
      submitted_at = case when p_status = 'running' then now() else submitted_at end,
      approved_at = case when p_status = 'approved' then now() else null end,
      rejection_reason = case
        when p_status in ('rejected','cancelled') then nullif(btrim(coalesce(p_comment,'')), '')
        when p_status in ('running','approved','draft') then null
        else rejection_reason
      end,
      update_by = coalesce(nullif(btrim(p_actor),''), 'workflow-engine')
  where id = p_business_id;
  if not found then
    raise exception '工器具归还单不存在或已删除';
  end if;
end
$function$;

--
-- Name: execute_vehicle_archive_workflow_callback; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.execute_vehicle_archive_workflow_callback(p_business_id uuid, p_status text, p_actor text, p_comment text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform pg_catalog.set_config('app.workflow_engine', 'on', true);

  update public.vehicle_archive
  set audit_status = case p_status
        when 'running' then 'pending'
        when 'approved' then 'approved'
        when 'rejected' then 'rejected'
        when 'withdrawn' then 'pending'
        when 'cancelled' then 'pending'
        else audit_status
      end,
      audit_time = case
        when p_status in ('approved', 'rejected') then pg_catalog.now()
        else null
      end,
      audit_by = case
        when p_status in ('approved', 'rejected') then p_actor
        else null
      end,
      audit_remark = case
        when p_status in ('approved', 'rejected', 'cancelled')
          then nullif(pg_catalog.btrim(coalesce(p_comment, '')), '')
        else null
      end
  where id = p_business_id;

  if not found then
    raise exception '车辆档案不存在或已被删除';
  end if;
end;
$function$;

--
-- Name: execute_workflow_business_callback; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.execute_workflow_business_callback(p_business_type text, p_business_id uuid, p_status text, p_actor text, p_comment text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_business_type = 'smis_tool_return' then
    perform app_private.execute_tool_return_workflow_callback(
      p_business_id, p_status, p_actor, p_comment
    );
  elsif p_business_type = 'hr_recruitment_requisition' then
    perform app_private.execute_hr_recruitment_workflow_callback(
      p_business_id, p_status, p_actor, p_comment
    );
  else
    perform app_private.execute_workflow_business_callback_before_hr_p2(
      p_business_type, p_business_id, p_status, p_actor, p_comment
    );
  end if;
end
$function$;

--
-- Name: execute_workflow_business_callback_before_hr; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.execute_workflow_business_callback_before_hr(p_business_type text, p_business_id uuid, p_status text, p_actor text, p_comment text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_business_type = 'tms_carrier_payment_application' then
    perform app_private.execute_carrier_payment_application_workflow_callback(
      p_business_id, p_status, p_actor, p_comment
    );
  elsif p_business_type = 'tms_expense_reimbursement' then
    perform app_private.execute_expense_reimbursement_workflow_callback(
      p_business_id, p_status, p_actor, p_comment
    );
  elsif p_business_type = 'vehicle_archive' then
    perform app_private.execute_vehicle_archive_workflow_callback(
      p_business_id, p_status, p_actor, p_comment
    );
  else
    perform app_private.execute_workflow_business_callback_legacy(
      p_business_type, p_business_id, p_status, p_actor, p_comment
    );
  end if;
end
$function$;

--
-- Name: execute_workflow_business_callback_before_hr_p1; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.execute_workflow_business_callback_before_hr_p1(p_business_type text, p_business_id uuid, p_status text, p_actor text, p_comment text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_business_type in ('hr_personnel_change', 'hr_lifecycle_case') then
    perform app_private.execute_hr_workflow_business_callback(
      p_business_type, p_business_id, p_status, p_actor, p_comment
    );
  else
    perform app_private.execute_workflow_business_callback_before_hr(
      p_business_type, p_business_id, p_status, p_actor, p_comment
    );
  end if;
end;
$function$;

--
-- Name: execute_workflow_business_callback_before_hr_p2; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.execute_workflow_business_callback_before_hr_p2(p_business_type text, p_business_id uuid, p_status text, p_actor text, p_comment text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_business_type='hr_self_service_request' then
    perform app_private.execute_hr_self_service_workflow_callback(p_business_id,p_status,p_actor,p_comment);
  else
    perform app_private.execute_workflow_business_callback_before_hr_p1(
      p_business_type,p_business_id,p_status,p_actor,p_comment);
  end if;
end $function$;

--
-- Name: execute_workflow_business_callback_legacy; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.execute_workflow_business_callback_legacy(p_business_type text, p_business_id uuid, p_status text, p_actor text, p_comment text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_invoice_direction text;
begin
  perform pg_catalog.set_config('app.workflow_engine','on',true);
  if p_business_type='tms_waybill_cost' then
    update public.tms_waybill_cost set
      audit_status=case p_status when 'running' then 'pending_review' when 'approved' then 'approved'
        when 'rejected' then 'rejected' when 'withdrawn' then 'draft' when 'cancelled' then 'draft'
        else audit_status end,
      submitted_at=case when p_status='running' then now() else submitted_at end,
      submitted_by=case when p_status='running' then p_actor else submitted_by end,
      reviewed_at=case when p_status='running' then null when p_status in ('approved','rejected') then now() else reviewed_at end,
      reviewed_by=case when p_status='running' then null when p_status in ('approved','rejected') then p_actor else reviewed_by end,
      review_remark=case when p_status='running' then null when p_status in ('approved','rejected','cancelled')
        then nullif(btrim(coalesce(p_comment,'')),'') else review_remark end
    where id=p_business_id;
    if not found then raise exception '运单费用不存在或已被删除'; end if;

  elsif p_business_type='tms_invoice' then
    select direction into v_invoice_direction from public.tms_invoice where id=p_business_id;
    if not found then raise exception '发票不存在或已被删除'; end if;
    update public.tms_invoice set
      status=case p_status when 'running' then 'pending_review'
        when 'approved' then case when v_invoice_direction='output' then 'issued' else 'certified' end
        when 'rejected' then 'draft' when 'withdrawn' then 'draft' when 'cancelled' then 'draft' else status end,
      submitted_at=case when p_status='running' then now() else submitted_at end,
      submitted_by=case when p_status='running' then p_actor else submitted_by end,
      reviewed_at=case when p_status='running' then null when p_status in ('approved','rejected','withdrawn','cancelled') then now() else reviewed_at end,
      reviewed_by=case when p_status='running' then null when p_status in ('approved','rejected','withdrawn','cancelled') then p_actor else reviewed_by end,
      review_remark=case when p_status='running' then null when p_status in ('approved','rejected','withdrawn','cancelled')
        then nullif(btrim(coalesce(p_comment,'')),'') else review_remark end
    where id=p_business_id;

  elsif p_business_type in ('tms_carrier_statement','tms_customer_statement') then
    if p_business_type='tms_carrier_statement' then
      update public.tms_carrier_statement set
        status=case p_status when 'running' then 'pending_review' when 'approved' then 'confirmed'
          when 'rejected' then 'draft' when 'withdrawn' then 'draft' when 'cancelled' then 'draft' else status end,
        submitted_at=case when p_status='running' then now() else submitted_at end,
        submitted_by=case when p_status='running' then p_actor else submitted_by end,
        reviewed_at=case when p_status='running' then null when p_status in ('approved','rejected') then now() else reviewed_at end,
        reviewed_by=case when p_status='running' then null when p_status in ('approved','rejected') then p_actor else reviewed_by end,
        review_remark=case when p_status='running' then null else nullif(btrim(coalesce(p_comment,'')),'') end
      where id=p_business_id;
    else
      update public.tms_customer_statement set
        status=case p_status when 'running' then 'pending_review' when 'approved' then 'confirmed'
          when 'rejected' then 'draft' when 'withdrawn' then 'draft' when 'cancelled' then 'draft' else status end,
        submitted_at=case when p_status='running' then now() else submitted_at end,
        submitted_by=case when p_status='running' then p_actor else submitted_by end,
        reviewed_at=case when p_status='running' then null when p_status in ('approved','rejected') then now() else reviewed_at end,
        reviewed_by=case when p_status='running' then null when p_status in ('approved','rejected') then p_actor else reviewed_by end,
        review_remark=case when p_status='running' then null else nullif(btrim(coalesce(p_comment,'')),'') end
      where id=p_business_id;
    end if;
    if not found then raise exception '对账单不存在或已被删除'; end if;

  elsif p_business_type='tms_contract' then
    update public.tms_contract set
      contract_status=case p_status when 'running' then 'pending' when 'approved' then 'approved'
        when 'rejected' then 'rejected' when 'withdrawn' then 'draft' when 'cancelled' then 'draft'
        else contract_status end
    where id=p_business_id;
    if not found then raise exception '合同不存在或已被删除'; end if;

  elsif p_business_type='vehicle_archive' then
    update public.vehicle_archive set
      audit_status=case p_status when 'running' then 'pending' when 'approved' then 'approved'
        when 'rejected' then 'rejected' when 'withdrawn' then 'pending' when 'cancelled' then 'pending'
        else audit_status end,
      audit_time=case when p_status in ('approved','rejected') then now() else audit_time end,
      audit_by=case when p_status in ('approved','rejected') then p_actor else audit_by end,
      audit_remark=case when p_status in ('approved','rejected','cancelled')
        then nullif(btrim(coalesce(p_comment,'')),'') else audit_remark end
    where id=p_business_id;
    if not found then raise exception '车辆档案不存在或已被删除'; end if;
  end if;
end;
$function$;

--
-- Name: field_access_map; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.field_access_map(p_resource_key text, p_record_owner_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_object_agg(f.field_key, app_private.resolve_field_access(r.resource_key, f.field_key, p_record_owner_id) order by f.sort, f.id), '{}'::jsonb)
  from public.sys_permission_resource r join public.sys_permission_field f on f.resource_id=r.id
  where r.resource_key=p_resource_key and r.enabled and f.enabled and f.sensitive;
$function$;

--
-- Name: get_ai_project_capability_snapshot; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.get_ai_project_capability_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_auth jsonb := '{}'::jsonb;
  v_storage jsonb := '{}'::jsonb;
  v_cron jsonb := jsonb_build_object('enabled', false, 'jobs', 0, 'activeJobs', 0);
  v_queues jsonb := jsonb_build_object('enabled', false, 'queues', 0);
  v_statement_stats jsonb := jsonb_build_object('enabled', false, 'trackedStatements', 0);
  v_public_tables integer := 0;
  v_rls_tables integer := 0;
  v_force_rls_tables integer := 0;
  v_policy_count integer := 0;
  v_unindexed_foreign_keys integer := 0;
  v_invalid_indexes integer := 0;
  v_public_views integer := 0;
  v_security_invoker_views integer := 0;
begin
  if (select auth.uid()) is null or not exists (
    select 1
    from public.sys_user as app_user
    where app_user.auth_user_id = (select auth.uid())
      and app_user.status = '1'
  ) then
    raise exception 'Active authenticated user permission is required'
      using errcode = '42501';
  end if;

  select
    count(*)::integer,
    count(*) filter (where cls.relrowsecurity)::integer,
    count(*) filter (where cls.relforcerowsecurity)::integer
  into v_public_tables, v_rls_tables, v_force_rls_tables
  from pg_catalog.pg_class as cls
  join pg_catalog.pg_namespace as ns on ns.oid = cls.relnamespace
  where ns.nspname = 'public'
    and cls.relkind in ('r', 'p');

  select count(*)::integer
  into v_policy_count
  from pg_catalog.pg_policy as policy
  join pg_catalog.pg_class as cls on cls.oid = policy.polrelid
  join pg_catalog.pg_namespace as ns on ns.oid = cls.relnamespace
  where ns.nspname = 'public';

  select count(*)::integer
  into v_unindexed_foreign_keys
  from pg_catalog.pg_constraint as constraint_record
  join pg_catalog.pg_class as relation_record
    on relation_record.oid = constraint_record.conrelid
  join pg_catalog.pg_namespace as ns
    on ns.oid = relation_record.relnamespace
  where constraint_record.contype = 'f'
    and ns.nspname = 'public'
    and not exists (
      select 1
      from pg_catalog.pg_index as index_record
      where index_record.indrelid = constraint_record.conrelid
        and index_record.indisvalid
        and index_record.indisready
        and (index_record.indkey::smallint[])[0:cardinality(constraint_record.conkey) - 1]
          @> constraint_record.conkey
    );

  select count(*)::integer
  into v_invalid_indexes
  from pg_catalog.pg_index as index_record
  join pg_catalog.pg_class as relation_record on relation_record.oid = index_record.indrelid
  join pg_catalog.pg_namespace as ns on ns.oid = relation_record.relnamespace
  where ns.nspname = 'public'
    and (not index_record.indisvalid or not index_record.indisready);

  select
    count(*)::integer,
    count(*) filter (
      where coalesce(cls.reloptions, '{}'::text[]) @> array['security_invoker=true']
    )::integer
  into v_public_views, v_security_invoker_views
  from pg_catalog.pg_class as cls
  join pg_catalog.pg_namespace as ns on ns.oid = cls.relnamespace
  where ns.nspname = 'public'
    and cls.relkind in ('v', 'm');

  if pg_catalog.to_regclass('auth.users') is not null then
    select jsonb_build_object(
      'enabled', true,
      'users', count(*)::integer,
      'confirmedUsers', count(*) filter (where confirmed_at is not null)::integer,
      'active30d', count(*) filter (
        where last_sign_in_at >= pg_catalog.now() - interval '30 days'
      )::integer
    )
    into v_auth
    from auth.users;
  else
    v_auth := jsonb_build_object(
      'enabled', false,
      'users', 0,
      'confirmedUsers', 0,
      'active30d', 0
    );
  end if;

  if pg_catalog.to_regclass('storage.buckets') is not null then
    select jsonb_build_object(
      'enabled', true,
      'buckets', (select count(*)::integer from storage.buckets),
      'publicBuckets', (
        select count(*)::integer from storage.buckets where public
      ),
      'objects', (select count(*)::integer from storage.objects),
      'totalBytes', (
        select coalesce(sum((metadata->>'size')::bigint), 0)::bigint
        from storage.objects
        where metadata->>'size' ~ '^[0-9]+$'
      ),
      'policies', (
        select count(*)::integer
        from pg_catalog.pg_policy as policy
        where policy.polrelid in (
          pg_catalog.to_regclass('storage.buckets'),
          pg_catalog.to_regclass('storage.objects')
        )
      )
    )
    into v_storage;
  else
    v_storage := jsonb_build_object(
      'enabled', false,
      'buckets', 0,
      'publicBuckets', 0,
      'objects', 0,
      'totalBytes', 0,
      'policies', 0
    );
  end if;

  if pg_catalog.to_regclass('cron.job') is not null then
    execute $query$
      select jsonb_build_object(
        'enabled', true,
        'jobs', count(*)::integer,
        'activeJobs', count(*) filter (where active)::integer
      )
      from cron.job
    $query$
    into v_cron;
  else
    v_cron := jsonb_build_object(
      'enabled', exists(select 1 from pg_catalog.pg_extension where extname = 'pg_cron'),
      'jobs', 0,
      'activeJobs', 0
    );
  end if;

  if pg_catalog.to_regclass('pgmq.meta') is not null then
    execute $query$
      select jsonb_build_object(
        'enabled', true,
        'queues', count(*)::integer
      )
      from pgmq.meta
    $query$
    into v_queues;
  else
    v_queues := jsonb_build_object(
      'enabled', exists(select 1 from pg_catalog.pg_extension where extname = 'pgmq'),
      'queues', 0
    );
  end if;

  if exists (
    select 1 from pg_catalog.pg_extension where extname = 'pg_stat_statements'
  ) and pg_catalog.to_regclass('public.pg_stat_statements') is not null then
    execute $query$
      select jsonb_build_object(
        'enabled', true,
        'trackedStatements', count(*)::integer,
        'meanExecutionMs', coalesce(round(avg(mean_exec_time)::numeric, 2), 0),
        'maxMeanExecutionMs', coalesce(round(max(mean_exec_time)::numeric, 2), 0)
      )
      from public.pg_stat_statements
    $query$
    into v_statement_stats;
  else
    v_statement_stats := jsonb_build_object(
      'enabled', exists(
        select 1 from pg_catalog.pg_extension where extname = 'pg_stat_statements'
      ),
      'trackedStatements', 0
    );
  end if;

  return jsonb_build_object(
    'projectRef', 'ckbftoopuyophiebamwy',
    'capturedAt', pg_catalog.clock_timestamp(),
    'database', jsonb_build_object(
      'version', pg_catalog.current_setting('server_version'),
      'sizeBytes', pg_catalog.pg_database_size(pg_catalog.current_database()),
      'activeConnections', (
        select count(*)::integer
        from pg_catalog.pg_stat_activity
        where datname = pg_catalog.current_database()
      ),
      'maxConnections', pg_catalog.current_setting('max_connections')::integer,
      'publicTables', v_public_tables,
      'publicViews', v_public_views,
      'estimatedRows', (
        select coalesce(sum(greatest(cls.reltuples, 0)), 0)::bigint
        from pg_catalog.pg_class as cls
        join pg_catalog.pg_namespace as ns on ns.oid = cls.relnamespace
        where ns.nspname = 'public'
          and cls.relkind in ('r', 'p')
      ),
      'cacheHitPercent', (
        select coalesce(
          round(100 * blks_hit::numeric / nullif(blks_hit + blks_read, 0), 2),
          100
        )
        from pg_catalog.pg_stat_database
        where datname = pg_catalog.current_database()
      )
    ),
    'security', jsonb_build_object(
      'publicTables', v_public_tables,
      'rlsEnabledTables', v_rls_tables,
      'forceRlsTables', v_force_rls_tables,
      'rlsCoveragePercent', case
        when v_public_tables = 0 then 100
        else round(100 * v_rls_tables::numeric / v_public_tables, 1)
      end,
      'policyCount', v_policy_count,
      'invalidIndexes', v_invalid_indexes,
      'unindexedForeignKeys', v_unindexed_foreign_keys,
      'views', v_public_views,
      'securityInvokerViews', v_security_invoker_views,
      'tablesWithoutRls', coalesce((
        select jsonb_agg(format('%I.%I', ns.nspname, cls.relname) order by cls.relname)
        from pg_catalog.pg_class as cls
        join pg_catalog.pg_namespace as ns on ns.oid = cls.relnamespace
        where ns.nspname = 'public'
          and cls.relkind in ('r', 'p')
          and not cls.relrowsecurity
      ), '[]'::jsonb),
      'unindexedForeignKeyTables', coalesce((
        select jsonb_agg(
          distinct format('%I.%I', ns.nspname, relation_record.relname)
        )
        from pg_catalog.pg_constraint as constraint_record
        join pg_catalog.pg_class as relation_record
          on relation_record.oid = constraint_record.conrelid
        join pg_catalog.pg_namespace as ns on ns.oid = relation_record.relnamespace
        where constraint_record.contype = 'f'
          and ns.nspname = 'public'
          and not exists (
            select 1
            from pg_catalog.pg_index as index_record
            where index_record.indrelid = constraint_record.conrelid
              and index_record.indisvalid
              and index_record.indisready
              and (index_record.indkey::smallint[])
                [0:cardinality(constraint_record.conkey) - 1] @> constraint_record.conkey
          )
      ), '[]'::jsonb)
    ),
    'performance', jsonb_build_object(
      'statements', v_statement_stats,
      'sequentialScans', (
        select coalesce(sum(seq_scan), 0)::bigint
        from pg_catalog.pg_stat_user_tables
        where schemaname = 'public'
      ),
      'indexScans', (
        select coalesce(sum(idx_scan), 0)::bigint
        from pg_catalog.pg_stat_user_tables
        where schemaname = 'public'
      ),
      'deadRows', (
        select coalesce(sum(n_dead_tup), 0)::bigint
        from pg_catalog.pg_stat_user_tables
        where schemaname = 'public'
      )
    ),
    'auth', v_auth,
    'storage', v_storage,
    'realtime', jsonb_build_object(
      'enabled', exists(
        select 1 from pg_catalog.pg_publication where pubname = 'supabase_realtime'
      ),
      'publishedTables', (
        select count(*)::integer
        from pg_catalog.pg_publication_tables
        where pubname = 'supabase_realtime'
      )
    ),
    'cron', v_cron,
    'queues', v_queues,
    'vectors', jsonb_build_object(
      'enabled', exists(select 1 from pg_catalog.pg_extension where extname = 'vector'),
      'columns', (
        select count(*)::integer
        from pg_catalog.pg_attribute as attribute_record
        join pg_catalog.pg_type as type_record on type_record.oid = attribute_record.atttypid
        join pg_catalog.pg_class as relation_record
          on relation_record.oid = attribute_record.attrelid
        join pg_catalog.pg_namespace as ns on ns.oid = relation_record.relnamespace
        where ns.nspname = 'public'
          and attribute_record.attnum > 0
          and not attribute_record.attisdropped
          and type_record.typname in ('vector', 'halfvec', 'sparsevec')
      ),
      'indexes', (
        select count(*)::integer
        from pg_catalog.pg_index as index_record
        join pg_catalog.pg_class as index_relation on index_relation.oid = index_record.indexrelid
        join pg_catalog.pg_am as access_method on access_method.oid = index_relation.relam
        join pg_catalog.pg_namespace as ns on ns.oid = index_relation.relnamespace
        where ns.nspname = 'public'
          and access_method.amname in ('hnsw', 'ivfflat')
      )
    ),
    'extensions', jsonb_build_object(
      'installed', (
        select coalesce(jsonb_agg(
          jsonb_build_object('name', extension_record.extname, 'version', extension_record.extversion)
          order by extension_record.extname
        ), '[]'::jsonb)
        from pg_catalog.pg_extension as extension_record
      ),
      'vaultEnabled', exists(
        select 1 from pg_catalog.pg_extension where extname = 'supabase_vault'
      )
    )
  );
end;
$function$;

--
-- Name: get_authorized_application_menu_flat; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.get_authorized_application_menu_flat(p_app_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cur_uid uuid := (select auth.uid());
  v_app_code text := lower(nullif(btrim(p_app_code), ''));
  v_role_ids uuid[] := '{}';
  v_menu_ids uuid[] := '{}';
  v_flat jsonb := '[]'::jsonb;
begin
  if v_cur_uid is null or not exists (
    select 1
    from public.sys_application application_row
    where application_row.app_code = v_app_code
      and application_row.enabled
  ) then
    return v_flat;
  end if;

  if app_private.is_platform_super() then
    select array_remove(array_agg(menu_row.id order by menu_row.sort nulls last, menu_row.id), null)
    into v_menu_ids
    from public.sys_menu menu_row
    where menu_row.app_code = v_app_code
      and (menu_row.meta->>'is_enable') is distinct from 'false';
  else
    select array_remove(array_agg(distinct role_row.id), null)
    into v_role_ids
    from public.sys_user current_user_row
    join public.sys_role role_row
      on role_row.role_code = any(coalesce(current_user_row.user_roles, array[]::text[]))
     and role_row.enabled
    where current_user_row.auth_user_id = v_cur_uid
      and current_user_row.status = '1'
      and current_user_row.deleted_at is null;

    if v_role_ids is null or array_length(v_role_ids, 1) is null then
      return v_flat;
    end if;

    select array_remove(array_agg(distinct role_menu.menu_id), null)
    into v_menu_ids
    from public.sys_role_menu role_menu
    join public.sys_menu menu_row on menu_row.id = role_menu.menu_id
    where role_menu.role_id = any(v_role_ids)
      and menu_row.app_code = v_app_code
      and (menu_row.meta->>'is_enable') is distinct from 'false';
  end if;

  if v_menu_ids is null or array_length(v_menu_ids, 1) is null then
    return v_flat;
  end if;

  -- A role grant is valid only together with its navigation ancestry. Include
  -- those folders in the response without expanding to ungranted siblings.
  with recursive granted_menu_ancestry as (
    select menu_row.id, menu_row.parent_id
    from public.sys_menu menu_row
    where menu_row.id = any(v_menu_ids)
      and menu_row.app_code = v_app_code
      and (menu_row.meta->>'is_enable') is distinct from 'false'

    union

    select parent_menu.id, parent_menu.parent_id
    from public.sys_menu parent_menu
    join granted_menu_ancestry child_menu
      on child_menu.parent_id = parent_menu.id
    where parent_menu.app_code = v_app_code
      and (parent_menu.meta->>'is_enable') is distinct from 'false'
  )
  select array_remove(array_agg(distinct ancestry.id), null)
  into v_menu_ids
  from granted_menu_ancestry ancestry;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', menu_row.id,
    'parentId', menu_row.parent_id,
    'name', menu_row.name,
    'path', menu_row.path,
    'component', menu_row.component,
    'meta', menu_row.meta,
    'sort', menu_row.sort,
    'type', menu_row.type
  ) order by menu_row.sort nulls last, menu_row.id), '[]'::jsonb)
  into v_flat
  from public.sys_menu menu_row
  where menu_row.id = any(v_menu_ids);

  return v_flat;
end;
$function$;

--
-- Name: get_carrier_payment_application_workflow_snapshot; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.get_carrier_payment_application_workflow_snapshot(p_instance_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_instance public.wf_instance;
  v_application record;
  v_access jsonb;
  v_amount_access text;
  v_evidence_access text;
  v_metrics jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_attachments jsonb := '[]'::jsonb;
begin
  if (select auth.uid()) is null
     or not app_private.can_view_workflow_instance(p_instance_id) then
    raise exception '无权查看该审批业务信息' using errcode = '42501';
  end if;

  select instance_row.*
  into v_instance
  from public.wf_instance instance_row
  where instance_row.id = p_instance_id;

  if not found then
    raise exception '审批实例不存在';
  end if;

  select
    application_row.*,
    (
      select count(*)::integer
      from public.tms_carrier_payment_application_item item_row
      where item_row.application_id = application_row.id
    ) as statement_count,
    (
      select coalesce(
        string_agg(
          item_row.statement_no_snapshot,
          '、'
          order by item_row.statement_no_snapshot
        ),
        ''
      )
      from public.tms_carrier_payment_application_item item_row
      where item_row.application_id = application_row.id
    ) as statement_nos
  into v_application
  from public.tms_carrier_payment_application application_row
  where application_row.id = v_instance.business_id;

  if not found then
    return jsonb_build_object(
      'instanceId', v_instance.id,
      'businessType', v_instance.business_type,
      'businessId', v_instance.business_id,
      'title', v_instance.business_title,
      'metrics', '[]'::jsonb,
      'fields', '[]'::jsonb,
      'warnings', jsonb_build_array('业务原单已删除，当前仅展示流程快照'),
      'attachments', '[]'::jsonb
    );
  end if;

  v_access := app_private.field_access_map(
    'tms.carrier_payment_application',
    v_application.created_by_user_id
  );
  v_amount_access := coalesce(v_access->>'applicationAmounts', 'hidden');
  v_evidence_access := coalesce(v_access->>'basisEvidence', 'hidden');

  if v_instance.status = 'running' and not exists (
    select 1
    from public.wf_task task_row
    where task_row.instance_id = v_instance.id
      and task_row.status = 'pending'
  ) then
    v_warnings := jsonb_build_array(
      '流程运行中但当前没有待办任务，请联系审批管理员检查流程条件。'
    );
  end if;

  v_metrics := jsonb_build_array(
    jsonb_build_object(
      'label', '关联对账单',
      'value', v_application.statement_count::text || ' 份',
      'tone', 'primary'
    ),
    jsonb_build_object(
      'label', '计划付款日',
      'value', v_application.planned_payment_date::text,
      'tone', 'info'
    )
  );

  if v_amount_access <> 'hidden' then
    v_metrics := jsonb_build_array(jsonb_build_object(
      'label', '申请金额',
      'value', case
        when v_amount_access = 'masked' then '***'
        else '¥ ' || to_char(v_application.amount, 'FM999,999,990.00')
      end,
      'tone', 'warning'
    )) || v_metrics;
  end if;

  if v_amount_access = 'masked' then
    v_warnings := v_warnings || jsonb_build_array('申请金额已按字段权限脱敏');
  end if;
  if v_evidence_access = 'masked' then
    v_warnings := v_warnings || jsonb_build_array('付款依据已按字段权限脱敏');
  end if;
  if v_evidence_access in ('read', 'edit') then
    v_attachments := app_private.workflow_attachment_list(v_application.basis_urls);
  end if;

  return jsonb_build_object(
    'instanceId', v_instance.id,
    'businessType', v_instance.business_type,
    'businessId', v_instance.business_id,
    'title', v_instance.business_title,
    'subtitle', v_application.carrier_name_snapshot,
    'businessNo', v_application.application_no,
    'status', v_application.status,
    'routePath', '/tms-transportation/finance-center/payment-application',
    'metrics', v_metrics,
    'fields', jsonb_build_array(
      jsonb_build_object('label', '申请单号', 'value', v_application.application_no),
      jsonb_build_object(
        'label', '付款承运商', 'value', v_application.carrier_name_snapshot
      ),
      jsonb_build_object(
        'label',
        '关联对账单',
        'value', coalesce(nullif(v_application.statement_nos, ''), '--')
      ),
      jsonb_build_object('label', '付款方式', 'value', v_application.payment_method),
      jsonb_build_object(
        'label', '备注', 'value', coalesce(v_application.remark, '--')
      )
    ),
    'warnings', v_warnings,
    'attachments', v_attachments,
    'fieldAccess', v_access
  );
end;
$function$;

--
-- Name: get_contract_workflow_snapshot; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.get_contract_workflow_snapshot(p_instance_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_instance public.wf_instance;
  v_contract public.tms_contract%rowtype;
  v_party_name text;
  v_amount_access text;
  v_attachment_access text;
  v_metrics jsonb := '[]'::jsonb;
  v_attachments jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
begin
  if (select auth.uid()) is null or not app_private.can_view_workflow_instance(p_instance_id) then
    raise exception '无权查看该审批业务信息' using errcode = '42501';
  end if;

  select * into v_instance from public.wf_instance where id = p_instance_id;
  if not found then
    raise exception '审批实例不存在';
  end if;

  select contract_row.*
    into v_contract
  from public.tms_contract contract_row
  where contract_row.id = v_instance.business_id
    ;

  if not found then
    v_warnings := jsonb_build_array('业务原单已删除，当前仅展示流程快照');
    return jsonb_build_object(
      'instanceId', v_instance.id,
      'businessType', v_instance.business_type,
      'businessId', v_instance.business_id,
      'title', v_instance.business_title,
      'warnings', v_warnings,
      'metrics', '[]'::jsonb,
      'fields', '[]'::jsonb,
      'attachments', '[]'::jsonb
    );
  end if;

  select coalesce(customer.customer_name, carrier.company_name)
    into v_party_name
  from public.tms_contract contract_row
  left join public.tms_customer customer
    on customer.id = contract_row.customer_id
   
  left join public.tms_carrier carrier
    on carrier.id = contract_row.carrier_id
   
  where contract_row.id = v_contract.id;

  v_amount_access := app_private.resolve_field_access(
    'tms.contract', 'contractAmount', v_contract.created_by_user_id
  );
  v_attachment_access := app_private.resolve_field_access(
    'tms.contract', 'attachments', v_contract.created_by_user_id
  );

  if v_amount_access in ('read', 'edit') then
    v_metrics := v_metrics || jsonb_build_object(
      'label', '合同金额',
      'value', '¥ ' || to_char(coalesce(v_contract.contract_amount, 0), 'FM999,999,990.00'),
      'tone', 'warning'
    );
  elsif v_amount_access = 'masked' then
    v_metrics := v_metrics || jsonb_build_object(
      'label', '合同金额',
      'value', '***',
      'tone', 'warning'
    );
  end if;

  v_metrics := v_metrics || jsonb_build_array(
    jsonb_build_object(
      'label', '生效日期',
      'value', coalesce(v_contract.effective_date::text, '--'),
      'tone', 'info'
    ),
    jsonb_build_object(
      'label', '运输明细',
      'value', jsonb_array_length(v_contract.transport_details)::text || ' 条',
      'tone', 'primary'
    )
  );

  if v_attachment_access in ('read', 'edit') then
    v_attachments := app_private.workflow_attachment_list(v_contract.attachments);
  end if;

  return jsonb_build_object(
    'instanceId', v_instance.id,
    'businessType', v_instance.business_type,
    'businessId', v_instance.business_id,
    'title', v_instance.business_title,
    'subtitle', v_contract.contract_name,
    'businessNo', v_contract.contract_no,
    'status', v_contract.contract_status,
    'routePath', '/tms-transportation/basic-data/contract-detail/' || v_instance.business_id::text,
    'metrics', v_metrics,
    'fields', jsonb_build_array(
      jsonb_build_object('label', '合同编号', 'value', coalesce(v_contract.contract_no, '--')),
      jsonb_build_object('label', '合同相对方', 'value', coalesce(v_party_name, '--')),
      jsonb_build_object('label', '业务合同分类', 'value', coalesce(v_contract.business_contract_type, '--')),
      jsonb_build_object('label', '合同类别', 'value', coalesce(v_contract.contract_category, '--')),
      jsonb_build_object('label', '运输方式', 'value', coalesce(v_contract.transport_mode, '--')),
      jsonb_build_object('label', '计费方式', 'value', coalesce(v_contract.billing_method, '--')),
      jsonb_build_object('label', '经办人', 'value', coalesce(v_contract.handler, '--')),
      jsonb_build_object(
        'label', '有效期',
        'value', concat_ws(' 至 ', v_contract.effective_date::text, v_contract.expiry_date::text)
      )
    ),
    'warnings', v_warnings,
    'attachments', v_attachments
  );
end;
$function$;

--
-- Name: get_expense_reimbursement_workflow_snapshot; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.get_expense_reimbursement_workflow_snapshot(p_instance_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_instance public.wf_instance%rowtype;
  v_reimbursement record;
  v_access jsonb;
  v_amount_level text;
  v_payee_level text;
  v_evidence_level text;
  v_payment_level text;
  v_metrics jsonb := '[]'::jsonb;
  v_fields jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_attachments jsonb := '[]'::jsonb;
begin
  if auth.uid() is null or not app_private.can_view_workflow_instance(p_instance_id) then
    raise exception '无权查看该审批业务信息' using errcode = '42501';
  end if;
  select instance_row.*
  into v_instance
  from public.wf_instance instance_row
  where instance_row.id = p_instance_id;
  if not found then raise exception '审批实例不存在'; end if;

  select reimbursement_row.*,
         (select count(*)::integer
          from public.tms_expense_reimbursement_item item_row
          where item_row.reimbursement_id = reimbursement_row.id
            ) as item_count,
         (select string_agg(
            distinct item_row.waybill_no_snapshot,
            '、' order by item_row.waybill_no_snapshot
          )
          from public.tms_expense_reimbursement_item item_row
          where item_row.reimbursement_id = reimbursement_row.id
            ) as waybill_nos
  into v_reimbursement
  from public.tms_expense_reimbursement reimbursement_row
  where reimbursement_row.id = v_instance.business_id
    ;

  if not found then
    return jsonb_build_object(
      'instanceId', v_instance.id,
      'businessType', v_instance.business_type,
      'businessId', v_instance.business_id,
      'title', v_instance.business_title,
      'subtitle', null,
      'businessNo', null,
      'status', null,
      'routePath', '/fms/settlement/expense-reimbursement',
      'metrics', '[]'::jsonb,
      'fields', '[]'::jsonb,
      'warnings', jsonb_build_array('业务原单已删除，当前仅展示流程基本信息'),
      'attachments', '[]'::jsonb
    );
  end if;

  v_access := app_private.field_access_map(
    'tms.expense_reimbursement', v_reimbursement.created_by_user_id
  );
  v_amount_level := coalesce(v_access->>'reimbursementAmounts', 'hidden');
  v_payee_level := coalesce(v_access->>'payeeDetails', 'hidden');
  v_evidence_level := coalesce(v_access->>'reimbursementEvidence', 'hidden');
  v_payment_level := coalesce(v_access->>'paymentExecution', 'hidden');

  if v_amount_level <> 'hidden' then
    v_metrics := v_metrics || jsonb_build_array(jsonb_build_object(
      'label', '报销金额',
      'value', case when v_amount_level = 'masked' then '***'
        else '¥ ' || to_char(
          coalesce(v_reimbursement.total_amount, 0), 'FM999,999,990.00'
        ) end,
      'tone', 'warning'
    ));
    if v_amount_level = 'masked' then
      v_warnings := v_warnings || jsonb_build_array('报销金额已按字段权限脱敏');
    end if;
  end if;
  v_metrics := v_metrics || jsonb_build_array(
    jsonb_build_object(
      'label', '费用笔数',
      'value', coalesce(v_reimbursement.item_count, 0)::text || ' 笔',
      'tone', 'primary'
    ),
    jsonb_build_object(
      'label', '计划付款日',
      'value', coalesce(v_reimbursement.planned_payment_date::text, '--'),
      'tone', 'info'
    )
  );

  v_fields := jsonb_build_array(
    jsonb_build_object(
      'label', '申请人',
      'value', coalesce(v_reimbursement.applicant_name_snapshot, '--')
    ),
    jsonb_build_object(
      'label', '关联运单',
      'value', coalesce(v_reimbursement.waybill_nos, '--')
    )
  );
  if v_payee_level <> 'hidden' then
    v_fields := v_fields || jsonb_build_array(
      jsonb_build_object(
        'label', '收款人',
        'value', case when v_payee_level = 'masked' then '***'
          else coalesce(v_reimbursement.payee_name, '--') end
      ),
      jsonb_build_object(
        'label', '收款账号',
        'value', case when v_payee_level = 'masked' then
          coalesce(app_private.mask_permission_value(
            v_reimbursement.payee_account, 'bank_account'
          ), '--')
          else coalesce(v_reimbursement.payee_account, '--') end
      )
    );
  end if;
  if v_evidence_level <> 'hidden' then
    v_fields := v_fields || jsonb_build_array(jsonb_build_object(
      'label', '报销说明',
      'value', case when v_evidence_level = 'masked' then '***'
        else coalesce(v_reimbursement.remark, '--') end
    ));
  end if;
  if v_payment_level <> 'hidden' and v_reimbursement.payment_reference is not null then
    v_fields := v_fields || jsonb_build_array(jsonb_build_object(
      'label', '付款流水',
      'value', case when v_payment_level = 'masked' then
        app_private.mask_permission_value(
          v_reimbursement.payment_reference, 'bank_account'
        ) else v_reimbursement.payment_reference end
    ));
  end if;

  if v_evidence_level in ('read', 'edit') then
    v_attachments := v_attachments || app_private.workflow_attachment_list(
      v_reimbursement.basis_urls
    );
  elsif jsonb_array_length(coalesce(v_reimbursement.basis_urls, '[]'::jsonb)) > 0 then
    v_warnings := v_warnings || jsonb_build_array('报销依据已按字段权限隐藏');
  end if;
  if v_payment_level in ('read', 'edit') then
    v_attachments := v_attachments || app_private.workflow_attachment_list(
      v_reimbursement.payment_voucher_urls
    );
  elsif jsonb_array_length(
    coalesce(v_reimbursement.payment_voucher_urls, '[]'::jsonb)
  ) > 0 then
    v_warnings := v_warnings || jsonb_build_array('付款凭证已按字段权限隐藏');
  end if;

  return jsonb_build_object(
    'instanceId', v_instance.id,
    'businessType', v_instance.business_type,
    'businessId', v_instance.business_id,
    'title', '费用报销 ' || v_reimbursement.reimbursement_no,
    'subtitle', case when v_payee_level in ('read', 'edit')
      then v_reimbursement.payee_name else null end,
    'businessNo', v_reimbursement.reimbursement_no,
    'status', v_reimbursement.status,
    'routePath', '/fms/settlement/expense-reimbursement/detail/' ||
      v_reimbursement.id::text,
    'metrics', v_metrics,
    'fields', v_fields,
    'warnings', v_warnings,
    'attachments', v_attachments
  );
end;
$function$;

--
-- Name: get_header_notification_center; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.get_header_notification_center(p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := (select app_private.current_app_user_id());
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_result jsonb;
begin

  select jsonb_build_object(
    'notices', coalesce((
      select jsonb_agg(row_data order by create_time desc)
      from (
        select jsonb_build_object(
          'id', n.id,
          'category', n.category,
          'title', n.title,
          'content', n.content,
          'severity', n.severity,
          'isRead', n.is_read,
          'createdAt', n.create_time,
          'routePath', n.route_path,
          'routeQuery', n.route_query,
          'instanceId', n.instance_id
        ) row_data, n.create_time
        from public.sys_notification n
        where true
          and n.recipient_user_id = v_user_id
          and n.category = 'notice'
        order by n.create_time desc
        limit v_limit
      ) rows
    ), '[]'::jsonb),
    'messages', coalesce((
      select jsonb_agg(row_data order by create_time desc)
      from (
        select jsonb_build_object(
          'id', n.id,
          'category', n.category,
          'title', n.title,
          'content', n.content,
          'severity', n.severity,
          'isRead', n.is_read,
          'createdAt', n.create_time,
          'routePath', n.route_path,
          'routeQuery', n.route_query,
          'instanceId', n.instance_id
        ) row_data, n.create_time
        from public.sys_notification n
        where true
          and n.recipient_user_id = v_user_id
          and n.category = 'message'
        order by n.create_time desc
        limit v_limit
      ) rows
    ), '[]'::jsonb),
    'todos', coalesce((
      select jsonb_agg(row_data order by create_time desc)
      from (
        select jsonb_build_object(
          'id', n.id,
          'category', n.category,
          'title', n.title,
          'content', n.content,
          'severity', n.severity,
          'isRead', n.is_read,
          'createdAt', n.create_time,
          'routePath', n.route_path,
          'routeQuery', n.route_query,
          'instanceId', n.instance_id
        ) row_data, n.create_time
        from public.sys_notification n
        where true
          and n.recipient_user_id = v_user_id
          and n.category = 'todo'
          and n.is_read = false
        order by n.create_time desc
        limit v_limit
      ) rows
    ), '[]'::jsonb),
    'unreadNoticeCount', (
      select count(*) from public.sys_notification n
      where n.recipient_user_id = v_user_id
        and n.category = 'notice' and n.is_read = false
    ),
    'unreadMessageCount', (
      select count(*) from public.sys_notification n
      where n.recipient_user_id = v_user_id
        and n.category = 'message' and n.is_read = false
    ),
    'pendingTodoCount', (
      select count(*) from public.sys_notification n
      where n.recipient_user_id = v_user_id
        and n.category = 'todo' and n.is_read = false
    )
  ) into v_result;

  return v_result || jsonb_build_object(
    'totalUnreadCount',
    coalesce((v_result ->> 'unreadNoticeCount')::integer, 0)
      + coalesce((v_result ->> 'unreadMessageCount')::integer, 0)
      + coalesce((v_result ->> 'pendingTodoCount')::integer, 0)
  );
end;
$function$;

--
-- Name: get_hr_workflow_business_snapshot; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.get_hr_workflow_business_snapshot(p_instance_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  instance_row public.wf_instance;
  business_row record;
  result_value jsonb;
  metrics_value jsonb := '[]'::jsonb;
  fields_value jsonb := '[]'::jsonb;
  warnings_value jsonb := '[]'::jsonb;
  subtitle_value text;
  business_no_value text;
  status_value text;
  route_value text;
begin
  if (select auth.uid()) is null
    or not app_private.can_view_workflow_instance(p_instance_id)
  then
    raise exception '无权查看该审批业务信息' using errcode = '42501';
  end if;

  select *
  into instance_row
  from public.wf_instance
  where id = p_instance_id;

  if not found then
    raise exception '审批实例不存在';
  end if;

  if instance_row.business_type = 'hr_personnel_change' then
    select
      change_row.*,
      employee_row.employee_name,
      employee_row.employee_no,
      app_private.workflow_dictionary_label(
        'hrPersonnelChangeType',
        change_row.change_type
      ) as change_type_label
    into business_row
    from public.hr_personnel_change change_row
    left join public.hr_employee employee_row
      on employee_row.id = change_row.employee_id
      
    where change_row.id = instance_row.business_id
      ;

    route_value := '/hr/personnel/personnel-change';
    if not found then
      warnings_value := jsonb_build_array('业务原单已删除，当前仅展示流程快照');
    else
      business_no_value := business_row.change_no;
      status_value := business_row.status;
      subtitle_value := concat_ws(
        ' · ',
        business_row.employee_name,
        business_row.employee_no
      );
      metrics_value := jsonb_build_array(
        jsonb_build_object(
          'label', '异动类型',
          'value', coalesce(business_row.change_type_label, '待确认'),
          'tone', 'primary'
        ),
        jsonb_build_object(
          'label', '生效日期',
          'value', coalesce(business_row.effective_date::text, '--'),
          'tone', 'info'
        )
      );
      fields_value := jsonb_build_array(
        jsonb_build_object('label', '异动单号', 'value', coalesce(business_row.change_no, '--')),
        jsonb_build_object('label', '员工', 'value', coalesce(business_row.employee_name, '--')),
        jsonb_build_object('label', '员工编号', 'value', coalesce(business_row.employee_no, '--')),
        jsonb_build_object(
          'label', '异动类型',
          'value', coalesce(business_row.change_type_label, business_row.change_type, '--')
        ),
        jsonb_build_object('label', '生效日期', 'value', coalesce(business_row.effective_date::text, '--')),
        jsonb_build_object('label', '异动原因', 'value', coalesce(business_row.reason, '--'))
      );
    end if;

  elsif instance_row.business_type = 'hr_lifecycle_case' then
    select
      case_row.*,
      employee_row.employee_name,
      employee_row.employee_no,
      app_private.workflow_dictionary_label(
        'hrLifecycleCaseType',
        case_row.case_type
      ) as case_type_label
    into business_row
    from public.hr_lifecycle_case case_row
    left join public.hr_employee employee_row
      on employee_row.id = case_row.employee_id
      
    where case_row.id = instance_row.business_id
      ;

    route_value := '/hr/personnel/lifecycle';
    if not found then
      warnings_value := jsonb_build_array('业务原单已删除，当前仅展示流程快照');
    else
      business_no_value := business_row.case_no;
      status_value := business_row.status;
      subtitle_value := concat_ws(' · ', business_row.employee_name, business_row.employee_no);
      metrics_value := jsonb_build_array(
        jsonb_build_object(
          'label', '事项类型',
          'value', coalesce(business_row.case_type_label, '待确认'),
          'tone', 'primary'
        ),
        jsonb_build_object(
          'label', '计划生效',
          'value', coalesce(business_row.planned_effective_date::text, '--'),
          'tone', 'info'
        )
      );
      fields_value := jsonb_build_array(
        jsonb_build_object('label', '事项编号', 'value', coalesce(business_row.case_no, '--')),
        jsonb_build_object('label', '员工', 'value', coalesce(business_row.employee_name, '--')),
        jsonb_build_object('label', '员工编号', 'value', coalesce(business_row.employee_no, '--')),
        jsonb_build_object(
          'label', '事项类型',
          'value', coalesce(business_row.case_type_label, business_row.case_type, '--')
        ),
        jsonb_build_object(
          'label', '计划生效日期',
          'value', coalesce(business_row.planned_effective_date::text, '--')
        ),
        jsonb_build_object('label', '备注', 'value', coalesce(business_row.remark, '--'))
      );
    end if;

  elsif instance_row.business_type = 'hr_self_service_request' then
    select
      request_row.*,
      employee_row.employee_name,
      employee_row.employee_no,
      app_private.workflow_dictionary_label(
        'hrSelfServiceRequestType',
        request_row.request_type
      ) as request_type_label
    into business_row
    from public.hr_self_service_request request_row
    left join public.hr_employee employee_row
      on employee_row.id = request_row.employee_id
      
    where request_row.id = instance_row.business_id
      ;

    route_value := '/hr/operations/self-service';
    if not found then
      warnings_value := jsonb_build_array('业务原单已删除，当前仅展示流程快照');
    else
      business_no_value := business_row.request_no;
      status_value := business_row.status;
      subtitle_value := concat_ws(' · ', business_row.employee_name, business_row.title);
      metrics_value := jsonb_build_array(
        jsonb_build_object(
          'label', '申请类型',
          'value', coalesce(business_row.request_type_label, '待确认'),
          'tone', 'primary'
        ),
        jsonb_build_object(
          'label', '申请时长',
          'value', coalesce(business_row.duration_hours::text || ' 小时', '--'),
          'tone', 'info'
        )
      );
      fields_value := jsonb_build_array(
        jsonb_build_object('label', '申请编号', 'value', coalesce(business_row.request_no, '--')),
        jsonb_build_object('label', '员工', 'value', coalesce(business_row.employee_name, '--')),
        jsonb_build_object('label', '申请标题', 'value', coalesce(business_row.title, '--')),
        jsonb_build_object(
          'label', '申请类型',
          'value', coalesce(business_row.request_type_label, business_row.request_type, '--')
        ),
        jsonb_build_object('label', '开始时间', 'value', coalesce(business_row.start_at::text, '--')),
        jsonb_build_object('label', '结束时间', 'value', coalesce(business_row.end_at::text, '--'))
      );
    end if;

  elsif instance_row.business_type = 'hr_recruitment_requisition' then
    select
      requisition_row.*,
      organization_row.organization_name,
      position_row.position_name
    into business_row
    from public.hr_recruitment_requisition requisition_row
    left join public.sys_organization organization_row
      on organization_row.id = requisition_row.organization_id
      
    left join public.hr_position position_row
      on position_row.id = requisition_row.position_id
      
    where requisition_row.id = instance_row.business_id
      ;

    route_value := '/hr/recruitment/workbench';
    if not found then
      warnings_value := jsonb_build_array('业务原单已删除，当前仅展示流程快照');
    else
      business_no_value := business_row.requisition_no;
      status_value := business_row.status;
      subtitle_value := concat_ws(
        ' · ',
        business_row.organization_name,
        business_row.position_name
      );
      metrics_value := jsonb_build_array(
        jsonb_build_object(
          'label', '招聘人数',
          'value', coalesce(business_row.opening_count, 0)::text || ' 人',
          'tone', 'primary'
        ),
        jsonb_build_object(
          'label', '期望到岗',
          'value', coalesce(business_row.expected_onboard_date::text, '--'),
          'tone', 'info'
        )
      );
      fields_value := jsonb_build_array(
        jsonb_build_object('label', '需求编号', 'value', coalesce(business_row.requisition_no, '--')),
        jsonb_build_object('label', '招聘组织', 'value', coalesce(business_row.organization_name, '--')),
        jsonb_build_object('label', '招聘岗位', 'value', coalesce(business_row.position_name, '--')),
        jsonb_build_object('label', '需求人数', 'value', coalesce(business_row.opening_count, 0)::text || ' 人'),
        jsonb_build_object('label', '已录用', 'value', coalesce(business_row.hired_count, 0)::text || ' 人'),
        jsonb_build_object(
          'label', '期望到岗日期',
          'value', coalesce(business_row.expected_onboard_date::text, '--')
        )
      );
    end if;
  else
    raise exception '不支持的 HR 审批业务类型: %', instance_row.business_type;
  end if;

  result_value := jsonb_build_object(
    'instanceId', instance_row.id,
    'businessType', instance_row.business_type,
    'businessId', instance_row.business_id,
    'title', instance_row.business_title,
    'subtitle', subtitle_value,
    'businessNo', business_no_value,
    'status', status_value,
    'routePath', route_value,
    'metrics', metrics_value,
    'fields', fields_value,
    'warnings', warnings_value,
    'attachments', '[]'::jsonb
  );

  return result_value;
end
$function$;

--
-- Name: get_tool_return_workflow_snapshot; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.get_tool_return_workflow_snapshot(p_instance_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_instance public.wf_instance;
  v_return public.smis_tool_return;
  v_quantity numeric;
  v_item_count integer;
begin
  if auth.uid() is null or not app_private.can_view_workflow_instance(p_instance_id) then
    raise exception '无权查看该审批业务信息' using errcode = '42501';
  end if;
  select * into v_instance from public.wf_instance where id = p_instance_id;
  if not found or v_instance.business_type <> 'smis_tool_return' then
    raise exception '工器具归还审批实例不存在';
  end if;
  select * into v_return from public.smis_tool_return where id = v_instance.business_id;
  if not found then
    return jsonb_build_object(
      'instanceId', v_instance.id,
      'businessType', v_instance.business_type,
      'businessId', v_instance.business_id,
      'title', v_instance.business_title,
      'warnings', jsonb_build_array('业务原单已删除，当前仅展示流程快照'),
      'metrics', '[]'::jsonb,
      'fields', '[]'::jsonb,
      'attachments', '[]'::jsonb
    );
  end if;
  select count(*)::integer, coalesce(sum(return_quantity),0)
  into v_item_count, v_quantity
  from public.smis_tool_return_item where return_id = v_return.id;
  return jsonb_build_object(
    'instanceId', v_instance.id,
    'businessType', v_instance.business_type,
    'businessId', v_instance.business_id,
    'title', v_instance.business_title,
    'subtitle', concat_ws(' · ', v_return.employee_name_snapshot, v_return.organization_name_snapshot),
    'businessNo', v_return.return_no,
    'status', v_return.status,
    'routePath', '/smis/safety-production/tool-requisition/tool-requisition-return',
    'metrics', jsonb_build_array(
      jsonb_build_object('label','归还明细','value',v_item_count::text || ' 项','tone','primary'),
      jsonb_build_object('label','归还数量','value',trim(trailing '.' from trim(trailing '0' from v_quantity::text)),'tone','success'),
      jsonb_build_object('label','归还日期','value',v_return.return_date::text,'tone','info')
    ),
    'fields', jsonb_build_array(
      jsonb_build_object('label','归还单号','value',v_return.return_no),
      jsonb_build_object('label','源发放单号','value',v_return.source_document_no),
      jsonb_build_object('label','领用人','value',v_return.employee_name_snapshot),
      jsonb_build_object('label','所属部门','value',coalesce(v_return.organization_name_snapshot,'--')),
      jsonb_build_object('label','备注','value',coalesce(v_return.remark,'--'))
    ),
    'warnings', '[]'::jsonb,
    'attachments', '[]'::jsonb
  );
end
$function$;

--
-- Name: get_waybill_cost_workflow_snapshot; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.get_waybill_cost_workflow_snapshot(p_instance_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_instance public.wf_instance%rowtype;
  v_cost record;
  v_access jsonb;
  v_amount_level text;
  v_payment_level text;
  v_evidence_level text;
  v_metrics jsonb := '[]'::jsonb;
  v_fields jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_attachments jsonb := '[]'::jsonb;
begin
  if auth.uid() is null or not app_private.can_view_workflow_instance(p_instance_id) then
    raise exception '无权查看该审批业务信息' using errcode = '42501';
  end if;
  select instance_row.* into v_instance
  from public.wf_instance instance_row
  where instance_row.id = p_instance_id;
  if not found then raise exception '审批实例不存在'; end if;

  select
    cost_row.*,
    waybill_row.waybill_no,
    item_row.item_name as expense_item_label
  into v_cost
  from public.tms_waybill_cost cost_row
  left join public.tms_waybill waybill_row
    on waybill_row.id = cost_row.waybill_id
   
  left join public.tms_expense_item item_row
    on item_row.id = cost_row.expense_item_id
   
  where cost_row.id = v_instance.business_id
    ;

  if not found then
    return jsonb_build_object(
      'instanceId', v_instance.id,
      'businessType', v_instance.business_type,
      'businessId', v_instance.business_id,
      'title', v_instance.business_title,
      'subtitle', null,
      'businessNo', null,
      'status', null,
      'routePath', '/tms-transportation/finance-center/waybill-cost',
      'metrics', '[]'::jsonb,
      'fields', '[]'::jsonb,
      'warnings', jsonb_build_array('业务原单已删除，当前仅展示流程基本信息'),
      'attachments', '[]'::jsonb
    );
  end if;

  v_access := app_private.field_access_map(
    'tms.waybill_cost', v_cost.created_by_user_id
  );
  v_amount_level := coalesce(v_access->>'costAmounts', 'hidden');
  v_payment_level := coalesce(v_access->>'paymentDetails', 'hidden');
  v_evidence_level := coalesce(v_access->>'expenseEvidence', 'hidden');

  if v_amount_level <> 'hidden' then
    v_metrics := v_metrics || jsonb_build_array(jsonb_build_object(
      'label', '费用金额',
      'value', case
        when v_amount_level = 'masked' then '***'
        else '¥ ' || to_char(coalesce(v_cost.amount, 0), 'FM999,999,990.00')
      end,
      'tone', 'warning'
    ));
    if v_amount_level = 'masked' then
      v_warnings := v_warnings || jsonb_build_array('费用金额已按字段权限脱敏');
    end if;
  end if;
  v_metrics := v_metrics || jsonb_build_array(jsonb_build_object(
    'label', '发生日期',
    'value', coalesce(v_cost.occurred_on::text, '--'),
    'tone', 'info'
  ));

  v_fields := jsonb_build_array(
    jsonb_build_object('label', '运单号', 'value', coalesce(v_cost.waybill_no, '--')),
    jsonb_build_object('label', '费用项目', 'value', coalesce(v_cost.expense_item_label, '--')),
    jsonb_build_object('label', '备注', 'value', coalesce(v_cost.remark, '--'))
  );
  if v_payment_level <> 'hidden' then
    v_fields := v_fields || jsonb_build_array(jsonb_build_object(
      'label', '收款方',
      'value', case
        when v_payment_level = 'masked' then '***'
        else coalesce(v_cost.payee_name, '--')
      end
    ));
  end if;
  if v_evidence_level in ('read', 'edit') then
    v_attachments := app_private.workflow_attachment_list(v_cost.attachments);
  elsif jsonb_array_length(coalesce(v_cost.attachments, '[]'::jsonb)) > 0 then
    v_warnings := v_warnings || jsonb_build_array('费用票据已按字段权限隐藏');
  end if;

  return jsonb_build_object(
    'instanceId', v_instance.id,
    'businessType', v_instance.business_type,
    'businessId', v_instance.business_id,
    'title', v_instance.business_title,
    'subtitle', concat_ws(' · ', v_cost.expense_item_label,
      case when v_payment_level in ('read', 'edit') then v_cost.payee_name else null end),
    'businessNo', coalesce(v_cost.cost_no, v_cost.waybill_no),
    'status', v_cost.audit_status,
    'routePath', '/tms-transportation/finance-center/waybill-cost',
    'metrics', v_metrics,
    'fields', v_fields,
    'warnings', v_warnings,
    'attachments', v_attachments
  );
end;
$function$;

--
-- Name: get_workflow_bottleneck_analytics; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.get_workflow_bottleneck_analytics(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_days integer := least(greatest(coalesce(p_days, 30), 7), 365);
  v_is_platform_super boolean := (select app_private.is_platform_super());
  v_result jsonb;
begin

  if (select auth.uid()) is null then
    raise exception '当前登录用户未绑定业务账号';
  end if;

  with task_base as (
    select
      task.id,
      instance.definition_id,
      definition.name as definition_name,
      instance.business_type,
      task.node_key,
      task.node_name,
      task.assignee_user_id,
      task.assignee_name_snapshot,
      task.assignment_source,
      task.status,
      task.create_time,
      task.handled_at,
      task.due_at,
      greatest(
        extract(epoch from (coalesce(task.handled_at, now()) - task.create_time)) / 3600.0,
        0
      ) as elapsed_hours,
      (
        task.due_at is not null
        and (
          (task.handled_at is not null and task.handled_at > task.due_at)
          or (task.status = 'pending' and now() > task.due_at)
        )
      ) as is_sla_breached
    from public.wf_task task
    join public.wf_instance instance on instance.id = task.instance_id
    join public.wf_definition definition on definition.id = instance.definition_id
    where true
      and task.create_time >= now() - make_interval(days => v_days)
  ), summary as (
    select
      count(*)::integer task_count,
      count(*) filter (where status = 'pending')::integer pending_count,
      count(*) filter (where status = 'pending' and is_sla_breached)::integer overdue_pending_count,
      count(*) filter (where handled_at is not null)::integer handled_count,
      count(*) filter (where due_at is not null)::integer sla_measured_count,
      count(*) filter (where is_sla_breached)::integer sla_breached_count,
      count(*) filter (where assignment_source = 'delegation')::integer delegated_count,
      count(*) filter (where assignment_source = 'transfer')::integer transferred_count,
      round(
        coalesce(avg(elapsed_hours) filter (where handled_at is not null), 0)::numeric,
        1
      ) as average_handle_hours,
      round(
        coalesce(
          percentile_cont(0.9) within group (order by elapsed_hours)
            filter (where handled_at is not null),
          0
        )::numeric,
        1
      ) as p90_handle_hours
    from task_base
  ), node_base as (
    select
      definition_id,
      definition_name,
      business_type,
      node_key,
      node_name,
      count(*)::integer task_count,
      count(*) filter (where status = 'pending')::integer pending_count,
      count(*) filter (where status = 'pending' and is_sla_breached)::integer overdue_pending_count,
      count(*) filter (where handled_at is not null)::integer handled_count,
      count(*) filter (where status = 'approved')::integer approved_count,
      count(*) filter (where status = 'rejected')::integer rejected_count,
      count(*) filter (where due_at is not null)::integer sla_measured_count,
      count(*) filter (where is_sla_breached)::integer sla_breached_count,
      round(
        coalesce(avg(elapsed_hours) filter (where handled_at is not null), 0)::numeric,
        1
      ) as average_handle_hours,
      round(
        coalesce(
          percentile_cont(0.9) within group (order by elapsed_hours)
            filter (where handled_at is not null),
          0
        )::numeric,
        1
      ) as p90_handle_hours
    from task_base
    group by
      business_type, node_key, node_name
  ), node_rows as (
    select
      node_base.*,
      case
        when sla_measured_count = 0 then 100::numeric
        else round(
          (sla_measured_count - sla_breached_count) * 100.0 / sla_measured_count,
          1
        )
      end as sla_compliance_rate
    from node_base
  ), node_stats as (
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'definitionId', definition_id,
          'definitionName', definition_name,
          'businessType', business_type,
          'nodeKey', node_key,
          'nodeName', node_name,
          'taskCount', task_count,
          'pendingCount', pending_count,
          'overduePendingCount', overdue_pending_count,
          'handledCount', handled_count,
          'approvedCount', approved_count,
          'rejectedCount', rejected_count,
          'slaMeasuredCount', sla_measured_count,
          'slaBreachedCount', sla_breached_count,
          'slaComplianceRate', sla_compliance_rate,
          'averageHandleHours', average_handle_hours,
          'p90HandleHours', p90_handle_hours,
          'riskLevel',
            case
              when overdue_pending_count > 0
                or (sla_measured_count >= 5 and sla_compliance_rate < 70) then 'critical'
              when pending_count >= 10
                or (sla_measured_count >= 5 and sla_compliance_rate < 90) then 'warning'
              else 'normal'
            end
        )
        order by
          overdue_pending_count desc,
          sla_breached_count desc,
          pending_count desc,
          p90_handle_hours desc,
          task_count desc,
          definition_name,
          node_name
      ),
      '[]'::jsonb
    ) as value
    from (
      select *
      from node_rows
      order by
        overdue_pending_count desc,
        sla_breached_count desc,
        pending_count desc,
        p90_handle_hours desc,
        task_count desc,
        definition_name,
        node_name
      limit 50
    ) ranked_nodes
  ), approver_base as (
    select
      assignee_user_id,
      max(assignee_name_snapshot) as assignee_name,
      count(*)::integer task_count,
      count(*) filter (where status = 'pending')::integer pending_count,
      count(*) filter (where status = 'pending' and is_sla_breached)::integer overdue_pending_count,
      count(*) filter (where handled_at is not null)::integer handled_count,
      count(*) filter (where status = 'approved')::integer approved_count,
      count(*) filter (where status = 'rejected')::integer rejected_count,
      count(*) filter (where due_at is not null)::integer sla_measured_count,
      count(*) filter (where is_sla_breached)::integer sla_breached_count,
      count(*) filter (where assignment_source = 'delegation')::integer delegated_count,
      count(*) filter (where assignment_source = 'transfer')::integer transferred_count,
      round(
        coalesce(avg(elapsed_hours) filter (where handled_at is not null), 0)::numeric,
        1
      ) as average_handle_hours,
      round(
        coalesce(
          percentile_cont(0.9) within group (order by elapsed_hours)
            filter (where handled_at is not null),
          0
        )::numeric,
        1
      ) as p90_handle_hours
    from task_base
    group by assignee_user_id
  ), approver_rows as (
    select
      approver_base.*,
      case
        when sla_measured_count = 0 then 100::numeric
        else round(
          (sla_measured_count - sla_breached_count) * 100.0 / sla_measured_count,
          1
        )
      end as sla_compliance_rate
    from approver_base
  ), approver_stats as (
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'assigneeUserId', assignee_user_id,
          'assigneeName', assignee_name,
          'taskCount', task_count,
          'pendingCount', pending_count,
          'overduePendingCount', overdue_pending_count,
          'handledCount', handled_count,
          'approvedCount', approved_count,
          'rejectedCount', rejected_count,
          'slaMeasuredCount', sla_measured_count,
          'slaBreachedCount', sla_breached_count,
          'slaComplianceRate', sla_compliance_rate,
          'delegatedCount', delegated_count,
          'transferredCount', transferred_count,
          'averageHandleHours', average_handle_hours,
          'p90HandleHours', p90_handle_hours,
          'riskLevel',
            case
              when overdue_pending_count > 0 then 'critical'
              when pending_count >= 10
                or (sla_measured_count >= 5 and sla_compliance_rate < 90) then 'warning'
              else 'normal'
            end
        )
        order by
          overdue_pending_count desc,
          pending_count desc,
          sla_breached_count desc,
          p90_handle_hours desc,
          task_count desc,
          assignee_name
      ),
      '[]'::jsonb
    ) as value
    from (
      select *
      from approver_rows
      order by
        overdue_pending_count desc,
        pending_count desc,
        sla_breached_count desc,
        p90_handle_hours desc,
        task_count desc,
        assignee_name
      limit 100
    ) ranked_approvers
  )
  select jsonb_build_object(
    'periodDays', v_days,
    'generatedAt', now(),
    'minimumSampleSize', 5,
    'summary', jsonb_build_object(
      'taskCount', summary.task_count,
      'pendingCount', summary.pending_count,
      'overduePendingCount', summary.overdue_pending_count,
      'handledCount', summary.handled_count,
      'slaMeasuredCount', summary.sla_measured_count,
      'slaBreachedCount', summary.sla_breached_count,
      'slaComplianceRate',
        case
          when summary.sla_measured_count = 0 then 100
          else round(
            (summary.sla_measured_count - summary.sla_breached_count)
              * 100.0 / summary.sla_measured_count,
            1
          )
        end,
      'delegatedCount', summary.delegated_count,
      'transferredCount', summary.transferred_count,
      'averageHandleHours', summary.average_handle_hours,
      'p90HandleHours', summary.p90_handle_hours
    ),
    'nodes', node_stats.value,
    'approvers', approver_stats.value
  )
  into v_result
  from summary cross join node_stats cross join approver_stats;

  return v_result;
end;
$function$;

--
-- Name: get_workflow_business_snapshot; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.get_workflow_business_snapshot(p_instance_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_i public.wf_instance;
  v_r record;
  v_result jsonb;
  v_metrics jsonb := '[]'::jsonb;
  v_fields jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_attachments jsonb := '[]'::jsonb;
  v_subtitle text;
  v_business_no text;
  v_status text;
  v_route text;
begin
  if (select auth.uid()) is null or not app_private.can_view_workflow_instance(p_instance_id) then
    raise exception '无权查看该审批业务信息' using errcode='42501';
  end if;
  select * into v_i from public.wf_instance where id=p_instance_id;
  if not found then raise exception '审批实例不存在'; end if;

  if v_i.business_type='tms_waybill_cost' then
    select c.*,w.waybill_no into v_r from public.tms_waybill_cost c
      left join public.tms_waybill w on w.id=c.waybill_id where c.id=v_i.business_id;
    if not found then v_warnings:=jsonb_build_array('业务原单已删除，当前仅展示流程快照'); else
      v_business_no:=v_r.waybill_no; v_status:=v_r.audit_status;
      v_subtitle:=concat_ws(' · ',v_r.cost_type,v_r.payee_name);
      v_metrics:=jsonb_build_array(
        jsonb_build_object('label','费用金额','value','¥ '||to_char(coalesce(v_r.amount,0),'FM999,999,990.00'),'tone','warning'),
        jsonb_build_object('label','发生日期','value',coalesce(v_r.occurred_on::text,'--'),'tone','info'));
      v_fields:=jsonb_build_array(
        jsonb_build_object('label','运单号','value',coalesce(v_r.waybill_no,'--')),
        jsonb_build_object('label','费用项目','value',coalesce(v_r.cost_type,'--')),
        jsonb_build_object('label','收款方','value',coalesce(v_r.payee_name,'--')),
        jsonb_build_object('label','备注','value',coalesce(v_r.remark,'--')));
      v_attachments:=app_private.workflow_attachment_list(v_r.attachments);
      v_route:='/tms-transportation/finance-center/waybill-cost';
    end if;

  elsif v_i.business_type='tms_invoice' then
    select * into v_r from public.tms_invoice where id=v_i.business_id;
    if not found then v_warnings:=jsonb_build_array('业务原单已删除，当前仅展示流程快照'); else
      v_business_no:=coalesce(v_r.invoice_no,v_r.invoice_record_no); v_status:=v_r.status;
      v_subtitle:=concat_ws(' · ',v_r.counterparty_name_snapshot,v_r.invoice_type);
      v_metrics:=jsonb_build_array(
        jsonb_build_object('label','含税金额','value','¥ '||to_char(coalesce(v_r.total_amount,0),'FM999,999,990.00'),'tone','warning'),
        jsonb_build_object('label','税额','value','¥ '||to_char(coalesce(v_r.tax_amount,0),'FM999,999,990.00'),'tone','info'),
        jsonb_build_object('label','税率','value',coalesce(v_r.tax_rate::text,'--')||'%','tone','info'));
      v_fields:=jsonb_build_array(
        jsonb_build_object('label','发票号码','value',coalesce(v_r.invoice_no,'--')),
        jsonb_build_object('label','开票方向','value',coalesce(v_r.direction,'--')),
        jsonb_build_object('label','发票抬头','value',coalesce(v_r.invoice_title,'--')),
        jsonb_build_object('label','开票日期','value',coalesce(v_r.issue_date::text,'--')));
      v_attachments:=app_private.workflow_attachment_list(v_r.attachments);
      v_route:='/tms-transportation/finance-center/invoice-management';
    end if;

  elsif v_i.business_type in ('tms_carrier_statement','tms_customer_statement') then
    if v_i.business_type='tms_carrier_statement' then
      select s.*, s.carrier_name_snapshot party_name,
        (select coalesce(sum(x.line_amount),0) from public.tms_carrier_statement_item x where x.statement_id=s.id and x.is_active) total_amount,
        (select count(*) from public.tms_carrier_statement_item x where x.statement_id=s.id and x.is_active) item_count
      into v_r from public.tms_carrier_statement s where s.id=v_i.business_id;
      v_route:='/tms-transportation/finance-center/carrier-settlement';
    else
      select s.*, s.customer_name_snapshot party_name,
        (select coalesce(sum(x.line_amount),0) from public.tms_customer_statement_item x where x.statement_id=s.id and x.is_active) total_amount,
        (select count(*) from public.tms_customer_statement_item x where x.statement_id=s.id and x.is_active) item_count
      into v_r from public.tms_customer_statement s where s.id=v_i.business_id;
      v_route:='/tms-transportation/finance-center/customer-settlement';
    end if;
    if not found then v_warnings:=jsonb_build_array('业务原单已删除，当前仅展示流程快照'); else
      v_business_no:=v_r.statement_no; v_status:=v_r.status;
      v_subtitle:=v_r.party_name;
      v_metrics:=jsonb_build_array(
        jsonb_build_object('label','对账金额','value','¥ '||to_char(coalesce(v_r.total_amount,0),'FM999,999,990.00'),'tone','warning'),
        jsonb_build_object('label','有效明细','value',v_r.item_count::text||' 条','tone','primary'),
        jsonb_build_object('label','已结算','value','¥ '||to_char(coalesce(v_r.settled_amount,0),'FM999,999,990.00'),'tone','success'));
      v_fields:=jsonb_build_array(
        jsonb_build_object('label','对账单号','value',coalesce(v_r.statement_no,'--')),
        jsonb_build_object('label','账期开始','value',coalesce(v_r.period_start::text,'--')),
        jsonb_build_object('label','账期结束','value',coalesce(v_r.period_end::text,'--')),
        jsonb_build_object('label','备注','value',coalesce(v_r.remark,'--')));
    end if;

  elsif v_i.business_type='tms_contract' then
    select * into v_r from public.tms_contract where id=v_i.business_id;
    if not found then v_warnings:=jsonb_build_array('业务原单已删除，当前仅展示流程快照'); else
      v_business_no:=v_r.contract_no; v_status:=v_r.contract_status; v_subtitle:=v_r.contract_name;
      v_metrics:=jsonb_build_array(
        jsonb_build_object('label','合同金额','value','¥ '||to_char(coalesce(v_r.contract_amount,0),'FM999,999,990.00'),'tone','warning'),
        jsonb_build_object('label','签订时间','value',coalesce(v_r.sign_time::date::text,'--'),'tone','info'));
      v_fields:=jsonb_build_array(
        jsonb_build_object('label','合同编号','value',coalesce(v_r.contract_no,'--')),
        jsonb_build_object('label','计费方式','value',coalesce(v_r.billing_method,'--')),
        jsonb_build_object('label','经办人','value',coalesce(v_r.handler,'--')),
        jsonb_build_object('label','联系人','value',coalesce(v_r.contact_name,'--')));
      v_attachments:=app_private.workflow_attachment_list(v_r.attachments);
      v_route:='/tms-transportation/basic-data/contract-detail/'||v_i.business_id::text;
    end if;

  elsif v_i.business_type='vehicle_archive' then
    select * into v_r from public.vehicle_archive where id=v_i.business_id;
    if not found then v_warnings:=jsonb_build_array('业务原单已删除，当前仅展示流程快照'); else
      v_business_no:=v_r.plate_no; v_status:=v_r.audit_status;
      v_subtitle:=concat_ws(' · ',v_r.company_name,v_r.brand_model);
      v_metrics:=jsonb_build_array(
        jsonb_build_object('label','核定载质量','value',coalesce(v_r.approved_load_mass::text,'--')||' kg','tone','primary'),
        jsonb_build_object('label','车辆类型','value',coalesce(v_r.vehicle_type,'--'),'tone','info'));
      v_fields:=jsonb_build_array(
        jsonb_build_object('label','车牌号','value',coalesce(v_r.plate_no,'--')),
        jsonb_build_object('label','VIN','value',coalesce(v_r.vin,'--')),
        jsonb_build_object('label','所属公司','value',coalesce(v_r.company_name,'--')),
        jsonb_build_object('label','营运类型','value',coalesce(v_r.operation_type,'--')));
      v_attachments:=app_private.workflow_attachment_list(v_r.attachments);
      v_route:='/vehicle-manage-system/archive-manage/vehicle-archive-detail/'||v_i.business_id::text;
    end if;
  else
    select coalesce(jsonb_agg(jsonb_build_object('label',key,'value',value::text)),'[]'::jsonb)
      into v_fields from jsonb_each(coalesce(v_i.context_snapshot,'{}'::jsonb));
  end if;

  if v_i.status='running' and not exists(
    select 1 from public.wf_task t where t.instance_id=v_i.id and t.status='pending'
  ) then
    v_warnings:=v_warnings||jsonb_build_array('流程运行中但当前没有待办任务，请联系审批管理员检查流程条件。');
  end if;

  v_result:=jsonb_build_object(
    'instanceId',v_i.id,'businessType',v_i.business_type,'businessId',v_i.business_id,
    'title',v_i.business_title,'subtitle',v_subtitle,'businessNo',v_business_no,
    'status',v_status,'routePath',v_route,'metrics',v_metrics,'fields',v_fields,
    'warnings',v_warnings,'attachments',v_attachments);
  return v_result;
end;
$function$;

--
-- Name: get_workflow_business_snapshot_v2; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.get_workflow_business_snapshot_v2(p_instance_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  business_type_value text;
begin
  select instance_row.business_type
  into business_type_value
  from public.wf_instance instance_row
  where instance_row.id = p_instance_id;

  if business_type_value = 'tms_expense_reimbursement' then
    return app_private.get_expense_reimbursement_workflow_snapshot(p_instance_id);
  end if;

  return app_private.get_workflow_business_snapshot_v2_before_reimbursement(p_instance_id);
end
$function$;

--
-- Name: get_workflow_business_snapshot_v2_before_reimbursement; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.get_workflow_business_snapshot_v2_before_reimbursement(p_instance_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_type text;
  v_business_id uuid;
  v_snapshot jsonb;
  v_ocr record;
  v_access jsonb;
  v_include_ocr boolean := true;
begin
  select instance_row.business_type, instance_row.business_id
  into v_type, v_business_id
  from public.wf_instance instance_row
  where instance_row.id = p_instance_id;

  if v_type = 'tms_carrier_payment_application' then
    v_snapshot := app_private.get_carrier_payment_application_workflow_snapshot(
      p_instance_id
    );
    select app_private.field_access_map(
      'tms.carrier_payment_application', application_row.created_by_user_id
    ) into v_access
    from public.tms_carrier_payment_application application_row
    where application_row.id = v_business_id;
    v_include_ocr := found
      and coalesce(v_access->>'applicationAmounts', 'hidden') in ('read', 'edit')
      and coalesce(v_access->>'basisEvidence', 'hidden') in ('read', 'edit');
  elsif v_type = 'tms_waybill_cost' then
    v_snapshot := app_private.get_waybill_cost_workflow_snapshot(p_instance_id);
    select app_private.field_access_map(
      'tms.waybill_cost', cost_row.created_by_user_id
    ) into v_access
    from public.tms_waybill_cost cost_row
    where cost_row.id = v_business_id;
    v_include_ocr := found
      and coalesce(v_access->>'costAmounts', 'hidden') in ('read', 'edit')
      and coalesce(v_access->>'paymentDetails', 'hidden') in ('read', 'edit')
      and coalesce(v_access->>'expenseLocation', 'hidden') in ('read', 'edit')
      and coalesce(v_access->>'expenseEvidence', 'hidden') in ('read', 'edit');
  elsif v_type = 'tms_contract' then
    v_snapshot := app_private.get_contract_workflow_snapshot(p_instance_id);
  else
    v_snapshot := app_private.get_workflow_business_snapshot(p_instance_id);
  end if;

  if v_include_ocr then
    select
      artifact_row.id,
      artifact_row.raw_ocr_text,
      artifact_row.create_time
    into v_ocr
    from public.ai_artifact_review artifact_row
    where artifact_row.entity_type = v_type
      and artifact_row.entity_id = v_business_id
      and artifact_row.status = 'applied'
    order by artifact_row.reviewed_at desc nulls last, artifact_row.create_time desc
    limit 1;
    if found then
      v_snapshot := v_snapshot || jsonb_build_object(
        'ocrEvidence', jsonb_build_object(
          'artifactId', v_ocr.id,
          'rawText', coalesce(v_ocr.raw_ocr_text, ''),
          'capturedAt', v_ocr.create_time
        )
      );
    end if;
  end if;
  return v_snapshot;
end;
$function$;

--
-- Name: get_workflow_business_snapshot_v3; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.get_workflow_business_snapshot_v3(p_instance_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  business_type_value text;
begin
  select instance_row.business_type
  into business_type_value
  from public.wf_instance instance_row
  where instance_row.id = p_instance_id;

  if business_type_value = 'smis_tool_return' then
    return app_private.get_tool_return_workflow_snapshot(p_instance_id);
  end if;
  if business_type_value in (
    'hr_personnel_change',
    'hr_lifecycle_case',
    'hr_self_service_request',
    'hr_recruitment_requisition'
  ) then
    return app_private.get_hr_workflow_business_snapshot(p_instance_id);
  end if;
  return app_private.get_workflow_business_snapshot_v2(p_instance_id);
end
$function$;

--
-- Name: get_workflow_callback_outbox; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.get_workflow_callback_outbox(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
  v_is_platform_super boolean := (select app_private.is_platform_super());
begin
  if (select auth.uid()) is null then
    raise exception '请先登录后查看审批回调' using errcode = '42501';
  end if;
  if p_status is not null
     and p_status not in ('pending', 'processing', 'retry_wait', 'succeeded', 'dead_letter') then
    raise exception '审批回调状态筛选值不合法';
  end if;

  select jsonb_build_object(
    'summary', (
      select jsonb_build_object(
        'pending', count(*) filter (where o.status = 'pending'),
        'processing', count(*) filter (where o.status = 'processing'),
        'retryWait', count(*) filter (where o.status = 'retry_wait'),
        'succeeded', count(*) filter (where o.status = 'succeeded'),
        'deadLetter', count(*) filter (where o.status = 'dead_letter')
      )
      from public.wf_business_callback_outbox o
    ),
    'items', coalesce((
      select jsonb_agg(to_jsonb(item) order by item."createTime" desc)
      from (
        select o.id,
               o.event_no as "eventNo",
               o.instance_id as "instanceId",
               i.business_title as "businessTitle",
               o.business_type as "businessType",
               o.business_id as "businessId",
               o.target_status as "targetStatus",
               o.status,
               o.attempt_count as "attemptCount",
               o.max_attempts as "maxAttempts",
               o.manual_retry_count as "manualRetryCount",
               o.next_attempt_at as "nextAttemptAt",
               o.processed_at as "processedAt",
               o.last_error_code as "lastErrorCode",
               o.last_error as "lastError",
               o.create_time as "createTime",
               coalesce((
                 select count(*) from public.wf_business_callback_attempt a
                 where a.outbox_id = o.id
               ), 0) as "totalAttempts"
        from public.wf_business_callback_outbox o
        join public.wf_instance i on i.id = o.instance_id
        where true
          and (p_status is null or o.status = p_status)
        order by o.create_time desc, o.id desc
        limit greatest(1, least(coalesce(p_limit, 50), 200))
      ) item
    ), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$function$;

--
-- Name: get_workflow_monitor_summary; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.get_workflow_monitor_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
  v_is_platform_super boolean := (select app_private.is_platform_super());
begin
  if (select auth.uid()) is null then
    raise exception '请先登录后查看审批监控' using errcode = '42501';
  end if;

  with scoped as (
    select
      i.status,
      i.started_at,
      i.finished_at,
      exists (
        select 1 from public.wf_task t
        where t.instance_id = i.id
          and t.status = 'pending'
          and t.due_at < now()
      ) as is_overdue
    from public.wf_instance i
  )
  select jsonb_build_object(
    'running_count', count(*) filter (where status = 'running'),
    'overdue_count', count(*) filter (where status = 'running' and is_overdue),
    'approved_30d_count', count(*) filter (
      where status = 'approved' and finished_at >= now() - interval '30 days'
    ),
    'rejected_30d_count', count(*) filter (
      where status = 'rejected' and finished_at >= now() - interval '30 days'
    ),
    'cancelled_30d_count', count(*) filter (
      where status = 'cancelled' and finished_at >= now() - interval '30 days'
    ),
    'average_duration_hours', coalesce(round((avg(
      extract(epoch from (finished_at - started_at)) / 3600
    ) filter (where finished_at is not null))::numeric, 1), 0)
  ) into v_result
  from scoped;

  return v_result;
end;
$function$;

--
-- Name: get_workflow_operational_analytics; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.get_workflow_operational_analytics(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_days integer := least(greatest(coalesce(p_days, 30), 7), 365);
  v_is_platform_super boolean := (select app_private.is_platform_super());
  v_result jsonb;
begin

  with base as (
    select
      instance.id,
      instance.business_type,
      instance.status,
      instance.started_at,
      instance.finished_at,
      exists (
        select 1
        from public.wf_task task
        where task.instance_id = instance.id
          and task.status = 'pending'
          and task.due_at < now()
      ) as is_overdue,
      case
        when instance.finished_at is not null
          then extract(epoch from (instance.finished_at - instance.started_at)) / 3600.0
        else null
      end as duration_hours
    from public.wf_instance instance
    where true
      and instance.started_at >= now() - make_interval(days => v_days)
  ), summary as (
    select
      count(*)::integer total_count,
      count(*) filter (where status = 'running')::integer running_count,
      count(*) filter (where status = 'approved')::integer approved_count,
      count(*) filter (where status = 'rejected')::integer rejected_count,
      count(*) filter (where status in ('withdrawn','cancelled'))::integer interrupted_count,
      count(*) filter (where is_overdue)::integer overdue_count,
      round(coalesce(avg(duration_hours) filter (where duration_hours is not null), 0)::numeric, 1)
        average_duration_hours
    from base
  ), business_rows as (
    select
      business_type,
      count(*)::integer total_count,
      count(*) filter (where status = 'running')::integer running_count,
      count(*) filter (where status = 'approved')::integer approved_count,
      count(*) filter (where status = 'rejected')::integer rejected_count,
      count(*) filter (where status in ('withdrawn','cancelled'))::integer interrupted_count,
      count(*) filter (where is_overdue)::integer overdue_count,
      round(coalesce(avg(duration_hours) filter (where duration_hours is not null), 0)::numeric, 1)
        average_duration_hours
    from base
    group by business_type
  ), business_stats as (
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'businessType', business_type,
          'totalCount', total_count,
          'runningCount', running_count,
          'approvedCount', approved_count,
          'rejectedCount', rejected_count,
          'interruptedCount', interrupted_count,
          'overdueCount', overdue_count,
          'averageDurationHours', average_duration_hours,
          'approvalRate',
            case when approved_count + rejected_count = 0 then 0
              else round(approved_count * 100.0 / (approved_count + rejected_count), 1) end
        )
        order by total_count desc, business_type
      ),
      '[]'::jsonb
    ) value
    from business_rows
  ), report_days as (
    select generate_series(
      current_date - (v_days - 1),
      current_date,
      interval '1 day'
    )::date as report_date
  ), daily_rows as (
    select
      report_days.report_date,
      count(base.id)::integer started_count,
      count(base.id) filter (where base.status = 'approved')::integer approved_count,
      count(base.id) filter (where base.status = 'rejected')::integer rejected_count
    from report_days
    left join base on base.started_at::date = report_days.report_date
    group by report_days.report_date
    order by report_days.report_date
  ), daily_stats as (
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'date', report_date,
          'startedCount', started_count,
          'approvedCount', approved_count,
          'rejectedCount', rejected_count
        )
        order by report_date
      ),
      '[]'::jsonb
    ) value
    from daily_rows
  )
  select jsonb_build_object(
    'periodDays', v_days,
    'generatedAt', now(),
    'summary', jsonb_build_object(
      'totalCount', summary.total_count,
      'runningCount', summary.running_count,
      'approvedCount', summary.approved_count,
      'rejectedCount', summary.rejected_count,
      'interruptedCount', summary.interrupted_count,
      'overdueCount', summary.overdue_count,
      'averageDurationHours', summary.average_duration_hours
    ),
    'businessTypes', business_stats.value,
    'daily', daily_stats.value
  )
  into v_result
  from summary cross join business_stats cross join daily_stats;

  return v_result;
end;
$function$;

--
-- Name: guard_scm_order_line_sources; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.guard_scm_order_line_sources()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_reference record;
  v_source public.scm_sales_document%rowtype;
  v_source_line jsonb;
  v_quantity numeric;
  v_allocated numeric;
begin
  if new.kind<>'sales_order' or (tg_op='UPDATE' and new.lines is not distinct from old.lines) then return new; end if;
  for v_reference in
    select distinct line->>'source_document_id' as document_id, line->>'source_line_id' as line_id
    from jsonb_array_elements(new.lines) line
    where nullif(line->>'source_document_id','') is not null
  loop
    if v_reference.document_id !~ '^[0-9a-fA-F-]{36}$' or nullif(v_reference.line_id,'') is null then
      raise exception '订单来源明细缺少有效的源单或源行号' using errcode='23514';
    end if;
    select * into v_source from public.scm_sales_document
      where id=v_reference.document_id::uuid for update;
    if v_source.id is null
      or v_source.kind not in ('sales_quotation','sales_contract')
      or v_source.status<>'effective'
      or v_source.project_id is distinct from new.project_id
      or v_source.customer_id is distinct from new.customer_id then
      raise exception '订单来源单据的状态、项目或客户不符' using errcode='23514';
    end if;
    select value into v_source_line from jsonb_array_elements(v_source.lines)
      where value->>'line_id'=v_reference.line_id;
    if v_source_line is null then raise exception '订单来源物料行不存在' using errcode='23514'; end if;
    select coalesce(sum((line->>'quantity')::numeric),0) into v_quantity
      from jsonb_array_elements(new.lines) line
      where line->>'source_document_id'=v_reference.document_id
        and line->>'source_line_id'=v_reference.line_id;
    select coalesce(sum((line.value->>'quantity')::numeric),0) into v_allocated
      from public.scm_sales_document other
      cross join lateral jsonb_array_elements(other.lines) line
      where other.kind='sales_order'  and other.id<>new.id
        and other.status not in ('cancelled','closed','terminated')
        and line.value->>'source_document_id'=v_reference.document_id
        and line.value->>'source_line_id'=v_reference.line_id;
    if v_quantity+v_allocated>(v_source_line->>'quantity')::numeric then
      raise exception '订单数量超过来源明细剩余数量' using errcode='23514';
    end if;
  end loop;
  return new;
end
$function$;

--
-- Name: guard_scm_sales_document_delete; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.guard_scm_sales_document_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF OLD.status NOT IN ('draft','created') THEN
    RAISE EXCEPTION '只能删除草稿单据' USING ERRCODE='23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.scm_sales_document x WHERE x.source_id=OLD.id) THEN
    RAISE EXCEPTION '单据已被下游引用，无法删除' USING ERRCODE='23514';
  END IF;
  RETURN OLD;
END
$function$;

--
-- Name: guard_scm_sales_document_fulfillment; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.guard_scm_sales_document_fulfillment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_source public.scm_sales_document%ROWTYPE; v_line jsonb; v_source_line jsonb; v_source_line_id text; v_quantity numeric; v_allocated numeric; v_original numeric;
BEGIN
 IF NEW.source_id IS NOT NULL THEN
   SELECT * INTO v_source FROM public.scm_sales_document WHERE id=NEW.source_id FOR UPDATE;
   IF NEW.kind IN ('project_quotation','sales_contract','sales_order') AND v_source.status<>'effective' THEN
     RAISE EXCEPTION '来源单据须先生效' USING ERRCODE='23514';
   END IF;
   IF NEW.kind IN ('shipping_notice','loading') THEN
     FOR v_line IN SELECT value FROM jsonb_array_elements(NEW.lines) LOOP
       v_source_line_id := nullif(v_line->>'source_line_id','');
       IF v_source_line_id IS NULL THEN RAISE EXCEPTION '发货明细必须关联来源物料行' USING ERRCODE='23514'; END IF;
       SELECT value INTO v_source_line FROM jsonb_array_elements(v_source.lines) WHERE value->>'line_id'=v_source_line_id;
       IF v_source_line IS NULL THEN RAISE EXCEPTION '来源物料行不存在' USING ERRCODE='23514'; END IF;
       v_quantity := (v_line->>'quantity')::numeric;
       v_original := (v_source_line->>'quantity')::numeric;
       SELECT coalesce(sum((other_line.value->>'quantity')::numeric),0) INTO v_allocated
       FROM public.scm_sales_document child
       CROSS JOIN LATERAL jsonb_array_elements(child.lines) other_line
       WHERE child.source_id=NEW.source_id AND child.kind=NEW.kind AND child.id<>NEW.id
         AND child.status NOT IN ('cancelled','closed','terminated')
         AND other_line.value->>'source_line_id'=v_source_line_id;
       IF v_quantity+v_allocated>v_original THEN
         RAISE EXCEPTION '发货数量超过来源单据剩余数量' USING ERRCODE='23514';
       END IF;
     END LOOP;
   END IF;
 END IF;
 IF TG_OP='UPDATE' AND NEW.lines IS DISTINCT FROM OLD.lines
   AND EXISTS (SELECT 1 FROM public.scm_sales_document child WHERE child.source_id=NEW.id)
 THEN RAISE EXCEPTION '单据已被下游引用，不可修改物料明细' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$;

--
-- Name: guard_tms_address_geofence_write; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.guard_tms_address_geofence_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_geofence_changed boolean;
begin
  v_geofence_changed := case
    when tg_op = 'INSERT' then
      coalesce(new.geofence_enabled, false)
      or new.geofence_radius_m is not null
      or new.geofence_updated_at is not null
    else
      new.geofence_enabled is distinct from old.geofence_enabled
      or new.geofence_radius_m is distinct from old.geofence_radius_m
      or new.geofence_updated_at is distinct from old.geofence_updated_at
  end;

  if v_geofence_changed
     and not app_private.has_permission('TmsCustomerAddress:Geofence') then
    raise exception using errcode = '42501', message = '当前角色未获维护地址围栏权限';
  end if;


  return new;
end;
$function$;

--
-- Name: has_fms_operation_permission; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.has_fms_operation_permission(p_rpc_name text, p_action text DEFAULT NULL::text, p_is_new boolean DEFAULT NULL::boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_permission text;
begin
  case p_rpc_name
    when 'act_fms_asset_depreciation_run' then
      v_permission := 'FinanceFixedAsset:Depreciation';
    when 'act_fms_commercial_bill' then
      v_permission := case lower(p_action)
        when 'receive' then 'FinanceCommercialBill:Receive'
        when 'issue' then 'FinanceCommercialBill:Issue'
        when 'endorse' then 'FinanceCommercialBill:Endorse'
        when 'discount' then 'FinanceCommercialBill:Discount'
        when 'settle' then 'FinanceCommercialBill:Settle'
        when 'cancel' then 'FinanceCommercialBill:Cancel'
      end;
    when 'act_fms_fixed_asset' then
      v_permission := case lower(p_action)
        when 'activate' then 'FinanceFixedAsset:Activate'
        when 'suspend' then 'FinanceFixedAsset:Suspend'
        when 'resume' then 'FinanceFixedAsset:Resume'
        when 'dispose' then 'FinanceFixedAsset:Dispose'
      end;
    when 'act_fms_payroll_run' then
      v_permission := case lower(p_action)
        when 'approve' then 'FinancePayroll:Approve'
        when 'pay' then 'FinancePayroll:Pay'
        when 'cancel' then 'FinancePayroll:Cancel'
      end;
    when 'act_fms_period_close_run' then
      v_permission := case lower(p_action)
        when 'close' then 'FinancePeriodClose:Close'
        when 'cancel' then 'FinancePeriodClose:Cancel'
        when 'reopen' then 'FinancePeriodClose:Reopen'
      end;
    when 'act_fms_tax_period' then
      v_permission := case lower(p_action)
        when 'review' then 'FinanceTaxManagement:Review'
        when 'file' then 'FinanceTaxManagement:File'
        when 'pay' then 'FinanceTaxManagement:Pay'
        when 'cancel' then 'FinanceTaxManagement:Cancel'
      end;
    when 'auto_match_fms_bank_reconciliation' then
      v_permission := 'FinanceBankReconciliation:AutoMatch';
    when 'calculate_fms_asset_depreciation' then
      v_permission := 'FinanceFixedAsset:Depreciation';
    when 'delete_fms_asset_category' then
      v_permission := 'FinanceFixedAsset:ManageCategory';
    when 'delete_fms_auxiliary_type' then
      v_permission := 'FinanceAccountingAuxiliary:DeleteType';
    when 'delete_fms_commercial_bill' then
      v_permission := 'FinanceCommercialBill:Delete';
    when 'delete_fms_fixed_asset' then
      v_permission := 'FinanceFixedAsset:Delete';
    when 'delete_fms_fund_account' then
      v_permission := 'FinanceFundAccount:Delete';
    when 'delete_fms_fund_transfer' then
      v_permission := 'FinanceFundTransfer:Delete';
    when 'delete_fms_payroll_line' then
      v_permission := 'FinancePayroll:Edit';
    when 'delete_fms_posting_rule' then
      v_permission := 'FinanceAutoPosting:Delete';
    when 'delete_fms_tax_ledger_line' then
      v_permission := 'FinanceTaxManagement:Edit';
    when 'delete_fms_voucher_template' then
      v_permission := 'FinanceVoucherTemplate:Delete';
    when 'generate_fms_profit_loss_carryforward' then
      v_permission := 'FinancePeriodClose:Carryforward';
    when 'ignore_fms_bank_statement_line' then
      v_permission := 'FinanceBankReconciliation:Ignore';
    when 'import_fms_bank_reconciliation' then
      v_permission := 'FinanceBankReconciliation:Add';
    when 'initialize_fms_accounting_defaults' then
      v_permission := 'FinanceAccountingSubject:Initialize';
    when 'initialize_fms_financial_statement_items_base' then
      v_permission := 'FinanceFinancialReports:EditConfig';
    when 'match_fms_bank_statement_line' then
      v_permission := 'FinanceBankReconciliation:Match';
    when 'process_pending_fms_posting_events' then
      v_permission := 'FinanceAutoPosting:ProcessPending';
    when 'retry_fms_posting_event' then
      v_permission := 'FinanceAutoPosting:Retry';
    when 'run_fms_period_close_checks' then
      return app_private.has_permission('FinancePeriodClose:Add')
        or app_private.has_permission('FinancePeriodClose:Recheck');
    when 'save_fms_account_set' then
      v_permission := case when p_is_new
        then 'FinanceAccountSet:Add' else 'FinanceAccountSet:Edit' end;
    when 'save_fms_asset_category' then
      v_permission := 'FinanceFixedAsset:ManageCategory';
    when 'save_fms_cash_flow_allocations' then
      v_permission := 'FinanceVoucherCenter:Edit';
    when 'save_fms_commercial_bill' then
      v_permission := case when p_is_new
        then 'FinanceCommercialBill:Add' else 'FinanceCommercialBill:Edit' end;
    when 'save_fms_financial_statement_formulas' then
      v_permission := 'FinanceFinancialReports:EditConfig';
    when 'save_fms_financial_statement_item' then
      v_permission := 'FinanceFinancialReports:EditConfig';
    when 'save_fms_financial_statement_mappings' then
      v_permission := 'FinanceFinancialReports:EditConfig';
    when 'save_fms_fixed_asset' then
      v_permission := case when p_is_new
        then 'FinanceFixedAsset:Add' else 'FinanceFixedAsset:Edit' end;
    when 'save_fms_fund_account' then
      v_permission := case when p_is_new
        then 'FinanceFundAccount:Add' else 'FinanceFundAccount:Edit' end;
    when 'save_fms_fund_transfer' then
      v_permission := case when p_is_new
        then 'FinanceFundTransfer:Add' else 'FinanceFundTransfer:Edit' end;
    when 'save_fms_opening_balance' then
      v_permission := case when p_is_new
        then 'FinanceOpeningBalance:Add' else 'FinanceOpeningBalance:Edit' end;
    when 'save_fms_payroll_line' then
      return app_private.has_permission('FinancePayroll:Edit')
        or app_private.has_permission('FinancePayroll:Calculate');
    when 'save_fms_payroll_run' then
      v_permission := case when p_is_new
        then 'FinancePayroll:Add' else 'FinancePayroll:Edit' end;
    when 'save_fms_posting_rule' then
      v_permission := case when p_is_new
        then 'FinanceAutoPosting:Add' else 'FinanceAutoPosting:Edit' end;
    when 'save_fms_subject' then
      v_permission := case when p_is_new
        then 'FinanceAccountingSubject:Add' else 'FinanceAccountingSubject:Edit' end;
    when 'save_fms_tax_ledger_line' then
      return app_private.has_permission('FinanceTaxManagement:Edit')
        or app_private.has_permission('FinanceTaxManagement:Calculate');
    when 'save_fms_tax_period' then
      v_permission := case when p_is_new
        then 'FinanceTaxManagement:Add' else 'FinanceTaxManagement:Edit' end;
    when 'save_fms_voucher' then
      v_permission := case when p_is_new
        then 'FinanceVoucherCenter:Add' else 'FinanceVoucherCenter:Edit' end;
    when 'save_fms_voucher_template' then
      v_permission := case when p_is_new
        then 'FinanceVoucherTemplate:Add' else 'FinanceVoucherTemplate:Edit' end;
    when 'set_fms_account_set_status' then
      v_permission := case lower(p_action)
        when 'active' then 'FinanceAccountSet:Active'
        when 'suspended' then 'FinanceAccountSet:Suspended'
        when 'archived' then 'FinanceAccountSet:Archived'
      end;
    when 'set_fms_accounting_period_status' then
      v_permission := 'FinanceAccountSet:ManagePeriod';
    when 'set_fms_opening_balance_status' then
      v_permission := case lower(p_action)
        when 'confirmed' then 'FinanceOpeningBalance:Confirm'
        when 'draft' then 'FinanceOpeningBalance:Reopen'
      end;
    when 'sync_fms_auxiliary_items' then
      v_permission := 'FinanceAccountingAuxiliary:Sync';
    when 'transition_fms_bank_reconciliation' then
      v_permission := case lower(p_action)
        when 'complete' then 'FinanceBankReconciliation:Complete'
        when 'void' then 'FinanceBankReconciliation:Void'
      end;
    when 'transition_fms_fund_transfer' then
      v_permission := case lower(p_action)
        when 'submit' then 'FinanceFundTransfer:Submit'
        when 'approve' then 'FinanceFundTransfer:Approve'
        when 'reject' then 'FinanceFundTransfer:Reject'
        when 'execute' then 'FinanceFundTransfer:Execute'
        when 'reverse' then 'FinanceFundTransfer:Reverse'
      end;
    when 'transition_fms_voucher' then
      v_permission := case lower(p_action)
        when 'submit' then 'FinanceVoucherCenter:Submit'
        when 'approve' then 'FinanceVoucherCenter:Approve'
        when 'reject' then 'FinanceVoucherCenter:Reject'
        when 'post' then 'FinanceVoucherCenter:Post'
        when 'void' then 'FinanceVoucherCenter:Void'
        when 'reverse' then 'FinanceVoucherCenter:Reverse'
      end;
    when 'unmatch_fms_bank_statement_line' then
      v_permission := 'FinanceBankReconciliation:Unmatch';
    else
      return false;
  end case;

  return v_permission is not null and app_private.has_permission(v_permission);
end;
$function$;

--
-- Name: has_permission; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.has_permission(p_permission text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'app_private'
AS $function$ select app_private.is_platform_super() or exists ( select 1 from public.sys_user current_user_row join public.sys_role role_row on role_row.enabled is true and role_row.role_code = any(coalesce(current_user_row.user_roles, array[]::text[])) join public.sys_role_menu role_menu on role_menu.role_id = role_row.id join public.sys_menu menu_row on menu_row.id = role_menu.menu_id and menu_row.type = 'button' where current_user_row.auth_user_id = auth.uid() and current_user_row.status = '1' and current_user_row.deleted_at is null and menu_row.name = p_permission and (menu_row.meta->>'is_enable') is distinct from 'false' ); $function$;

--
-- Name: hr_add_benefit_event; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.hr_add_benefit_event(p_entity_type text, p_entity_id uuid, p_event_type text, p_from_status text, p_to_status text, p_summary text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into public.hr_benefit_event( entity_type, entity_id, event_type, from_status, to_status,
    summary, payload, actor_user_id, actor_name
  ) values ( p_entity_type, p_entity_id, p_event_type,
    p_from_status, p_to_status, p_summary, coalesce(p_payload, '{}'::jsonb),
    (select app_user.id from public.sys_user app_user
      where app_user.auth_user_id = auth.uid()
        
        and app_user.deleted_at is null
      limit 1),
    coalesce(auth.jwt() ->> 'email', auth.uid()::text)
  );
end
$function$;

