--
-- Name: hr_find_leave_policy; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.hr_find_leave_policy(p_employee_id uuid, p_leave_type_id uuid, p_effective_date date)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select policy_row.id
  from public.hr_leave_policy policy_row
  join public.hr_employee employee_row
    on employee_row.id = p_employee_id 
  left join lateral (
    select assignment_row.grade_id
    from public.hr_employee_assignment assignment_row
    where assignment_row.employee_id = employee_row.id
      
      and assignment_row.assignment_status = 'active'
      and assignment_row.effective_start <= p_effective_date
      and coalesce(assignment_row.effective_end, 'infinity'::date) >= p_effective_date
    order by assignment_row.primary_assignment desc, assignment_row.effective_start desc
    limit 1
  ) assignment_row on true
  where true
    and policy_row.leave_type_id = p_leave_type_id
    and policy_row.status = 'active'
    and policy_row.effective_from <= p_effective_date
    and coalesce(policy_row.effective_to, 'infinity'::date) >= p_effective_date
    and (
      policy_row.scope_type = 'all'
      or (policy_row.scope_type = 'organization' and policy_row.organization_id = employee_row.organization_id)
      or (policy_row.scope_type = 'employee' and policy_row.employee_id = employee_row.id)
      or (policy_row.scope_type = 'grade' and policy_row.grade_id = assignment_row.grade_id)
    )
  order by case policy_row.scope_type
    when 'employee' then 40 when 'organization' then 30 when 'grade' then 20 else 10 end desc,
    policy_row.effective_from desc
  limit 1;
$function$;

--
-- Name: hr_get_employee_relation_case_detail_internal; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.hr_get_employee_relation_case_detail_internal(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_case public.hr_employee_relation_case;
  v_result jsonb;
  v_sensitive boolean := app_private.is_platform_super()
    or app_private.has_permission('Hr:EmployeeRelations:Sensitive:View');
begin
  if not app_private.can_execute_business_action(
    'HrEmployeeRelations', 'Hr:EmployeeRelations:View', p_id, false
  ) then
    raise exception '当前账号没有查看员工关系案件的权限' using errcode = '42501';
  end if;
  select * into v_case from public.hr_employee_relation_case where id = p_id;
  if v_case.id is null or not app_private.hr_employee_relation_case_visible(v_case.subject_employee_id, v_case.reporter_employee_id,
    v_case.owner_employee_id
  ) then
    raise exception '员工关系案件不存在或无权查看' using errcode = '42501';
  end if;

  select (to_jsonb(v_case)
      - case when v_sensitive then '__none__' else 'allegation_summary' end
      - case when v_sensitive then '__none__' else 'findings_summary' end
      - case when v_sensitive then '__none__' else 'resolution_summary' end
      - case when v_sensitive then '__none__' else 'attachment_urls' end
      - case when v_sensitive then '__none__' else 'reporter_employee_id' end)
    || jsonb_build_object(
      'title', case when v_sensitive then v_case.title else '受限员工关系案件' end,
      'sensitive_restricted', not v_sensitive,
      'subject_employee', jsonb_build_object(
        'id', subject.id, 'employee_no', subject.employee_no,
        'employee_name', subject.employee_name, 'job_title', subject.job_title,
        'organization_name', organization.organization_name,
        'position_name', position.position_name
      ),
      'owner_employee', case when owner.id is null then null else jsonb_build_object(
        'id', owner.id, 'employee_no', owner.employee_no,
        'employee_name', owner.employee_name, 'job_title', owner.job_title
      ) end,
      'reporter_employee', case when not v_sensitive or v_case.anonymous_report
          or reporter.id is null then null else jsonb_build_object(
        'id', reporter.id, 'employee_no', reporter.employee_no,
        'employee_name', reporter.employee_name, 'job_title', reporter.job_title
      ) end,
      'actions', coalesce((
        select jsonb_agg(
          (to_jsonb(action)
            - case when v_sensitive then '__none__' else 'title' end
            - case when v_sensitive then '__none__' else 'completion_note' end
            - case when v_sensitive then '__none__' else 'remark' end)
          || jsonb_build_object(
            'title', case when v_sensitive then action.title else '受限处置行动' end,
            'owner_employee', jsonb_build_object(
              'id', action_owner.id, 'employee_no', action_owner.employee_no,
              'employee_name', action_owner.employee_name, 'job_title', action_owner.job_title
            )
          ) order by action.due_date, action.create_time
        )
        from public.hr_employee_relation_action action
        join public.hr_employee action_owner
          on action_owner.id = action.owner_employee_id
          
        where action.case_id = v_case.id 
      ), '[]'::jsonb),
      'events', coalesce((
        select jsonb_agg(
          (to_jsonb(event) - case when v_sensitive then '__none__' else 'comment' end)
          || jsonb_build_object(
            'actor', case when actor.id is null then null else jsonb_build_object(
              'id', actor.id, 'employee_no', actor.employee_no,
              'employee_name', actor.employee_name, 'job_title', actor.job_title
            ) end
          ) order by event.create_time desc
        )
        from public.hr_employee_relation_event event
        left join public.hr_employee actor
          on actor.id = event.actor_employee_id 
        where event.case_id = v_case.id 
      ), '[]'::jsonb)
    ) into v_result
  from public.hr_employee subject
  left join public.sys_organization organization on organization.id = subject.organization_id
  left join public.hr_position position on position.id = subject.position_id
  left join public.hr_employee owner
    on owner.id = v_case.owner_employee_id 
  left join public.hr_employee reporter
    on reporter.id = v_case.reporter_employee_id 
  where subject.id = v_case.subject_employee_id ;
  return v_result;
end
$function$;

--
-- Name: hr_guard_approval_record; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.hr_guard_approval_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if coalesce(current_setting('app.workflow_engine', true), '') = 'on' then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if old.status not in ('draft', 'rejected') then
      raise exception '当前状态的人事单据不可编辑';
    end if;
    if new.status is distinct from old.status then
      raise exception '人事单据状态只能通过审批流程变更';
    end if;
  elsif tg_op = 'DELETE' and old.status not in ('draft', 'rejected', 'cancelled') then
    raise exception '仅草稿、已驳回或已取消单据允许删除';
  end if;
  return coalesce(new, old);
end;
$function$;

--
-- Name: hr_list_employee_relations_records_internal; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.hr_list_employee_relations_records_internal(p_kind text, p_from integer DEFAULT 0, p_to integer DEFAULT 19, p_keyword text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_case_type text DEFAULT NULL::text, p_severity text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_sensitive boolean := app_private.is_platform_super()
    or app_private.has_permission('Hr:EmployeeRelations:Sensitive:View');
  v_offset integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(500,
    greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1));
  v_keyword text := nullif(btrim(p_keyword), '');
  v_result jsonb;
begin
  if p_kind not in ('case', 'action') then
    raise exception '不支持的员工关系记录类型';
  end if;
  if not app_private.can_execute_business_action(
    'HrEmployeeRelations', 'Hr:EmployeeRelations:View', null, false
  ) then
    raise exception '当前账号没有查看员工关系案件的权限' using errcode = '42501';
  end if;

  if p_kind = 'case' then
    with filtered as materialized (
      select relation_case.*,
        case when v_sensitive then relation_case.title else '受限员工关系案件' end as safe_title,
        jsonb_build_object(
          'id', subject.id, 'employee_no', subject.employee_no,
          'employee_name', subject.employee_name, 'job_title', subject.job_title,
          'organization_name', organization.organization_name,
          'position_name', position.position_name
        ) as subject_employee,
        case when owner.id is null then null else jsonb_build_object(
          'id', owner.id, 'employee_no', owner.employee_no,
          'employee_name', owner.employee_name, 'job_title', owner.job_title
        ) end as owner_employee,
        case when not v_sensitive or relation_case.anonymous_report or reporter.id is null then null
          else jsonb_build_object(
            'id', reporter.id, 'employee_no', reporter.employee_no,
            'employee_name', reporter.employee_name, 'job_title', reporter.job_title
          ) end as reporter_employee,
        (select count(*) from public.hr_employee_relation_action action
          where action.case_id = relation_case.id 
            and action.status in ('planned', 'in_progress')) as open_action_count,
        case
          when relation_case.status not in ('triaged', 'investigating', 'action_required')
            or relation_case.target_resolution_date is null then 'clear'
          when relation_case.target_resolution_date < current_date then 'overdue'
          when relation_case.target_resolution_date <= current_date + 7 then 'due_soon'
          else 'on_track'
        end as due_status
      from public.hr_employee_relation_case relation_case
      join public.hr_employee subject
        on subject.id = relation_case.subject_employee_id
        
      left join public.sys_organization organization on organization.id = subject.organization_id
      left join public.hr_position position on position.id = subject.position_id
      left join public.hr_employee owner
        on owner.id = relation_case.owner_employee_id 
      left join public.hr_employee reporter
        on reporter.id = relation_case.reporter_employee_id
        
      where true
        and app_private.hr_employee_relation_case_visible(relation_case.subject_employee_id,
          relation_case.reporter_employee_id, relation_case.owner_employee_id
        )
        and (p_status is null or relation_case.status = p_status)
        and (p_case_type is null or relation_case.case_type = p_case_type)
        and (p_severity is null or relation_case.severity = p_severity)
        and (
          v_keyword is null
          or relation_case.case_no ilike '%' || v_keyword || '%'
          or (v_sensitive and relation_case.title ilike '%' || v_keyword || '%')
          or subject.employee_no ilike '%' || v_keyword || '%'
          or subject.employee_name ilike '%' || v_keyword || '%'
          or owner.employee_name ilike '%' || v_keyword || '%'
        )
    ), paged as (
      select * from filtered
      order by
        case due_status when 'overdue' then 0 when 'due_soon' then 1 else 2 end,
        case severity when 'critical' then 0 when 'high' then 1 when 'medium' then 2 else 3 end,
        update_time desc
      offset v_offset limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce(jsonb_agg(
        (to_jsonb(paged)
          - 'title' - 'allegation_summary' - 'findings_summary' - 'resolution_summary'
          - 'attachment_urls' - 'reporter_employee_id')
        || jsonb_build_object('title', paged.safe_title)
        order by
          case paged.due_status when 'overdue' then 0 when 'due_soon' then 1 else 2 end,
          case paged.severity when 'critical' then 0 when 'high' then 1
            when 'medium' then 2 else 3 end,
          paged.update_time desc
      ), '[]'::jsonb),
      'total', (select count(*) from filtered)
    ) into v_result from paged;
    return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
  end if;

  with filtered as materialized (
    select action.*,
      case when v_sensitive then action.title else '受限处置行动' end as safe_title,
      jsonb_build_object(
        'id', relation_case.id, 'case_no', relation_case.case_no,
        'title', case when v_sensitive then relation_case.title else '受限员工关系案件' end,
        'case_type', relation_case.case_type, 'status', relation_case.status,
        'severity', relation_case.severity
      ) as relation_case,
      jsonb_build_object(
        'id', owner.id, 'employee_no', owner.employee_no,
        'employee_name', owner.employee_name, 'job_title', owner.job_title
      ) as owner_employee,
      case
        when action.status not in ('planned', 'in_progress') then 'clear'
        when action.due_date < current_date then 'overdue'
        when action.due_date <= current_date + 7 then 'due_soon'
        else 'on_track'
      end as due_status
    from public.hr_employee_relation_action action
    join public.hr_employee_relation_case relation_case
      on relation_case.id = action.case_id 
    join public.hr_employee owner
      on owner.id = action.owner_employee_id 
    where true
      and app_private.hr_employee_relation_case_visible(relation_case.subject_employee_id,
        relation_case.reporter_employee_id, relation_case.owner_employee_id
      )
      and (p_status is null or action.status = p_status)
      and (p_case_type is null or relation_case.case_type = p_case_type)
      and (p_severity is null or relation_case.severity = p_severity)
      and (
        v_keyword is null
        or relation_case.case_no ilike '%' || v_keyword || '%'
        or (v_sensitive and action.title ilike '%' || v_keyword || '%')
        or owner.employee_no ilike '%' || v_keyword || '%'
        or owner.employee_name ilike '%' || v_keyword || '%'
      )
  ), paged as (
    select * from filtered
    order by case due_status when 'overdue' then 0 when 'due_soon' then 1 else 2 end,
      due_date, update_time desc
    offset v_offset limit v_limit
  )
  select jsonb_build_object(
    'records', coalesce(jsonb_agg(
      (to_jsonb(paged) - 'title' - 'completion_note' - 'remark')
        || jsonb_build_object('title', paged.safe_title)
      order by case paged.due_status when 'overdue' then 0
        when 'due_soon' then 1 else 2 end, paged.due_date, paged.update_time desc
    ), '[]'::jsonb),
    'total', (select count(*) from filtered)
  ) into v_result from paged;
  return coalesce(v_result, jsonb_build_object('records', '[]'::jsonb, 'total', 0));
end
$function$;

--
-- Name: hr_mask_external_email; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.hr_mask_external_email(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case
    when nullif(btrim(p_value), '') is null then null
    when strpos(btrim(p_value), '@') > 1
      then left(btrim(p_value), 1) || '***' || substring(btrim(p_value) from strpos(btrim(p_value), '@'))
    else '***'
  end;
$function$;

--
-- Name: hr_mask_external_phone; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.hr_mask_external_phone(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case
    when nullif(btrim(p_value), '') is null then null
    when length(btrim(p_value)) >= 7
      then left(btrim(p_value), 3) || '****' || right(btrim(p_value), 4)
    else '***'
  end;
$function$;

--
-- Name: hr_service_case_visible; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.hr_service_case_visible(p_employee_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select app_private.is_platform_super()
    or (
      (
        app_private.has_permission('Hr:SelfService:Manage')
        or p_employee_id = app_private.hr_current_employee_id()
      )
    )
$function$;

--
-- Name: hr_validate_compensation_review_budget; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.hr_validate_compensation_review_budget(p_cycle_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_overrun record;
begin
  select
    coalesce(organization.organization_name, '未分配组织') as organization_name,
    coalesce(budget.budget_amount, 0) as budget_amount,
    coalesce(sum(greatest(item.proposed_base_amount - item.current_base_amount, 0)), 0) as used_amount
  into v_overrun
  from public.hr_compensation_review_item item
  left join public.sys_organization organization
    on organization.id = item.organization_id
   
  left join public.hr_compensation_review_budget budget
    on budget.cycle_id = item.cycle_id
   
   and budget.organization_id is not distinct from item.organization_id
  where item.cycle_id = p_cycle_id
    and item.status <> 'excluded'
  group by item.organization_id, organization.organization_name, budget.budget_amount
  having coalesce(sum(greatest(item.proposed_base_amount - item.current_base_amount, 0)), 0)
       > coalesce(budget.budget_amount, 0)
  order by
    coalesce(sum(greatest(item.proposed_base_amount - item.current_base_amount, 0)), 0)
      - coalesce(budget.budget_amount, 0) desc
  limit 1;

  if found then
    raise exception '% 调薪预算超支：预算 %，已建议 %',
      v_overrun.organization_name, v_overrun.budget_amount, v_overrun.used_amount;
  end if;
end;
$function$;

--
-- Name: hr_valuate_attendance_record; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.hr_valuate_attendance_record(p_record_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_record public.hr_attendance_record;
  v_shift public.hr_shift;
  v_planned_start timestamptz;
  v_planned_end timestamptz;
  v_scheduled integer := 0;
  v_work integer := 0;
  v_late integer := 0;
  v_early integer := 0;
  v_absence integer := 0;
  v_overtime integer := 0;
  v_status text := 'normal';
  v_exception text := 'clear';
  v_note text;
begin
  select * into v_record from public.hr_attendance_record where id = p_record_id for update;
  if not found then raise exception '考勤记录不存在'; end if;
  if v_record.locked_at is not null then raise exception '考勤记录已封账，不能重新核算'; end if;

  if v_record.shift_id is not null then
    select * into v_shift from public.hr_shift
    where id = v_record.shift_id ;
  else
    select shift.* into v_shift
    from public.hr_shift_assignment assignment
    join public.hr_shift shift on shift.id = assignment.shift_id 
    where true
      and assignment.employee_id = v_record.employee_id
      and assignment.work_date = v_record.work_date
      and assignment.assignment_status <> 'cancelled';
  end if;

  if found then
    v_planned_start := (v_record.work_date::timestamp + v_shift.start_time) at time zone v_shift.time_zone;
    v_planned_end := ((v_record.work_date + case when v_shift.cross_day then 1 else 0 end)::timestamp
      + v_shift.end_time) at time zone v_shift.time_zone;
    v_scheduled := greatest(floor(extract(epoch from (v_planned_end - v_planned_start)) / 60)::integer
      - v_shift.break_minutes, 0);
  end if;

  if v_record.attendance_status in ('leave', 'business_trip') then
    v_status := v_record.attendance_status;
    v_note := case when v_status = 'leave' then '已批准休假，不生成出勤异常' else '已登记出差，不生成出勤异常' end;
  elsif v_record.clock_in_at is null or v_record.clock_out_at is null then
    v_status := 'absent';
    v_absence := v_scheduled;
    v_exception := 'open';
    v_note := case
      when v_record.clock_in_at is null and v_record.clock_out_at is null then '缺少上下班打卡'
      when v_record.clock_in_at is null then '缺少上班打卡'
      else '缺少下班打卡'
    end;
  else
    v_work := greatest(floor(extract(epoch from (v_record.clock_out_at - v_record.clock_in_at)) / 60)::integer
      - coalesce(v_shift.break_minutes, 0), 0);
    if v_planned_start is not null then
      v_late := greatest(floor(extract(epoch from (v_record.clock_in_at - v_planned_start)) / 60)::integer
        - v_shift.late_grace_minutes, 0);
      v_early := greatest(floor(extract(epoch from (v_planned_end - v_record.clock_out_at)) / 60)::integer
        - v_shift.early_leave_grace_minutes, 0);
    end if;
    v_absence := greatest(v_scheduled - v_work, 0);
    v_overtime := greatest(v_work - v_scheduled, 0);
    if v_late > 0 then v_status := 'late';
    elsif v_early > 0 then v_status := 'early_leave';
    else v_status := 'normal'; end if;
    if v_late > 0 or v_early > 0 or v_absence > 0 then v_exception := 'open'; end if;
    v_note := concat_ws('；',
      case when v_late > 0 then '迟到 ' || v_late || ' 分钟' end,
      case when v_early > 0 then '早退 ' || v_early || ' 分钟' end,
      case when v_absence > 0 then '缺勤 ' || v_absence || ' 分钟' end,
      case when v_overtime > 0 then '超出计划 ' || v_overtime || ' 分钟' end
    );
    if v_note = '' then v_note := '打卡覆盖计划工时'; end if;
  end if;

  update public.hr_attendance_record
  set shift_id = coalesce(shift_id, v_shift.id),
      scheduled_minutes = v_scheduled,
      work_minutes = v_work,
      overtime_minutes = v_overtime,
      late_minutes = v_late,
      early_leave_minutes = v_early,
      absence_minutes = v_absence,
      payable_minutes = v_work,
      attendance_status = v_status,
      exception_status = v_exception,
      valuation_note = v_note
  where id = p_record_id;
end
$function$;

--
-- Name: is_driver_user; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.is_driver_user()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from public.sys_user u
    where u.auth_user_id = (select auth.uid())
      and u.status = '1'
      and u.deleted_at is null
      and u.user_type = '2'
  );
$function$;

--
-- Name: is_enabled_dictionary_value; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.is_enabled_dictionary_value(p_type_code text, p_value text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select nullif(btrim(coalesce(p_value, '')), '') is not null
    and exists (
      select 1
      from public.sys_dict_type dictionary_type
      join public.sys_dictionary dictionary_item
        on dictionary_item.type_id = dictionary_type.id
      where dictionary_type.code = p_type_code
        and dictionary_type.status = '1'
        and dictionary_item.status = '1'
        and btrim(dictionary_item.value) = btrim(p_value)
    );
$function$;

--
-- Name: is_fms_system_posting; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.is_fms_system_posting()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select coalesce(current_setting('app.fms_system_posting', true), '') = 'on'
$function$;

--
-- Name: is_platform_super; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.is_platform_super()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from public.sys_user u
    join public.sys_role r
      on r.role_code = 'R_SUPER'
     and r.role_code = any(coalesce(u.user_roles, array[]::text[]))
    where u.auth_user_id = auth.uid()
      and u.status = '1'
      and r.enabled is true
  )
$function$;

--
-- Name: list_mdm_production_employees; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.list_mdm_production_employees(p_id uuid, p_from integer, p_to integer, p_keyword text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 contact boolean; identity boolean; payload jsonb;
begin
 if auth.uid() is null or not (
 app_private.has_permission('MdmProductionPersonnel:Add') or app_private.has_permission('MdmProductionPersonnel:Edit')
 or app_private.has_permission('MdmProductionPersonnel:View')) then
 raise exception '没有生产人员参选权限' using errcode='42501'; end if;
 contact:=app_private.has_permission('Hr:Employee:View') and app_private.resolve_field_access('hr.employee','contactDetails',null) in ('read','edit');
 identity:=app_private.has_permission('Hr:Employee:View') and app_private.resolve_field_access('hr.employee','identityDetails',null) in ('read','edit');
 with source as materialized (
  select e.id,e.employee_no,e.employee_name,e.avatar_url,e.job_title,e.employment_status,e.employment_type,
   case when contact then e.phone end as phone,case when identity then e.gender end as gender,
   e.hire_date,e.organization_id,o.organization_code,o.organization_name
  from public.mdm_employee e left join public.mdm_organization o on o.id=e.organization_id 
  where e.employment_status in ('active','probation') and (p_id is null or e.id=p_id)
  and (nullif(btrim(p_keyword),'') is null or e.employee_no ilike '%'||p_keyword||'%' or e.employee_name ilike '%'||p_keyword||'%' or e.job_title ilike '%'||p_keyword||'%')
 ), page as (select * from source order by employee_name,employee_no,id offset greatest(coalesce(p_from,0),0) limit least(greatest(coalesce(p_to,9)-greatest(coalesce(p_from,0),0)+1,1),200))
 select jsonb_build_object('total',(select count(*) from source),'records',coalesce((select jsonb_agg(jsonb_build_object(
 'id',p.id,'employee_no',p.employee_no,'employee_name',p.employee_name,
 'avatar_url',p.avatar_url,'job_title',p.job_title,'employment_status',p.employment_status,'employment_type',p.employment_type,
 'phone',p.phone,'gender',p.gender,'hire_date',p.hire_date,
 'organization',case when p.organization_id is null then null else jsonb_build_object('id',p.organization_id,'organization_code',p.organization_code,'organization_name',p.organization_name) end
 ) order by p.employee_name,p.employee_no,p.id) from page p),'[]'::jsonb),
 'field_access',jsonb_build_object('contactDetails',contact,'identityDetails',identity)) into payload;
 return payload;
end $function$;

--
-- Name: mark_header_notifications_read; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mark_header_notifications_read(p_category text DEFAULT NULL::text, p_notification_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := (select app_private.current_app_user_id());
  v_count integer;
begin
  if p_category is not null and p_category not in ('notice', 'message') then
    raise exception '待办事项需完成审批后自动归档';
  end if;

  update public.sys_notification n
  set is_read = true,
      read_at = coalesce(n.read_at, now())
  where true
    and n.recipient_user_id = v_user_id
    and n.category in ('notice', 'message')
    and n.is_read = false
    and (p_category is null or n.category = p_category)
    and (p_notification_ids is null or n.id = any(p_notification_ids));

  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

--
-- Name: mask_permission_value; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mask_permission_value(p_value text, p_strategy text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_length integer := char_length(coalesce(p_value, ''));
begin
  if p_value is null then
    return null;
  end if;

  return case p_strategy
    when 'phone' then
      case when v_length >= 7
        then left(p_value, 3) || repeat('*', greatest(v_length - 7, 4)) || right(p_value, 4)
        else repeat('*', greatest(v_length, 4))
      end
    when 'id_card' then
      case when v_length >= 8
        then left(p_value, 4) || repeat('*', v_length - 8) || right(p_value, 4)
        else repeat('*', greatest(v_length, 4))
      end
    when 'bank_account' then
      case when v_length >= 8
        then left(p_value, 4) || repeat('*', v_length - 8) || right(p_value, 4)
        else repeat('*', greatest(v_length, 4))
      end
    when 'address' then
      case when v_length > 6 then left(p_value, 6) || '***' else '***' end
    when 'amount' then '***'
    else '***'
  end;
end;
$function$;

--
-- Name: mdm_add_work_center_devices; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_add_work_center_devices(p_work_center_id uuid, p_equipment_ids uuid[], p_main_equipment_id uuid DEFAULT NULL::uuid, p_point text DEFAULT '无'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_equipment_ids uuid[];
  v_inserted_count integer;
begin
  if auth.uid() is null
    or not app_private.has_permission('MdmWorkCenter:Devices')
  then
    raise exception '没有配置工作中心设备权限' using errcode = '42501';
  end if;

  perform 1 from public.mdm_work_center c where c.id = p_work_center_id;
  if not found then
    raise exception '工作中心不存在或不在当前工作范围内';
  end if;



  select coalesce(array_agg(distinct equipment_id), '{}'::uuid[])
    into v_equipment_ids
    from unnest(coalesce(p_equipment_ids, '{}'::uuid[])) as selected(equipment_id);

  if cardinality(v_equipment_ids) < 1 or cardinality(v_equipment_ids) > 100 then
    raise exception '请选择 1 至 100 台设备';
  end if;

  if p_point not in ('无', '投入点', '产出点') then
    raise exception '投入 / 产出点无效';
  end if;

  if p_main_equipment_id is not null
    and not (p_main_equipment_id = any(v_equipment_ids))
  then
    raise exception '主设备必须来自本次所选设备';
  end if;

  if p_main_equipment_id is not null
    and exists (
      select 1
        from public.mdm_work_center_device b
       where b.work_center_id = p_work_center_id
         and b.is_main
    )
  then
    raise exception '当前工作中心已经设置主设备';
  end if;

  if (
    select count(*)
      from public.mdm_equipment e
     where e.id = any(v_equipment_ids)
       and e.status = 'enabled'
       and not exists (
         select 1
           from public.mdm_work_center_device b
          where b.equipment_id = e.id
       )
  ) <> cardinality(v_equipment_ids)
  then
    raise exception '所选设备无效或已被其他工作中心关联';
  end if;

  insert into public.mdm_work_center_device (
    work_center_id,
    equipment_id,
    is_main,
    point
  )
  select
    p_work_center_id,
    equipment_id,
    equipment_id = p_main_equipment_id,
    p_point
  from unnest(v_equipment_ids) as selected(equipment_id);

  get diagnostics v_inserted_count = row_count;
  return v_inserted_count;
end
$function$;

--
-- Name: mdm_bom_guard; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_bom_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_permission text;
begin
  if tg_op <> 'DELETE' then
    if new.group_id is not null and not exists(
      select 1 from public.mdm_master_group g
      where g.id=new.group_id  and g.domain='bom' and g.enabled
    ) then
      raise exception '所选 BOM 分组不存在、已停用或不可用' using errcode='23503';
    end if;
    if new.base_quantity <= 0 or new.base_quantity <> trunc(new.base_quantity) then
      raise exception '基准数量必须为大于 0 的整数' using errcode='23514';
    end if;
  end if;
  if tg_op = 'INSERT' and new.status <> 'design' then
    raise exception '新建 BOM 必须处于设计状态' using errcode='22023';
  end if;
  if tg_op = 'UPDATE' and new.bom_code is distinct from old.bom_code then
    raise exception 'BOM 编码由系统生成，不允许修改' using errcode='22023';
  end if;
  if tg_op = 'UPDATE' and old.status <> new.status then
    v_permission := case
      when old.status in ('design','changing') and new.status='review' then 'MdmBomMaintenance:Submit'
      when old.status='review' and new.status='effective' then 'MdmBomMaintenance:Approve'
      when old.status='review' and new.status='design' then 'MdmBomMaintenance:Approve'
      when old.status='effective' and new.status='changing' then 'MdmBomMaintenance:Edit'
      when old.status in ('effective','changing') and new.status='archived' then 'MdmBomMaintenance:Archive'
      when old.status not in ('archived','void') and new.status='void' then 'MdmBomMaintenance:Archive'
      else null end;
    if v_permission is null then
      raise exception '不允许从 % 状态变更为 %', old.status, new.status using errcode='22023';
    end if;
    if not app_private.has_permission(v_permission) then
      raise exception '当前账号没有执行 BOM 状态变更的权限' using errcode='42501';
    end if;
  end if;
  if tg_op='DELETE' and old.status <> 'design' then
    raise exception '仅设计状态的 BOM 可以删除' using errcode='55000';
  end if;
  return case when tg_op='DELETE' then old else new end;
end
$function$;

--
-- Name: mdm_bom_item_guard; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_bom_item_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_bom public.mdm_bom%rowtype;
  v_cycle boolean;
begin
  select * into v_bom from public.mdm_bom where id=coalesce(new.bom_id, old.bom_id);
  if not found then raise exception 'BOM 不存在' using errcode='P0002'; end if;
  if v_bom.status not in ('design','changing') then raise exception '仅设计或变更中的 BOM 可以调整组件' using errcode='55000'; end if;
  if tg_op <> 'DELETE' then
    if new.component_material_id=v_bom.material_id then raise exception '父项物料不能作为自身组件' using errcode='23514'; end if;
    with recursive dependency(material_id, path) as (
      select child.material_id, array[v_bom.material_id, child.material_id]
      from public.mdm_bom child
      where child.material_id=new.component_material_id and child.status <> 'void'
      union all
      select next_bom.material_id, dependency.path || next_bom.material_id
      from dependency
      join public.mdm_bom_item next_item on next_item.bom_id in (
        select id from public.mdm_bom where material_id=dependency.material_id and status <> 'void'
      )
      join public.mdm_bom next_bom on next_bom.material_id=next_item.component_material_id and next_bom.status <> 'void'
      where not next_bom.material_id=any(dependency.path)
    ) select exists(select 1 from dependency where material_id=v_bom.material_id) into v_cycle;
    if v_cycle then raise exception '该组件会形成循环 BOM' using errcode='23514'; end if;
  end if;
  return case when tg_op='DELETE' then old else new end;
end $function$;

--
-- Name: mdm_change_request_state_audit; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_change_request_state_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_action text;
  v_comment text;
  v_actor_user_id uuid;
  v_actor_email text;
begin
  if tg_op = 'UPDATE' and new.state is not distinct from old.state then
    return new;
  end if;

  v_action := coalesce(
    nullif(current_setting('app.mdm_change_action', true), ''),
    case when tg_op = 'INSERT' then 'create' else 'system_transition' end
  );
  v_comment := nullif(current_setting('app.mdm_change_comment', true), '');

  begin
    v_actor_user_id := app_private.mdm_current_actor_user_id();
    v_actor_email := app_private.mdm_current_actor_email();
  exception when sqlstate '42501' then
    v_actor_user_id := null;
    v_actor_email := 'system';
  end;

  insert into public.mdm_change_request_event (
    request_id,
    from_state,
    to_state,
    action,
    actor_user_id,
    actor_email,
    comment,
    snapshot
  ) values (
    new.id,
    case when tg_op = 'UPDATE' then old.state else null end,
    new.state,
    v_action,
    v_actor_user_id,
    v_actor_email,
    v_comment,
    jsonb_build_object(
      'requestNo', new.request_no,
      'domainKey', new.domain_key,
      'sourceType', new.source_type,
      'sourceRecordId', new.source_record_id,
      'operation', new.operation,
      'version', new.version,
      'effectiveAt', new.effective_at,
      'beforeData', new.before_data,
      'proposedData', new.proposed_data
    )
  );

  perform app_private.mdm_emit_outbox_event('change_request',
    new.id,
    'mdm.change-request.' || replace(new.state, '_', '-'),
    jsonb_build_object(
      'requestId', new.id,
      'requestNo', new.request_no,
      'sourceType', new.source_type,
      'sourceRecordId', new.source_record_id,
      'operation', new.operation,
      'state', new.state,
      'effectiveAt', new.effective_at,
      'beforeData', new.before_data,
      'proposedData', new.proposed_data
    )
  );

  return new;
end
$function$;

--
-- Name: mdm_component_type_group_guard; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_component_type_group_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if not exists(select 1 from public.mdm_master_group g
   where g.id=new.group_id  and g.domain='component-type') then
   raise exception '行业分组不存在或不可用' using errcode='23503';
 end if;
 return new;
end $function$;

--
-- Name: mdm_convert_accessory_work_orders_internal; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_convert_accessory_work_orders_internal(p_item_ids uuid[], p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_item public.mdm_accessory_processing_item%rowtype;
  v_list public.mdm_accessory_processing_list%rowtype;
  v_project uuid := nullif(p_config->>'projectId','')::uuid;
  v_type uuid;
  v_order uuid;
  v_start date := coalesce(nullif(p_config->>'plannedStartDate','')::date,
    (now() at time zone 'Asia/Shanghai')::date);
  v_end date := nullif(p_config->>'plannedEndDate','')::date;
  v_construction text := nullif(btrim(p_config->>'constructionNo'),'');
  v_created integer := 0;
  v_skipped integer := 0;
begin
  if auth.uid() is null or not app_private.has_permission('MdmAccessoryProcessing:GenerateWorkOrder') then
    raise exception '当前账号没有转生产工单的权限' using errcode='42501';
  end if;
  if coalesce(array_length(p_item_ids,1),0) not between 1 and 100
     or jsonb_typeof(p_config)<>'object' then
    raise exception '请选择 1 至 100 个已生成物料的加工件' using errcode='22023';
  end if;
  if v_end is null or v_end<v_start then
    raise exception '计划完工日期不能早于计划开始日期' using errcode='22023';
  end if;
  if length(v_construction)>120 then
    raise exception '施工号不能超过 120 个字符' using errcode='22023';
  end if;
  for v_item in
    select * from public.mdm_accessory_processing_item
    where id=any(p_item_ids) order by list_id,line_no for update
  loop
    select * into v_list from public.mdm_accessory_processing_list
    where id=v_item.list_id for update;
    if v_type is null then
      select id into v_type from public.mdm_document_type
      where document_type_code='PP40' and enabled
      order by id limit 1;
      if v_type is null then
        raise exception '未启用 PP40 配件加工工单类型' using errcode='22023';
      end if;
    end if;
    if v_item.material_id is null then
      raise exception '第 % 个加工件尚未生成物料编码',v_item.line_no using errcode='22023';
    end if;
    if v_project is null then v_project := v_list.project_id; end if;
    if v_project is null or
       not exists(select 1 from public.mdm_project
         where id=v_project  and enabled) then
      raise exception '请先关联有效的系统项目' using errcode='22023';
    end if;
    if v_list.project_id is not null and v_list.project_id<>v_project then
      raise exception '所选加工件分属不同项目，请分别转单' using errcode='22023';
    end if;
    if v_list.project_id is null then
      update public.mdm_accessory_processing_list set project_id=v_project
      where id=v_list.id;
    end if;
    if exists(select 1 from public.mes_work_order
      where accessory_item_id=v_item.id and deleted_at is null) then
      v_skipped := v_skipped+1;
      continue;
    end if;
    if v_item.width_mm is null or v_item.width_mm <= 0 then
      raise exception '第 % 个加工件缺少展宽，请先删除编码并补齐展宽',v_item.line_no using errcode='22023';
    end if;
    insert into public.mes_work_order (work_order_no,work_order_type_id,project_id,construction_no,
      material_id,order_quantity,planned_start_date,planned_end_date,
      source,accessory_item_id,remark
    ) values ('',v_type,v_project,v_construction,v_item.material_id,v_item.quantity,
      v_start,v_end,'accessory_processing',v_item.id,
      left('配件加工清单：'||v_list.drawing_name||'；原表第'||v_item.row_no::text||'行',500)
    ) returning id into v_order;
    insert into public.mes_work_order_detail (work_order_id,area,number,length_mm,pieces,width_mm,
      area_sqm,remark,sort_order
    ) values (v_order,'',v_item.row_no::text,v_item.length_m*1000,v_item.quantity,
      v_item.width_mm,
      v_item.width_mm*v_item.length_m*v_item.quantity/1000,
      left(v_item.remark,500),10
    );
    v_created := v_created+1;
    if not exists(select 1 from public.mdm_accessory_processing_item i
      where i.list_id=v_item.list_id and not exists(
        select 1 from public.mes_work_order o
        where o.accessory_item_id=i.id and o.deleted_at is null
      )) then
      update public.mdm_accessory_processing_list set status='generated'
      where id=v_item.list_id;
    end if;
  end loop;
  if v_created+v_skipped <> cardinality(array(select distinct unnest(p_item_ids))) then
    raise exception '部分加工件不存在，请刷新后重试' using errcode='22023';
  end if;
  return jsonb_build_object('created',v_created,'skipped',v_skipped);
end
$function$;

--
-- Name: mdm_copy_process_route; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_copy_process_route(p_id uuid, p_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_source public.mdm_process_route%rowtype;
  v_target_id uuid;
  v_sequence record;
  v_step record;
  v_new_sequence_id uuid;
  v_new_step_id uuid;
  v_sequence_map jsonb := '{}'::jsonb;
  v_step_map jsonb := '{}'::jsonb;
  v_target_name text;
begin
  if auth.uid() is null or not app_private.has_permission('MdmProcessRoute:Copy') then
    raise exception '没有复制工艺路线权限' using errcode = '42501';
  end if;

  select * into strict v_source
  from public.mdm_process_route
  where id = p_id;


  v_target_name := coalesce(nullif(btrim(p_name), ''), v_source.name || ' - 副本');
  if char_length(v_target_name) > 200 then
    raise exception '路线名称不能超过 200 个字符' using errcode = '22023';
  end if;

  perform set_config('app.process_route_copy', '1', true);

  insert into public.mdm_process_route( material_id, name, code, route_type, allocation_mode, group_id,
    version, batch_from, batch_to, production_unit_id, department_id,
    effective_date, expiry_date, is_default, source, custom_unit_conversion,
    enabled, path, remark
  )
  values ( v_source.material_id, v_target_name, '',
    v_source.route_type, v_source.allocation_mode, v_source.group_id,
    v_source.version, v_source.batch_from, v_source.batch_to,
    v_source.production_unit_id, v_source.department_id,
    v_source.effective_date, v_source.expiry_date, false, 'copy',
    v_source.custom_unit_conversion, v_source.enabled, v_source.path, v_source.remark
  )
  returning id into v_target_id;

  delete from public.mdm_process_route_sequence
  where route_id = v_target_id;

  for v_sequence in
    select *
    from public.mdm_process_route_sequence
    where route_id = v_source.id
    order by sequence_no, id
  loop
    insert into public.mdm_process_route_sequence( route_id, sequence_no, sequence_type, remark
    )
    values ( v_target_id, v_sequence.sequence_no,
      v_sequence.sequence_type, v_sequence.remark
    )
    returning id into v_new_sequence_id;

    v_sequence_map := v_sequence_map ||
      jsonb_build_object(v_sequence.id::text, v_new_sequence_id::text);
  end loop;

  for v_step in
    select *
    from public.mdm_process_route_step
    where route_id = v_source.id
    order by sort, code, id
  loop
    insert into public.mdm_process_route_step( route_id, code, name, sort, work_center_id, work_center_ids,
      run_output_quantity, run_processing_minutes, run_green_minutes, setup_minutes,
      operator_count, machine_count, template_id, work_center_policy, config_updated_at,
      sequence_id, operation_id, description, unit_id, basic_batch, department_id,
      operation_mode, control_code_id, processing_mode, report_mode, inspection_mode,
      sequence_control, rework_mode, need_inspection, first_inspection,
      first_inspection_control, is_first, is_last, critical, unit_conversion,
      activities, outsourcing, inspection, sop_documents
    )
    values ( v_target_id, v_step.code, v_step.name, v_step.sort,
      v_step.work_center_id, v_step.work_center_ids, v_step.run_output_quantity,
      v_step.run_processing_minutes, v_step.run_green_minutes, v_step.setup_minutes,
      v_step.operator_count, v_step.machine_count, v_step.template_id,
      v_step.work_center_policy, v_step.config_updated_at,
      (v_sequence_map ->> v_step.sequence_id::text)::uuid,
      v_step.operation_id, v_step.description, v_step.unit_id, v_step.basic_batch,
      v_step.department_id, v_step.operation_mode, v_step.control_code_id,
      v_step.processing_mode, v_step.report_mode, v_step.inspection_mode,
      v_step.sequence_control, v_step.rework_mode, v_step.need_inspection,
      v_step.first_inspection, v_step.first_inspection_control,
      v_step.is_first, v_step.is_last, v_step.critical, v_step.unit_conversion,
      v_step.activities, v_step.outsourcing, v_step.inspection, v_step.sop_documents
    )
    returning id into v_new_step_id;

    v_step_map := v_step_map ||
      jsonb_build_object(v_step.id::text, v_new_step_id::text);
  end loop;

  for v_sequence in
    select *
    from public.mdm_process_route_sequence
    where route_id = v_source.id
  loop
    update public.mdm_process_route_sequence
    set
      transfer_in_step_id = case
        when v_sequence.transfer_in_step_id is null then null
        else (v_step_map ->> v_sequence.transfer_in_step_id::text)::uuid
      end,
      transfer_out_step_id = case
        when v_sequence.transfer_out_step_id is null then null
        else (v_step_map ->> v_sequence.transfer_out_step_id::text)::uuid
      end
    where id = (v_sequence_map ->> v_sequence.id::text)::uuid;
  end loop;

  perform set_config('app.process_route_copy', '0', true);
  return v_target_id;
end
$function$;

--
-- Name: mdm_current_actor_email; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_current_actor_email()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_email text;
begin
  select u.user_email
    into v_email
  from public.sys_user u
  where u.auth_user_id = (select auth.uid())
    and u.status = '1'
    and u.deleted_at is null;

  if nullif(btrim(v_email), '') is null then
    raise exception '当前业务账号邮箱不可用' using errcode = '42501';
  end if;
  return v_email;
end
$function$;

--
-- Name: mdm_current_actor_user_id; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_current_actor_user_id()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid;
begin
  select u.id
    into v_user_id
  from public.sys_user u
  where u.auth_user_id = (select auth.uid())
    and u.status = '1'
    and u.deleted_at is null;

  if v_user_id is null then
    raise exception '当前业务账号不存在或已停用' using errcode = '42501';
  end if;
  return v_user_id;
end
$function$;

--
-- Name: mdm_delete_accessory_processing_items_internal; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_delete_accessory_processing_items_internal(p_item_ids uuid[], p_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_item public.mdm_accessory_processing_item%rowtype;
  v_material public.mdm_material%rowtype;
  v_list_ids uuid[] := '{}'::uuid[];
  v_processed integer := 0;
begin
  if auth.uid() is null or not app_private.has_permission('MdmAccessoryProcessing:Delete') then
    raise exception '当前账号没有删除加工件或物料编码的权限' using errcode='42501';
  end if;
  if p_mode not in ('items','codes') or coalesce(cardinality(p_item_ids),0) not between 1 and 100 then
    raise exception '请选择 1 至 100 个加工件并指定删除方式' using errcode='22023';
  end if;
  if cardinality(p_item_ids) <> (
    select count(distinct selected.id) from unnest(p_item_ids) as selected(id)
  ) then
    raise exception '所选加工件包含重复或无效编号，请刷新后重试' using errcode='22023';
  end if;

  for v_item in
    select * from public.mdm_accessory_processing_item
    where id=any(p_item_ids)  for update
  loop

    if p_mode='codes' and v_item.material_id is null then
      raise exception '所选加工件包含未生成编码的记录，请只选择已编码件' using errcode='22023';
    end if;
    if exists (
      select 1 from public.mes_work_order where accessory_item_id=v_item.id
    ) then
      raise exception '加工件“%”已关联生产工单，请先处理工单',v_item.name using errcode='22023';
    end if;

    v_list_ids := array_append(v_list_ids,v_item.list_id);
    if v_item.material_id is not null then
      select * into v_material from public.mdm_material
      where id=v_item.material_id  for update;
      if not found then
        raise exception '加工件“%”关联的物料不存在，请刷新后重试',v_item.name using errcode='22023';
      end if;
      if exists (
        select 1 from public.mdm_accessory_processing_item
        where material_id=v_item.material_id and id<>v_item.id
      ) then
        raise exception '物料编码 % 仍由其他加工件使用，不能删除',v_item.material_code using errcode='22023';
      end if;
      if exists (
        select 1 from public.mdm_bom_item
        where component_material_id=v_item.material_id
      ) or exists (
        select 1 from public.mdm_bom where material_id=v_item.material_id
      ) then
        raise exception '物料编码 % 已被项目 BOM 引用，请先处理 BOM',v_item.material_code using errcode='22023';
      end if;

      update public.mdm_accessory_processing_item set
        material_id=null,material_code=null,
        image_urls=case when jsonb_array_length(image_urls)=0
          then v_material.image_urls else image_urls end
      where id=v_item.id;
      begin
        delete from public.mdm_material where id=v_material.id;
      exception when foreign_key_violation then
        raise exception '物料编码 % 已被其他业务单据引用，请先处理关联',v_item.material_code
          using errcode='22023';
      end;
    end if;

    if p_mode='items' then
      begin
        delete from public.mdm_accessory_processing_item where id=v_item.id;
      exception when foreign_key_violation then
        raise exception '加工件“%”已被其他业务引用，无法删除',v_item.name using errcode='22023';
      end;
    end if;
    v_processed := v_processed+1;
  end loop;

  if v_processed<>cardinality(p_item_ids) then
    raise exception '部分加工件不存在，本批次未执行，请刷新后重试' using errcode='22023';
  end if;
  if p_mode='codes' then
    update public.mdm_accessory_processing_list
    set status='draft'
    where id=any(v_list_ids) and status in ('materials_ready','generated');
  else
    delete from public.mdm_accessory_processing_list l
    where l.id=any(v_list_ids)
      and not exists (
        select 1 from public.mdm_accessory_processing_item i where i.list_id=l.id
      );
  end if;
  return jsonb_build_object('processed',v_processed);
end
$function$;

--
-- Name: mdm_delete_legacy_accessory_order_drafts_internal; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_delete_legacy_accessory_order_drafts_internal(p_order_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_order public.mdm_accessory_work_order%rowtype;
  v_processed integer := 0;
begin
  if auth.uid() is null or not app_private.has_permission('MdmAccessoryProcessing:Delete') then
    raise exception '当前账号没有删除旧版加工工单草稿的权限' using errcode = '42501';
  end if;
  if coalesce(cardinality(p_order_ids), 0) not between 1 and 100
    or cardinality(p_order_ids) <> (select count(distinct selected.id) from unnest(p_order_ids) as selected(id)) then
    raise exception '请选择 1 至 100 张有效且不重复的旧版加工工单草稿' using errcode = '22023';
  end if;

  for v_order in
    select * from public.mdm_accessory_work_order
    where id = any(p_order_ids)
    
    for update
  loop

    if v_order.status <> 'draft' then
      raise exception '旧版加工工单 % 已不是草稿，请到业务页面核对', v_order.order_no
        using errcode = '22023';
    end if;
    delete from public.mdm_accessory_work_order where id = v_order.id;
    v_processed := v_processed + 1;
  end loop;

  if v_processed <> cardinality(p_order_ids) then
    raise exception '部分旧版加工工单已变化，本次未删除任何记录，请重新检查'
      using errcode = '22023';
  end if;
  return v_processed;
end
$function$;

--
-- Name: mdm_emit_outbox_event; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_emit_outbox_event(p_aggregate_type text, p_aggregate_id uuid, p_event_type text, p_payload jsonb, p_correlation_id uuid DEFAULT NULL::uuid, p_causation_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event_id uuid;
begin
  if nullif(btrim(p_aggregate_type), '') is null
    or nullif(btrim(p_event_type), '') is null
    or jsonb_typeof(p_payload) is distinct from 'object' then
    raise exception '主数据事件参数不完整' using errcode = '22023';
  end if;

  insert into public.mdm_outbox_event (
    aggregate_type,
    aggregate_id,
    event_type,
    event_version,
    payload,
    correlation_id,
    causation_id
  ) values (
    p_aggregate_type,
    p_aggregate_id,
    p_event_type,
    1,
    p_payload,
    p_correlation_id,
    p_causation_id
  ) returning id into v_event_id;

  insert into public.mdm_outbox_delivery (event_id, consumer_id)
  select v_event_id, consumer.id
  from public.mdm_outbox_consumer consumer
  where true
    and consumer.enabled
    and ('*' = any (consumer.event_types) or p_event_type = any (consumer.event_types));

  return v_event_id;
end
$function$;

--
-- Name: mdm_generate_accessory_materials_internal; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_generate_accessory_materials_internal(p_item_ids uuid[], p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_item public.mdm_accessory_processing_item%rowtype;
  v_list public.mdm_accessory_processing_list%rowtype;
  v_project uuid := nullif(p_config->>'projectId','')::uuid;
  v_type uuid := nullif(p_config->>'materialTypeId','')::uuid;
  v_category uuid := nullif(p_config->>'categoryId','')::uuid;
  v_rule uuid := nullif(p_config->>'codeRuleId','')::uuid;
  v_source text := p_config->>'materialSource';
  v_type_code text;
  v_unit_code text;
  v_code text;
  v_material uuid;
  v_images jsonb;
  v_created integer := 0;
  v_skipped integer := 0;
begin
  if auth.uid() is null or not app_private.has_permission('MdmAccessoryProcessing:GenerateMaterial') then
    raise exception '当前账号没有生成物料编码的权限' using errcode='42501';
  end if;
  if coalesce(array_length(p_item_ids,1),0) not between 1 and 100
     or jsonb_typeof(p_config) <> 'object' then
    raise exception '请选择 1 至 100 个加工件并确认物料配置' using errcode='22023';
  end if;
  if v_project is null then
    raise exception '请选择系统项目' using errcode='22023';
  end if;
  if v_source not in ('purchase','self_made','outsourcing') then
    raise exception '请选择有效的物料来源' using errcode='22023';
  end if;
  for v_item in
    select * from public.mdm_accessory_processing_item
    where id = any(p_item_ids) order by list_id,line_no for update
  loop
    select * into v_list from public.mdm_accessory_processing_list
    where id=v_item.list_id for update;

    if not exists(select 1 from public.mdm_project
      where id=v_project  and enabled=true) then
      raise exception '系统项目已失效，请重新选择' using errcode='22023';
    end if;
    if v_list.project_id is not null and v_list.project_id <> v_project then
      raise exception '加工清单已关联其他系统项目，请按项目分别生成编码' using errcode='22023';
    end if;
    if v_item.material_id is not null then
      v_skipped := v_skipped+1;
      continue;
    end if;
    if v_item.width_mm is null or v_item.width_mm <= 0 then
      raise exception '第 % 个加工件缺少展宽，请先编辑清单再生成编码',v_item.line_no using errcode='22023';
    end if;
    select type_code into v_type_code from public.mdm_material_type
    where id=v_type  and status='enabled';
    if not found then raise exception '物料类型已失效，请重新选择' using errcode='22023'; end if;
    if not exists(select 1 from public.mdm_material_category
      where id=v_category  and status='enabled') then
      raise exception '物料分类已失效，请重新选择' using errcode='22023';
    end if;
    if not exists(select 1 from public.mdm_material_code_rule
      where id=v_rule  and status='enabled') then
      raise exception '编码策略已失效，请重新选择' using errcode='22023';
    end if;
    select unit_code into v_unit_code from public.mdm_unit_of_measure
    where id=v_item.base_unit_id  and status='enabled';
    if not found then raise exception '加工件基本单位已失效，请先编辑清单' using errcode='22023'; end if;
    v_images := coalesce(p_config->'imageUrlsByItem'->(v_item.id::text),v_item.image_urls,'[]'::jsonb);
    if jsonb_typeof(v_images)<>'array' or jsonb_array_length(v_images)>5
       or exists(select 1 from jsonb_array_elements(v_images) as image(value)
         where jsonb_typeof(image.value)<>'string' or length(image.value #>> '{}')>2048
           or image.value #>> '{}' !~ '^https://') then
      raise exception '第 % 个加工件图片无效',v_item.line_no using errcode='22023';
    end if;
    v_code := app_private.mdm_generate_material_code_internal(v_rule,v_type,v_category);
    insert into public.mdm_material (category_id,material_code,material_name,specification_model,
      drawing_no,basic_unit,base_unit_id,material_type,material_type_id,
      material_source,material_composition,description,image_urls,code_rule_id,length
    ) values (v_category,v_code,left(v_item.name,120),left(v_item.specification_model,120),
      nullif(left(v_list.drawing_name,120),''),v_unit_code,v_item.base_unit_id,
      v_type_code,v_type,v_source,nullif(left(v_item.material_color,120),''),
      left(coalesce(nullif(concat_ws('；',nullif(v_item.material_color,''),nullif(v_item.remark,'')),''),
        v_item.specification_model,v_item.name),1000),
      v_images,v_rule,v_item.length_m
    ) returning id into v_material;
    update public.mdm_accessory_processing_item set
      material_id=v_material,material_code=v_code,material_type_id=v_type,
      material_source=v_source,category_id=v_category,code_rule_id=v_rule,
      image_urls=v_images
    where id=v_item.id;
    update public.mdm_accessory_processing_list
    set project_id=v_project where id=v_item.list_id and project_id is null;
    v_created := v_created+1;
    if not exists(select 1 from public.mdm_accessory_processing_item
      where list_id=v_item.list_id and material_id is null) then
      update public.mdm_accessory_processing_list
      set status='materials_ready' where id=v_item.list_id and status='draft';
    end if;
  end loop;
  if v_created+v_skipped <> cardinality(array(select distinct unnest(p_item_ids))) then
    raise exception '部分加工件不存在，请刷新后重试' using errcode='22023';
  end if;
  return jsonb_build_object('created',v_created,'skipped',v_skipped);
end
$function$;

--
-- Name: mdm_generate_accessory_processing_stage_internal; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_generate_accessory_processing_stage_internal(p_list_id uuid, p_stage text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_list public.mdm_accessory_processing_list%rowtype;
  v_item public.mdm_accessory_processing_item%rowtype;
  v_project uuid;
  v_customer uuid;
  v_parent_material uuid;
  v_bom uuid;
  v_match_count integer;
  v_parent_category uuid;
  v_parent_type uuid;
  v_parent_unit uuid;
  v_parent_type_code text;
  v_parent_unit_code text;
begin
  if p_stage<>'bom' then
    raise exception '请在配件加工清单列表中配置物料编码或生产工单' using errcode='22023';
  end if;
  if auth.uid() is null or not app_private.has_permission('MdmAccessoryProcessing:GenerateBom') then
    raise exception '当前账号没有转项目 BOM 的权限' using errcode='42501';
  end if;
  select * into v_list from public.mdm_accessory_processing_list
  where id=p_list_id for update;
  if not found or not true then
    raise exception '加工清单不存在或不在当前范围内' using errcode='42501';
  end if;
  if v_list.bom_id is not null then
    return jsonb_build_object('projectId',v_list.project_id,'bomId',v_list.bom_id,
      'status',v_list.status,'stage','bom');
  end if;
  if not exists(select 1 from public.mdm_accessory_processing_item where list_id=v_list.id)
     or exists(select 1 from public.mdm_accessory_processing_item
       where list_id=v_list.id and material_id is null) then
    raise exception '请先为清单内每个加工件生成物料编码' using errcode='22023';
  end if;
  if v_list.project_id is not null then
    select id,customer_id into v_project,v_customer from public.mdm_project
    where id=v_list.project_id  and enabled;
    if not found then raise exception '关联项目已失效' using errcode='22023'; end if;
  else
    select count(*) into v_match_count from public.mdm_project
    where btrim(project_name)=btrim(v_list.project_name) and enabled;
    if v_match_count=1 then
      select id into v_project from public.mdm_project
      where btrim(project_name)=btrim(v_list.project_name)
        and enabled limit 1;
    elsif v_match_count>1 then
      raise exception '同名项目有多条，请先明确选择系统项目' using errcode='22023';
    else
      if v_list.customer_id is null or not exists(select 1 from public.mdm_customer
        where id=v_list.customer_id  and enabled) then
        raise exception '新建项目前请先选择有效客户' using errcode='22023';
      end if;
      insert into public.mdm_project(project_code,project_name,customer_id,source)
      values('PJACC'||upper(replace(v_list.id::text,'-','')),
        btrim(v_list.project_name),v_list.customer_id,'manual')
      returning id into v_project;
    end if;
  end if;
  select category_id,material_type_id,base_unit_id
  into v_parent_category,v_parent_type,v_parent_unit
  from public.mdm_accessory_processing_item
  where list_id=v_list.id order by line_no limit 1;
  select type_code into v_parent_type_code from public.mdm_material_type
  where id=v_parent_type ;
  select unit_code into v_parent_unit_code from public.mdm_unit_of_measure
  where id=v_parent_unit ;
  insert into public.mdm_material (category_id,material_code,material_name,specification_model,
    basic_unit,material_type,material_type_id,material_source,description,base_unit_id
  ) values (coalesce(v_list.category_id,v_parent_category),
    'ACC-PJ-'||upper(replace(v_list.id::text,'-','')),
    left(v_list.project_name||'配件总成',120),left(v_list.drawing_name,120),
    left(v_parent_unit_code,40),left(v_parent_type_code,40),v_parent_type,
    'self_made','由配件加工清单生成的项目 BOM 父项',v_parent_unit
  ) returning id into v_parent_material;
  insert into public.mdm_bom (bom_code,material_id,version,purpose,status,
    base_quantity,base_unit_id,project_id,description
  ) values ('BOM-ACC-'||upper(replace(v_list.id::text,'-','')),
    v_parent_material,'1','production','design',1,v_parent_unit,v_project,
    left('配件加工清单：'||v_list.drawing_name,500)
  ) returning id into v_bom;
  for v_item in select * from public.mdm_accessory_processing_item
    where list_id=v_list.id order by line_no
  loop
    insert into public.mdm_bom_item (bom_id,component_material_id,sequence_no,quantity,unit_id,position_no,remark
    ) values (v_bom,v_item.material_id,v_item.line_no*10,v_item.quantity,
      v_item.base_unit_id,v_item.row_no::text,left(v_item.remark,500)
    );
  end loop;
  update public.mdm_accessory_processing_list
  set project_id=v_project,bom_id=v_bom,
    status=case when status='generated' then 'generated' else 'bom_ready' end
  where id=v_list.id;
  return jsonb_build_object('projectId',v_project,'bomId',v_bom,'status',
    case when v_list.status='generated' then 'generated' else 'bom_ready' end,'stage','bom');
end
$function$;

--
-- Name: mdm_generate_material_code_internal; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_generate_material_code_internal(p_rule_id uuid, p_material_type_id uuid DEFAULT NULL::uuid, p_category_id uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rule public.mdm_material_code_rule%rowtype;
  v_segment jsonb;
  v_ordinality bigint;
  v_padding_index bigint;
  v_before_padding text := '';
  v_after_padding text := '';
  v_piece text;
  v_sequence text;
  v_padding integer;
  v_code text;
begin
  if (select auth.uid()) is null then
    raise exception '请先登录后再生成物料编码' using errcode = '42501';
  end if;
  if not (
    app_private.has_permission('MdmMaterialArchive:GenerateCode')
    or app_private.has_permission('MdmMaterialArchive:Add')
    or app_private.has_permission('MdmAccessoryProcessing:GenerateMaterial')
  ) then
    raise exception '当前账号没有生成物料编码的权限' using errcode = '42501';
  end if;

  select *
  into v_rule
  from public.mdm_material_code_rule
  where id = p_rule_id
    and status = 'enabled'
  for update;

  if not found then
    raise exception '编码规则不存在或已停用' using errcode = 'P0002';
  end if;

  select coalesce(
    max(segment.ordinality) filter (where segment.value->>'source' = 'fixed'),
    jsonb_array_length(v_rule.segments) + 1
  )
  into v_padding_index
  from jsonb_array_elements(v_rule.segments) with ordinality as segment(value, ordinality);

  for v_segment, v_ordinality in
    select segment.value, segment.ordinality
    from jsonb_array_elements(v_rule.segments) with ordinality as segment(value, ordinality)
    order by segment.ordinality
  loop
    v_piece := case v_segment->>'source'
      when 'fixed' then upper(coalesce(v_segment->>'value', ''))
      when 'material_type' then (
        select nullif(upper(btrim(code_prefix)), '')
        from public.mdm_material_type
        where id = p_material_type_id
          
          and status = 'enabled'
      )
      when 'material_category' then (
        select nullif(upper(btrim(code_prefix)), '')
        from public.mdm_material_category
        where id = p_category_id
          
          and status = 'enabled'
      )
      when 'date' then case v_segment->>'format'
        when 'YYYY' then to_char(current_date, 'YYYY')
        when 'YYYYMM' then to_char(current_date, 'YYYYMM')
        else to_char(current_date, 'YYYYMMDD')
      end
      else null
    end;

    if v_piece is null and v_segment->>'source' = 'material_type' then
      raise exception '所选物料类型不存在、已停用或未配置编码前缀' using errcode = '22023';
    end if;
    if v_piece is null and v_segment->>'source' = 'material_category' then
      raise exception '所选物料分类不存在、已停用或未配置编码前缀' using errcode = '22023';
    end if;

    if v_ordinality < v_padding_index then
      v_before_padding := v_before_padding || coalesce(v_piece, '');
    else
      v_after_padding := v_after_padding || coalesce(v_piece, '');
    end if;
  end loop;

  v_sequence := lpad(v_rule.next_value::text, v_rule.sequence_digits, '0');
  if char_length(v_sequence) > v_rule.sequence_digits then
    raise exception '编码流水已超过配置位数，请调整规则' using errcode = '22003';
  end if;

  v_padding := v_rule.code_length
    - char_length(v_before_padding)
    - char_length(v_after_padding)
    - char_length(v_rule.prefix)
    - char_length(v_sequence);
  if v_padding < 0 then
    raise exception '编码结果超过规则总长度，请调整号段、固定字段或流水位数' using errcode = '22023';
  end if;

  v_code := v_before_padding
    || repeat('0', v_padding)
    || v_after_padding
    || upper(v_rule.prefix)
    || v_sequence;

  update public.mdm_material_code_rule
  set next_value = next_value + 1
  where id = v_rule.id;

  return v_code;
end
$function$;

--
-- Name: mdm_non_working_statutory_holiday_dates; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_non_working_statutory_holiday_dates(p_department_id uuid, p_start_date date, p_end_date date)
 RETURNS TABLE(work_date date)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with recursive production_scope as (
  select d.id,d.parent_id,d.organization_id,0 depth,array[d.id] visited
  from public.mdm_production_department d
  where d.id=p_department_id 
  union all
  select d.id,d.parent_id,d.organization_id,s.depth+1,s.visited||d.id
  from public.mdm_production_department d
  join production_scope s on d.id=s.parent_id
  where not d.id=any(s.visited)
), linked_org as (
  select organization_id from production_scope
  where organization_id is not null order by depth limit 1
), org_scope as (
  select o.id,o.parent_id,0 depth,array[o.id] visited
  from public.mdm_organization o
  join linked_org l on l.organization_id=o.id
  where true
  union all
  select o.id,o.parent_id,s.depth+1,s.visited||o.id
  from public.mdm_organization o
  join org_scope s on o.id=s.parent_id
  where not o.id=any(s.visited)
)
select distinct dates.day::date work_date
from public.smis_statutory_holiday h
join org_scope o on o.id=h.organization_id
cross join lateral generate_series(
  greatest(h.start_date,p_start_date)::timestamp,
  least(h.end_date,p_end_date)::timestamp,
  interval '1 day'
) dates(day)
where h.holiday_type<>'makeup_work'
  and h.start_date<=p_end_date and h.end_date>=p_start_date
order by work_date
$function$;

--
-- Name: mdm_operational_master_guard; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_operational_master_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_domain text; v_id uuid;
begin
 v_domain:=case tg_table_name when 'mdm_customer' then 'customer' when 'mdm_project' then 'project' when 'mdm_operation' then 'operation' else null end;
 if new.group_id is not null and not exists(select 1 from public.mdm_master_group g where g.id=new.group_id  and g.domain=v_domain) then
  raise exception '所选分组不可用' using errcode='23503';
 end if;
 if tg_table_name='mdm_operation' then
  foreach v_id in array new.work_center_ids loop
   if not exists(select 1 from public.mdm_work_center c where c.id=v_id ) then raise exception '工作中心不可用' using errcode='23503'; end if;
  end loop;
 end if;
 return new;
end $function$;

