--
-- Name: mdm_production_reference_list; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_production_reference_list(p_kind text, p_keyword text, p_from integer, p_to integer, p_route_id uuid, p_center_id uuid, p_bound boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; term text:=replace(replace(replace(coalesce(p_keyword,''),'\','\\'),'%','\%'),'_','\_');
begin
 if auth.uid() is null or not(app_private.has_permission('MdmWorkCenter:View') or app_private.has_permission('MdmOperationTemplate:View') or app_private.has_permission('MdmProcessRoute:View')) then raise exception '没有查看生产配置权限' using errcode='42501';end if;
 if p_from<0 or p_to<p_from or p_to-p_from>999 then raise exception '分页范围无效';end if;
 if p_kind='routes' then
 with source as(select r.*,jsonb_build_object('id',m.id,'material_code',m.material_code,'material_name',m.material_name,'specification_model',m.specification_model) material from public.mdm_process_route r join public.mdm_material m on m.id=r.material_id  where r.name ilike '%'||term||'%'),page as(select * from source order by create_time desc limit p_to-p_from+1 offset p_from)
 select jsonb_build_object('records',coalesce((select jsonb_agg(to_jsonb(p)) from page p),'[]'),'total',(select count(*) from source)) into result;
 elsif p_kind='steps' then
 with source as(select s.*,jsonb_build_object('id',r.id,'name',r.name,'material',jsonb_build_object('id',m.id,'material_code',m.material_code,'material_name',m.material_name,'specification_model',m.specification_model)) route,
 case when t.id is not null then jsonb_build_object('id',t.id,'name',t.name,'total_score',t.total_score) end template,
 case when c.id is not null then jsonb_build_object('id',c.id,'code',c.code,'name',c.name) end work_center
 from public.mdm_process_route_step s join public.mdm_process_route r on r.id=s.route_id  join public.mdm_material m on m.id=r.material_id  left join public.mdm_operation_template t on t.id=s.template_id  left join public.mdm_work_center c on c.id=s.work_center_id 
 where (p_route_id is null or s.route_id=p_route_id) and (p_center_id is null or s.work_center_id=p_center_id) and (p_bound is null or (s.template_id is not null)=p_bound) and (s.code ilike '%'||term||'%' or s.name ilike '%'||term||'%' or m.material_code ilike '%'||term||'%' or m.material_name ilike '%'||term||'%' or m.specification_model ilike '%'||term||'%' or r.name ilike '%'||term||'%' or t.name ilike '%'||term||'%')),page as(select * from source order by sort,code limit p_to-p_from+1 offset p_from)
 select jsonb_build_object('records',coalesce((select jsonb_agg(to_jsonb(p)) from page p),'[]'),'total',(select count(*) from source)) into result;
 elsif p_kind='devices' and app_private.has_permission('MdmWorkCenter:View') then
 select jsonb_build_object('records',coalesce(jsonb_agg(to_jsonb(d)||jsonb_build_object('equipment',jsonb_build_object('id',e.id,'equipment_code',e.equipment_code,'equipment_name',e.equipment_name))),'[]'),'total',count(*)) into result from public.mdm_work_center_device d join public.mdm_equipment e on e.id=d.equipment_id  where d.work_center_id=p_center_id;
 else raise exception '未知生产配置查询';end if;return result;
end $function$;

--
-- Name: mdm_production_reference_options; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_production_reference_options(p_kind text, p_keyword text, p_from integer, p_to integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;term text:=replace(replace(replace(coalesce(p_keyword,''),'\','\\'),'%','\%'),'_','\_');
begin
 if auth.uid() is null or not ((p_kind='material' and app_private.has_permission('MdmProcessRoute:View')) or (p_kind='equipment' and app_private.has_permission('MdmWorkCenter:View'))) then raise exception '没有查看生产参选数据权限' using errcode='42501';end if;
 if p_from<0 or p_to<p_from or p_to-p_from>999 then raise exception '分页范围无效';end if;
 if p_kind='material' then
 with source as(select id,material_code,material_name,specification_model from public.mdm_material where (material_code ilike '%'||term||'%' or material_name ilike '%'||term||'%')), page as(select * from source order by material_code limit p_to-p_from+1 offset p_from)
 select jsonb_build_object('records',coalesce((select jsonb_agg(to_jsonb(p)) from page p),'[]'),'total',(select count(*) from source)) into result;
 else
 with source as(select id,equipment_code,equipment_name from public.mdm_equipment where (equipment_code ilike '%'||term||'%' or equipment_name ilike '%'||term||'%')), page as(select * from source order by equipment_code limit p_to-p_from+1 offset p_from)
 select jsonb_build_object('records',coalesce((select jsonb_agg(to_jsonb(p)) from page p),'[]'),'total',(select count(*) from source)) into result;
 end if;return result;
end $function$;

--
-- Name: mdm_quality_issue_state_audit; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_quality_issue_state_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_action text;
  v_comment text;
  v_actor_user_id uuid;
  v_actor_email text;
begin
  if tg_op = 'UPDATE' and new.state is not distinct from old.state then
    return new;
  end if;

  v_action := coalesce(
    nullif(current_setting('app.mdm_issue_action', true), ''),
    case when tg_op = 'INSERT' then 'detected' else 'system_reassessment' end
  );
  v_comment := nullif(current_setting('app.mdm_issue_comment', true), '');

  begin
    v_actor_user_id := app_private.mdm_current_actor_user_id();
    v_actor_email := app_private.mdm_current_actor_email();
  exception when sqlstate '42501' then
    v_actor_user_id := null;
    v_actor_email := 'system';
  end;

  insert into public.mdm_quality_issue_event (
    issue_id,
    from_state,
    to_state,
    action,
    actor_user_id,
    actor_email,
    comment,
    event_data
  ) values (
    new.id,
    case when tg_op = 'UPDATE' then old.state else null end,
    new.state,
    v_action,
    v_actor_user_id,
    v_actor_email,
    v_comment,
    jsonb_build_object(
      'observedStatus', new.observed_status,
      'severity', new.severity,
      'detectionCount', new.detection_count
    )
  );

  perform app_private.mdm_emit_outbox_event('quality_issue',
    new.id,
    'mdm.quality-issue.' || replace(new.state, '_', '-'),
    jsonb_build_object(
      'issueId', new.id,
      'ruleId', new.rule_id,
      'sourceType', new.source_type,
      'sourceRecordId', new.source_record_id,
      'state', new.state,
      'observedStatus', new.observed_status,
      'dueAt', new.due_at
    )
  );

  return new;
end
$function$;

--
-- Name: mdm_refresh_process_route_path; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_refresh_process_route_path(p_route_id uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with next_path as (
    select coalesce(
      string_agg(
        coalesce(nullif(btrim(step.name), ''), step.code),
        '→'
        order by step.sort, step.code, step.id
      ),
      ''
    ) as value
    from public.mdm_process_route_step step
    where step.route_id = p_route_id
  )
  update public.mdm_process_route route
  set path = next_path.value
  from next_path
  where route.id = p_route_id
    and route.path is distinct from next_path.value
$function$;

--
-- Name: mdm_require_esop_write; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_require_esop_write(p_permission text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then
    raise exception '请先登录后再维护 ESOP' using errcode = '42501';
  end if;

  if not app_private.has_permission(p_permission) then
    raise exception '当前账号没有此 ESOP 操作权限' using errcode = '42501';
  end if;
end;
$function$;

--
-- Name: mdm_save_accessory_processing_draft_internal; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_save_accessory_processing_draft_internal(p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_item_id uuid;
  v_existing public.mdm_accessory_processing_list%rowtype;
  v_source text;
  v_item jsonb;
  v_line integer := 0;
  v_sketch text;
  v_images jsonb;
  v_project uuid;
  v_customer uuid;
  v_category uuid;
  v_item_category uuid;
  v_default_type uuid;
  v_item_type uuid;
  v_default_unit uuid;
  v_item_unit uuid;
  v_item_source text;
  v_item_spec text;
  v_width numeric;
  v_length numeric;
  v_mode text := coalesce(nullif(p_payload->>'mode',''),'SaveDraft');
  v_rule uuid;
  v_copy_item uuid;
begin
  if auth.uid() is null or v_mode not in ('SaveDraft','Add','Edit','Copy')
     or not app_private.has_permission('MdmAccessoryProcessing:'||v_mode) then
    raise exception '当前账号没有保存加工清单的权限' using errcode='42501';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception '清单内容无效' using errcode='22023';
  end if;
  if v_mode = 'Copy' then
    v_copy_item := nullif(p_payload->>'sourceItemId','')::uuid;
    if v_copy_item is null then
      raise exception '复制操作缺少来源加工件' using errcode='22023';
    end if;
    perform 1
      from public.mdm_accessory_processing_item i
      join public.mdm_accessory_processing_list l on l.id=i.list_id
      where i.id=v_copy_item ;
    if not found then
      raise exception '来源加工件不存在' using errcode='42501';
    end if;
  end if;
  v_source := nullif(btrim(p_payload->>'sourcePath'),'');
  if v_source is not null then
    if split_part(v_source,'/',3) <> 'source'
       or not exists (
         select 1 from storage.objects o
         where o.bucket_id='mdm-accessory-processing' and o.name=v_source
       ) then
      raise exception '加工清单原件不存在' using errcode='22023';
    end if;
  end if;
  if nullif(btrim(p_payload->>'projectName'),'') is null then
    raise exception '请填写项目名称' using errcode='22023';
  end if;
  if jsonb_typeof(p_payload->'items') <> 'array'
     or jsonb_array_length(p_payload->'items') not between 1 and 100 then
    raise exception '加工清单需要 1 至 100 个加工件' using errcode='22023';
  end if;
  v_project := nullif(p_payload->>'projectId','')::uuid;
  v_customer := nullif(p_payload->>'customerId','')::uuid;
  v_category := nullif(p_payload->>'categoryId','')::uuid;
  if v_project is not null and not exists (
    select 1 from public.mdm_project where id=v_project  and enabled
  ) then raise exception '所选项目不可用' using errcode='22023'; end if;
  if v_customer is not null and not exists (
    select 1 from public.mdm_customer where id=v_customer  and enabled
  ) then raise exception '所选客户不可用' using errcode='22023'; end if;
  if v_category is null then
    select id into v_category from public.mdm_material_category
    where status='enabled' and category_name='配件'
    order by case when category_code='B59' then 0 else 1 end,id limit 1;
  end if;
  if v_category is null or not exists (
    select 1 from public.mdm_material_category
    where id=v_category  and status='enabled'
  ) then raise exception '请先选择有效的配件物料分类' using errcode='22023'; end if;
  select id into v_default_type from public.mdm_material_type
    where status='enabled' and type_name='半成品'
    order by id limit 1;
  select id into v_default_unit from public.mdm_unit_of_measure
    where status='enabled'
      and (upper(unit_name)='PC' or upper(coalesce(symbol,''))='PC'
           or upper(unit_code)='PC' or unit_name='件')
    order by case when upper(unit_name)='PC' then 0
                  when upper(coalesce(symbol,''))='PC' then 1
                  when upper(unit_code)='PC' then 2 else 3 end,id limit 1;
  v_id := nullif(p_payload->>'id','')::uuid;
  if v_id is not null then
    select * into v_existing from public.mdm_accessory_processing_list
    where id=v_id  for update;
    if v_mode not in ('SaveDraft','Edit') or not found or v_existing.status <> 'draft'
       or exists (select 1 from public.mdm_accessory_processing_item
                  where list_id=v_id and material_id is not null) then
      raise exception '草稿不存在或不可编辑' using errcode='42501';
    end if;
    if v_existing.source_path is distinct from v_source then
      raise exception '更换原件请新建清单' using errcode='22023';
    end if;
    update public.mdm_accessory_processing_list set
      source_name=left(p_payload->>'sourceName',255),
      project_name=left(btrim(p_payload->>'projectName'),160),
      drawing_name=left(coalesce(p_payload->>'drawingName',''),160),
      project_id=v_project, customer_id=v_customer, category_id=v_category,
      confidence=least(1,greatest(0,coalesce((p_payload->>'confidence')::numeric,0))),
      warnings=coalesce(p_payload->'warnings','[]'::jsonb)
    where id=v_id;
    delete from public.mdm_accessory_processing_item where list_id=v_id;
  else
    if v_mode not in ('SaveDraft','Add','Copy') then
      raise exception '新增清单操作无效' using errcode='22023';
    end if;
    v_id := gen_random_uuid();
    insert into public.mdm_accessory_processing_list (
      id,auth_user_id,source_path,source_name,project_name,drawing_name,
      project_id,customer_id,category_id,confidence,warnings
    ) values (
      v_id,auth.uid(),v_source,left(p_payload->>'sourceName',255),
      left(btrim(p_payload->>'projectName'),160),left(coalesce(p_payload->>'drawingName',''),160),
      v_project,v_customer,v_category,
      least(1,greatest(0,coalesce((p_payload->>'confidence')::numeric,0))),
      coalesce(p_payload->'warnings','[]'::jsonb)
    );
  end if;
  for v_item in select value from jsonb_array_elements(p_payload->'items') loop
    v_line := v_line + 1;
    v_sketch := nullif(v_item->>'sketchPath','');
    if v_sketch is not null and (
      (v_source is not null and split_part(v_sketch,'/',2) <> split_part(v_source,'/',2))
      or split_part(v_sketch,'/',3) <> 'sketch'
      or not exists (
        select 1 from storage.objects o where o.bucket_id='mdm-accessory-processing'
          and o.name=v_sketch
      )
    ) then raise exception '第 % 个加工件草图无效',v_line using errcode='22023'; end if;
    v_images := coalesce(v_item->'imageUrls','[]'::jsonb);
    if jsonb_typeof(v_images)<>'array' then
      raise exception '第 % 个加工件图片无效',v_line using errcode='22023';
    end if;
    if jsonb_array_length(v_images)>5
       or exists(select 1 from jsonb_array_elements(v_images) as image(value)
         where jsonb_typeof(image.value)<>'string' or length(image.value #>> '{}')>2048
           or image.value #>> '{}' !~ '^https://') then
      raise exception '第 % 个加工件图片无效',v_line using errcode='22023';
    end if;
    v_item_category := coalesce(nullif(v_item->>'categoryId','')::uuid,v_category);
    v_item_type := coalesce(nullif(v_item->>'materialTypeId','')::uuid,v_default_type);
    v_item_unit := coalesce(nullif(v_item->>'baseUnitId','')::uuid,v_default_unit);
    v_item_source := coalesce(nullif(v_item->>'materialSource',''),'self_made');
    v_rule := nullif(v_item->>'codeRuleId','')::uuid;
    if v_rule is null then
      select id into v_rule from public.mdm_material_code_rule
      where status='enabled'
      order by case when strategy='material_type' then 0 else 1 end,sort,id limit 1;
    end if;
    if v_rule is not null and not exists (
      select 1 from public.mdm_material_code_rule
      where id=v_rule  and status='enabled'
    ) then raise exception '第 % 个加工件编码策略无效',v_line using errcode='22023'; end if;
    if not exists (select 1 from public.mdm_material_category where id=v_item_category
       and status='enabled') then
      raise exception '第 % 个加工件物料分类无效',v_line using errcode='22023';
    end if;
    if v_item_type is null or not exists (select 1 from public.mdm_material_type
      where id=v_item_type  and status='enabled') then
      raise exception '第 % 个加工件物料类型无效',v_line using errcode='22023';
    end if;
    if v_item_unit is null or not exists (select 1 from public.mdm_unit_of_measure
      where id=v_item_unit  and status='enabled') then
      raise exception '第 % 个加工件基本单位无效',v_line using errcode='22023';
    end if;
    if v_item_source not in ('purchase','self_made','outsourcing') then
      raise exception '第 % 个加工件物料来源无效',v_line using errcode='22023';
    end if;
    v_width := nullif(v_item->>'widthMm','')::numeric;
    v_length := (v_item->>'lengthM')::numeric;
    v_item_spec := coalesce(nullif(btrim(v_item->>'specificationModel'),''),
      '展宽 '||coalesce(v_width::text,'—')||' mm × 长度 '||v_length::text||' m');
    v_item_id := gen_random_uuid();
    insert into public.mdm_accessory_processing_item (
      id,list_id,line_no,row_no,name,width_mm,length_m,quantity,
      material_color,remark,sketch_path,image_urls,sketch_bounds,material_code,
      specification_model,base_unit_id,material_type_id,material_source,category_id,code_rule_id
    ) values (
      v_item_id,v_id,v_line,(v_item->>'rowNo')::integer,btrim(v_item->>'name'),
      v_width,v_length,(v_item->>'quantity')::integer,
      left(coalesce(v_item->>'materialColor',''),160),
      left(coalesce(v_item->>'remark',''),500),v_sketch,v_images,v_item->'sketch',
      null,
      left(v_item_spec,120),v_item_unit,v_item_type,v_item_source,v_item_category,v_rule
    );
  end loop;
  return v_id;
end $function$;

--
-- Name: mdm_save_bom_with_assignments; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_save_bom_with_assignments(p_header jsonb, p_items jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_bom_id uuid; v_material_id uuid; v_route_id uuid;
 v_first_step_id uuid; v_item jsonb; v_step_id uuid; v_step_name text; v_type_id uuid;
begin
 v_bom_id:=public.mdm_save_bom(p_header,p_items);
 select material_id into v_material_id from public.mdm_bom where id=v_bom_id for update;
 v_route_id:=nullif(p_header->>'process_route_id','')::uuid;
 if v_route_id is null then
   select route.id into v_route_id from public.mdm_process_route route
   where route.material_id=v_material_id and route.enabled
   order by route.is_default desc,route.update_time desc,route.id limit 1;
 elsif not exists(select 1 from public.mdm_process_route route where route.id=v_route_id
    and route.material_id=v_material_id and route.enabled) then
   raise exception '所选工艺路线不可用，或不属于当前 BOM 父项物料' using errcode='23503';
 end if;
 update public.mdm_bom set process_route_id=v_route_id,update_time=now()
 where id=v_bom_id ;
 select step.id into v_first_step_id from public.mdm_process_route_step step
 join public.mdm_process_route_sequence sequence
 on sequence.id=step.sequence_id 
 where step.route_id=v_route_id 
 order by sequence.sequence_no,step.sort,step.code,step.id limit 1;
 for v_item in select value from jsonb_array_elements(p_items) loop
   v_step_id:=coalesce(nullif(v_item->>'process_route_step_id','')::uuid,v_first_step_id);
   v_type_id:=nullif(v_item->>'component_type_id','')::uuid;
   v_step_name:=null;
   if v_step_id is not null then
     select step.name into v_step_name from public.mdm_process_route_step step
     where step.id=v_step_id  and step.route_id=v_route_id;
     if not found then raise exception '组件所选工序不属于 BOM 关联的工艺路线' using errcode='23503'; end if;
   end if;
   if v_type_id is not null and not exists(select 1 from public.mdm_component_type
       where id=v_type_id ) then
     raise exception '组件类型不存在' using errcode='23503';
   end if;
   update public.mdm_bom_item item set process_route_step_id=v_step_id,
     operation_name=v_step_name,component_type_id=v_type_id,update_time=now()
   where item.bom_id=v_bom_id 
     and item.component_material_id=(v_item->>'component_material_id')::uuid
     and item.sequence_no=coalesce((v_item->>'sequence_no')::integer,10);
 end loop;
 return v_bom_id;
end $function$;

--
-- Name: mdm_save_work_center_with_activities; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_save_work_center_with_activities(p_center_id uuid, p_center jsonb, p_activities jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_target_id uuid := coalesce(p_center_id, gen_random_uuid());
  v_department_id uuid := nullif(p_center->>'department_id', '')::uuid;
  v_control_code_id uuid := nullif(p_center->>'operation_control_code_id', '')::uuid;
  v_person_ids uuid[];
begin
  if auth.uid() is null then
    raise exception '请先登录' using errcode = '42501';
  end if;

  if jsonb_typeof(coalesce(p_activities, '[]'::jsonb)) <> 'array'
    or jsonb_array_length(coalesce(p_activities, '[]'::jsonb)) > 100
  then
    raise exception '活动信息格式无效或超过 100 行';
  end if;

  perform 1 from public.mdm_production_department d where d.id = v_department_id;
  if not found then
    raise exception '所属产线不存在或不在当前工作范围内';
  end if;



  if p_center_id is null then
    if not (
      app_private.has_permission('MdmWorkCenter:Add')
      or app_private.has_permission('MdmWorkCenter:Copy')
    ) then
      raise exception '没有新增工作中心权限' using errcode = '42501';
    end if;
  else
    if not app_private.has_permission('MdmWorkCenter:Edit') then
      raise exception '没有编辑工作中心权限' using errcode = '42501';
    end if;

    if not exists (
      select 1
        from public.mdm_work_center c
       where c.id = p_center_id

    ) then
      raise exception '工作中心不存在或不在当前工作范围内';
    end if;
  end if;

  if v_control_code_id is not null
    and not exists (
      select 1
        from public.mdm_operation_control_code c
       where c.id = v_control_code_id
         and c.enabled
    )
  then
    raise exception '所选工序控制码无效';
  end if;

  select coalesce(array_agg(value::uuid), '{}'::uuid[])
    into v_person_ids
    from jsonb_array_elements_text(coalesce(p_center->'person_ids', '[]'::jsonb));

  if p_center_id is null then
    insert into public.mdm_work_center (
      id,
      code,
      name,
      department_id,
      operation_control_code_id,
      main_center_id,
      personnel_mode,
      headcount,
      person_ids,
      capacity_mode,
      daily_capacity_minutes,
      efficiency_percent,
      utilization_percent,
      parallel_capacity,
      queue_minutes,
      policy,
      sort,
      remark
    )
    values (
      v_target_id,
      btrim(p_center->>'code'),
      btrim(p_center->>'name'),
      v_department_id,
      v_control_code_id,
      nullif(p_center->>'main_center_id', '')::uuid,
      coalesce(nullif(p_center->>'personnel_mode', ''), '指定人数'),
      coalesce((p_center->>'headcount')::integer, 1),
      v_person_ids,
      coalesce(nullif(p_center->>'capacity_mode', ''), 'finite'),
      coalesce((p_center->>'daily_capacity_minutes')::integer, 480),
      coalesce((p_center->>'efficiency_percent')::numeric, 100),
      coalesce((p_center->>'utilization_percent')::numeric, 100),
      coalesce((p_center->>'parallel_capacity')::integer, 1),
      coalesce((p_center->>'queue_minutes')::numeric, 0),
      coalesce(p_center->'policy', '{}'::jsonb),
      coalesce((p_center->>'sort')::integer, 0),
      coalesce(p_center->>'remark', '')
    );
  else
    update public.mdm_work_center as wc
       set code = btrim(p_center->>'code'),
           name = btrim(p_center->>'name'),
           department_id = v_department_id,
           operation_control_code_id = v_control_code_id,
           main_center_id = nullif(p_center->>'main_center_id', '')::uuid,
           personnel_mode = coalesce(nullif(p_center->>'personnel_mode', ''), '指定人数'),
           headcount = coalesce((p_center->>'headcount')::integer, 1),
           person_ids = v_person_ids,
           capacity_mode = coalesce(nullif(p_center->>'capacity_mode', ''), 'finite'),
           daily_capacity_minutes = coalesce((p_center->>'daily_capacity_minutes')::integer, 480),
           efficiency_percent = coalesce((p_center->>'efficiency_percent')::numeric, 100),
           utilization_percent = coalesce((p_center->>'utilization_percent')::numeric, 100),
           parallel_capacity = coalesce((p_center->>'parallel_capacity')::integer, 1),
           queue_minutes = coalesce((p_center->>'queue_minutes')::numeric, 0),
           policy = coalesce(p_center->'policy', '{}'::jsonb),
           sort = coalesce((p_center->>'sort')::integer, 0),
           remark = coalesce(p_center->>'remark', '')
     where wc.id = v_target_id;
  end if;

  if exists (
    select 1
      from jsonb_array_elements(coalesce(p_activities, '[]'::jsonb)) as item
     where (
       nullif(item->>'plan_formula_id', '') is not null
       and not exists (
         select 1
           from public.mdm_activity_formula f
          where f.id = (item->>'plan_formula_id')::uuid
            and f.enabled
       )
     )
     or (
       nullif(item->>'report_formula_id', '') is not null
       and not exists (
         select 1
           from public.mdm_activity_formula f
          where f.id = (item->>'report_formula_id')::uuid
            and f.enabled
       )
     )
  ) then
    raise exception '活动信息中包含无效公式';
  end if;

  delete from public.mdm_work_center_activity a
   where a.work_center_id = v_target_id;

  insert into public.mdm_work_center_activity (
    work_center_id,
    activity_name,
    activity_type,
    maintenance_rule,
    base_quantity,
    activity_unit,
    plan_formula_id,
    report_formula_id,
    backflush,
    remark,
    sort
  )
  select
    v_target_id,
    item->>'activity_name',
    item->>'activity_type',
    coalesce(nullif(item->>'maintenance_rule', ''), 'no_check'),
    round(coalesce((item->>'base_quantity')::numeric, 0), 2),
    coalesce(nullif(item->>'activity_unit', ''), 'minute'),
    nullif(item->>'plan_formula_id', '')::uuid,
    nullif(item->>'report_formula_id', '')::uuid,
    coalesce((item->>'backflush')::boolean, false),
    coalesce(item->>'remark', ''),
    ordinal::integer - 1
  from jsonb_array_elements(coalesce(p_activities, '[]'::jsonb))
       with ordinality as activity_rows(item, ordinal);

  return v_target_id;
end
$function$;

--
-- Name: mdm_set_accessory_processing_project_internal; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_set_accessory_processing_project_internal(p_list_id uuid, p_project_id uuid, p_customer_id uuid, p_project_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_list public.mdm_accessory_processing_list%rowtype;
  v_project_name text;
  v_customer_id uuid;
begin
  if auth.uid() is null
     or not app_private.has_permission('MdmAccessoryProcessing:SaveDraft') then
    raise exception '当前账号没有修改项目归属的权限' using errcode='42501';
  end if;
  select * into v_list from public.mdm_accessory_processing_list
  where id=p_list_id for update;
  if not found or not true then
    raise exception '加工清单不存在或不可用' using errcode='42501';
  end if;
  if v_list.status not in ('draft','materials_ready') then
    raise exception '当前阶段不可修改项目归属' using errcode='22023';
  end if;
  if p_project_id is not null then
    select project_name,customer_id into v_project_name,v_customer_id
    from public.mdm_project
    where id=p_project_id  and enabled;
    if not found then
      raise exception '所选项目不可用或已停用' using errcode='22023';
    end if;
  else
    v_project_name := nullif(btrim(p_project_name),'');
    if v_project_name is null then
      raise exception '请填写项目名称' using errcode='22023';
    end if;
    v_customer_id := p_customer_id;
    if v_customer_id is not null and not exists (
      select 1 from public.mdm_customer
      where id=v_customer_id  and enabled
    ) then
      raise exception '所选客户不可用或已停用' using errcode='22023';
    end if;
  end if;
  update public.mdm_accessory_processing_list
  set project_id=p_project_id,
      customer_id=v_customer_id
  where id=v_list.id;
end
$function$;

--
-- Name: mdm_shift_schedule_occurrence_overlap; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_shift_schedule_occurrence_overlap(p_left_start date, p_left_end date, p_left_weekdays smallint[], p_right_start date, p_right_end date, p_right_weekdays smallint[])
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
with bounds as (
  select greatest(p_left_start,p_right_start) start_date,
    least(coalesce(p_left_end,'infinity'::date),coalesce(p_right_end,'infinity'::date)) end_date
), candidate_dates as (
  select day::date work_date from bounds
  cross join lateral generate_series(
    start_date::timestamp,least(end_date,start_date+6)::timestamp,interval '1 day'
  ) day where end_date>=start_date
)
select exists(
  select 1 from candidate_dates
  where extract(dow from work_date)::smallint=any(p_left_weekdays)
    and extract(dow from work_date)::smallint=any(p_right_weekdays)
)
$function$;

--
-- Name: mdm_shift_schedule_range; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_shift_schedule_range(p_start date, p_end date)
 RETURNS daterange
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$ select daterange(p_start,coalesce(p_end,'infinity'::date),'[]') $function$;

--
-- Name: mdm_sync_material_category_code_prefix; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_sync_material_category_code_prefix()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
begin
 if nullif(btrim(new.code_prefix),'') is null then new.code_prefix:=btrim(new.category_code);
 elsif tg_op='UPDATE' and btrim(old.code_prefix)=btrim(old.category_code)
   and new.code_prefix is not distinct from old.code_prefix
   and new.category_code is distinct from old.category_code then new.code_prefix:=btrim(new.category_code);
 else new.code_prefix:=btrim(new.code_prefix); end if;
 return new;
end; $function$;

--
-- Name: mdm_sync_process_route_path; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_sync_process_route_path()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'DELETE' then
    perform app_private.mdm_refresh_process_route_path(old.route_id);
  elsif tg_op = 'UPDATE' and new.route_id is distinct from old.route_id then
    perform app_private.mdm_refresh_process_route_path(old.route_id);
    perform app_private.mdm_refresh_process_route_path(new.route_id);
  else
    perform app_private.mdm_refresh_process_route_path(new.route_id);
  end if;
  return null;
end
$function$;

--
-- Name: mdm_sync_process_step_work_centers; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_sync_process_step_work_centers()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_normalized uuid[];
begin
  if cardinality(coalesce(new.work_center_ids, '{}'::uuid[])) = 0
     and new.work_center_id is not null then
    new.work_center_ids := array[new.work_center_id];
  end if;

  select coalesce(array_agg(item_id order by first_ordinal), '{}'::uuid[])
  into v_normalized
  from (
    select item_id, min(ordinality) as first_ordinal
    from unnest(coalesce(new.work_center_ids, '{}'::uuid[]))
      with ordinality as selected(item_id, ordinality)
    group by item_id
  ) deduplicated;

  new.work_center_ids := v_normalized;
  new.work_center_id := new.work_center_ids[1];

  if exists (
    select 1
    from unnest(new.work_center_ids) selected(item_id)
    left join public.mdm_work_center center on center.id = selected.item_id
    where center.id is null
  ) then
    raise exception '工作中心不存在' using errcode = '23503';
  end if;

  if new.department_id is not null and exists (
    select 1
    from unnest(new.work_center_ids) selected(item_id)
    join public.mdm_work_center center on center.id = selected.item_id
    where center.department_id <> new.department_id
  ) then
    raise exception '工作中心必须属于所选车间' using errcode = '23514';
  end if;

  return new;
end
$function$;

--
-- Name: mdm_update_accessory_processing_item_internal; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_update_accessory_processing_item_internal(p_item_id uuid, p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_item public.mdm_accessory_processing_item%rowtype;
  v_list public.mdm_accessory_processing_list%rowtype;
  v_type uuid := nullif(p_payload->>'materialTypeId','')::uuid;
  v_unit uuid := nullif(p_payload->>'baseUnitId','')::uuid;
  v_category uuid := nullif(p_payload->>'categoryId','')::uuid;
  v_rule uuid := nullif(p_payload->>'codeRuleId','')::uuid;
  v_source text := p_payload->>'materialSource';
  v_sketch text := nullif(p_payload->>'sketchPath','');
  v_images jsonb := coalesce(p_payload->'imageUrls','[]'::jsonb);
begin
  if auth.uid() is null or not app_private.has_permission('MdmAccessoryProcessing:Edit') then
    raise exception '当前账号没有编辑加工件的权限' using errcode='42501';
  end if;
  if jsonb_typeof(p_payload)<>'object' then
    raise exception '加工件内容无效' using errcode='22023';
  end if;
  select * into v_item from public.mdm_accessory_processing_item
  where id=p_item_id for update;
  if not found then
    raise exception '加工件不存在或不在可操作范围内' using errcode='42501';
  end if;
  select * into v_list from public.mdm_accessory_processing_list
  where id=v_item.list_id for update;
  if v_item.material_id is not null or exists(select 1 from public.mes_work_order
    where accessory_item_id=v_item.id and deleted_at is null) then
    raise exception '已生成物料或工单的加工件不可编辑' using errcode='22023';
  end if;
  if not exists(select 1 from public.mdm_material_type
    where id=v_type  and status='enabled')
    or not exists(select 1 from public.mdm_unit_of_measure
    where id=v_unit  and status='enabled')
    or not exists(select 1 from public.mdm_material_category
    where id=v_category  and status='enabled')
    or (v_rule is not null and not exists(select 1 from public.mdm_material_code_rule
      where id=v_rule  and status='enabled'))
    or v_source not in ('purchase','self_made','outsourcing') then
    raise exception '物料属性已失效，请重新选择' using errcode='22023';
  end if;
  if v_sketch is not null and (
    split_part(v_sketch,'/',3) <> 'sketch'
    or (v_list.source_path is not null and split_part(v_sketch,'/',2) <>
      split_part(v_list.source_path,'/',2))
    or not exists(select 1 from storage.objects
      where bucket_id='mdm-accessory-processing' and name=v_sketch)
  ) then raise exception '加工草图无效' using errcode='22023'; end if;
  if jsonb_typeof(v_images)<>'array' then
    raise exception '加工件图片无效' using errcode='22023';
  end if;
  if jsonb_array_length(v_images)>5
     or exists(select 1 from jsonb_array_elements(v_images) as image(value)
       where jsonb_typeof(image.value)<>'string' or length(image.value #>> '{}')>2048
         or image.value #>> '{}' !~ '^https://') then
    raise exception '加工件图片无效' using errcode='22023';
  end if;
  update public.mdm_accessory_processing_item set
    row_no=(p_payload->>'rowNo')::integer,
    name=left(btrim(p_payload->>'name'),160),
    width_mm=nullif(p_payload->>'widthMm','')::numeric,
    length_m=(p_payload->>'lengthM')::numeric,
    quantity=(p_payload->>'quantity')::integer,
    material_color=left(coalesce(p_payload->>'materialColor',''),160),
    remark=left(coalesce(p_payload->>'remark',''),500),
    specification_model=left(coalesce(nullif(btrim(p_payload->>'specificationModel'),''),
      '展宽 '||coalesce(p_payload->>'widthMm','—')||' mm × 长度 '||
      (p_payload->>'lengthM')||' m'),120),
    base_unit_id=v_unit,material_type_id=v_type,material_source=v_source,
    category_id=v_category,code_rule_id=v_rule,sketch_path=v_sketch,image_urls=v_images
  where id=p_item_id;
end
$function$;

--
-- Name: mdm_work_center_activities; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_work_center_activities(p_center_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 if auth.uid() is null or not(app_private.has_permission('MdmWorkCenter:View') or app_private.has_permission('MdmWorkCenter:Edit')) then raise exception '没有查看工作中心活动权限' using errcode='42501';end if;
 if not exists(select 1 from public.mdm_work_center c where c.id=p_center_id) then raise exception '工作中心不存在或不在当前工作范围内';end if;
 select coalesce(jsonb_agg(to_jsonb(a)||jsonb_build_object('plan_formula',case when pf.id is null then null else jsonb_build_object('id',pf.id,'code',pf.code,'name',pf.name,'expression',pf.plan_expression) end,'report_formula',case when rf.id is null then null else jsonb_build_object('id',rf.id,'code',rf.code,'name',rf.name,'expression',rf.report_expression) end) order by a.sort,a.id),'[]'::jsonb) into result
 from public.mdm_work_center_activity a left join public.mdm_activity_formula pf on pf.id=a.plan_formula_id  left join public.mdm_activity_formula rf on rf.id=a.report_formula_id  where a.work_center_id=p_center_id;
 return result;
end$function$;

--
-- Name: mdm_work_center_reference_options; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.mdm_work_center_reference_options(p_kind text, p_keyword text DEFAULT ''::text, p_from integer DEFAULT 0, p_to integer DEFAULT 9, p_center_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  result jsonb;
  term text := coalesce(p_keyword, '');
begin
  if auth.uid() is null
    or not (
      app_private.has_permission('MdmWorkCenter:View')
      or app_private.has_permission('MdmWorkCenter:Add')
      or app_private.has_permission('MdmWorkCenter:Edit')
      or app_private.has_permission('MdmWorkCenter:Copy')
      or app_private.has_permission('MdmWorkCenter:Devices')
    )
  then
    raise exception '没有查看工作中心参选数据权限' using errcode = '42501';
  end if;

  if p_from < 0 or p_to < p_from or p_to - p_from > 999 then
    raise exception '分页范围无效';
  end if;





  if p_kind = 'control_code' then
    with source as (
      select i.id, i.control_code as code, i.control_code_name as name
        from public.mdm_operation_control_code i
where i.enabled
         and (
           i.control_code ilike '%' || term || '%'
           or i.control_code_name ilike '%' || term || '%'
         )
    ),
    page as (
      select * from source order by code limit p_to - p_from + 1 offset p_from
    )
    select jsonb_build_object(
      'records', coalesce((select jsonb_agg(to_jsonb(i)) from page i), '[]'::jsonb),
      'total', (select count(*) from source)
    ) into result;
  elsif p_kind = 'activity_formula' then
    with source as (
      select i.id, i.code, i.name, i.activity_type, i.plan_expression, i.report_expression
        from public.mdm_activity_formula i
where i.enabled
         and (
           i.code ilike '%' || term || '%'
           or i.name ilike '%' || term || '%'
         )
    ),
    page as (
      select * from source order by code limit p_to - p_from + 1 offset p_from
    )
    select jsonb_build_object(
      'records', coalesce((select jsonb_agg(to_jsonb(i)) from page i), '[]'::jsonb),
      'total', (select count(*) from source)
    ) into result;
  elsif p_kind = 'equipment' then
    with source as (
      select i.id, i.equipment_code as code, i.equipment_name as name
        from public.mdm_equipment i
where i.status = 'enabled'
         and not exists (
           select 1 from public.mdm_work_center_device b where b.equipment_id = i.id
         )
         and (
           i.equipment_code ilike '%' || term || '%'
           or i.equipment_name ilike '%' || term || '%'
         )
    ),
    page as (
      select * from source order by code limit p_to - p_from + 1 offset p_from
    )
    select jsonb_build_object(
      'records', coalesce((select jsonb_agg(to_jsonb(i)) from page i), '[]'::jsonb),
      'total', (select count(*) from source)
    ) into result;
  else
    raise exception '未知工作中心参选类型';
  end if;

  return result;
end
$function$;

--
-- Name: next_document_number; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.next_document_number(p_rule_key text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rule public.sys_document_number_rule;
  v_now timestamptz := clock_timestamp();
  v_period_key text;
  v_sequence bigint;
  v_width integer;
  v_result text;
begin

  select * into v_rule
  from public.sys_document_number_rule
  where rule_key = p_rule_key and enabled;
  if not found then
    raise exception '未找到已启用的编号规则：%', p_rule_key;
  end if;
  if not v_rule.auto_enabled then
    raise exception '编号规则 % 已切换为手工填写', v_rule.rule_name;
  end if;

  v_period_key := app_private.document_number_period_key(
    v_rule.reset_cycle, v_now, v_rule.timezone
  );
  insert into public.sys_document_number_counter (
    rule_id, rule_version, period_key, current_value, create_by, update_by
  ) values (
    v_rule.id, v_rule.rule_version, v_period_key, v_rule.sequence_start,
    coalesce(nullif(auth.jwt() ->> 'email', ''), 'number-engine'),
    coalesce(nullif(auth.jwt() ->> 'email', ''), 'number-engine')
  )
  on conflict (rule_id, rule_version, period_key)
  do update set
    current_value = public.sys_document_number_counter.current_value + 1,
    update_time = now(),
    update_by = coalesce(nullif(auth.jwt() ->> 'email', ''), 'number-engine')
  returning current_value into v_sequence;

  v_width := substring(v_rule.template from '\{SEQ:([1-9][0-9]?)\}')::integer;
  if length(v_sequence::text) > v_width then
    raise exception '编号规则 % 的 % 位流水号已用尽，请调整模板', v_rule.rule_name, v_width;
  end if;

  v_result := v_rule.template;
  v_result := replace(v_result, '{YYYYMMDD}', to_char(v_now at time zone v_rule.timezone, 'YYYYMMDD'));
  v_result := replace(v_result, '{YYYYMM}', to_char(v_now at time zone v_rule.timezone, 'YYYYMM'));
  v_result := replace(v_result, '{YYMM}', to_char(v_now at time zone v_rule.timezone, 'YYMM'));
  v_result := replace(v_result, '{YYYY}', to_char(v_now at time zone v_rule.timezone, 'YYYY'));
  v_result := replace(v_result, '{YY}', to_char(v_now at time zone v_rule.timezone, 'YY'));
  v_result := replace(v_result, '{MM}', to_char(v_now at time zone v_rule.timezone, 'MM'));
  v_result := replace(v_result, '{DD}', to_char(v_now at time zone v_rule.timezone, 'DD'));
  return regexp_replace(v_result, '\{SEQ:[1-9][0-9]?\}', lpad(v_sequence::text, v_width, '0'));
end;
$function$;

--
-- Name: next_fms_voucher_no; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.next_fms_voucher_no(p_account_set_id uuid, p_fiscal_year smallint, p_period_no smallint, p_voucher_type text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_sequence bigint;
  v_prefix text;
begin
  insert into public.fms_voucher_number_counter ( account_set_id, fiscal_year, period_no, voucher_type, current_value
  ) values ( p_account_set_id, p_fiscal_year, p_period_no, p_voucher_type, 1)
  on conflict (account_set_id, fiscal_year, period_no, voucher_type)
  do update set current_value = public.fms_voucher_number_counter.current_value + 1
  returning current_value into v_sequence;

  v_prefix := case p_voucher_type
    when 'receipt' then '收'
    when 'payment' then '付'
    when 'transfer' then '转'
    when 'adjustment' then '调'
    when 'closing' then '结'
    when 'reversal' then '冲'
    else '记'
  end;
  return format('%s-%s%s-%s', v_prefix, p_fiscal_year, lpad(p_period_no::text, 2, '0'), lpad(v_sequence::text, 6, '0'));
end;
$function$;

--
-- Name: normalize_mdm_business_type; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.normalize_mdm_business_type()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  new.business_type_code := upper(btrim(new.business_type_code));
  new.business_type_name := btrim(new.business_type_name);
  new.inventory_direction := nullif(lower(btrim(coalesce(new.inventory_direction,''))),'');
  new.owner_type := nullif(lower(btrim(coalesce(new.owner_type,''))),'');
  new.remark := btrim(coalesce(new.remark,''));
  new.text_color := upper(btrim(coalesce(new.text_color,'')));
  new.tag_style := lower(btrim(coalesce(new.tag_style,'')));

  if new.source_business_type_id = new.id then
    raise exception '源业务类型不能选择当前业务类型' using errcode='23514';
  end if;
  if new.is_default and not new.enabled then
    raise exception '默认业务类型必须保持启用' using errcode='23514';
  end if;
  if new.is_default then
    update public.mdm_business_type sibling
    set is_default=false
    where true
      and sibling.document_type_id=new.document_type_id
      and sibling.id is distinct from new.id
      and sibling.is_default;
  end if;
  return new;
end
$function$;

--
-- Name: normalize_mdm_document_type; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.normalize_mdm_document_type()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_menu_type text;
begin
  new.document_type_code := upper(btrim(new.document_type_code));
  new.document_type_name := btrim(new.document_type_name);
  new.remark := btrim(coalesce(new.remark,''));
  new.text_color := upper(btrim(coalesce(new.text_color,'')));
  new.tag_style := lower(btrim(coalesce(new.tag_style,'')));

  select menu.type into v_menu_type from public.sys_menu menu where menu.id=new.menu_id;
  if v_menu_type is distinct from 'menu' then
    raise exception '单据类型必须归属到具体菜单功能' using errcode='22023';
  end if;
  if new.is_default and not new.enabled then
    raise exception '默认单据类型必须保持启用' using errcode='23514';
  end if;
  if new.is_default then
    update public.mdm_document_type sibling
    set is_default=false
    where true
      and sibling.menu_id=new.menu_id
      and sibling.id is distinct from new.id
      and sibling.is_default;
  end if;
  return new;
end
$function$;

--
-- Name: permission_access_rank; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.permission_access_rank(p_access text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case p_access
    when 'edit' then 3
    when 'read' then 2
    when 'masked' then 1
    else 0
  end;
$function$;

