--
-- Name: publish_workflow_definition; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.publish_workflow_definition(p_definition_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_is_platform_super boolean := (select app_private.is_platform_super());
  v_definition public.wf_definition;
  v_version public.wf_version;
  v_actor text := coalesce(nullif(auth.jwt() ->> 'email', ''), auth.uid()::text);
begin
  if (select auth.uid()) is null or not v_is_platform_super then
    raise exception '当前账号没有流程发布权限' using errcode = '42501';
  end if;

  select *
  into v_definition
  from public.wf_definition d
  where d.id = p_definition_id
    
  for update;

  if not found then
    raise exception '流程不存在或无权发布';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(v_definition.business_type, 81173)
  );

  if exists (
    select 1
    from public.wf_definition d
    where true
      and d.business_type = v_definition.business_type
      and d.status = 'published'
      and d.id <> v_definition.id
  ) then
    raise exception '该业务类型已有启用流程，请先停用后再发布';
  end if;

  select *
  into v_version
  from public.wf_version v
  where v.definition_id = v_definition.id
    and v.status = 'draft'
  for update;

  if not found then
    raise exception '没有可发布的草稿版本';
  end if;

  perform app_private.validate_workflow_config(v_version.config);

  update public.wf_version
  set status = 'retired', update_by = v_actor
  where definition_id = v_definition.id
    and status = 'published';

  update public.wf_version
  set status = 'published',
      published_at = now(),
      published_by = v_actor,
      update_by = v_actor
  where id = v_version.id
  returning * into v_version;

  update public.wf_definition
  set status = 'published',
      current_version_id = v_version.id,
      published_at = now(),
      published_by = v_actor,
      update_by = v_actor
  where id = v_definition.id;

  return jsonb_build_object(
    'definitionId', v_definition.id,
    'versionId', v_version.id,
    'versionNo', v_version.version_no);
end;
$function$;

--
-- Name: reference_production_shift_patterns; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.reference_production_shift_patterns(p_source_department_id uuid, p_target_department_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  affected integer;
begin
  if auth.uid() is null
    or app_private.has_permission('MdmFactoryCalendar:View') is not true
    or app_private.has_permission('MdmFactoryCalendar:ReferencePattern') is not true then
    raise exception '没有查看或参考轮班模式权限' using errcode = '42501';
  end if;
  if not exists(select 1 from public.mdm_production_department
    where id = p_source_department_id) then
    raise exception '来源部门不存在或无权访问' using errcode = '42501';
  end if;
  -- Lock the target parent, including against concurrent FK inserts/deletion.
  -- All copy calls retain the established per-target transaction lock as well.
  perform pg_advisory_xact_lock(hashtextextended(p_target_department_id::text, 8722));
  perform 1 from public.mdm_production_department
  where id = p_target_department_id for update;
  if not found then
    raise exception '目标部门不存在或无权访问' using errcode = '42501';
  end if;
  if exists(select 1 from public.mdm_production_shift_pattern
    where department_id = p_target_department_id) then
    raise exception '当前产线已有轮班模式，不能参考其他产线';
  end if;
  insert into public.mdm_production_shift_pattern(
    department_id, name, description, sort, color, shifts
  )
  select p_target_department_id, name, description, sort, color, shifts
  from public.mdm_production_shift_pattern
  where department_id = p_source_department_id;
  get diagnostics affected = row_count;
  if affected = 0 then raise exception '来源产线没有可参考的轮班模式'; end if;
  return affected;
end
$function$;

--
-- Name: refresh_fms_voucher_totals; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.refresh_fms_voucher_totals(p_voucher_id uuid)
 RETURNS void
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  update public.fms_voucher v
  set total_debit = totals.debit,
      total_credit = totals.credit,
      line_count = totals.line_count
  from (
    select coalesce(sum(line.debit_amount), 0)::numeric(20, 2) as debit,
      coalesce(sum(line.credit_amount), 0)::numeric(20, 2) as credit,
      count(*)::integer as line_count
    from public.fms_voucher_line line
    where line.voucher_id = p_voucher_id
  ) totals
  where v.id = p_voucher_id
$function$;

--
-- Name: resolve_field_access; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.resolve_field_access(p_resource_key text, p_field_key text, p_record_owner_id uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid:=app_private.current_app_user_id(); v_field public.sys_permission_field%rowtype; v_access text;
begin
 if auth.uid() is null or v_user is null then return 'hidden'; end if;
 if app_private.is_platform_super() then return 'edit'; end if;
 select f.* into v_field from public.sys_permission_resource r join public.sys_permission_field f on f.resource_id=r.id where r.resource_key=p_resource_key and r.enabled and f.field_key=p_field_key and f.sensitive and f.enabled;
 if not found then return 'hidden'; end if;
 if v_field.owner_override_enabled and p_record_owner_id is not null and p_record_owner_id=v_user then return 'edit'; end if;
 select up.access_level into v_access from public.sys_user_field_permission up where up.user_id=v_user and up.resource_id=v_field.resource_id and up.field_id=v_field.id;
 if found then return v_access; end if;
 select case max(app_private.permission_access_rank(rp.access_level)) when 3 then 'edit' when 2 then 'read' when 1 then 'masked' when 0 then 'hidden' end into v_access
 from public.sys_user u join public.sys_role r on r.enabled and r.role_code=any(coalesce(u.user_roles,array[]::text[])) join public.sys_role_field_permission rp on rp.role_id=r.id and rp.resource_id=v_field.resource_id and rp.field_id=v_field.id
 where u.id=v_user and u.status='1' and u.deleted_at is null;
 return coalesce(v_access,v_field.default_access,'hidden');
end; $function$;

--
-- Name: resolve_fms_posting_account_set; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.resolve_fms_posting_account_set()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_count integer;
begin
  select id into v_id
  from public.fms_account_set
  where true
    and status = 'active'
    and is_default
  order by enabled_on, id
  limit 1;

  if v_id is not null then
    return v_id;
  end if;

  select count(*)::integer into v_count
  from public.fms_account_set
  where true
    and status = 'active';

  if v_count = 1 then
    select id into v_id
    from public.fms_account_set
    where true
      and status = 'active'
    order by enabled_on, id
    limit 1;
    return v_id;
  end if;

  return null;
end;
$function$;

--
-- Name: retry_workflow_business_callback; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.retry_workflow_business_callback(p_outbox_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result text;
begin
  if (select auth.uid()) is null or not (select app_private.is_platform_super()) then
    raise exception '当前账号没有审批回调补偿权限' using errcode = '42501';
  end if;

  update public.wf_business_callback_outbox
  set status = 'pending',
      attempt_count = 0,
      next_attempt_at = now(),
      processed_at = null,
      locked_at = null,
      locked_by = null,
      manual_retry_count = manual_retry_count + 1,
      last_error_code = null,
      last_error = null
  where id = p_outbox_id
    and status in ('retry_wait', 'dead_letter');

  if not found then
    raise exception '仅失败重试中或死信状态的回调允许人工补偿';
  end if;

  v_result := app_private.attempt_workflow_business_callback(
    p_outbox_id,
    'workflow-manual:' || auth.uid()::text
  );

  return jsonb_build_object('id', p_outbox_id, 'status', v_result);
end;
$function$;

--
-- Name: revoke_workflow_delegation; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.revoke_workflow_delegation(p_delegation_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := (select app_private.current_app_user_id());
  v_is_platform_super boolean := (select app_private.is_platform_super());
  v_reason text := btrim(coalesce(p_reason, ''));
  v_delegation public.wf_delegation;
  v_actor_name text;
  v_delegator_name text;
  v_task record;
begin
  if (select auth.uid()) is null or v_user_id is null then
    raise exception '当前登录用户未绑定业务账号';
  end if;
  if char_length(v_reason) not between 4 and 300 then
    raise exception '撤销原因需填写 4 至 300 个字符';
  end if;

  select * into v_delegation
  from public.wf_delegation
  where id = p_delegation_id
    
  for update;

  if not found or (not v_is_platform_super and v_delegation.delegator_user_id <> v_user_id) then
    raise exception '委托不存在或无权撤销' using errcode = '42501';
  end if;
  if v_delegation.revoked_at is not null then return v_delegation.id; end if;

  select coalesce(nullif(nick_name,''), nullif(user_name,''), user_email, id::text)
  into v_actor_name from public.sys_user where id = v_user_id;
  select coalesce(nullif(nick_name,''), nullif(user_name,''), user_email, id::text)
  into v_delegator_name from public.sys_user where id = v_delegation.delegator_user_id;

  update public.wf_delegation
  set revoked_at = now(), revoked_by = v_user_id, revoke_reason = v_reason
  where id = v_delegation.id;

  perform 1
  from public.wf_instance instance
  where instance.id in (
    select task.instance_id from public.wf_task task
    where task.delegation_id = v_delegation.id
      and task.status = 'pending'
  )
  order by instance.id
  for update;

  for v_task in
    select task.*, instance.business_type, instance.business_id, instance.business_title
    from public.wf_task task
    join public.wf_instance instance on instance.id = task.instance_id
    join public.sys_user original_user on original_user.id = task.original_assignee_user_id
    where task.delegation_id = v_delegation.id
      and task.status = 'pending'
      and original_user.status = '1'
    order by task.id
    for update of task
  loop
    update public.wf_task
    set assignee_user_id = v_task.original_assignee_user_id,
        assignee_name_snapshot = v_task.original_assignee_name_snapshot,
        assignment_source = 'direct', delegation_id = null,
        last_assigned_by = v_user_id, assignment_reason = v_reason
    where id = v_task.id;

    insert into public.wf_action(
      instance_id, task_id, node_key, node_name, action,
      actor_user_id, actor_name_snapshot, comment, metadata) values (
      v_task.instance_id, v_task.id, v_task.node_key, v_task.node_name, 'delegation_revoke',
      v_user_id, v_actor_name, v_reason,
      jsonb_build_object(
        'delegationId', v_delegation.id,
        'fromUserId', v_delegation.delegate_user_id,
        'toUserId', v_task.original_assignee_user_id,
        'toUserName', v_task.original_assignee_name_snapshot
      )
    );

    perform app_private.enqueue_user_notification(
      v_task.original_assignee_user_id, 'todo', '委托已撤销，待办已收回',
      '“' || v_task.business_title || '”已恢复由你审批：' || v_reason,
      'info', 'workflow_delegation_revoke', v_task.id,
      v_task.business_type, v_task.business_id, v_task.instance_id,
      '/workflow/workbench', jsonb_build_object('tab','pending','instanceId',v_task.instance_id)
    );
  end loop;

  return v_delegation.id;
end;
$function$;

--
-- Name: save_employee_profile_records_secure; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.save_employee_profile_records_secure(p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_employee_json jsonb := coalesce(p_payload -> 'employee', '{}'::jsonb);
  v_employee_id uuid := nullif(v_employee_json ->> 'id', '')::uuid;
  v_current public.hr_employee%rowtype;
  v_input public.hr_employee%rowtype;
  v_safe_employee jsonb;
  v_create_result jsonb;
  v_owner_id uuid;
  v_contact_access text;
  v_identity_access text;
  v_compensation_access text;
  v_career_access text;
  v_item jsonb;
  v_child_id uuid;
  v_records jsonb;
begin
  if p_payload is null or jsonb_typeof(p_payload) <> 'object'
     or jsonb_typeof(v_employee_json) <> 'object' then
    raise exception '员工档案数据格式不正确';
  end if;
  if exists (
    select 1 from jsonb_object_keys(p_payload) payload_key
    where payload_key <> all(array[
      'employee', 'driver', 'contracts', 'educations',
      'work_experiences', 'trainings', 'rewards'
    ]::text[])
  ) then
    raise exception '员工档案包含不允许写入的模块';
  end if;
  if exists (
    select 1 from jsonb_object_keys(v_employee_json) employee_key
    where employee_key <> all(array[
      'id', 'organization_id', 'employee_no', 'employee_name',
      'avatar_url', 'position_id', 'job_title', 'employment_status', 'employment_type',
      'gender', 'birth_date', 'phone', 'email', 'id_card_no', 'ethnicity',
      'education_level', 'school_name', 'major_name', 'marital_status',
      'political_status', 'native_place', 'home_address', 'hire_date',
      'probation_end_date', 'leave_date', 'contract_start_date', 'contract_end_date',
      'emergency_contact_name', 'emergency_contact_relation',
      'emergency_contact_phone', 'remark'
    ]::text[])
  ) then
    raise exception '员工基础档案包含不允许写入的字段';
  end if;

  if v_employee_id is null then
    if not app_private.can_execute_business_action(
      'HrEmployeeRoster', 'Hr:Employee:Add', null, false
    ) then
      raise exception 'Missing employee create permission' using errcode = '42501';
    end if;

    v_create_result := public.hr_create_employee_with_driver_secure(
      v_employee_json - 'id' - 'job_title',
      case when p_payload -> 'driver' = 'null'::jsonb then null else p_payload -> 'driver' end
    );
    v_employee_id := nullif(v_create_result ->> 'employee_id', '')::uuid;
    if v_employee_id is null then
      raise exception '保存员工基础档案后未返回员工 ID';
    end if;

    select employee_row.* into v_current
    from public.hr_employee employee_row
    where employee_row.id = v_employee_id
    for update;
  else
    if not app_private.can_execute_business_action(
      'HrEmployeeRoster', 'Hr:Employee:Edit', null, false
    ) then
      raise exception 'Missing employee edit permission' using errcode = '42501';
    end if;

    select employee_row.* into v_current
    from public.hr_employee employee_row
    where employee_row.id = v_employee_id

    for update;
    if not found then
      raise exception '员工档案不存在或无权编辑' using errcode = 'P0002';
    end if;

    v_contact_access := app_private.resolve_field_access(
      'hr.employee', 'contactDetails', v_current.created_by_user_id
    );
    v_identity_access := app_private.resolve_field_access(
      'hr.employee', 'identityDetails', v_current.created_by_user_id
    );
    v_career_access := app_private.resolve_field_access(
      'hr.employee', 'careerRecords', v_current.created_by_user_id
    );

    v_safe_employee := v_employee_json - 'id' - 'job_title';
    if v_contact_access <> 'edit' then
      v_safe_employee := v_safe_employee
        - 'phone' - 'email' - 'home_address'
        - 'emergency_contact_name' - 'emergency_contact_relation'
        - 'emergency_contact_phone';
    end if;
    if v_identity_access <> 'edit' then
      v_safe_employee := v_safe_employee
        - 'gender' - 'birth_date' - 'id_card_no' - 'ethnicity'
        - 'education_level' - 'school_name' - 'major_name'
        - 'marital_status' - 'political_status' - 'native_place';
    end if;
    if v_career_access <> 'edit' then
      v_safe_employee := v_safe_employee - 'remark';
    end if;

    select populated.* into v_input
    from jsonb_populate_record(null::public.hr_employee, v_safe_employee) populated;

    if v_safe_employee ? 'organization_id' and not exists (
      select 1 from public.sys_organization organization_row
      where organization_row.id = v_input.organization_id
        
        and organization_row.status = '1'
    ) then
      raise exception '所选组织不存在、已停用或不可用';
    end if;

    update public.hr_employee employee_row
    set
      organization_id = case when v_safe_employee ? 'organization_id' then v_input.organization_id else employee_row.organization_id end,
      employee_no = case when v_safe_employee ? 'employee_no' then btrim(v_input.employee_no) else employee_row.employee_no end,
      employee_name = case when v_safe_employee ? 'employee_name' then btrim(v_input.employee_name) else employee_row.employee_name end,
      avatar_url = case when v_safe_employee ? 'avatar_url' then v_input.avatar_url else employee_row.avatar_url end,
      position_id = case when v_safe_employee ? 'position_id' then v_input.position_id else employee_row.position_id end,
      employment_status = case when v_safe_employee ? 'employment_status' then v_input.employment_status else employee_row.employment_status end,
      employment_type = case when v_safe_employee ? 'employment_type' then v_input.employment_type else employee_row.employment_type end,
      gender = case when v_safe_employee ? 'gender' then v_input.gender else employee_row.gender end,
      birth_date = case when v_safe_employee ? 'birth_date' then v_input.birth_date else employee_row.birth_date end,
      phone = case when v_safe_employee ? 'phone' then v_input.phone else employee_row.phone end,
      email = case when v_safe_employee ? 'email' then v_input.email else employee_row.email end,
      id_card_no = case when v_safe_employee ? 'id_card_no' then v_input.id_card_no else employee_row.id_card_no end,
      ethnicity = case when v_safe_employee ? 'ethnicity' then v_input.ethnicity else employee_row.ethnicity end,
      education_level = case when v_safe_employee ? 'education_level' then v_input.education_level else employee_row.education_level end,
      school_name = case when v_safe_employee ? 'school_name' then v_input.school_name else employee_row.school_name end,
      major_name = case when v_safe_employee ? 'major_name' then v_input.major_name else employee_row.major_name end,
      marital_status = case when v_safe_employee ? 'marital_status' then v_input.marital_status else employee_row.marital_status end,
      political_status = case when v_safe_employee ? 'political_status' then v_input.political_status else employee_row.political_status end,
      native_place = case when v_safe_employee ? 'native_place' then v_input.native_place else employee_row.native_place end,
      home_address = case when v_safe_employee ? 'home_address' then v_input.home_address else employee_row.home_address end,
      hire_date = case when v_safe_employee ? 'hire_date' then v_input.hire_date else employee_row.hire_date end,
      probation_end_date = case when v_safe_employee ? 'probation_end_date' then v_input.probation_end_date else employee_row.probation_end_date end,
      leave_date = case when v_safe_employee ? 'leave_date' then v_input.leave_date else employee_row.leave_date end,
      contract_start_date = case when v_safe_employee ? 'contract_start_date' then v_input.contract_start_date else employee_row.contract_start_date end,
      contract_end_date = case when v_safe_employee ? 'contract_end_date' then v_input.contract_end_date else employee_row.contract_end_date end,
      emergency_contact_name = case when v_safe_employee ? 'emergency_contact_name' then v_input.emergency_contact_name else employee_row.emergency_contact_name end,
      emergency_contact_relation = case when v_safe_employee ? 'emergency_contact_relation' then v_input.emergency_contact_relation else employee_row.emergency_contact_relation end,
      emergency_contact_phone = case when v_safe_employee ? 'emergency_contact_phone' then v_input.emergency_contact_phone else employee_row.emergency_contact_phone end,
      remark = case when v_safe_employee ? 'remark' then v_input.remark else employee_row.remark end
    where employee_row.id = v_employee_id
    returning employee_row.* into v_current;
  end if;

  v_owner_id := v_current.created_by_user_id;
  v_contact_access := app_private.resolve_field_access(
    'hr.employee', 'contactDetails', v_owner_id
  );
  v_compensation_access := app_private.resolve_field_access(
    'hr.employee', 'compensationDetails', v_owner_id
  );
  v_career_access := app_private.resolve_field_access(
    'hr.employee', 'careerRecords', v_owner_id
  );

  if p_payload ? 'contracts' then
    v_records := coalesce(p_payload -> 'contracts', '[]'::jsonb);
    if jsonb_typeof(v_records) <> 'array' then
      raise exception '劳动合同数据格式不正确';
    end if;

    if v_career_access = 'edit' then
      if exists (
        select 1 from jsonb_array_elements(v_records) record_row
        where nullif(record_row ->> 'id', '') is not null
          and not exists (
            select 1 from public.hr_employee_contract child_row
            where child_row.id = (record_row ->> 'id')::uuid
              and child_row.employee_id = v_employee_id
              
          )
      ) then raise exception '劳动合同包含不属于当前员工的记录'; end if;

      delete from public.hr_employee_contract child_row
      where child_row.employee_id = v_employee_id
        
        and child_row.id not in (
          select (record_row ->> 'id')::uuid
          from jsonb_array_elements(v_records) record_row
          where nullif(record_row ->> 'id', '') is not null
        );

      for v_item in select value from jsonb_array_elements(v_records) loop
        v_child_id := coalesce(nullif(v_item ->> 'id', '')::uuid, gen_random_uuid());
        insert into public.hr_employee_contract(
          id, employee_id, contract_no, contract_type, contract_status,
          sign_date, start_date, end_date, probation_end_date, work_location,
          monthly_salary, remark
        ) values (
          v_child_id, v_employee_id,
          btrim(v_item ->> 'contract_no'),
          coalesce(nullif(v_item ->> 'contract_type', ''), 'fixed_term'),
          coalesce(nullif(v_item ->> 'contract_status', ''), 'active'),
          nullif(v_item ->> 'sign_date', '')::date,
          nullif(v_item ->> 'start_date', '')::date,
          nullif(v_item ->> 'end_date', '')::date,
          nullif(v_item ->> 'probation_end_date', '')::date,
          nullif(v_item ->> 'work_location', ''),
          case when v_compensation_access = 'edit'
            then nullif(v_item ->> 'monthly_salary', '')::numeric else null end,
          nullif(v_item ->> 'remark', '')
        )
        on conflict (id) do update set
          contract_no = excluded.contract_no,
          contract_type = excluded.contract_type,
          contract_status = excluded.contract_status,
          sign_date = excluded.sign_date,
          start_date = excluded.start_date,
          end_date = excluded.end_date,
          probation_end_date = excluded.probation_end_date,
          work_location = excluded.work_location,
          monthly_salary = case when v_compensation_access = 'edit'
            then excluded.monthly_salary else hr_employee_contract.monthly_salary end,
          remark = excluded.remark;
      end loop;
    elsif v_compensation_access = 'edit' then
      for v_item in select value from jsonb_array_elements(v_records) loop
        if nullif(v_item ->> 'id', '') is not null and v_item ? 'monthly_salary' then
          update public.hr_employee_contract child_row
          set monthly_salary = nullif(v_item ->> 'monthly_salary', '')::numeric
          where child_row.id = (v_item ->> 'id')::uuid
            and child_row.employee_id = v_employee_id
            ;
        end if;
      end loop;
    end if;
  end if;

  if p_payload ? 'educations' and v_career_access = 'edit' then
    v_records := coalesce(p_payload -> 'educations', '[]'::jsonb);
    if jsonb_typeof(v_records) <> 'array' then raise exception '教育经历数据格式不正确'; end if;
    if exists (
      select 1 from jsonb_array_elements(v_records) record_row
      where nullif(record_row ->> 'id', '') is not null
        and not exists (
          select 1 from public.hr_employee_education child_row
          where child_row.id = (record_row ->> 'id')::uuid
            and child_row.employee_id = v_employee_id
            
        )
    ) then raise exception '教育经历包含不属于当前员工的记录'; end if;

    delete from public.hr_employee_education child_row
    where child_row.employee_id = v_employee_id
      
      and child_row.id not in (
        select (record_row ->> 'id')::uuid
        from jsonb_array_elements(v_records) record_row
        where nullif(record_row ->> 'id', '') is not null
      );

    for v_item in select value from jsonb_array_elements(v_records) loop
      v_child_id := coalesce(nullif(v_item ->> 'id', '')::uuid, gen_random_uuid());
      insert into public.hr_employee_education(
        id, employee_id, school_name, major_name, education_level,
        degree, start_date, end_date, full_time, certificate_no, remark
      ) values (
        v_child_id, v_employee_id,
        btrim(v_item ->> 'school_name'), nullif(v_item ->> 'major_name', ''),
        btrim(v_item ->> 'education_level'), nullif(v_item ->> 'degree', ''),
        nullif(v_item ->> 'start_date', '')::date,
        nullif(v_item ->> 'end_date', '')::date,
        coalesce((v_item ->> 'full_time')::boolean, true),
        nullif(v_item ->> 'certificate_no', ''), nullif(v_item ->> 'remark', '')
      )
      on conflict (id) do update set
        school_name = excluded.school_name,
        major_name = excluded.major_name,
        education_level = excluded.education_level,
        degree = excluded.degree,
        start_date = excluded.start_date,
        end_date = excluded.end_date,
        full_time = excluded.full_time,
        certificate_no = excluded.certificate_no,
        remark = excluded.remark;
    end loop;
  end if;

  if p_payload ? 'work_experiences' and v_career_access = 'edit' then
    v_records := coalesce(p_payload -> 'work_experiences', '[]'::jsonb);
    if jsonb_typeof(v_records) <> 'array' then raise exception '工作经历数据格式不正确'; end if;
    if exists (
      select 1 from jsonb_array_elements(v_records) record_row
      where nullif(record_row ->> 'id', '') is not null
        and not exists (
          select 1 from public.hr_employee_work_experience child_row
          where child_row.id = (record_row ->> 'id')::uuid
            and child_row.employee_id = v_employee_id
            
        )
    ) then raise exception '工作经历包含不属于当前员工的记录'; end if;

    delete from public.hr_employee_work_experience child_row
    where child_row.employee_id = v_employee_id
      
      and child_row.id not in (
        select (record_row ->> 'id')::uuid
        from jsonb_array_elements(v_records) record_row
        where nullif(record_row ->> 'id', '') is not null
      );

    for v_item in select value from jsonb_array_elements(v_records) loop
      v_child_id := coalesce(nullif(v_item ->> 'id', '')::uuid, gen_random_uuid());
      insert into public.hr_employee_work_experience(
        id, employee_id, company_name, department_name, job_title,
        start_date, end_date, responsibilities, leaving_reason,
        reference_name, reference_phone
      ) values (
        v_child_id, v_employee_id,
        btrim(v_item ->> 'company_name'), nullif(v_item ->> 'department_name', ''),
        btrim(v_item ->> 'job_title'), nullif(v_item ->> 'start_date', '')::date,
        nullif(v_item ->> 'end_date', '')::date,
        nullif(v_item ->> 'responsibilities', ''),
        nullif(v_item ->> 'leaving_reason', ''),
        case when v_contact_access = 'edit'
          then nullif(v_item ->> 'reference_name', '') else null end,
        case when v_contact_access = 'edit'
          then nullif(v_item ->> 'reference_phone', '') else null end
      )
      on conflict (id) do update set
        company_name = excluded.company_name,
        department_name = excluded.department_name,
        job_title = excluded.job_title,
        start_date = excluded.start_date,
        end_date = excluded.end_date,
        responsibilities = excluded.responsibilities,
        leaving_reason = excluded.leaving_reason,
        reference_name = case when v_contact_access = 'edit'
          then excluded.reference_name else hr_employee_work_experience.reference_name end,
        reference_phone = case when v_contact_access = 'edit'
          then excluded.reference_phone else hr_employee_work_experience.reference_phone end;
    end loop;
  end if;

  if p_payload ? 'trainings' then
    v_records := coalesce(p_payload -> 'trainings', '[]'::jsonb);
    if jsonb_typeof(v_records) <> 'array' then raise exception '培训经历数据格式不正确'; end if;

    if v_career_access = 'edit' then
      if exists (
        select 1 from jsonb_array_elements(v_records) record_row
        where nullif(record_row ->> 'id', '') is not null
          and not exists (
            select 1 from public.hr_employee_training child_row
            where child_row.id = (record_row ->> 'id')::uuid
              and child_row.employee_id = v_employee_id
              
          )
      ) then raise exception '培训经历包含不属于当前员工的记录'; end if;

      delete from public.hr_employee_training child_row
      where child_row.employee_id = v_employee_id
        
        and child_row.id not in (
          select (record_row ->> 'id')::uuid
          from jsonb_array_elements(v_records) record_row
          where nullif(record_row ->> 'id', '') is not null
        );

      for v_item in select value from jsonb_array_elements(v_records) loop
        v_child_id := coalesce(nullif(v_item ->> 'id', '')::uuid, gen_random_uuid());
        insert into public.hr_employee_training(
          id, employee_id, training_name, training_type, provider_name,
          start_date, end_date, training_result, certificate_name, certificate_no,
          cost, remark
        ) values (
          v_child_id, v_employee_id,
          btrim(v_item ->> 'training_name'), btrim(v_item ->> 'training_type'),
          nullif(v_item ->> 'provider_name', ''),
          nullif(v_item ->> 'start_date', '')::date,
          nullif(v_item ->> 'end_date', '')::date,
          nullif(v_item ->> 'training_result', ''),
          nullif(v_item ->> 'certificate_name', ''),
          nullif(v_item ->> 'certificate_no', ''),
          case when v_compensation_access = 'edit'
            then nullif(v_item ->> 'cost', '')::numeric else null end,
          nullif(v_item ->> 'remark', '')
        )
        on conflict (id) do update set
          training_name = excluded.training_name,
          training_type = excluded.training_type,
          provider_name = excluded.provider_name,
          start_date = excluded.start_date,
          end_date = excluded.end_date,
          training_result = excluded.training_result,
          certificate_name = excluded.certificate_name,
          certificate_no = excluded.certificate_no,
          cost = case when v_compensation_access = 'edit'
            then excluded.cost else hr_employee_training.cost end,
          remark = excluded.remark;
      end loop;
    elsif v_compensation_access = 'edit' then
      for v_item in select value from jsonb_array_elements(v_records) loop
        if nullif(v_item ->> 'id', '') is not null and v_item ? 'cost' then
          update public.hr_employee_training child_row
          set cost = nullif(v_item ->> 'cost', '')::numeric
          where child_row.id = (v_item ->> 'id')::uuid
            and child_row.employee_id = v_employee_id
            ;
        end if;
      end loop;
    end if;
  end if;

  if p_payload ? 'rewards' then
    v_records := coalesce(p_payload -> 'rewards', '[]'::jsonb);
    if jsonb_typeof(v_records) <> 'array' then raise exception '奖惩经历数据格式不正确'; end if;

    if v_career_access = 'edit' then
      if exists (
        select 1 from jsonb_array_elements(v_records) record_row
        where nullif(record_row ->> 'id', '') is not null
          and not exists (
            select 1 from public.hr_employee_reward child_row
            where child_row.id = (record_row ->> 'id')::uuid
              and child_row.employee_id = v_employee_id
              
          )
      ) then raise exception '奖惩经历包含不属于当前员工的记录'; end if;

      delete from public.hr_employee_reward child_row
      where child_row.employee_id = v_employee_id
        
        and child_row.id not in (
          select (record_row ->> 'id')::uuid
          from jsonb_array_elements(v_records) record_row
          where nullif(record_row ->> 'id', '') is not null
        );

      for v_item in select value from jsonb_array_elements(v_records) loop
        v_child_id := coalesce(nullif(v_item ->> 'id', '')::uuid, gen_random_uuid());
        insert into public.hr_employee_reward(
          id, employee_id, record_type, record_level, title,
          record_date, issuing_organization, amount, description
        ) values (
          v_child_id, v_employee_id,
          btrim(v_item ->> 'record_type'), nullif(v_item ->> 'record_level', ''),
          btrim(v_item ->> 'title'), nullif(v_item ->> 'record_date', '')::date,
          nullif(v_item ->> 'issuing_organization', ''),
          case when v_compensation_access = 'edit'
            then nullif(v_item ->> 'amount', '')::numeric else null end,
          nullif(v_item ->> 'description', '')
        )
        on conflict (id) do update set
          record_type = excluded.record_type,
          record_level = excluded.record_level,
          title = excluded.title,
          record_date = excluded.record_date,
          issuing_organization = excluded.issuing_organization,
          amount = case when v_compensation_access = 'edit'
            then excluded.amount else hr_employee_reward.amount end,
          description = excluded.description;
      end loop;
    elsif v_compensation_access = 'edit' then
      for v_item in select value from jsonb_array_elements(v_records) loop
        if nullif(v_item ->> 'id', '') is not null and v_item ? 'amount' then
          update public.hr_employee_reward child_row
          set amount = nullif(v_item ->> 'amount', '')::numeric
          where child_row.id = (v_item ->> 'id')::uuid
            and child_row.employee_id = v_employee_id
            ;
        end if;
      end loop;
    end if;
  end if;

  return v_employee_id;
end;
$function$;

--
-- Name: save_workflow_definition; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.save_workflow_definition(p_definition jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_is_platform_super boolean := (select app_private.is_platform_super());
  v_definition public.wf_definition;
  v_version public.wf_version;
  v_definition_id uuid;
  v_config jsonb := coalesce(p_definition -> 'config', '{"nodes":[]}'::jsonb);
  v_actor text;
begin
  if (select auth.uid()) is null or not v_is_platform_super then
    raise exception '当前账号没有流程配置权限' using errcode = '42501';
  end if;

  perform app_private.validate_workflow_config(v_config);
  v_actor := coalesce(nullif(auth.jwt() ->> 'email', ''), auth.uid()::text);

  begin
    v_definition_id := nullif(p_definition ->> 'id', '')::uuid;
  exception
    when invalid_text_representation then
      raise exception '流程 ID 格式不正确';
  end;

  if v_definition_id is null then



    insert into public.wf_definition(
      code,
      name,
      business_type,
      description,
      create_by,
      update_by
    )
    values (
      btrim(p_definition ->> 'code'),
      btrim(p_definition ->> 'name'),
      btrim(p_definition ->> 'businessType'),
      nullif(btrim(coalesce(p_definition ->> 'description', '')), ''),
      v_actor,
      v_actor
    )
    returning * into v_definition;

    insert into public.wf_version(
      definition_id,
      version_no,
      config,
      change_note,
      create_by,
      update_by
    )
    values (
      v_definition.id,
      1,
      v_config,
      nullif(btrim(coalesce(p_definition ->> 'changeNote', '')), ''),
      v_actor,
      v_actor
    )
    returning * into v_version;
  else
    select *
    into v_definition
    from public.wf_definition d
    where d.id = v_definition_id
      
    for update;

    if not found then
      raise exception '流程不存在或无权编辑';
    end if;


    if v_definition.current_version_id is not null and (
      v_definition.code <> btrim(p_definition ->> 'code')
      or v_definition.business_type <> btrim(p_definition ->> 'businessType')
    ) then
      raise exception '流程发布后不可修改流程编码和业务类型';
    end if;

    update public.wf_definition
    set name = btrim(p_definition ->> 'name'),
        description = nullif(btrim(coalesce(p_definition ->> 'description', '')), ''),
        update_by = v_actor
    where id = v_definition.id
    returning * into v_definition;

    select *
    into v_version
    from public.wf_version v
    where v.definition_id = v_definition.id
      and v.status = 'draft'
    for update;

    if found then
      update public.wf_version
      set config = v_config,
          change_note = nullif(btrim(coalesce(p_definition ->> 'changeNote', '')), ''),
          update_by = v_actor
      where id = v_version.id
      returning * into v_version;
    else
      insert into public.wf_version(
        definition_id,
        version_no,
        config,
        change_note,
        create_by,
        update_by
      )
      select v_definition.id,
             coalesce(max(v.version_no), 0) + 1,
             v_config,
             nullif(btrim(coalesce(p_definition ->> 'changeNote', '')), ''),
             v_actor,
             v_actor
      from public.wf_version v
      where v.definition_id = v_definition.id
      returning * into v_version;
    end if;
  end if;

  return jsonb_build_object(
    'definitionId', v_definition.id,
    'versionId', v_version.id,
    'versionNo', v_version.version_no);
end;
$function$;

--
-- Name: scm_purchase_permission_prefix; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.scm_purchase_permission_prefix(p_kind text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case p_kind
    when 'purchase_contract' then 'ScmPurchaseContract'
    when 'purchase_request' then 'ScmPurchaseRequest'
    when 'purchase_order' then 'ScmPurchaseOrder'
    when 'receipt_notice' then 'ScmReceiptNotice'
    else '' end
$function$;

--
-- Name: scm_quote_source_of_truth; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.scm_quote_source_of_truth()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_source public.scm_sales_document%rowtype; v_details jsonb;
begin
 if new.kind='sales_quotation' then
  v_details:=coalesce(new.details,'{}'::jsonb);
  if v_details->>'quotation_scene' not in ('standard','project') then
   raise exception '请选择标准产品或项目工程报价场景' using errcode='23514';
  end if;
  if v_details->>'quotation_scene'='standard' and new.project_id is null then
   raise exception '标准产品报价须关联已有项目' using errcode='23514';
  end if;
  if v_details->>'quotation_scene'='project' then
   if nullif(btrim(v_details->>'construction_no'),'') is null then raise exception '工程报价须填写施工号' using errcode='23514'; end if;
   if new.project_id is null and (not coalesce((v_details->>'auto_create_project')::boolean,false) or nullif(btrim(v_details->>'planned_project_name'),'') is null) then
    raise exception '工程报价须选择项目，或启用自动建项目并填写项目名称' using errcode='23514';
   end if;
   if (coalesce((v_details->>'auto_create_materials')::boolean,false) or coalesce((v_details->>'auto_build_bom')::boolean,false)) and
      (nullif(v_details->>'material_category_id','') is null or nullif(v_details->>'base_unit_id','') is null or nullif(v_details->>'material_code_rule_id','') is null) then
    raise exception '请完整配置工程物料分类、单位和编码规则' using errcode='23514';
   end if;
   if coalesce((v_details->>'auto_build_bom')::boolean,false) and not coalesce((v_details->>'auto_create_materials')::boolean,false) and
      exists(select 1 from jsonb_array_elements(new.lines) line where nullif(line->>'material_id','') is null) then
    raise exception '未编码工程子目须启用自动建物料才能搭建 BOM' using errcode='23514';
   end if;
   if nullif(v_details->>'material_category_id','') is not null and not exists(select 1 from public.mdm_material_category where id=(v_details->>'material_category_id')::uuid  and status='enabled') then raise exception '工程物料分类与报价组织不一致或已停用' using errcode='23514'; end if;
   if nullif(v_details->>'base_unit_id','') is not null and not exists(select 1 from public.mdm_unit_of_measure where id=(v_details->>'base_unit_id')::uuid  and status='enabled') then raise exception '工程基本单位与报价组织不一致或已停用' using errcode='23514'; end if;
   if nullif(v_details->>'material_code_rule_id','') is not null and not exists(select 1 from public.mdm_material_code_rule where id=(v_details->>'material_code_rule_id')::uuid  and status='enabled') then raise exception '工程编码规则与报价组织不一致或已停用' using errcode='23514'; end if;
  end if;
  return new;
 end if;
 if new.kind<>'project_quotation' then return new; end if;
 if current_setting('app.scm_project_activation',true)=new.id::text then return new; end if;
 if tg_op='UPDATE' and old.status<>'created' then return new; end if;
 if tg_op='UPDATE' and new.source_id is distinct from old.source_id then
  raise exception '项目报价创建后不可更换来源销售报价' using errcode='23514';
 end if;
 if new.source_id is null then raise exception '项目报价必须选择来源销售报价单' using errcode='23514'; end if;
 select * into v_source from public.scm_sales_document where id=new.source_id and kind='sales_quotation'  and status='effective' and true for share;
 if v_source.id is null or v_source.details->>'quotation_scene' is distinct from 'project' then raise exception '请选择已生效的工程销售报价单' using errcode='23514'; end if;
 new.project_id:=v_source.project_id;
 new.customer_id:=v_source.customer_id;
 new.currency:=v_source.currency;
 new.delivery_date:=v_source.delivery_date;
 new.details:=v_source.details;
 new.lines:=v_source.lines;
 new.fees:=v_source.fees;
 new.remark:=v_source.remark;
 return new;
end $function$;

--
-- Name: scm_receipt_stock_quantity; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.scm_receipt_stock_quantity(p_material_id uuid, p_receipt_quantity numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_material public.mdm_material%rowtype;
 v_purchase_factor numeric := 1;
 v_stock_factor numeric := 1;
begin
 select * into v_material from public.mdm_material
 where id=p_material_id ;
 if not found or p_receipt_quantity<=0 then
   raise exception '物料不存在或收料数量无效' using errcode='23514';
 end if;
 if v_material.purchase_unit_id is distinct from v_material.base_unit_id then
   select (x->>'base_factor')::numeric / nullif((x->>'source_factor')::numeric,0)
   into v_purchase_factor
   from jsonb_array_elements(coalesce(v_material.unit_conversions,'[]'::jsonb)) x
   where x->>'source_unit_id'=v_material.purchase_unit_id::text limit 1;
 end if;
 if v_material.inventory_unit_id is distinct from v_material.base_unit_id then
   select (x->>'base_factor')::numeric / nullif((x->>'source_factor')::numeric,0)
   into v_stock_factor
   from jsonb_array_elements(coalesce(v_material.unit_conversions,'[]'::jsonb)) x
   where x->>'source_unit_id'=v_material.inventory_unit_id::text limit 1;
 end if;
 if v_purchase_factor is null or v_stock_factor is null
    or v_purchase_factor<=0 or v_stock_factor<=0 then
   raise exception '物料缺少有效的采购单位或库存单位换算关系' using errcode='23514';
 end if;
 return round(p_receipt_quantity*v_purchase_factor/v_stock_factor,3);
end $function$;

--
-- Name: search_platform_global_pending_workflow_tasks; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.search_platform_global_pending_workflow_tasks(p_keyword text DEFAULT NULL::text, p_business_type text DEFAULT NULL::text, p_from integer DEFAULT 0, p_to integer DEFAULT 19)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_from integer:=greatest(coalesce(p_from,0),0);
  v_limit integer:=least(greatest(coalesce(p_to,19)-greatest(coalesce(p_from,0),0)+1,1),100);
  v_keyword text:=nullif(btrim(coalesce(p_keyword,'')),'');
  v_result jsonb;
begin
  if (select auth.uid()) is null or not (select app_private.is_platform_super()) then
    raise exception '仅平台超级管理员可以查看全局待办' using errcode='42501';
  end if;
  with base as (
    select t.*,i.business_title,i.business_type,i.business_id,i.initiator_name_snapshot,
      i.definition_id,i.version_id,i.status instance_status,i.current_node_key,
      d.code definition_code,d.name definition_name,v.version_no,v.config,
    from public.wf_task t
    join public.wf_instance i on i.id=t.instance_id
    join public.wf_definition d on d.id=i.definition_id
    join public.wf_version v on v.id=i.version_id
    where t.status='pending' and i.status='running' and i.current_node_key=t.node_key

      and (nullif(p_business_type,'') is null or i.business_type=p_business_type)
      and (v_keyword is null or i.business_title ilike '%'||v_keyword||'%'
        or i.business_id::text ilike '%'||v_keyword||'%'
        or i.initiator_name_snapshot ilike '%'||v_keyword||'%'
        or t.assignee_name_snapshot ilike '%'||v_keyword||'%'
        or d.name ilike '%'||v_keyword||'%')
  ), grouped as (
    select instance_id,node_key,min(id::text)::uuid representative_id,count(*)::integer assignee_count,
      count(*) filter(where status='pending')::integer pending_assignee_count,
      jsonb_agg(distinct assignee_name_snapshot order by assignee_name_snapshot) assignee_names,
      min(due_at) due_at,min(create_time) create_time,
      min(case when due_at is not null and due_at<now() then 0 else 1 end) urgency_order
    from base group by instance_id,node_key
  ), records as (
    select to_jsonb(b)-array['business_title','business_type','business_id','initiator_name_snapshot',
      'definition_id','version_id','instance_status','current_node_key','definition_code',
      'definition_name','version_no','config']
      ||jsonb_build_object(
        'assigneeCount',g.assignee_count,'pendingAssigneeCount',g.pending_assignee_count,
        'assigneeNames',g.assignee_names,
        'instance',jsonb_build_object('id',b.instance_id,'definitionId',b.definition_id,
          'versionId',b.version_id,'businessType',b.business_type,'businessId',b.business_id,
          'businessTitle',b.business_title,'initiatorNameSnapshot',b.initiator_name_snapshot,
          'status',b.instance_status,'currentNodeKey',b.current_node_key,
          'definition',jsonb_build_object('id',b.definition_id,'code',b.definition_code,
            'name',b.definition_name,'businessType',b.business_type),
          'version',jsonb_build_object('id',b.version_id,'versionNo',b.version_no,'config',b.config))
      ) record,g.urgency_order,g.due_at,g.create_time
    from grouped g join base b on b.id=g.representative_id
  ), page_rows as (
    select * from records order by urgency_order,due_at nulls last,create_time desc
    offset v_from limit v_limit
  )
  select jsonb_build_object(
    'records',coalesce((select jsonb_agg(record order by urgency_order,due_at nulls last,create_time desc) from page_rows),'[]'::jsonb),
    'total',(select count(*) from grouped),
    'taskTotal',(select coalesce(sum(assignee_count),0) from grouped)
  ) into v_result;
  return v_result;
end;$function$;

--
-- Name: search_workflow_instances_for_monitor; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.search_workflow_instances_for_monitor(p_keyword text DEFAULT NULL::text, p_business_type text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_sla_status text DEFAULT NULL::text, p_from integer DEFAULT 0, p_to integer DEFAULT 19)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_from integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1), 100);
  v_result jsonb;
  v_is_platform_super boolean := (select app_private.is_platform_super());
begin
  if (select auth.uid()) is null then
    raise exception '请先登录后查看审批监控' using errcode = '42501';
  end if;
  if nullif(p_status, '') is not null
     and p_status not in ('running', 'approved', 'rejected', 'withdrawn', 'cancelled') then
    raise exception '无效的流程状态';
  end if;
  if nullif(p_sla_status, '') is not null and p_sla_status not in ('normal', 'overdue') then
    raise exception '无效的时效状态';
  end if;

  with scoped as (
    select
      i as instance_record,
      d.name as definition_name,
      d.code as definition_code,
      v.version_no,
      coalesce(task_stats.pending_task_count, 0) as pending_task_count,
      task_stats.nearest_due_at,
      coalesce(task_stats.is_overdue, false) as is_overdue,
      round(
        (extract(epoch from (coalesce(i.finished_at, now()) - i.started_at)) / 3600)::numeric,
        1
      ) as duration_hours
    from public.wf_instance i
    join public.wf_definition d on d.id = i.definition_id
    join public.wf_version v on v.id = i.version_id
    left join lateral (
      select
        count(*)::integer as pending_task_count,
        min(t.due_at) as nearest_due_at,
        bool_or(t.due_at < now()) filter (where t.due_at is not null) as is_overdue
      from public.wf_task t
      where t.instance_id = i.id and t.status = 'pending'
    ) task_stats on true
  ), filtered as (
    select
      to_jsonb(instance_record) || jsonb_build_object(
        'definition_name', definition_name,
        'definition_code', definition_code,
        'version_no', version_no,
        'pending_task_count', pending_task_count,
        'nearest_due_at', nearest_due_at,
        'is_overdue', is_overdue,
        'duration_hours', duration_hours
      ) as record,
      (instance_record).started_at as started_at
    from scoped
    where (
      nullif(btrim(coalesce(p_keyword, '')), '') is null
      or (instance_record).business_title ilike '%' || btrim(p_keyword) || '%'
      or (instance_record).business_id::text ilike '%' || btrim(p_keyword) || '%'
      or (instance_record).initiator_name_snapshot ilike '%' || btrim(p_keyword) || '%'
      or definition_name ilike '%' || btrim(p_keyword) || '%'
    )
      and (nullif(p_business_type, '') is null or (instance_record).business_type = p_business_type)
      and (nullif(p_status, '') is null or (instance_record).status = p_status)
      and (
        nullif(p_sla_status, '') is null
        or (p_sla_status = 'overdue' and is_overdue)
        or (p_sla_status = 'normal' and not is_overdue)
      )
  ), page_rows as (
    select record, started_at
    from filtered
    order by started_at desc
    offset v_from limit v_limit
  )
  select jsonb_build_object(
    'records', coalesce((select jsonb_agg(record order by started_at desc) from page_rows), '[]'::jsonb),
    'total', (select count(*) from filtered)
  ) into v_result;

  return v_result;
end;
$function$;

