 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin

  insert into public.tms_expense_item(
    item_code, item_name, business_category, is_selectable,
    reimbursement_allowed, is_enabled, sort, remark, create_by, update_by
  )
  select x.item_code, x.item_name, null, false, false, true,
