  on conflict (item_code) do nothing;

  insert into public.tms_expense_item(
    parent_id, item_code, item_name, business_category,
    is_selectable, reimbursement_allowed, is_enabled, sort, remark,
    create_by, update_by
  )
  select parent.id, x.item_code, x.item_name, x.business_category,
         true, x.reimbursement_allowed, true, x.sort, x.remark,
         'expense-item-engine', 'expense-item-engine'
  from (values
    ('FYXM-YS', 'FYXM-CYF', '承运费', 'carrier_freight', false, 10, '承运商结算费用'),
    ('FYXM-YS', 'FYXM-LQF', '路桥费', 'toll', true, 20, '高速、桥梁及道路通行费'),
    ('FYXM-YS', 'FYXM-TCF', '停车费', 'parking', true, 30, '运输相关停车费用'),
    ('FYXM-YS', 'FYXM-RYF', '燃油费', 'fuel', true, 40, '车辆燃油支出'),
    ('FYXM-YS', 'FYXM-ZXF', '装卸费', 'loading', true, 50, '装车、卸车及搬运费用'),
    ('FYXM-YS', 'FYXM-YCF', '压车等候费', 'waiting', true, 60, '压车、排队及等候费用'),
    ('FYXM-ZT', 'FYXM-NYF', '能源费', 'in_transit_energy', true, 10, '运输途中综合能源费用'),
    ('FYXM-ZT', 'FYXM-CDF', '充电费', 'in_transit_charging', true, 20, '新能源车辆充电费用'),
    ('FYXM-ZT', 'FYXM-JQF', '加气费', 'in_transit_gas', true, 30, '燃气车辆加气费用'),
    ('FYXM-ZT', 'FYXM-ZTQT', '其他在途费', 'in_transit_other', true, 40, '其他运输途中费用'),
    ('FYXM-QT', 'FYXM-SJF', '司机费用', 'driver_expense', true, 10, '司机垫付、补贴及相关费用'),
    ('FYXM-QT', 'FYXM-HSP', '货损赔付', 'cargo_damage', true, 20, '货损、差异及赔付成本'),
    ('FYXM-QT', 'FYXM-QTF', '其他费用', 'other', true, 30, '未归入其他项目的运单费用')
  ) as x(
    parent_code, item_code, item_name, business_category,
    reimbursement_allowed, sort, remark
  )
  join public.tms_expense_item parent
    on parent.item_code = x.parent_code
  on conflict (item_code) do nothing;
end;
$function$;

--
-- Name: set_hr_employee_creator_identity; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.set_hr_employee_creator_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_current_user_id uuid := app_private.current_app_user_id();
begin

  if tg_op = 'INSERT' then
    if v_current_user_id is not null then
      if new.created_by_user_id is null then
        new.created_by_user_id := v_current_user_id;
      elsif new.created_by_user_id <> v_current_user_id then
        raise exception 'Employee creator must be the current user' using errcode='42501';
      end if;
    end if;
  elsif new.created_by_user_id is distinct from old.created_by_user_id
        and new.created_by_user_id is not null then
    raise exception 'Employee creator cannot be changed' using errcode='42501';
  end if;

  return new;
end;
$function$;

--
-- Name: set_tms_customer_creator_identity; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.set_tms_customer_creator_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_current_user_id uuid := app_private.current_app_user_id();
  v_formal_user_id uuid := '85fa360f-101a-45be-b07c-94e51f7c50a8'::uuid;
begin

  if tg_op = 'INSERT' then
    if (select auth.uid()) is not null then
      if v_current_user_id is null then
        raise exception 'Authenticated application user not found' using errcode='42501';
      end if;
      new.created_by_user_id := v_current_user_id;
    elsif new.created_by_user_id is null then
      raise exception 'Creator identity is required';
    end if;
  elsif new.created_by_user_id is distinct from old.created_by_user_id then
  end if;
  return new;
end;
$function$;

--
-- Name: set_tms_financial_document_creator_identity; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.set_tms_financial_document_creator_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_current_user_id uuid := app_private.current_app_user_id();
begin
  if tg_op = 'INSERT' then
    if v_current_user_id is not null then
      new.created_by_user_id := v_current_user_id;
    elsif new.created_by_user_id is null then
      select user_row.id
      into new.created_by_user_id
      from public.sys_user user_row
      where true
        and user_row.deleted_at is null
        and (
          lower(user_row.user_email) = lower(new.create_by)
          or lower(user_row.user_name) = lower(new.create_by)
          or lower(user_row.nick_name) = lower(new.create_by)
        )
      order by
        case
          when lower(user_row.user_email) = lower(new.create_by) then 0
          when lower(user_row.user_name) = lower(new.create_by) then 1
          else 2
        end,
        user_row.create_time,
        user_row.id
      limit 1;
    end if;

    if new.created_by_user_id is null then
      raise exception 'Authenticated financial document creator identity is required'
        using errcode = '42501';
    end if;
  elsif new.created_by_user_id is distinct from old.created_by_user_id then
    raise exception 'Financial document creator identity is immutable' using errcode = '42501';
  end if;

  return new;
end;
$function$;

--
-- Name: set_vehicle_archive_creator_identity; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.set_vehicle_archive_creator_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_current_user_id uuid := app_private.current_app_user_id();
begin
  if tg_op = 'INSERT' then

    if v_current_user_id is not null then
      new.created_by_user_id := v_current_user_id;
    elsif new.created_by_user_id is null then
      select user_row.id
      into new.created_by_user_id
      from public.sys_user user_row
      where lower(user_row.user_email) = lower(new.create_by)
        and user_row.deleted_at is null
      order by user_row.create_time, user_row.id
      limit 1;
    end if;


    if new.created_by_user_id is null or not exists (
      select 1
      from public.sys_user user_row
      where user_row.id = new.created_by_user_id
        
    ) then
      raise exception 'Authenticated vehicle archive creator identity is required'
        using errcode = '42501';
    end if;
  elsif new.created_by_user_id is distinct from old.created_by_user_id then
    raise exception 'Vehicle archive creator identity is immutable' using errcode = '42501';
  end if;

  return new;
end;
$function$;

--
-- Name: set_vehicle_supplier_creator_identity; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.set_vehicle_supplier_creator_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_current_user_id uuid := app_private.current_app_user_id();
begin
  if tg_op = 'INSERT' then

    if v_current_user_id is not null then
      new.created_by_user_id := v_current_user_id;
    elsif new.created_by_user_id is null and nullif(btrim(new.create_by), '') is not null then
      select user_row.id into new.created_by_user_id
      from public.sys_user user_row
      where lower(user_row.user_email) = lower(new.create_by)
        and user_row.deleted_at is null
      order by user_row.create_time, user_row.id limit 1;
    end if;
    if new.created_by_user_id is null or not exists (
      select 1 from public.sys_user user_row
      where user_row.id = new.created_by_user_id
    ) then
      raise exception 'Vehicle supplier creator is missing'
        using errcode = '42501';
    end if;
  elsif new.created_by_user_id is distinct from old.created_by_user_id then
    raise exception 'Vehicle supplier creator identity is immutable' using errcode = '42501';
  end if;
  return new;
end;
$function$;

--
-- Name: set_workflow_definition_enabled; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.set_workflow_definition_enabled(p_definition_id uuid, p_enabled boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_is_platform_super boolean := (select app_private.is_platform_super());
  v_definition public.wf_definition;
begin
  if (select auth.uid()) is null or not v_is_platform_super then
    raise exception '当前账号没有流程启停权限' using errcode = '42501';
  end if;

  select *
  into v_definition
  from public.wf_definition d
  where d.id = p_definition_id
    
  for update;

  if not found then
    raise exception '流程不存在或无权操作';
  end if;


  if p_enabled and v_definition.current_version_id is null then
    raise exception '流程尚未发布，不能启用';
  end if;

  if p_enabled and exists (
    select 1
    from public.wf_definition d
    where true
      and d.business_type = v_definition.business_type
      and d.status = 'published'
      and d.id <> v_definition.id
  ) then
    raise exception '该业务类型已有启用流程';
  end if;

  update public.wf_definition
  set status = case when p_enabled then 'published' else 'disabled' end
  where id = p_definition_id;
end;
$function$;

--
-- Name: start_workflow; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.start_workflow(p_business_type text, p_business_id uuid, p_business_title text, p_context jsonb, p_idempotency_key text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := app_private.current_app_user_id();
  v_actor text := coalesce(nullif(auth.jwt() ->> 'email', ''), auth.uid()::text);
  v_actor_name text;
  v_definition public.wf_definition;
  v_instance_id uuid;
  v_context jsonb := coalesce(p_context, '{}'::jsonb);
  v_business record;
begin
  if auth.uid() is null or v_user_id is null then raise exception '当前登录用户未绑定业务账号'; end if;
  if jsonb_typeof(v_context) <> 'object' then raise exception '流程上下文必须是对象'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_business_type || ':' || p_business_id::text, 91311));
  select id into v_instance_id from public.wf_instance
  where business_type = p_business_type
    and business_id = p_business_id and status = 'running';
  if found then return v_instance_id; end if;

  select coalesce(nullif(nick_name, ''), nullif(user_name, ''), user_email, id::text)
  into v_actor_name from public.sys_user
  where id = v_user_id  and status = '1';
  select * into v_definition from public.wf_definition
  where business_type = p_business_type and status = 'published';
  if not found then raise exception '当前业务类型没有已启用的审批流程'; end if;

  if p_business_type = 'tms_waybill_cost' then
    select c.id, c.audit_status business_status, c.amount, c.cost_type, c.waybill_id
    into v_business from public.tms_waybill_cost c
    where c.id = p_business_id  for update;
    if not found then raise exception '运单费用不存在或无权提交'; end if;
    if v_business.business_status not in ('draft', 'rejected') then raise exception '当前费用状态不允许提交审批'; end if;
    v_context := v_context || jsonb_build_object(
      'amount', v_business.amount, 'costType', v_business.cost_type, 'waybillId', v_business.waybill_id
    );
  elsif p_business_type = 'tms_in_transit_expense' then
    raise exception '在途费用申报功能已停用，请使用运单费用流程';
  elsif p_business_type = 'tms_expense_reimbursement' then
    select r.id, r.status business_status, r.total_amount, r.reimbursement_no,
           r.payment_method, r.planned_payment_date,
           (select count(*)::integer from public.tms_expense_reimbursement_item i
            where i.reimbursement_id = r.id) item_count,
           (select count(distinct i.waybill_id)::integer
            from public.tms_expense_reimbursement_item i
            where i.reimbursement_id = r.id) waybill_count
    into v_business from public.tms_expense_reimbursement r
    where r.id = p_business_id 
    for update;
    if not found then raise exception '费用报销单不存在、无明细或无权提交'; end if;
    if v_business.business_status not in ('draft', 'rejected') then raise exception '当前报销单状态不允许提交审批'; end if;
    v_context := v_context || jsonb_build_object(
      'amount', v_business.total_amount, 'reimbursementNo', v_business.reimbursement_no,
      'paymentMethod', v_business.payment_method, 'plannedPaymentDate', v_business.planned_payment_date,
      'itemCount', v_business.item_count, 'waybillCount', v_business.waybill_count
    );
  end if;

  insert into public.wf_instance(
    definition_id, version_id, business_type, business_id, business_title,
    initiator_user_id, initiator_name_snapshot, context_snapshot, create_by, update_by
  ) values (
    v_definition.id, v_definition.current_version_id, p_business_type, p_business_id,
    btrim(p_business_title), v_user_id, v_actor_name, v_context, v_actor, v_actor
  ) returning id into v_instance_id;
  insert into public.wf_action(
    instance_id, action, actor_user_id, actor_name_snapshot, comment,
    idempotency_key, create_by
  ) values (
    v_instance_id, 'submit', v_user_id, v_actor_name, '提交审批',
    nullif(p_idempotency_key, ''), v_actor
  );
  perform app_private.apply_workflow_business_status(
    p_business_type, p_business_id, 'running', v_actor_name, null
  );
  perform app_private.activate_next_workflow_node(v_instance_id, 0);
  return v_instance_id;
end;
$function$;

--
-- Name: sync_delete_auth_user_on_app_delete; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.sync_delete_auth_user_on_app_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if old.auth_user_id is not null
     and exists (
       select 1
       from auth.users
       where id = old.auth_user_id
     )
  then
    delete from auth.users
    where id = old.auth_user_id;
  end if;

  return old;
end;
$function$;

--
-- Name: sync_hr_employee_position_title; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.sync_hr_employee_position_title()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_position public.hr_position%rowtype;
  v_job_profile public.hr_job_profile%rowtype;
begin
  select * into v_position
  from public.hr_position position_row
  where position_row.id = new.position_id
    ;

  if not found then raise exception '所选岗位不存在或不可用'; end if;
  if not v_position.enabled then raise exception '所选岗位已停用'; end if;
  if v_position.organization_id is not null
     and new.organization_id is distinct from v_position.organization_id then
    raise exception '所选岗位不属于员工所在组织';
  end if;

  select * into v_job_profile
  from public.hr_job_profile profile_row
  where profile_row.id = v_position.job_profile_id
    ;
  new.job_title := v_job_profile.job_name;
  return new;
end;
$function$;

--
-- Name: sync_hr_employee_primary_assignment; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.sync_hr_employee_primary_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_position public.hr_position%rowtype;
  v_current public.hr_employee_assignment%rowtype;
  v_effective_date date := current_date;
  v_assignment_status text;
begin
  if coalesce(current_setting('app.hr_assignment_engine', true), '') = 'on' then return new; end if;
  if new.organization_id is null then return new; end if;
  if tg_op = 'UPDATE'
     and new.organization_id is not distinct from old.organization_id
     and new.position_id is not distinct from old.position_id
     and new.employment_status is not distinct from old.employment_status then return new; end if;

  select * into v_position from public.hr_position
  where id = new.position_id ;
  if not found then raise exception '员工当前岗位不存在或不可用'; end if;
  v_assignment_status := case when new.employment_status='leave' then 'suspended'
    when new.employment_status='terminated' then 'ended' else 'active' end;

  select * into v_current from public.hr_employee_assignment
  where employee_id=new.id and primary_assignment and effective_end is null
  for update;

  if found and v_current.effective_start >= v_effective_date then
    update public.hr_employee_assignment set
      organization_id=new.organization_id, position_id=new.position_id,
      job_profile_id=v_position.job_profile_id, grade_id=v_position.grade_id,
      assignment_status=v_assignment_status,
      effective_end=case when new.employment_status='terminated' then coalesce(new.leave_date,v_effective_date) else null end,
      version=version+1
    where id=v_current.id;
  else
    if found then update public.hr_employee_assignment
      set effective_end=v_effective_date-1,assignment_status='ended',version=version+1
      where id=v_current.id; end if;
    insert into public.hr_employee_assignment(employee_id,organization_id,position_id,job_profile_id,grade_id,
      business_title,assignment_status,primary_assignment,fte,effective_start,effective_end,source_type
    ) values(new.id,new.organization_id,new.position_id,v_position.job_profile_id,v_position.grade_id,
      null,v_assignment_status,true,1,v_effective_date,
      case when new.employment_status='terminated' then coalesce(new.leave_date,v_effective_date) else null end,
      'employee_profile'
    );
  end if;
  return new;
end;
$function$;

--
-- Name: sync_mdm_business_partner_role; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.sync_mdm_business_partner_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  source_row jsonb;
  source_id_value uuid;
  role_code_value text;
  source_code_value text;
  partner_code_value text;
  partner_name_value text;
  legal_name_value text;
  registration_no_value text;
  tax_no_value text;
  enabled_value boolean;
  status_value text;
  region_value text;
  address_value text;
  contact_name_value text;
  contact_phone_value text;
  contact_email_value text;
  old_source_id uuid;
begin
  if tg_op = 'DELETE' then
    source_row := to_jsonb(old);
  else
    source_row := to_jsonb(new);
  end if;

  source_id_value := (source_row ->> 'id')::uuid;

  case tg_table_name
    when 'mdm_customer' then
      role_code_value := 'customer';
      source_code_value := source_row ->> 'customer_code';
      partner_name_value := source_row ->> 'customer_name';
      legal_name_value := coalesce(nullif(source_row ->> 'invoice_title', ''), partner_name_value);
      tax_no_value := nullif(source_row ->> 'tax_no', '');
      enabled_value := coalesce((source_row ->> 'enabled')::boolean, true);
      status_value := case when enabled_value then 'enabled' else 'disabled' end;
      contact_name_value := source_row ->> 'contact_name';
    when 'mdm_carrier' then
      role_code_value := 'carrier';
      source_code_value := source_row ->> 'carrier_code';
      partner_name_value := source_row ->> 'company_name';
      legal_name_value := partner_name_value;
      registration_no_value := nullif(source_row ->> 'business_license_no', '');
      tax_no_value := coalesce(nullif(source_row ->> 'tax_no', ''), nullif(source_row ->> 'tax_registration_no', ''));
      enabled_value := coalesce((source_row ->> 'enabled')::boolean, true);
      status_value := case when enabled_value then 'enabled' else 'disabled' end;
      contact_name_value := source_row ->> 'contact_name';
    when 'mdm_supplier' then
      role_code_value := 'supplier';
      source_code_value := source_row ->> 'supplier_code';
      partner_name_value := source_row ->> 'supplier_name';
      legal_name_value := partner_name_value;
      enabled_value := true;
      status_value := 'enabled';
      contact_name_value := source_row ->> 'contact_person';
    when 'mdm_insurance_company' then
      role_code_value := 'insurance_company';
      partner_name_value := source_row ->> 'company_name';
      legal_name_value := partner_name_value;
      enabled_value := true;
      status_value := 'enabled';
      contact_name_value := source_row ->> 'contact_person';
    when 'mdm_external_vendor' then
      role_code_value := 'external_vendor';
      source_code_value := source_row ->> 'vendor_code';
      partner_name_value := source_row ->> 'vendor_name';
      legal_name_value := partner_name_value;
      registration_no_value := nullif(source_row ->> 'registration_no', '');
      status_value := coalesce(nullif(source_row ->> 'status', ''), 'draft');
      enabled_value := status_value not in ('disabled', 'inactive', 'archived');
      contact_name_value := source_row ->> 'contact_name';
    else
      raise exception 'Unsupported MDM role source table: %', tg_table_name;
  end case;

  partner_code_value := role_code_value || ':' || coalesce(nullif(btrim(source_code_value), ''), source_id_value::text);
  region_value := source_row ->> 'region';
  address_value := source_row ->> 'address_detail';
  contact_phone_value := source_row ->> 'contact_phone';
  contact_email_value := source_row ->> 'contact_email';

  if tg_op = 'DELETE' then
    delete from public.mdm_business_partner_role
    where source_table = tg_table_name and source_id = source_id_value;

    delete from public.mdm_business_partner partner
    where partner.id = source_id_value
      and not exists (
        select 1
        from public.mdm_business_partner_role role_record
        where role_record.partner_id = partner.id
          
      );
    return old;
  end if;

  if tg_op = 'UPDATE' then
    old_source_id := old.id;
    if old_source_id <> source_id_value then
      delete from public.mdm_business_partner_role
      where source_table = tg_table_name and source_id = old_source_id;

      delete from public.mdm_business_partner partner
      where partner.id = old_source_id
        and not exists (
          select 1
          from public.mdm_business_partner_role role_record
          where role_record.partner_id = partner.id
        );
    end if;
  end if;

  insert into public.mdm_business_partner (
    id,
    partner_code,
    source_code,
    partner_name,
    legal_name,
    registration_no,
    tax_no,
    enabled,
    status,
    region,
    address_detail,
    contact_name,
    contact_phone,
    contact_email
  ) values (
    source_id_value,
    partner_code_value,
    source_code_value,
    partner_name_value,
    legal_name_value,
    registration_no_value,
    tax_no_value,
    enabled_value,
    status_value,
    region_value,
    address_value,
    contact_name_value,
    contact_phone_value,
    contact_email_value
  )
  on conflict (id) do update
  set partner_code = excluded.partner_code,
      source_code = excluded.source_code,
      partner_name = excluded.partner_name,
      legal_name = excluded.legal_name,
      registration_no = excluded.registration_no,
      tax_no = excluded.tax_no,
      enabled = excluded.enabled,
      status = excluded.status,
      region = excluded.region,
      address_detail = excluded.address_detail,
      contact_name = excluded.contact_name,
      contact_phone = excluded.contact_phone,
      contact_email = excluded.contact_email;


  insert into public.mdm_business_partner_role (
    partner_id,
    role_code,
    source_table,
    source_id
  ) values (
    source_id_value,
    role_code_value,
    tg_table_name,
    source_id_value
  )
  on conflict (source_table, source_id) do update
  set partner_id = excluded.partner_id,
      role_code = excluded.role_code;

  return new;
end;
$function$;

--
-- Name: sync_notification_subject_from_source; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.sync_notification_subject_from_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row jsonb := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  v_status text := case when tg_op = 'DELETE' then 'cancelled' else 'active' end;
  v_business_id uuid := (v_row ->> 'id')::uuid;
begin
  if tg_table_name = 'tms_contract' then
    if coalesce((v_row ->> 'is_completed')::boolean, false) then v_status := 'resolved'; end if;
    perform app_private.upsert_notification_subject('tms_contract_expiry', 'tms_contract', v_business_id, 'expiry_date',
      '运输合同「' || coalesce(v_row ->> 'contract_name', v_row ->> 'contract_no', '未命名') || '」到期',
      case when v_row ->> 'expiry_date' is null then null
        else ((v_row ->> 'expiry_date')::date + time '09:00') at time zone 'Asia/Shanghai' end,
      nullif(v_row ->> 'created_by_user_id', '')::uuid,
      '/tms/basic-data/contract', jsonb_build_object('contractId', v_business_id),
      jsonb_build_object('businessNo', v_row ->> 'contract_no'), v_status
    );
  elsif tg_table_name = 'fms_commercial_bill' then
    if coalesce(v_row ->> 'status', '') in ('settled', 'cancelled', 'voided') then v_status := 'resolved'; end if;
    perform app_private.upsert_notification_subject('fms_commercial_bill_due', 'fms_commercial_bill', v_business_id, 'due_date',
      '商业票据「' || coalesce(v_row ->> 'bill_no', '未编号') || '」到期',
      case when v_row ->> 'due_date' is null then null
        else ((v_row ->> 'due_date')::date + time '09:00') at time zone 'Asia/Shanghai' end,
      null, '/fms/commercial-bill', jsonb_build_object('billId', v_business_id),
      jsonb_build_object('businessNo', v_row ->> 'bill_no'), v_status
    );
  elsif tg_table_name = 'vehicle_insurance' then
    perform app_private.upsert_notification_subject('vms_commercial_insurance_expiry', 'vehicle_insurance', v_business_id, 'commercial',
      coalesce(v_row ->> 'plate_no', '车辆') || ' 商业险到期',
      case when v_row ->> 'commercial_expire_date' is null then null
        else ((v_row ->> 'commercial_expire_date')::date + time '09:00') at time zone 'Asia/Shanghai' end,
      null, '/vms/reminder-manage/insurance-expiry', jsonb_build_object('vehicleId', v_row ->> 'vehicle_id'),
      jsonb_build_object('plateNo', v_row ->> 'plate_no'), v_status
    );
    perform app_private.upsert_notification_subject('vms_compulsory_insurance_expiry', 'vehicle_insurance', v_business_id, 'compulsory',
      coalesce(v_row ->> 'plate_no', '车辆') || ' 交强险到期',
      case when v_row ->> 'compulsory_expire_date' is null then null
        else ((v_row ->> 'compulsory_expire_date')::date + time '09:00') at time zone 'Asia/Shanghai' end,
      null, '/vms/reminder-manage/insurance-expiry', jsonb_build_object('vehicleId', v_row ->> 'vehicle_id'),
      jsonb_build_object('plateNo', v_row ->> 'plate_no'), v_status
    );
  elsif tg_table_name = 'vehicle_inspection' then
    perform app_private.upsert_notification_subject('vms_vehicle_inspection_expiry', 'vehicle_inspection', v_business_id, 'expire_date',
      coalesce(v_row ->> 'plate_no', '车辆') || ' 年检到期',
      case when v_row ->> 'expire_date' is null then null
        else ((v_row ->> 'expire_date')::date + time '09:00') at time zone 'Asia/Shanghai' end,
      null, '/vms/reminder-manage/inspection-expiry', jsonb_build_object('vehicleId', v_row ->> 'vehicle_id'),
      jsonb_build_object('plateNo', v_row ->> 'plate_no'), v_status
    );
  elsif tg_table_name = 'vehicle_archive' then
    if coalesce(v_row ->> 'operation_status', '') in ('scrapped', 'retired', 'inactive') then v_status := 'resolved'; end if;
    perform app_private.upsert_notification_subject('vms_vehicle_service_expiry', 'vehicle_archive', v_business_id, 'service_end',
      coalesce(v_row ->> 'plate_no', '车辆') || ' 服务期到期',
      case when v_row ->> 'service_end_time' is null then null
        else ((v_row ->> 'service_end_time')::date + time '09:00') at time zone 'Asia/Shanghai' end,
      null, '/vms/reminder-manage/vehicle-service-life', jsonb_build_object('vehicleId', v_business_id),
      jsonb_build_object('plateNo', v_row ->> 'plate_no'), v_status
    );
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$;

--
-- Name: sync_scm_purchase_request; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.sync_scm_purchase_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_source_id uuid;
  v_request public.scm_purchase_document%rowtype;
  v_total numeric;
  v_used numeric;
begin
  v_source_id:=case when tg_op='DELETE' then old.source_id else new.source_id end;
  if v_source_id is null or (case when tg_op='DELETE' then old.kind else new.kind end)<>'purchase_order' then
    return null;
  end if;
  select * into v_request from public.scm_purchase_document where id=v_source_id for update;
  if v_request.id is null then return null; end if;
  select coalesce(sum((l.value->>'quantity')::numeric),0) into v_total
    from jsonb_array_elements(v_request.lines) l;
  select coalesce(sum((l.value->>'quantity')::numeric),0) into v_used
    from public.scm_purchase_document d cross join lateral jsonb_array_elements(d.lines) l
    where d.source_id=v_source_id and d.kind='purchase_order' and d.status<>'cancelled'
      and l.value->>'source_line_id' is not null;
  update public.scm_purchase_document set status=case
    when v_used=0 then 'draft' when v_used>=v_total then 'completed' else 'purchasing' end
    where id=v_source_id and status is distinct from case
      when v_used=0 then 'draft' when v_used>=v_total then 'completed' else 'purchasing' end;
  return null;
end
$function$;

--
-- Name: tms_cargo_apply_material; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.tms_cargo_apply_material()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_material public.mdm_material%rowtype;
begin
  if new.material_id is not null then
    select * into v_material from public.mdm_material
    where id=new.material_id  and status='enabled';
    if not found then raise exception 'MDM material is unavailable'; end if;
    new.cargo_code := v_material.material_code;
    new.cargo_name := v_material.material_name;
    new.spec_model := v_material.specification_model;
    new.unit := v_material.basic_unit;
    if new.material_group_id is null then
      new.material_group_id := v_material.material_group_id;
    end if;
  end if;
  if new.material_group_id is not null and not exists (
    select 1 from public.mdm_master_group
    where id=new.material_group_id 
      and domain='material' and enabled
  ) then raise exception 'Material group is unavailable'; end if;
  return new;
end $function$;

