--
-- Name: transfer_workflow_task; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.transfer_workflow_task(p_task_id uuid, p_assignee_user_id uuid, p_reason text, p_idempotency_key text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := (select app_private.current_app_user_id());
  v_is_platform_super boolean := (select app_private.is_platform_super());
  v_reason text := btrim(coalesce(p_reason, ''));
  v_instance_id uuid;
  v_instance public.wf_instance;
  v_task public.wf_task;
  v_actor_name text;
  v_target_name text;
begin
  if (select auth.uid()) is null or v_user_id is null then
    raise exception '当前登录用户未绑定业务账号';
  end if;
  if char_length(v_reason) not between 4 and 300 then
    raise exception '转交原因需填写 4 至 300 个字符';
  end if;

  select instance_id into v_instance_id
  from public.wf_task
  where id = p_task_id ;
  if v_instance_id is null then raise exception '待办不存在或无权操作' using errcode = '42501'; end if;

  select * into v_instance from public.wf_instance
  where id = v_instance_id for update;
  select * into v_task from public.wf_task
  where id = p_task_id  for update;

  if not found or (not v_is_platform_super and v_task.assignee_user_id <> v_user_id) then
    raise exception '只有当前审批人可以转交待办' using errcode = '42501';
  end if;
  if v_task.status <> 'pending' or v_instance.status <> 'running' then
    raise exception '仅运行中的待办可以转交';
  end if;
  if p_assignee_user_id = v_task.assignee_user_id then raise exception '不能转交给当前审批人'; end if;

  if nullif(p_idempotency_key, '') is not null and exists (
    select 1 from public.wf_action
    where idempotency_key = p_idempotency_key
  ) then
    return v_task.instance_id;
  end if;

  select coalesce(nullif(nick_name,''), nullif(user_name,''), user_email, id::text)
  into v_actor_name from public.sys_user where id = v_user_id;
  select coalesce(nullif(nick_name,''), nullif(user_name,''), user_email, id::text)
  into v_target_name
  from public.sys_user
  where id = p_assignee_user_id  and status = '1';
  if v_target_name is null then raise exception '新审批人不存在、已停用或不可用'; end if;

  update public.wf_task
  set assignee_user_id = p_assignee_user_id,
      assignee_name_snapshot = v_target_name,
      assignment_source = 'transfer', delegation_id = null,
      last_assigned_by = v_user_id, assignment_reason = v_reason
  where id = v_task.id;

  insert into public.wf_action(
    instance_id, task_id, node_key, node_name, action,
    actor_user_id, actor_name_snapshot, comment, metadata,
    idempotency_key) values (
    v_task.instance_id, v_task.id, v_task.node_key, v_task.node_name, 'transfer',
    v_user_id, v_actor_name, v_reason,
    jsonb_build_object(
      'fromUserId', v_task.assignee_user_id,
      'fromUserName', v_task.assignee_name_snapshot,
      'toUserId', p_assignee_user_id,
      'toUserName', v_target_name,
      'originalAssigneeUserId', v_task.original_assignee_user_id,
      'originalAssigneeName', v_task.original_assignee_name_snapshot,
      'operatorType', case when v_is_platform_super then 'platform_super_transfer' else 'assignee_transfer' end
    ), nullif(p_idempotency_key, '')
  );

  perform app_private.enqueue_user_notification(
    p_assignee_user_id, 'todo', '收到转交审批',
    v_actor_name || '将“' || v_instance.business_title || '”转交给你审批：' || v_reason,
    'warning', 'workflow_transfer', v_task.id,
    v_instance.business_type, v_instance.business_id, v_instance.id,
    '/workflow/workbench', jsonb_build_object('tab','pending','instanceId',v_instance.id)
  );

  return v_task.instance_id;
end;
$function$;

--
-- Name: trg_assign_configurable_number; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.trg_assign_configurable_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rule public.sys_document_number_rule;
  v_current text;
  v_override text;
  v_value text;
begin
  select * into v_rule
  from public.sys_document_number_rule
  where rule_key = tg_argv[0] and enabled;
  if not found then
    raise exception '未找到已启用的编号规则：%', tg_argv[0];
  end if;

  v_current := nullif(btrim(coalesce(to_jsonb(new) ->> tg_argv[1], '')), '');
  v_override := nullif(btrim(current_setting(
    'app.document_number.' || replace(tg_argv[0], '.', '_'), true
  )), '');
  if v_rule.auto_enabled then
    v_value := app_private.next_document_number(tg_argv[0]);
  else
    v_value := coalesce(v_current, v_override);
    if v_rule.manual_required and v_value is null then
      raise exception '%未启用自动编码，请手工填写', v_rule.rule_name;
    end if;
  end if;
  new := jsonb_populate_record(new, jsonb_build_object(tg_argv[1], v_value));
  return new;
end;
$function$;

--
-- Name: trg_guard_workflow_delegation; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.trg_guard_workflow_delegation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'UPDATE' then
    if (new.delegator_user_id, new.delegate_user_id, new.starts_at, new.ends_at, new.reason)
       is distinct from
       (old.delegator_user_id, old.delegate_user_id, old.starts_at, old.ends_at, old.reason) then
      raise exception '已创建的委托主体、时间和原因不可修改；请撤销后重新创建';
    end if;
    return new;
  end if;

  if not exists (
    select 1
    from public.sys_user delegator
    join public.sys_user delegate_user on delegate_user.id = new.delegate_user_id
    where delegator.id = new.delegator_user_id
      
      and delegator.status = '1'
      
      and delegate_user.status = '1'
  ) then
    raise exception '委托人或受托人不存在或已停用';
  end if;

  if exists (
    select 1
    from public.wf_delegation delegation
    where true
      and delegation.revoked_at is null
      and tstzrange(delegation.starts_at, delegation.ends_at, '[)')
          && tstzrange(new.starts_at, new.ends_at, '[)')
      and delegation.delegator_user_id = new.delegator_user_id
  ) then
    raise exception '该时间段已存在有效委托，请先调整或撤销原委托';
  end if;

  if exists (
    select 1
    from public.wf_delegation delegation
    where true
      and delegation.revoked_at is null
      and tstzrange(delegation.starts_at, delegation.ends_at, '[)')
          && tstzrange(new.starts_at, new.ends_at, '[)')
      and (
        delegation.delegate_user_id = new.delegator_user_id
        or delegation.delegator_user_id = new.delegate_user_id
      )
  ) then
    raise exception '委托不允许形成转委托或循环委托，请调整时间或人员';
  end if;

  return new;
end;
$function$;

--
-- Name: trg_notify_workflow_action_created; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.trg_notify_workflow_action_created()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_instance public.wf_instance;
  v_action_label text;
  v_severity text;
begin
  if new.action not in ('approve', 'reject', 'cancel') then
    return new;
  end if;

  select * into v_instance
  from public.wf_instance i
  where i.id = new.instance_id;

  if not found or new.actor_user_id is null
     or new.actor_user_id = v_instance.initiator_user_id then
    return new;
  end if;

  v_action_label := case new.action
    when 'approve' then '通过了'
    when 'reject' then '驳回了'
    else '终止了'
  end;
  v_severity := case new.action
    when 'approve' then 'success'
    when 'reject' then 'danger'
    else 'warning'
  end;

  perform app_private.enqueue_user_notification(
    v_instance.initiator_user_id,
    'message',
    new.actor_name_snapshot || v_action_label || '审批节点',
    coalesce(nullif(new.node_name, '') || ' · ', '')
      || v_instance.business_title
      || coalesce('：' || nullif(btrim(coalesce(new.comment, '')), ''), ''),
    v_severity,
    'workflow_action',
    new.id,
    v_instance.business_type,
    v_instance.business_id,
    v_instance.id,
    '/workflow/workbench',
    jsonb_build_object('tab', 'initiated', 'instanceId', v_instance.id)
  );

  return new;
end;
$function$;

--
-- Name: trg_notify_workflow_instance_finished; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.trg_notify_workflow_instance_finished()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_title text;
  v_severity text;
begin
  if old.status = new.status or new.status = 'running' then
    return new;
  end if;

  v_title := case new.status
    when 'approved' then '审批已通过：'
    when 'rejected' then '审批已驳回：'
    when 'withdrawn' then '审批已撤回：'
    when 'cancelled' then '审批已取消：'
    else '审批状态已更新：'
  end || new.business_title;
  v_severity := case new.status
    when 'approved' then 'success'
    when 'rejected' then 'danger'
    when 'cancelled' then 'warning'
    else 'info'
  end;

  perform app_private.enqueue_user_notification(
    new.initiator_user_id,
    'notice',
    v_title,
    coalesce(nullif(btrim(coalesce(new.finish_comment, '')), ''), '流程处理完成，可进入审批工作台查看完整记录。'),
    v_severity,
    'workflow_instance',
    new.id,
    new.business_type,
    new.business_id,
    new.id,
    '/workflow/workbench',
    jsonb_build_object('tab', 'initiated', 'instanceId', new.id)
  );

  return new;
end;
$function$;

--
-- Name: trg_notify_workflow_task_created; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.trg_notify_workflow_task_created()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
