--
-- Name: trg_protect_workflow_records; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.trg_protect_workflow_records()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_table_name = 'wf_action' then
    raise exception '审批动作记录不可修改或删除';
  end if;

  if tg_table_name = 'wf_version' then
    if tg_op = 'DELETE' then
      -- During an ON DELETE CASCADE, the parent definition is already absent
      -- from the deleting statement's snapshot. Direct version deletion still
      -- sees the parent and remains blocked.
      if not exists (
        select 1
        from public.wf_definition d
        where d.id = old.definition_id
      ) then
        return old;
      end if;

      if old.status <> 'draft' then
        raise exception '已发布或已归档的流程版本不可修改';
      end if;
    elsif old.status <> 'draft'
      and (
        new.definition_id is distinct from old.definition_id
        or new.version_no is distinct from old.version_no
        or new.config is distinct from old.config
        
        or not (old.status = 'published' and new.status = 'retired')
      ) then
      raise exception '已发布或已归档的流程版本不可修改';
    end if;
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$function$;

--
-- Name: trg_require_workflow_for_finance_review; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.trg_require_workflow_for_finance_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_requires_workflow boolean:=false; v_label text;
begin
  if new.status is not distinct from old.status then return new; end if;
  if tg_table_name='tms_invoice' then
    v_requires_workflow:=new.status in ('pending_review','issued','certified') or old.status='pending_review';
    v_label:='发票';
  elsif tg_table_name='tms_carrier_statement' then
    v_requires_workflow:=new.status in ('pending_review','confirmed') or old.status='pending_review';
    v_label:='承运商对账单';
  elsif tg_table_name='tms_customer_statement' then
    v_requires_workflow:=new.status in ('pending_review','confirmed') or old.status='pending_review';
    v_label:='客户对账单';
  else
    v_requires_workflow:=new.status='pending_review' or old.status='pending_review';
    v_label:='财务单据';
  end if;
  if v_requires_workflow
    and coalesce(pg_catalog.current_setting('app.workflow_engine',true),'')<>'on' then
    raise exception '%审批状态必须通过审批中心流转',v_label;
  end if;
  return new;
end;$function$;

--
-- Name: trg_require_workflow_for_vehicle_review; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.trg_require_workflow_for_vehicle_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if (
    new.audit_status is distinct from old.audit_status
    or new.audit_by is distinct from old.audit_by
    or new.audit_time is distinct from old.audit_time
    or new.audit_remark is distinct from old.audit_remark
  ) and coalesce(
    pg_catalog.current_setting('app.workflow_engine', true),
    ''
  ) <> 'on' then
    raise exception '车辆档案审核状态与审核信息必须通过审批中心流转';
  end if;

  return new;
end;
$function$;

--
-- Name: trg_require_workflow_initial_review_state; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.trg_require_workflow_initial_review_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if coalesce(pg_catalog.current_setting('app.workflow_engine', true), '') = 'on' then
    return new;
  end if;

  if tg_table_name = 'tms_contract' then
    if new.contract_status in ('pending', 'approved', 'rejected') then
      raise exception '新合同必须先保存为草稿，再通过审批中心提交';
    end if;
  elsif tg_table_name = 'tms_waybill_cost' then
    if new.audit_status in ('pending_review', 'approved', 'rejected') then
      raise exception '新费用必须先保存为草稿，再通过审批中心提交';
    end if;
  elsif tg_table_name = 'tms_invoice' then
    if new.status in ('pending_review', 'issued', 'certified') then
      raise exception '新发票必须先保存为草稿，再通过审批中心提交';
    end if;
  elsif tg_table_name in ('tms_customer_statement', 'tms_carrier_statement') then
    if new.status in ('pending_review', 'confirmed') then
      raise exception '新对账单必须先保存为草稿，再通过审批中心提交';
    end if;
  elsif tg_table_name = 'vehicle_archive' then
    if new.audit_status in ('approved', 'rejected') then
      raise exception '新车辆档案必须先进入待审核，再通过审批中心处理';
    end if;
  end if;

  return new;
end;
$function$;

