--
-- Name: trg_sync_workflow_task_notification; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.trg_sync_workflow_task_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if old.status = 'pending' and new.status <> 'pending' then
    update public.sys_notification n
    set is_read = true,
        read_at = coalesce(n.read_at, now())
    where n.recipient_user_id = new.assignee_user_id
      and n.category = 'todo'
      and n.is_read = false
      and (
        (n.source_type = 'workflow_task' and n.source_id = new.id)
        or (
          n.source_type in ('workflow_task_due_soon', 'workflow_task_overdue')
          and n.source_id in (
            select e.id from public.wf_task_reminder_event e where e.task_id = new.id
          )
        )
      );

    update public.sys_notification n
    set is_read = true,
        read_at = coalesce(n.read_at, now())
    where n.category = 'message'
      and n.source_type = 'workflow_task_manager_escalation'
      and n.is_read = false
      and n.source_id in (
        select e.id from public.wf_task_reminder_event e where e.task_id = new.id
      );
  end if;
  return new;
end;
$function$;

--
-- Name: trg_validate_ai_artifact_review_transition; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.trg_validate_ai_artifact_review_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.ai_run_id is distinct from old.ai_run_id
    or new.auth_user_id is distinct from old.auth_user_id
    
    or new.feature is distinct from old.feature
    or new.artifact_type is distinct from old.artifact_type
    or new.proposed_payload is distinct from old.proposed_payload
    or new.confidence is distinct from old.confidence
    or new.field_confidence is distinct from old.field_confidence
    or new.warnings is distinct from old.warnings
    or new.metadata is distinct from old.metadata then
    raise exception 'AI artifact proposal fields are immutable';
  end if;

  if old.status <> new.status then
    if old.status <> 'pending' or new.status not in ('applied', 'rejected', 'superseded') then
      raise exception 'Invalid AI artifact review transition: % -> %', old.status, new.status;
    end if;
  elsif old.status = 'pending' and (
    new.final_payload is distinct from old.final_payload
    or new.accepted_fields is distinct from old.accepted_fields
    or new.corrected_fields is distinct from old.corrected_fields
    or new.entity_type is distinct from old.entity_type
    or new.entity_id is distinct from old.entity_id
    or new.review_note is distinct from old.review_note
    or new.reviewed_at is distinct from old.reviewed_at
  ) then
    raise exception 'Review fields can only change while completing a pending AI artifact';
  elsif old.status <> 'pending' and (
    new.final_payload is distinct from old.final_payload
    or new.accepted_fields is distinct from old.accepted_fields
    or new.corrected_fields is distinct from old.corrected_fields
    or new.entity_type is distinct from old.entity_type
    or new.entity_id is distinct from old.entity_id
    or new.review_note is distinct from old.review_note
    or new.reviewed_at is distinct from old.reviewed_at
  ) then
    raise exception 'Completed AI artifact reviews are immutable';
  end if;

  if new.status in ('applied', 'rejected') and new.reviewed_at is null then
    new.reviewed_at := now();
  end if;

  return new;
end;
$function$;

--
-- Name: trg_validate_ai_feedback_resolution_transition; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.trg_validate_ai_feedback_resolution_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.status in ('resolved', 'dismissed')
     and new.status not in (old.status, 'open') then
    raise exception 'Closed AI feedback can only remain closed or be reopened';
  end if;
  return new;
end;
$function$;

--
-- Name: trg_validate_document_number_rule; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.trg_validate_document_number_rule()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_seq_count integer;
  v_sample text;
begin
  new.rule_key := lower(btrim(new.rule_key));
  new.rule_name := btrim(new.rule_name);
  new.target_table := lower(btrim(new.target_table));
  new.target_column := lower(btrim(new.target_column));
  new.template := btrim(new.template);
  new.timezone := btrim(new.timezone);
  new.remark := nullif(btrim(coalesce(new.remark, '')), '');

  select count(*) into v_seq_count
  from regexp_matches(new.template, '\{SEQ:[1-9][0-9]?\}', 'g');
  if v_seq_count <> 1 then
    raise exception '编号模板必须且只能包含一个流水号令牌，例如 {SEQ:3}';
  end if;

  v_sample := new.template;
  v_sample := replace(v_sample, '{YYYYMMDD}', '20991231');
  v_sample := replace(v_sample, '{YYYYMM}', '209912');
  v_sample := replace(v_sample, '{YYMM}', '9912');
  v_sample := replace(v_sample, '{YYYY}', '2099');
  v_sample := replace(v_sample, '{YY}', '99');
  v_sample := replace(v_sample, '{MM}', '12');
  v_sample := replace(v_sample, '{DD}', '31');
  v_sample := regexp_replace(v_sample, '\{SEQ:[1-9][0-9]?\}', '999999999999');
  if v_sample ~ '[{}]' then
    raise exception '编号模板包含不支持的令牌';
  end if;
  if length(v_sample) > 50 then
    raise exception '编号模板生成结果不能超过 50 个字符';
  end if;
  if not exists (select 1 from pg_catalog.pg_timezone_names where name = new.timezone) then
    raise exception '无效时区：%', new.timezone;
  end if;

  if tg_op = 'UPDATE' then
    if new.rule_key is distinct from old.rule_key
       or new.target_table is distinct from old.target_table
       or new.target_column is distinct from old.target_column
       or new.category is distinct from old.category
       or new.builtin is distinct from old.builtin
       or new.manual_required is distinct from old.manual_required then
      raise exception '内置编号规则的标识、目标字段和业务分类不允许修改';
    end if;
    if new.template is distinct from old.template
       or new.reset_cycle is distinct from old.reset_cycle
       or new.sequence_start is distinct from old.sequence_start
       or new.timezone is distinct from old.timezone then
      new.rule_version := old.rule_version + 1;
    else
      new.rule_version := old.rule_version;
    end if;
  end if;
  return new;
end;
$function$;

--
-- Name: trg_validate_workflow_version_business_config; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.trg_validate_workflow_version_business_config()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_business_type text;
begin
  select d.business_type into v_business_type
  from public.wf_definition d
  where d.id = new.definition_id;

  if v_business_type is null then
    raise exception '流程定义不存在';
  end if;

  perform app_private.validate_workflow_business_config(v_business_type, new.config);
  return new;
end;
$function$;

--
-- Name: upsert_notification_subject; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.upsert_notification_subject(p_scenario_code text, p_business_type text, p_business_id uuid, p_subject_key text, p_subject_title text, p_due_at timestamp with time zone, p_owner_user_id uuid, p_route_path text, p_route_query jsonb, p_metadata jsonb, p_status text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_scenario public.sys_notification_scenario%rowtype;
  v_subject_id uuid;
begin
  select * into v_scenario
  from public.sys_notification_scenario
  where scenario_code = p_scenario_code and enabled is true;
  if not found then raise exception 'Notification scenario not found: %', p_scenario_code; end if;

  if p_due_at is null or p_status <> 'active' then
    update public.sys_notification_subject
    set status = case when p_status in ('resolved', 'cancelled') then p_status else 'cancelled' end,
        update_by = 'system-reminder'
    where true
      and scenario_id = v_scenario.id
      and business_type = p_business_type
      and business_id = p_business_id
      and subject_key = coalesce(nullif(p_subject_key, ''), 'default')
    returning id into v_subject_id;
    return v_subject_id;
  end if;

  insert into public.sys_notification_subject ( scenario_id, business_type, business_id, subject_key,
    subject_title, due_at, owner_user_id, route_path, route_query, metadata,
    status, create_by, update_by
  )
  values ( v_scenario.id, p_business_type, p_business_id,
    coalesce(nullif(p_subject_key, ''), 'default'), btrim(p_subject_title), p_due_at,
    p_owner_user_id, coalesce(nullif(p_route_path, ''), v_scenario.route_path),
    coalesce(p_route_query, '{}'::jsonb), coalesce(p_metadata, '{}'::jsonb),
    'active', 'system-reminder', 'system-reminder'
  )
  on conflict (scenario_id, business_type, business_id, subject_key)
  do update set
    subject_title = excluded.subject_title,
    due_at = excluded.due_at,
    owner_user_id = excluded.owner_user_id,
    route_path = excluded.route_path,
    route_query = excluded.route_query,
    metadata = excluded.metadata,
    status = 'active',
    update_by = excluded.update_by
  returning id into v_subject_id;
  return v_subject_id;
end;
$function$;

--
-- Name: validate_center_policy; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_center_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if jsonb_typeof(new.policy) is distinct from 'object' then raise exception '工作中心配置格式无效'; end if;
if coalesce(new.policy->>'reportMode','') not in ('手动开始手动结束','手动开始自动结束','自动开始手动结束','非生产工位') then raise exception '请选择有效的报工'; end if;
if coalesce(new.policy->>'deviation','') not in ('调整到下一班次','PMC调整') then raise exception '请选择有效的当班进度偏差调整'; end if;
if coalesce(new.policy->>'materialCheck','') not in ('无','单料单批','单料多批','多料多批') then raise exception '请选择有效的材料投料校验'; end if;
if coalesce(new.policy->>'timeAllocation','') not in ('分摊','多重配给') then raise exception '请选择有效的工时分配'; end if;
if coalesce(new.policy->>'goodDefault','') not in ('无','任务数量','机器计数','任务数量与机器计数取小值') then raise exception '请选择有效的报工良品数默认值'; end if;
if coalesce(new.policy->>'quantityCheck','') not in ('不检查','超产提醒','检查','限额100%（仅良品）','限额100%（含不良品）','自定义限额','限额机器计数','限额工单100%（含不良品）') then raise exception '请选择有效的报工数量检查'; end if;
if jsonb_typeof(new.policy->'specialFields') is distinct from 'array' then raise exception '请选择报工特殊项'; end if;
 if jsonb_array_length(new.policy->'specialFields')=0 or exists(select 1 from jsonb_array_elements_text(new.policy->'specialFields') v where v not in ('无','模具编号','模穴数','生产批号','备注')) then raise exception '报工特殊项选项无效'; end if;
 if jsonb_array_length(new.policy->'specialFields')>1 and (new.policy->'specialFields') ? '无' then raise exception '报工特殊项的“无”不能与其他选项同时选择'; end if;
if coalesce(new.policy->>'parallel','') not in ('不允许','允许') then raise exception '请选择有效的并行生产'; end if;
if coalesce(new.policy->>'progressLimit','') not in ('限额100%','不限制','限额120%') then raise exception '请选择有效的进度限额'; end if;
if coalesce(new.policy->>'shiftLock','') not in ('不锁定','锁定') then raise exception '请选择有效的班次锁定'; end if;
if coalesce(new.policy->>'taskOrder','') not in ('不管控','管控') then raise exception '请选择有效的任务排序(app)'; end if;
if coalesce(new.policy->>'autoChangeover','') not in ('否','是') then raise exception '请选择有效的自动换线'; end if;
if coalesce(new.policy->>'inspectionSave','') not in ('仅全部项完成可保存','部分项完成可保存') then raise exception '请选择有效的检验保存'; end if;
if jsonb_typeof(new.policy->'startControl') is distinct from 'array' then raise exception '请选择开始加工控制'; end if;
 if jsonb_array_length(new.policy->'startControl')=0 or exists(select 1 from jsonb_array_elements_text(new.policy->'startControl') v where v not in ('不控制','必须完成投料','必须首检完成','必须换模完成','单次首检','设备点检控制','每次开工投料')) then raise exception '开始加工控制选项无效'; end if;
 if jsonb_array_length(new.policy->'startControl')>1 and (new.policy->'startControl') ? '不控制' then raise exception '开始加工控制的“不控制”不能与其他选项同时选择'; end if;
if jsonb_typeof(new.policy->'reportControl') is distinct from 'array' then raise exception '请选择报工控制'; end if;
 if jsonb_array_length(new.policy->'reportControl')=0 or exists(select 1 from jsonb_array_elements_text(new.policy->'reportControl') v where v not in ('不控制','首检完成','巡检控制','末检控制','上模完成','与开工人一致')) then raise exception '报工控制选项无效'; end if;
 if jsonb_array_length(new.policy->'reportControl')>1 and (new.policy->'reportControl') ? '不控制' then raise exception '报工控制的“不控制”不能与其他选项同时选择'; end if;
if coalesce(new.policy->>'yellowPause','') not in ('否','是') then raise exception '请选择有效的黄灯暂停'; end if;
if coalesce(new.policy->>'personAllocation','') not in ('标准分配','流水线分配','按人员数量分配','按人员报额分配') then raise exception '请选择有效的人员分配'; end if;
if coalesce(new.policy->>'achievement','') not in ('按产能计算','按计划计算') then raise exception '请选择有效的当班达成率'; end if;
if coalesce(new.policy->>'clearBatch','') not in ('不清除','清除') then raise exception '请选择有效的报工后清除原料批号'; end if;
if coalesce(new.policy->>'quickJoin','') not in ('关闭','开启') then raise exception '请选择有效的快捷参与'; end if;
if coalesce(new.policy->>'planOrder','') not in ('按分配时间','按工序交期','按单号大小') then raise exception '请选择有效的计划排序'; end if;
if coalesce(new.policy->>'autoReport','') not in ('关闭','班次结束','自定义时间') then raise exception '请选择有效的自动报工'; end if;
if coalesce(new.policy->>'autoStart','') not in ('关闭','班次开始') then raise exception '请选择有效的自动开始'; end if;
if coalesce(new.policy->>'operationLimit','') !~ '^[0-9]+$' or (new.policy->>'operationLimit')::numeric>86400 or coalesce(new.policy->>'operationUnit','') not in ('秒','分钟') then raise exception '操作时限需为 0 至 86400 的整数'; end if;
 if coalesce(new.policy->>'customLimit','') !~ '^[0-9]+$' or (new.policy->>'customLimit')::integer not between 1 and 10000 then raise exception '自定义限额需为 1 至 10000 的整数百分比'; end if;
 if new.policy->>'autoReport'='自定义时间' and coalesce(new.policy->>'reportTime','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then raise exception '请选择有效的自定义报工时间'; end if;
 return new;
end $function$;

--
-- Name: validate_center_relations; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_center_relations()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare center public.mdm_work_center;
begin

 if tg_table_name='mdm_work_center' then
   if tg_op='UPDATE' then
     if new.qr_token is distinct from old.qr_token then raise exception '工作中心二维码不能修改'; end if;
     if (to_jsonb(new)-array['person_ids','update_by','update_time']) is distinct from (to_jsonb(old)-array['person_ids','update_by','update_time']) and not app_private.has_permission('MdmWorkCenter:Edit') then raise exception '没有编辑工作中心权限' using errcode='42501'; end if;
     if new.person_ids is distinct from old.person_ids and not (app_private.has_permission('MdmWorkCenter:Edit') or app_private.has_permission('MdmWorkCenter:Personnel')) then raise exception '没有人员安排权限' using errcode='42501'; end if;
   end if;
   if new.main_center_id is not null then

     perform pg_advisory_xact_lock(hashtextextended('mdm_work_center',8810));
     if exists(with recursive chain as(select id,main_center_id from public.mdm_work_center where id=new.main_center_id union select w.id,w.main_center_id from public.mdm_work_center w join chain c on w.id=c.main_center_id) select 1 from chain where id=new.id) then raise exception '主工序位不能形成循环'; end if;
   end if;
   if exists(select 1 from unnest(new.person_ids) p where not exists(select 1 from app_private.work_center_people() x where x.id=p  and x.enabled)) then raise exception '请选择已启用的生产人员'; end if;
   if new.personnel_mode='指定人员' and cardinality(new.person_ids)=0 then raise exception '指定人员模式至少选择一人'; end if;
   if new.personnel_mode='指定人数' then new.person_ids:='{}'; end if;
 elsif tg_table_name='mdm_work_center_adjustment' then
   select * into center from public.mdm_work_center where id=new.work_center_id  for update;
   if not found or center.personnel_mode<>'指定人员' then raise exception '仅指定人员的工作中心支持临时调整'; end if;

   if new.kind='短期离开' and not(new.person_id=any(center.person_ids)) then raise exception '短期离开只能选择当前指定人员'; end if;
   if new.kind='短期加入' and new.person_id=any(center.person_ids) then raise exception '该人员已是指定人员'; end if;
   if exists(select 1 from public.mdm_work_center_adjustment a where a.work_center_id=new.work_center_id and a.person_id=new.person_id and a.id<>new.id and tstzrange(a.start_time,a.end_time,'[)') && tstzrange(new.start_time,new.end_time,'[)')) then raise exception '该人员的临时调整时段存在重叠'; end if;


 elsif tg_table_name='mdm_process_route_step' then
   if tg_op='INSERT' and (new.template_id is not null or new.work_center_policy is not null or new.config_updated_at is not null) then raise exception '新增工序后请通过专用操作绑定模板或更新工艺'; end if;
   if tg_op='UPDATE' then
     if new.template_id is distinct from old.template_id and not app_private.has_permission('MdmOperationTemplate:'||case when new.template_id is null then 'Unbind' else 'Bind' end) then raise exception '没有模板绑定权限' using errcode='42501'; end if;
     if (new.work_center_policy is distinct from old.work_center_policy or new.config_updated_at is distinct from old.config_updated_at) and not app_private.has_permission('MdmWorkCenter:UpdateProcess') then raise exception '没有更新产品工艺权限' using errcode='42501'; end if;
     if (to_jsonb(new)-array['template_id','work_center_policy','config_updated_at','update_by','update_time']) is distinct from (to_jsonb(old)-array['template_id','work_center_policy','config_updated_at','update_by','update_time']) and not app_private.has_permission('MdmProcessRoute:Edit') then raise exception '没有编辑工艺路线权限' using errcode='42501'; end if;
   end if;
   if new.template_id is not null and not exists(select 1 from public.mdm_operation_template where id=new.template_id  and enabled) then raise exception '请选择启用的作业模板'; end if;
 end if;
 return new;
end $function$;

--
-- Name: validate_dict_type_cascade_parent; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_dict_type_cascade_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  parent_row public.sys_dict_type%rowtype;
begin
  if new.cascade_parent_type_id is not null then
    if new.node_type <> 'dictionary' then
      raise exception using errcode = '23514', message = '只有字典类型可以配置级联上级类型';
    end if;

    select * into parent_row
    from public.sys_dict_type
    where id = new.cascade_parent_type_id;

    if not found or parent_row.node_type <> 'dictionary' then
      raise exception using errcode = '23514', message = '级联上级必须是有效的字典类型';
    end if;


    if exists (
      with recursive ancestors as (
        select parent.id, parent.cascade_parent_type_id, array[parent.id] as visited
        from public.sys_dict_type parent
        where parent.id = new.cascade_parent_type_id
        union all
        select parent.id, parent.cascade_parent_type_id, ancestors.visited || parent.id
        from public.sys_dict_type parent
        join ancestors on parent.id = ancestors.cascade_parent_type_id
        where not parent.id = any(ancestors.visited)
      )
      select 1 from ancestors where id = new.id
    ) then
      raise exception using errcode = '23514', message = '字典类型级联关系不能形成循环';
    end if;
  end if;

  if exists (
    select 1
    from public.sys_dictionary child_entry
    join public.sys_dictionary parent_entry on parent_entry.id = child_entry.cascade_parent_id
    where child_entry.type_id = new.id
      and child_entry.cascade_parent_id is not null
      and (
        new.cascade_parent_type_id is null
        or parent_entry.type_id <> new.cascade_parent_type_id
      )
  ) then
    raise exception using errcode = '23514', message = '已有字典项的级联归属与新配置不一致，请先调整字典项';
  end if;

  return new;
end;
$function$;

--
-- Name: validate_dict_type_hierarchy; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_dict_type_hierarchy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  parent_row public.sys_dict_type%rowtype;
  has_cycle boolean;
begin
  if tg_op = 'UPDATE' and old.node_type is distinct from new.node_type then
    if exists (select 1 from public.sys_dict_type where parent_id = new.id) then
      raise exception '存在下级节点时不能修改节点类型';
    end if;

    if exists (select 1 from public.sys_dictionary where type_id = new.id) then
      raise exception '存在字典项时不能修改节点类型';
    end if;
  end if;

  if new.parent_id is null then
    if new.node_type <> 'directory' then
      raise exception '字典类型必须归属到上级目录';
    end if;
    return new;
  end if;

  if new.id is not null and new.parent_id = new.id then
    raise exception '字典目录不能选择自身作为上级';
  end if;

  select *
  into parent_row
  from public.sys_dict_type
  where id = new.parent_id;

  if not found then
    raise exception '上级字典目录不存在';
  end if;


  if parent_row.node_type <> 'directory' then
    raise exception '字典类型不能作为其他节点的上级';
  end if;

  if new.id is not null then
    with recursive descendants as (
      select id from public.sys_dict_type where parent_id = new.id
      union all
      select child.id
      from public.sys_dict_type child
      join descendants parent on child.parent_id = parent.id
    )
    select exists (select 1 from descendants where id = new.parent_id)
    into has_cycle;

    if has_cycle then
      raise exception '不能将字典目录移动到自己的下级';
    end if;
  end if;

  return new;
end;
$function$;

--
-- Name: validate_dictionary_cascade_assignment; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_dictionary_cascade_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  expected_parent_type_id uuid;
  parent_entry public.sys_dictionary%rowtype;
begin
  if new.cascade_parent_id is null then
    return new;
  end if;

  select cascade_parent_type_id into expected_parent_type_id
  from public.sys_dict_type
  where id = new.type_id ;

  if expected_parent_type_id is null then
    raise exception using errcode = '23514', message = '当前字典类型未配置级联上级类型';
  end if;

  select * into parent_entry
  from public.sys_dictionary
  where id = new.cascade_parent_id;

  if not found
    or parent_entry.type_id <> expected_parent_type_id then
    raise exception using errcode = '23514', message = '所选级联上级字典项与类型配置不一致';
  end if;

  return new;
end;
$function$;

--
-- Name: validate_dictionary_hierarchy; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_dictionary_hierarchy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  type_row public.sys_dict_type%rowtype;
  parent_row public.sys_dictionary%rowtype;
  has_cycle boolean;
begin
  select *
  into type_row
  from public.sys_dict_type
  where id = new.type_id;

  if not found or type_row.node_type <> 'dictionary' then
    raise exception '字典项必须归属于有效的字典类型';
  end if;


  if new.parent_id is null then
    return new;
  end if;

  if new.id is not null and new.parent_id = new.id then
    raise exception '字典项不能选择自身作为上级';
  end if;

  select *
  into parent_row
  from public.sys_dictionary
  where id = new.parent_id;

  if not found then
    raise exception '上级字典项不存在';
  end if;

  if parent_row.type_id is distinct from new.type_id then
    raise exception '上级字典项必须属于同一字典类型';
  end if;

  if new.id is not null then
    with recursive descendants as (
      select id
      from public.sys_dictionary
      where parent_id = new.id
      union all
      select child.id
      from public.sys_dictionary child
      join descendants parent on child.parent_id = parent.id
    )
    select exists (
      select 1
      from descendants
      where id = new.parent_id
    )
    into has_cycle;

    if has_cycle then
      raise exception '不能将字典项移动到自己的下级';
    end if;
  end if;

  return new;
end
$function$;

--
-- Name: validate_hr_employee_assignment_capacity; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_hr_employee_assignment_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_position public.hr_position%rowtype;
  v_incumbent_count integer;
begin
  if not new.primary_assignment
     or new.effective_end is not null
     or new.assignment_status = 'ended' then
    return new;
  end if;

  select position_row.*
  into v_position
  from public.hr_position position_row
  where position_row.id = new.position_id
    
  for update;

  if not found then
    raise exception '任职岗位不存在';
  end if;
  if not v_position.enabled then
    raise exception '任职岗位已停用';
  end if;
  if v_position.organization_id is not null
     and v_position.organization_id <> new.organization_id then
    raise exception '任职组织与岗位所属组织不一致';
  end if;
  if v_position.job_profile_id <> new.job_profile_id then
    raise exception '任职标准职务与岗位标准职务不一致';
  end if;

  select count(*)::integer
  into v_incumbent_count
  from public.hr_employee_assignment assignment_row
  where true
    and assignment_row.position_id = new.position_id
    and assignment_row.primary_assignment
    and assignment_row.effective_end is null
    and assignment_row.assignment_status <> 'ended'
    and assignment_row.id <> new.id;

  if not v_position.multiple_incumbents_allowed and v_incumbent_count >= 1 then
    raise exception '该岗位仅允许一人任职';
  end if;
  if v_incumbent_count >= v_position.headcount_limit then
    raise exception '该岗位编制已满（上限 % 人）', v_position.headcount_limit;
  end if;
  return new;
end;
$function$;

--
-- Name: validate_hr_personnel_change_target; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_hr_personnel_change_target()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_position public.hr_position%rowtype;
begin
  select position_row.*
  into v_position
  from public.hr_position position_row
  where position_row.id = new.to_position_id
    ;

  if not found then
    raise exception '目标岗位不存在';
  end if;
  if v_position.job_profile_id <> new.to_job_profile_id then
    raise exception '目标标准职务必须与目标岗位的标准职务一致';
  end if;
  if v_position.organization_id is not null
     and v_position.organization_id <> new.to_organization_id then
    raise exception '目标组织必须与目标岗位所属组织一致';
  end if;

  if new.change_type in ('promotion', 'demotion')
     and new.to_position_id is not distinct from new.from_position_id
     and new.to_job_profile_id is not distinct from new.from_job_profile_id
     and new.to_grade_id is not distinct from new.from_grade_id
     and new.to_business_title is not distinct from new.from_business_title then
    raise exception '晋升或降职至少需要实际调整岗位、职级或任职称谓';
  end if;
  return new;
end;
$function$;

--
-- Name: validate_hr_position_capacity; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_hr_position_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_incumbent_count integer;
begin
  select count(*)::integer
  into v_incumbent_count
  from public.hr_employee_assignment assignment_row
  where true
    and assignment_row.position_id = new.id
    and assignment_row.primary_assignment
    and assignment_row.effective_end is null
    and assignment_row.assignment_status <> 'ended';

  if new.headcount_limit < v_incumbent_count then
    raise exception '岗位编制上限不能低于当前任职人数（%）', v_incumbent_count;
  end if;
  if not new.multiple_incumbents_allowed and v_incumbent_count > 1 then
    raise exception '当前岗位已有多人任职，不能改为单人岗位';
  end if;
  return new;
end;
$function$;

--
-- Name: validate_mdm_production_record; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_mdm_production_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  prefix text := tg_argv[0];
  personnel_scope_edit boolean := false;
begin
  if tg_op='UPDATE' then

    if tg_table_name in ('mdm_production_department','mdm_production_personnel') then
      if new.enabled is distinct from old.enabled and not app_private.has_permission(prefix || case when new.enabled then ':Enable' else ':Disable' end) then
        raise exception '没有启用或禁用权限' using errcode='42501';
      end if;
      if tg_table_name='mdm_production_personnel' then
        personnel_scope_edit :=
          new.department_id is distinct from old.department_id
          and (to_jsonb(new)-array['department_id','update_by','update_time'])
              is not distinct from
              (to_jsonb(old)-array['department_id','update_by','update_time'])
          and app_private.has_permission('MdmPersonnelWorkCenter:Edit');
      end if;
      if (to_jsonb(new)-array['enabled','update_by','update_time']) is distinct from (to_jsonb(old)-array['enabled','update_by','update_time'])
        and not personnel_scope_edit
        and not app_private.has_permission(prefix || ':Edit') then raise exception '没有编辑权限' using errcode='42501'; end if;
    end if;
  end if;
  if tg_table_name='mdm_production_department' then
    if new.parent_id is not null then

      perform pg_advisory_xact_lock(hashtextextended('mdm_production_department', 8721));
      if exists(with recursive ancestors as (
        select id,parent_id from public.mdm_production_department where id=new.parent_id
        union
        select d.id,d.parent_id from public.mdm_production_department d join ancestors a on d.id=a.parent_id
      ) select 1 from ancestors where id=new.id) then raise exception '上级部门不能选择自身或下级部门'; end if;
    end if;
  elsif tg_table_name='mdm_production_personnel' then
    if exists(select 1 from unnest(new.permission_department_ids) selected(id)
      where not exists(select 1 from public.mdm_production_department d where d.id=selected.id )) then
      raise exception '权限部门必须为有效的生产部门';
    end if;
  elsif tg_table_name='mdm_production_calendar' then
    if new.work_date <= (current_timestamp at time zone 'Asia/Shanghai')::date then
      raise exception '只能设置明天及以后的生产日历';
    end if;
  end if;
  return new;
end
$function$;

--
-- Name: validate_mdm_shift_pattern; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_mdm_shift_pattern()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  s jsonb; b jsonb; output jsonb:='[]'; rests jsonb; st integer; en integer;
  bs integer; be integer; last_end integer; rest_minutes integer; handover integer;
  shift_index integer; next_start integer; next_shift jsonb;
begin
  if jsonb_typeof(new.shifts) is distinct from 'array' or jsonb_array_length(new.shifts) not between 1 and 12 then
    raise exception '轮班模式需包含 1 至 12 个班次';
  end if;
  for s in select value from jsonb_array_elements(new.shifts) loop
    if nullif(btrim(s->>'name'),'') is null or coalesce(s->>'startTime','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
      or coalesce(s->>'endTime','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then raise exception '请填写班次名称和有效的开始、结束时间'; end if;
    st:=split_part(s->>'startTime',':',1)::integer*60+split_part(s->>'startTime',':',2)::integer;
    en:=split_part(s->>'endTime',':',1)::integer*60+split_part(s->>'endTime',':',2)::integer;
    if en=st then raise exception '班次开始和结束时间不能相同'; end if;
    if en<st then en:=en+1440; end if;
    rests:='[]'; last_end:=st; rest_minutes:=0;
    if jsonb_typeof(s->'breaks') is distinct from 'array' or jsonb_array_length(s->'breaks')>20 then raise exception '休息时段格式不正确'; end if;
    for b in select value from jsonb_array_elements(s->'breaks') loop
      if coalesce(b->>'startTime','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
        or coalesce(b->>'endTime','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then raise exception '请选择有效的休息时间'; end if;
      bs:=split_part(b->>'startTime',':',1)::integer*60+split_part(b->>'startTime',':',2)::integer;
      be:=split_part(b->>'endTime',':',1)::integer*60+split_part(b->>'endTime',':',2)::integer;
      if bs<st then bs:=bs+1440; end if;
      if be<st then be:=be+1440; end if;
      if be<=bs or bs<last_end or be>en then raise exception '休息时段需按时间排序，不能重叠且必须在班次内'; end if;
      rest_minutes:=rest_minutes+be-bs; last_end:=be;
      rests:=rests||jsonb_build_array(jsonb_build_object('startTime',b->>'startTime','endTime',b->>'endTime'));
    end loop;
    handover:=coalesce((s->>'handoverMinutes')::integer,0);
    if handover<0 or handover>en-st or rest_minutes>=en-st then raise exception '交班时长或休息总时长超出班次范围'; end if;
    output:=output||jsonb_build_array(jsonb_build_object('name',btrim(s->>'name'),'startTime',s->>'startTime',
      'endTime',s->>'endTime','breaks',rests,'handoverMinutes',handover,'handoverAuto',coalesce((s->>'handoverAuto')::boolean,true),
      'restMinutes',rest_minutes,'workMinutes',en-st-rest_minutes));
  end loop;
  for shift_index in 0..jsonb_array_length(output)-1 loop
    s:=output->shift_index;
    if (s->>'handoverAuto')::boolean then
      st:=split_part(s->>'startTime',':',1)::integer*60+split_part(s->>'startTime',':',2)::integer;
      en:=split_part(s->>'endTime',':',1)::integer*60+split_part(s->>'endTime',':',2)::integer;
      if en<st then en:=en+1440; end if;
      next_shift:=output->((shift_index+1)%jsonb_array_length(output));
      next_start:=split_part(next_shift->>'startTime',':',1)::integer*60+split_part(next_shift->>'startTime',':',2)::integer;
      if next_start<=st then next_start:=next_start+1440; end if;
      output:=jsonb_set(output,array[shift_index::text,'handoverMinutes'],to_jsonb(greatest(0,en-next_start)));
    end if;
  end loop;
  new.shifts:=output;
  return new;
end $function$;

--
-- Name: validate_mdm_shift_schedule; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_mdm_shift_schedule()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_permission text; v_pattern public.mdm_production_shift_pattern%rowtype; v_shift jsonb;
begin
  v_permission:=case when tg_op='INSERT' then 'MdmShiftScheduling:Add'
    when new.deleted_at is not null and old.deleted_at is null then 'MdmShiftScheduling:Delete'
    else 'MdmShiftScheduling:Edit' end;
  if auth.uid() is null or not app_private.has_permission(v_permission) then
    raise exception '没有排班维护权限' using errcode='42501';
  end if;
  if new.date_mode not in ('single','ongoing','range')
    or (new.date_mode='single' and new.end_date is distinct from new.start_date)
    or (new.date_mode='ongoing' and new.end_date is not null)
    or (new.date_mode='range' and (new.end_date is null or new.end_date<new.start_date)) then
    raise exception '排班日期范围无效';
  end if;
  if cardinality(new.weekdays) is null or cardinality(new.weekdays) not between 1 and 7
    or array_position(new.weekdays,null) is not null
    or exists(select 1 from unnest(new.weekdays) weekday where weekday not between 0 and 6) then
    raise exception '请至少选择一个有效的参与星期';
  end if;
  select * into v_pattern from public.mdm_production_shift_pattern p
  where p.id=new.pattern_id and p.department_id=new.department_id ;
  if not found then raise exception '轮班模式不属于当前部门或产线'; end if;
  if new.shift_index<1 or new.shift_index>jsonb_array_length(v_pattern.shifts) then
    raise exception '请选择有效班次';
  end if;
  v_shift:=v_pattern.shifts->(new.shift_index-1);
  new.shift_name:=btrim(v_shift->>'name');
  new.shift_start_time:=(v_shift->>'startTime')::time;
  new.shift_end_time:=(v_shift->>'endTime')::time;
  if new.deleted_at is null and exists(
    select 1 from public.mdm_shift_schedule s
    where s.department_id=new.department_id
      and s.pattern_id=new.pattern_id and s.shift_index=new.shift_index
      and s.deleted_at is null and s.id<>new.id
      and app_private.mdm_shift_schedule_occurrence_overlap(
        s.start_date,s.end_date,s.weekdays,new.start_date,new.end_date,new.weekdays
      )
  ) then raise exception '该班次在所选参与日期内已有排班，请编辑现有排班'; end if;
  if new.deleted_at is null and tg_op='UPDATE' and exists(
    select 1 from public.mdm_shift_schedule_member mine
    join public.mdm_shift_schedule_member other
      on other.personnel_id=mine.personnel_id 
    join public.mdm_shift_schedule other_schedule
      on other_schedule.id=other.schedule_id and other_schedule.deleted_at is null
    where mine.schedule_id=new.id and other.schedule_id<>new.id
      and app_private.mdm_shift_schedule_occurrence_overlap(
        other_schedule.start_date,other_schedule.end_date,other_schedule.weekdays,
        new.start_date,new.end_date,new.weekdays
      )
  ) then raise exception '班组中有人员在所选参与日期内已安排其他班次'; end if;
  return new;
end
$function$;

--
-- Name: validate_mdm_shift_schedule_member; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_mdm_shift_schedule_member()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_row public.mdm_shift_schedule_member%rowtype := case when tg_op='DELETE' then old else new end; v_schedule public.mdm_shift_schedule%rowtype;
begin
  if auth.uid() is null or not app_private.has_permission('MdmShiftScheduling:Edit') then if tg_op='INSERT' and app_private.has_permission('MdmShiftScheduling:Add') then null; else raise exception '没有班组人员维护权限' using errcode='42501'; end if; end if;
  select * into v_schedule from public.mdm_shift_schedule where id=v_row.schedule_id  and deleted_at is null;
  if not found then raise exception '排班不存在或已删除'; end if;
  if tg_op<>'DELETE' then


  end if;
  return v_row;
end $function$;

--
-- Name: validate_operation_template; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_operation_template()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare item jsonb; total numeric:=0;
begin
 if tg_op='UPDATE' then

   if new.enabled is distinct from old.enabled and not app_private.has_permission('MdmOperationTemplate:'||case when new.enabled then 'Enable' else 'Disable' end) then raise exception '没有启用或禁用权限' using errcode='42501'; end if;
   if (to_jsonb(new)-array['enabled','total_score','update_by','update_time']) is distinct from (to_jsonb(old)-array['enabled','total_score','update_by','update_time']) and not app_private.has_permission('MdmOperationTemplate:Edit') then raise exception '没有编辑权限' using errcode='42501'; end if;
 end if;
 if jsonb_typeof(new.items) is distinct from 'array' or jsonb_array_length(new.items) not between 1 and 200 then raise exception '作业模板需包含 1 至 200 个任务项'; end if;
 for item in select value from jsonb_array_elements(new.items) loop
   if coalesce(item->>'inputMode','') not in ('输入','选择','扫码') or nullif(btrim(item->>'category'),'') is null or nullif(btrim(item->>'name'),'') is null or jsonb_typeof(item->'score') is distinct from 'number' or (item->>'score')::numeric not between 0 and 100000 then raise exception '请完整填写任务分类、任务名称、输入方式和有效分数'; end if;
   if jsonb_typeof(item->'choices') is distinct from 'array' then raise exception '选择项格式无效'; end if;
   if item->>'inputMode'='选择' and (jsonb_array_length(item->'choices')=0 or exists(select 1 from jsonb_array_elements(item->'choices') c where jsonb_typeof(c) <> 'string' or nullif(btrim(c#>>'{}'),'') is null)) then raise exception '选择方式至少需要一个有效选项'; end if;
   total:=total+(item->>'score')::numeric;
 end loop;
 new.total_score:=total; return new;
end $function$;

--
-- Name: validate_registration_strategy_param; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_registration_strategy_param()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role_id uuid;
  v_role record;
begin
  if new.param_key <> 'registration.default_role_id' or new.enabled is not true then
    return new;
  end if;

  begin
    v_role_id := new.param_value::uuid;
  exception when invalid_text_representation then
    raise exception '默认注册角色必须选择有效角色，不能手工填写编码';
  end;

  select r.id, r.role_name, r.role_code, r.enabled, r.builtin_type
  into v_role
  from public.sys_role r
  where r.id = v_role_id;

  if v_role.id is null then
    raise exception '默认注册角色不存在';
  end if;
  if v_role.enabled is not true then
    raise exception '默认注册角色必须处于启用状态';
  end if;
  if v_role.builtin_type = 'platform_super'
    or upper(v_role.role_code) ~ '(SUPER|ADMIN)'
  then
    raise exception '管理员或超级管理员角色不能作为默认注册角色';
  end if;

  return new;
end;
$function$;

--
-- Name: validate_scm_purchase_extensions; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_scm_purchase_extensions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_line jsonb; v_sales public.scm_sales_document%rowtype;
begin
  if new.kind='purchase_contract' then
    new.details:=jsonb_set(coalesce(new.details,'{}'::jsonb),'{contract_status}',
      to_jsonb(case new.status when 'draft' then 'DRFT' when 'submitted' then 'SUBM'
        when 'approved' then 'APRV' when 'effective' then 'APRV'
        when 'expired' then 'CNCL' when 'cancelled' then 'CNCL' else 'DRFT' end),true);
    new.details:=jsonb_set(new.details,'{effectiveness}',
      to_jsonb(case new.status when 'effective' then 'active'
        when 'expired' then 'expired' else 'inactive' end),true);
  end if;
  if new.kind not in ('purchase_contract','purchase_request') then return new; end if;
  if exists (select 1 from jsonb_array_elements(new.lines) x
    where x->>'line_no' is not null
      and (x->>'line_no' !~ '^[1-9][0-9]*$' or length(x->>'line_no')>9)) then
    raise exception '采购明细行号须为正整数' using errcode='23514';
  end if;
  if exists (select 1 from jsonb_array_elements(new.lines) x
    where x->>'line_no' is not null group by x->>'line_no' having count(*)>1) then
    raise exception '采购明细行号不可重复' using errcode='23514';
  end if;
  for v_line in select value from jsonb_array_elements(new.lines) loop
    if new.kind='purchase_contract'
      and coalesce(nullif(btrim(v_line->>'base_unit'),''),
        nullif(btrim(v_line->>'unit'),'')) is null then
      raise exception '合同明细基本单位不能为空' using errcode='23514';
    end if;
    if new.kind='purchase_request' and nullif(v_line->>'suggested_supplier_id','') is not null
      and not exists (select 1 from public.mdm_supplier s
        where s.id=(v_line->>'suggested_supplier_id')::uuid ) then
      raise exception '建议供应商与采购申请不一致' using errcode='23514';
    end if;
    if nullif(v_line->>'source_sales_document_id','') is not null then
      select * into v_sales from public.scm_sales_document s
      where s.id=(v_line->>'source_sales_document_id')::uuid
         and s.project_id=new.project_id
        and s.kind in ('sales_quotation','sales_contract') and s.status='effective';
      if v_sales.id is null or v_sales.document_no<>v_line->>'source_document_no'
        or not exists (select 1 from jsonb_array_elements(v_sales.lines) x
          where x->>'line_id'=v_line->>'quotation_line_id'
            and x->>'material_id'=v_line->>'material_id') then
        raise exception '销售来源明细与当前项目或物料不匹配' using errcode='23514';
      end if;
    end if;
    if nullif(v_line->>'source_purchase_document_id','') is not null
      and not exists (select 1 from public.scm_purchase_document p
        cross join lateral jsonb_array_elements(p.lines) source_line
        where p.id=(v_line->>'source_purchase_document_id')::uuid
           and p.project_id=new.project_id
          and p.kind='purchase_contract' and p.status='effective'
          and p.document_no=v_line->>'source_document_no'
          and source_line->>'line_id'=v_line->>'purchase_contract_line_id'
          and source_line->>'material_id'=v_line->>'material_id') then
      raise exception '采购合同来源明细与当前项目或物料不匹配' using errcode='23514';
    end if;
  end loop;
  return new;
end $function$;

--
-- Name: validate_scm_sales_document_relationships; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_scm_sales_document_relationships()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_customer uuid; v_line jsonb; v_fee jsonb; v_plan jsonb; v_seen text[]:=ARRAY[]::text[];
BEGIN
 SELECT customer_id INTO v_customer FROM public.mdm_project WHERE id=NEW.project_id;
 IF v_customer IS NOT NULL AND v_customer<>NEW.customer_id THEN
   RAISE EXCEPTION '客户与项目归属不一致' USING ERRCODE='23514';
 END IF;
 FOR v_line IN SELECT value FROM jsonb_array_elements(NEW.lines) LOOP
   IF nullif(v_line->>'line_id','') IS NULL OR v_line->>'line_id'=ANY(v_seen) THEN
     RAISE EXCEPTION '物料明细行号缺失或重复' USING ERRCODE='23514';
   END IF;
   v_seen:=array_append(v_seen,v_line->>'line_id');
   IF coalesce(v_line->>'material_description','')='' THEN
     RAISE EXCEPTION '请填写物料描述' USING ERRCODE='23514';
   END IF;
 END LOOP;
 v_seen:=ARRAY[]::text[];
 FOR v_fee IN SELECT value FROM jsonb_array_elements(NEW.fees) LOOP
   IF v_fee->>'expense_id'=ANY(v_seen) OR coalesce((v_fee->>'cost')::numeric,0)<0 THEN
     RAISE EXCEPTION '报价费用不能重复且成本须为非负数' USING ERRCODE='23514';
   END IF;
   v_seen:=array_append(v_seen,v_fee->>'expense_id');
 END LOOP;
 FOR v_plan IN SELECT value FROM jsonb_array_elements(NEW.payment_plans) LOOP
   IF coalesce((v_plan->>'amount')::numeric,0)<0 OR coalesce((v_plan->>'ratio')::numeric,0) NOT BETWEEN 0 AND 100 THEN
     RAISE EXCEPTION '收款计划金额或比例超出范围' USING ERRCODE='23514';
   END IF;
 END LOOP;
 IF NEW.kind='project_quotation' AND
 (coalesce((NEW.details->>'package_fee')::numeric,0)<0 OR coalesce((NEW.details->>'transport_fee')::numeric,0)<0) THEN
   RAISE EXCEPTION '附加费用不可为负数' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$;

--
-- Name: validate_supplier_group; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_supplier_group()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.group_id is not null and not exists (
    select 1 from public.mdm_master_group g
    where g.id=new.group_id  and g.domain='supplier'
  ) then
    raise exception '请选择有效的供应商分组' using errcode='23514';
  end if;
  return new;
end $function$;

--
-- Name: validate_tms_parent_unit; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_tms_parent_unit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_entity_label text := tg_argv[0];
  v_parent_exists integer;
  v_has_cycle boolean;
begin
  if new.parent_unit_id is null then
    return new;
  end if;

  if new.parent_unit_id = new.id then
    raise exception using
      errcode = '23514',
      message = format('%s不能选择自身作为上级单位', v_entity_label);
  end if;

  execute format(
    'select 1 from %I.%I where id = $1',
    tg_table_schema,
    tg_table_name
  )
  into v_parent_exists
  using new.parent_unit_id;

  if v_parent_exists is null then
    raise exception using
      errcode = '23503',
      message = format('所选上级%s不存在或无权访问', v_entity_label);
  end if;



  execute format(
    $query$
      with recursive ancestors as (
        select id, parent_unit_id
        from %I.%I
        where id = $1

        union

        select parent.id, parent.parent_unit_id
        from %I.%I as parent
        join ancestors on parent.id = ancestors.parent_unit_id
      )
      select exists(select 1 from ancestors where id = $2)
    $query$,
    tg_table_schema,
    tg_table_name,
    tg_table_schema,
    tg_table_name
  )
  into v_has_cycle
  using new.parent_unit_id, new.id;

  if v_has_cycle then
    raise exception using
      errcode = '23514',
      message = format('所选上级%s会形成循环层级', v_entity_label);
  end if;

  return new;
end;
$function$;

--
-- Name: validate_workflow_business_config; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_workflow_business_config(p_business_type text, p_config jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_node jsonb;
  v_operator text;
  v_field text;
  v_allowed_fields text[];
begin
  perform app_private.validate_workflow_config(p_config);
  if p_config ? 'allowAutoApprove' and jsonb_typeof(p_config -> 'allowAutoApprove') <> 'boolean' then
    raise exception '全条件未命中策略必须是布尔值';
  end if;
  v_allowed_fields := case p_business_type
    when 'tms_waybill_cost' then array['amount','costType','expenseItemName','payeeName','waybillNo','plateNo','driverName','occurredOn','ocrStatus']
    when 'tms_in_transit_expense' then array['amount','expenseType','waybillNo','plateNo','driverName','occurredOn']
    when 'tms_expense_reimbursement' then array['amount','reimbursementNo','paymentMethod','itemCount','waybillCount','plannedPaymentDate']
    when 'tms_invoice' then array['direction','invoiceType','invoiceNo','totalAmount','taxRate','counterpartyName']
    when 'tms_carrier_payment_application' then array['amount','applicationNo','carrierId','carrierName','plannedPaymentDate','statementCount']
    when 'tms_carrier_statement' then array['statementNo','statementAmount','carrierId','carrierName','costCount','settledAmount']
    when 'tms_customer_statement' then array['statementNo','statementAmount','customerId','customerName','waybillCount','settledAmount']
    when 'tms_contract' then array[
      'contractNo','contractAmount','businessContractType','contractCategory','transportMode',
      'customerId','carrierId','partyName','billingMethod','signTime','effectiveDate','expiryDate',
      'isCompleted','handler'
    ]
    when 'vehicle_archive' then array['plateNo','companyName','vehicleType','approvedLoadMass','operationType','isNewEnergy']
    else null end;
  for v_node in select value from jsonb_array_elements(p_config -> 'nodes') loop
    v_operator := coalesce(v_node #>> '{condition,operator}', 'always');
    if v_operator <> 'always' then
      v_field := btrim(coalesce(v_node #>> '{condition,field}', ''));
      if v_field = '' then raise exception '节点“%”必须选择条件字段', v_node ->> 'name'; end if;
      if v_allowed_fields is not null and not (v_field = any(v_allowed_fields)) then
        raise exception '节点“%”使用了业务类型 % 不支持的条件字段 %',
          v_node ->> 'name', p_business_type, v_field;
      end if;
      if v_operator = 'in' and (
        jsonb_typeof(v_node #> '{condition,value}') <> 'array'
        or jsonb_array_length(v_node #> '{condition,value}') = 0
      ) then
        raise exception '节点“%”的“属于”比较值必须是非空数组', v_node ->> 'name';
      end if;
    end if;
  end loop;
end;
$function$;

--
-- Name: validate_workflow_config; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.validate_workflow_config(p_config jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_node jsonb;
  v_count integer;
  v_mode text;
  v_threshold integer;
  v_due_hours integer;
  v_reminder_minutes integer;
  v_escalate_hours integer;
begin
  if p_config is null or jsonb_typeof(p_config) <> 'object'
     or jsonb_typeof(p_config -> 'nodes') <> 'array' then
    raise exception '流程配置必须包含 nodes 数组';
  end if;

  v_count := jsonb_array_length(p_config -> 'nodes');
  if v_count < 1 or v_count > 30 then
    raise exception '审批节点数量必须在 1 到 30 之间';
  end if;

  if (select count(distinct node ->> 'key') from jsonb_array_elements(p_config -> 'nodes') node) <> v_count then
    raise exception '审批节点标识不能重复';
  end if;

  if (select count(distinct (node ->> 'order')::integer) from jsonb_array_elements(p_config -> 'nodes') node) <> v_count then
    raise exception '审批节点顺序不能重复';
  end if;

  for v_node in select value from jsonb_array_elements(p_config -> 'nodes') loop
    if btrim(coalesce(v_node ->> 'key', '')) = ''
       or (v_node ->> 'key') !~ '^[A-Za-z][A-Za-z0-9_-]{1,39}$'
       or btrim(coalesce(v_node ->> 'name', '')) = '' then
      raise exception '节点标识或名称不正确';
    end if;

    v_mode := coalesce(v_node ->> 'approvalMode', '');
    if v_mode not in ('any', 'all', 'percentage') then
      raise exception '节点 % 的审批方式不正确', v_node ->> 'name';
    end if;

    if v_mode = 'percentage' then
      if coalesce(v_node ->> 'approvalThresholdPercent', '') !~ '^[0-9]+$' then
        raise exception '节点 % 的通过比例必须是 1 到 100 的整数', v_node ->> 'name';
      end if;
      v_threshold := (v_node ->> 'approvalThresholdPercent')::integer;
      if v_threshold < 1 or v_threshold > 100 then
        raise exception '节点 % 的通过比例必须是 1 到 100 的整数', v_node ->> 'name';
      end if;
    end if;

    if v_node ? 'rejectVetoEnabled'
       and jsonb_typeof(v_node -> 'rejectVetoEnabled') <> 'boolean' then
      raise exception '节点 % 的一票否决配置必须是布尔值', v_node ->> 'name';
    end if;

    if coalesce(v_node #>> '{assignee,type}', '') not in ('users', 'roles', 'initiator') then
      raise exception '节点 % 的审批人类型不正确', v_node ->> 'name';
    end if;
    if (v_node #>> '{assignee,type}') = 'users'
       and coalesce(jsonb_array_length(v_node #> '{assignee,userIds}'), 0) = 0 then
      raise exception '节点 % 必须选择审批人', v_node ->> 'name';
    end if;
    if (v_node #>> '{assignee,type}') = 'roles'
       and coalesce(jsonb_array_length(v_node #> '{assignee,roleCodes}'), 0) = 0 then
      raise exception '节点 % 必须选择审批角色', v_node ->> 'name';
    end if;

    if coalesce(v_node #>> '{condition,operator}', 'always') not in
       ('always', 'eq', 'ne', 'gt', 'gte', 'lt', 'lte', 'in', 'contains', 'not_empty') then
      raise exception '节点 % 的条件运算符不受支持', v_node ->> 'name';
    end if;

    if coalesce(v_node ->> 'dueHours', '') !~ '^[0-9]+$' then
      raise exception '节点 % 的审批时限必须是整数小时', v_node ->> 'name';
    end if;
    v_due_hours := (v_node ->> 'dueHours')::integer;
    if v_due_hours < 1 or v_due_hours > 720 then
      raise exception '节点 % 的审批时限必须在 1 到 720 小时之间', v_node ->> 'name';
    end if;

    if coalesce(v_node ->> 'reminderBeforeMinutes', '60') !~ '^[0-9]+$' then
      raise exception '节点 % 的到期前提醒必须是整数分钟', v_node ->> 'name';
    end if;
    v_reminder_minutes := coalesce((v_node ->> 'reminderBeforeMinutes')::integer, 60);
    if v_reminder_minutes < 0 or v_reminder_minutes > v_due_hours * 60 then
      raise exception '节点 % 的到期前提醒不能超过审批时限', v_node ->> 'name';
    end if;

    if coalesce(v_node ->> 'escalationEnabled', 'true') not in ('true', 'false') then
      raise exception '节点 % 的超时升级开关不正确', v_node ->> 'name';
    end if;
    if coalesce(v_node ->> 'escalateAfterHours', '4') !~ '^[0-9]+$' then
      raise exception '节点 % 的升级时间必须是整数小时', v_node ->> 'name';
    end if;
    v_escalate_hours := coalesce((v_node ->> 'escalateAfterHours')::integer, 4);
    if v_escalate_hours < 1 or v_escalate_hours > 720 then
      raise exception '节点 % 的升级时间必须在 1 到 720 小时之间', v_node ->> 'name';
    end if;
  end loop;
end;
$function$;

--
-- Name: withdraw_workflow; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.withdraw_workflow(p_instance_id uuid, p_comment text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := (select app_private.current_app_user_id());
  v_instance public.wf_instance;
  v_actor_name text;
begin
  select * into v_instance from public.wf_instance where id=p_instance_id for update;
  if not found or v_instance.initiator_user_id<>v_user_id then raise exception '流程不存在或仅发起人可以撤回'; end if;
  if v_instance.status<>'running' then raise exception '流程已结束，不能撤回'; end if;
  if exists (select 1 from public.wf_task where instance_id=p_instance_id and status in ('approved','rejected')) then
    raise exception '已有审批人处理，不能直接撤回';
  end if;
  select coalesce(nullif(nick_name,''),nullif(user_name,''),user_email,id::text)
  into v_actor_name from public.sys_user where id=v_user_id;
  update public.wf_task set status='cancelled',handled_at=now(),comment='发起人撤回'
  where instance_id=p_instance_id and status='pending';
  update public.wf_instance set status='withdrawn',finished_at=now(),finish_comment=p_comment,
    current_node_key=null,current_node_name=null,row_version=row_version+1 where id=p_instance_id;
  insert into public.wf_action(instance_id,action,actor_user_id,actor_name_snapshot,comment)
  values (p_instance_id,'withdraw',v_user_id,v_actor_name,nullif(btrim(coalesce(p_comment,'')),''));
  perform app_private.apply_workflow_business_status(
    v_instance.business_type,v_instance.business_id,'withdrawn',v_actor_name,p_comment
  );
end;
$function$;

--
-- Name: wms_assert_project_section; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.wms_assert_project_section(p_project_id uuid, p_construction_no text, p_allow_closed boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_project public.mdm_project%rowtype; v_section public.mdm_project_construction%rowtype;
begin
 if p_project_id is null and p_construction_no is null then return; end if;
 if p_project_id is null or nullif(btrim(p_construction_no),'') is null then raise exception '项目库存必须同时指定项目和施工号' using errcode='23514'; end if;
 select * into v_project from public.mdm_project where id=p_project_id ;
 if not found then raise exception '项目不存在或不可用' using errcode='23514'; end if;
 select * into v_section from public.mdm_project_construction where project_id=p_project_id and construction_no=p_construction_no;
 if not found then raise exception '施工号未在该项目登记' using errcode='23514'; end if;
 if not p_allow_closed and (not v_project.enabled or v_project.project_status in ('closed','cancelled') or v_section.status<>'active') then
   raise exception '项目或施工号已关闭，不能新增业务' using errcode='23514'; end if;
end $function$;

--
-- Name: wms_warehouse_organization_guard; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.wms_warehouse_organization_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_org public.mdm_organization%rowtype;
begin
 if new.organization_id is null then
  select id into new.organization_id from public.mdm_organization
  where is_system=true;
 end if;
 select * into v_org from public.mdm_organization
 where id=new.organization_id ;
 if not found or v_org.status<>'1' then
  raise exception '仓库库存组织不存在或已停用' using errcode='23514';end if;
 return new;
end $function$;

--
-- Name: workflow_attachment_list; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.workflow_attachment_list(p_value jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'name',coalesce(nullif(x->>'name',''),nullif(x->>'fileName',''),nullif(x->>'originalName',''),'附件'),
    'url',coalesce(nullif(x->>'url',''),nullif(x->>'fileUrl',''),nullif(x->>'downloadUrl','')),
    'fileType',coalesce(x->>'fileType',x->>'type'),
    'fileSize',coalesce(x->>'fileSize',x->>'size')
  )), '[]'::jsonb)
  from jsonb_array_elements(case when jsonb_typeof(p_value)='array' then p_value else '[]'::jsonb end) x
  where coalesce(nullif(x->>'url',''),nullif(x->>'fileUrl',''),nullif(x->>'downloadUrl','')) is not null
$function$;

--
-- Name: workflow_condition_matches; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.workflow_condition_matches(p_context jsonb, p_node jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_operator text := coalesce(p_node #>> '{condition,operator}', 'always');
  v_field text := p_node #>> '{condition,field}';
  v_expected jsonb := p_node #> '{condition,value}';
  v_actual jsonb;
begin
  if v_operator = 'always' then return true; end if;
  if v_field is null or v_field !~ '^[A-Za-z][A-Za-z0-9_.-]{0,79}$' then return false; end if;
  v_actual := p_context #> string_to_array(v_field, '.');
  if v_operator = 'not_empty' then return v_actual is not null and v_actual <> 'null'::jsonb and v_actual <> '""'::jsonb; end if;
  if v_operator = 'eq' then return v_actual = v_expected; end if;
  if v_operator = 'ne' then return v_actual is distinct from v_expected; end if;
  if v_operator in ('gt', 'gte', 'lt', 'lte') then
    begin
      return case v_operator
        when 'gt' then (v_actual #>> '{}')::numeric > (v_expected #>> '{}')::numeric
        when 'gte' then (v_actual #>> '{}')::numeric >= (v_expected #>> '{}')::numeric
        when 'lt' then (v_actual #>> '{}')::numeric < (v_expected #>> '{}')::numeric
        else (v_actual #>> '{}')::numeric <= (v_expected #>> '{}')::numeric end;
    exception when invalid_text_representation then return false; end;
  end if;
  if v_operator = 'in' then return jsonb_typeof(v_expected) = 'array' and v_expected @> jsonb_build_array(v_actual); end if;
  if v_operator = 'contains' then
    return case jsonb_typeof(v_actual)
      when 'array' then v_actual @> jsonb_build_array(v_expected)
      when 'string' then position(lower(v_expected #>> '{}') in lower(v_actual #>> '{}')) > 0
      else false end;
  end if;
  return false;
end;
$function$;

--
-- Name: workflow_dictionary_label; Type: FUNCTION; Schema: app_private
--

CREATE OR REPLACE FUNCTION app_private.workflow_dictionary_label(p_dict_code text, p_value text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select dictionary_item.label
  from public.sys_dictionary dictionary_item
  join public.sys_dict_type dictionary_type
    on dictionary_type.id = dictionary_item.type_id
  where dictionary_type.code = p_dict_code
    and dictionary_type.status = '1'
    and dictionary_item.status = '1'
    and dictionary_item.value = p_value
  order by dictionary_item.sort, dictionary_item.label
  limit 1
$function$;

