--
-- Name: cleanup_governed_delete_dependencies; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.cleanup_governed_delete_dependencies(p_resource_type text, p_resource_ids uuid[], p_dependency_code text, p_record_ids uuid[])
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  affected_count bigint := 0;
begin
  if coalesce(array_length(p_resource_ids, 1), 0) = 0
    or coalesce(array_length(p_record_ids, 1), 0) = 0 then
    return 0;
  end if;

  if p_resource_type = any(array['carrier', 'driver', 'cargo', 'customer_address', 'vehicle']) then
    return public.cleanup_master_data_delete_dependencies(
      p_resource_type,
      p_resource_ids,
      p_dependency_code,
      p_record_ids
    );
  end if;

  if p_resource_type = 'role' and p_dependency_code = 'role_menu_grant' then
    delete from public.sys_role_menu role_menu
    where role_menu.role_id = any(p_resource_ids)
      and role_menu.id = any(p_record_ids);
    get diagnostics affected_count = row_count;
    return affected_count;
  end if;

  if p_resource_type = 'role' and p_dependency_code = 'role_user_assignment' then
    update public.sys_user app_user
    set user_roles = array_remove(app_user.user_roles, role.role_code)
    from public.sys_role role
    where role.id = any(p_resource_ids)
      and app_user.id = any(p_record_ids)
      and role.role_code = any(coalesce(app_user.user_roles, '{}'::text[]));
    get diagnostics affected_count = row_count;
    return affected_count;
  end if;

  if p_resource_type = 'menu' and p_dependency_code = 'menu_role_grant' then
    delete from public.sys_role_menu role_menu
    where role_menu.menu_id = any(p_resource_ids)
      and role_menu.id = any(p_record_ids);
    get diagnostics affected_count = row_count;
    return affected_count;
  end if;

  if p_resource_type = 'dict_type' and p_dependency_code = 'dict_type_item' then
    delete from public.sys_dictionary dictionary
    where dictionary.type_id = any(p_resource_ids)
      and dictionary.id = any(p_record_ids);
    get diagnostics affected_count = row_count;
    return affected_count;
  end if;

  if p_resource_type = 'dictionary' and p_dependency_code = 'dictionary_child' then
    delete from public.sys_dictionary dictionary
    where dictionary.parent_id = any(p_resource_ids)
      and dictionary.id = any(p_record_ids);
    get diagnostics affected_count = row_count;
    return affected_count;
  end if;

  raise exception 'unsupported safe cleanup: % / %', p_resource_type, p_dependency_code
    using errcode = '22023';
end;
$function$;

--
-- Name: cleanup_master_data_delete_dependencies; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.cleanup_master_data_delete_dependencies(p_resource_type text, p_resource_ids uuid[], p_dependency_code text, p_record_ids uuid[])
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  deleted_count bigint := 0;
begin
  if coalesce(array_length(p_resource_ids, 1), 0) = 0
    or coalesce(array_length(p_record_ids, 1), 0) = 0 then
    return 0;
  end if;

  if p_resource_type = 'carrier' and p_dependency_code = 'carrier_price' then
    delete from public.tms_carrier_price price
    where price.carrier_id = any(p_resource_ids)
      and price.id = any(p_record_ids);
    get diagnostics deleted_count = row_count;
    return deleted_count;
  end if;

  if p_resource_type = 'vehicle' and p_dependency_code = 'vehicle_reminder_work_order' then
    delete from public.vehicle_reminder_work_order work_order
    where work_order.vehicle_id = any(p_resource_ids)
      and work_order.id = any(p_record_ids)
      and work_order.status in ('cancelled', 'resolved', 'closed');
    get diagnostics deleted_count = row_count;
    return deleted_count;
  end if;

  raise exception 'unsupported safe cleanup: % / %', p_resource_type, p_dependency_code
    using errcode = '22023';
end;
$function$;

--
-- Name: commit_ai_bank_statement_batch; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.commit_ai_bank_statement_batch(p_artifact_id uuid, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_artifact public.ai_artifact_review%rowtype;
  v_row jsonb;
  v_transaction_id uuid;
  v_ids uuid[] := '{}';
  v_count integer := 0;
  v_direction text;
  v_reference text;
begin
  if not app_private.is_platform_super() then raise exception '仅平台超级管理员可执行批量入账'; end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) < 1 or jsonb_array_length(p_rows) > 300 then
    raise exception '请选择 1 至 300 条可入账流水';
  end if;
  select * into v_artifact from public.ai_artifact_review
  where id = p_artifact_id and feature = 'bank_statement_batch_match' and status = 'pending'
    and auth_user_id = auth.uid();
  if not found then raise exception '批量匹配记录不存在、已处理或不属于当前用户'; end if;

  for v_row in select value from jsonb_array_elements(p_rows)
  loop
    v_direction := v_row->>'direction';
    v_reference := nullif(trim(v_row->>'bankReference'), '');
    if v_direction not in ('receipt','payment') or coalesce((v_row->>'amount')::numeric,0) <= 0
      or nullif(v_row->>'counterpartyId','') is null or nullif(v_row->>'transactionDate','') is null then
      raise exception '批次中存在缺少方向、往来单位、日期或金额的流水';
    end if;
    if v_reference is not null and exists (
      select 1 from public.tms_cash_transaction t
      where t.direction = v_direction and t.bank_reference = v_reference
    ) then raise exception '银行流水号已入账：%', v_reference; end if;

    if v_direction = 'receipt' then
      v_transaction_id := public.create_tms_customer_receipt(
        (v_row->>'counterpartyId')::uuid, (v_row->>'transactionDate')::date, (v_row->>'amount')::numeric,
        coalesce(nullif(v_row->>'paymentMethod',''),'bank_transfer'), v_reference,
        coalesce(v_row->'voucherUrls','[]'::jsonb), nullif(v_row->>'remark',''), coalesce(v_row->'allocations','[]'::jsonb)
      );
    else
      v_transaction_id := public.create_tms_carrier_payment(
        (v_row->>'counterpartyId')::uuid, (v_row->>'transactionDate')::date, (v_row->>'amount')::numeric,
        coalesce(nullif(v_row->>'paymentMethod',''),'bank_transfer'), v_reference,
        coalesce(v_row->'voucherUrls','[]'::jsonb), nullif(v_row->>'remark',''), coalesce(v_row->'allocations','[]'::jsonb)
      );
    end if;
    v_ids := array_append(v_ids, v_transaction_id);
    v_count := v_count + 1;
  end loop;

  update public.ai_artifact_review set
    status = 'applied', final_payload = jsonb_build_object('transactionIds', to_jsonb(v_ids), 'committedRows', p_rows),
    accepted_fields = array['rows'], corrected_fields = '{}', entity_type = 'tms_cash_transaction_batch',
    review_note = format('批量入账 %s 条银行流水', v_count), reviewed_at = now()
  where id = v_artifact.id;
  return jsonb_build_object('artifactId', v_artifact.id, 'committedCount', v_count, 'transactionIds', to_jsonb(v_ids));
end;
$function$;

--
-- Name: configure_document_number_rule; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.configure_document_number_rule(p_rule_key text, p_auto_enabled boolean, p_template text, p_reset_cycle text, p_sequence_start bigint DEFAULT 1, p_timezone text DEFAULT 'Asia/Shanghai'::text, p_remark text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_scene public.sys_document_number_scene%rowtype;
  v_is_platform_super boolean := app_private.is_platform_super();
  v_updated integer := 0;
  v_created integer := 0;
begin
  if not v_is_platform_super
    and not app_private.has_permission('System:DocumentNumberRule:Add') then
    raise exception '缺少新增编号规则权限' using errcode = '42501';
  end if;




  select *
    into v_scene
  from public.sys_document_number_scene
  where rule_key = lower(btrim(p_rule_key))
    and enabled
  limit 1;

  if not found then
    raise exception '编号功能未注册或已停用：%', p_rule_key;
  end if;


  update public.sys_document_number_rule rule
  set auto_enabled = p_auto_enabled,
      template = p_template,
      reset_cycle = p_reset_cycle,
      sequence_start = p_sequence_start,
      timezone = p_timezone,
      remark = p_remark
  where rule.rule_key = v_scene.rule_key;
  get diagnostics v_updated = row_count;

  insert into public.sys_document_number_rule (
    rule_key,
    rule_name,
    category,
    target_table,
    target_column,
    auto_enabled,
    template,
    reset_cycle,
    sequence_start,
    timezone,
    manual_required,
    builtin,
    enabled,
    remark
  )
  select v_scene.rule_key,
         v_scene.rule_name,
         v_scene.category,
         v_scene.target_table,
         v_scene.target_column,
         p_auto_enabled,
         p_template,
         p_reset_cycle,
         p_sequence_start,
         p_timezone,
         v_scene.manual_required,
         false,
         true,
         p_remark
  where not exists (
    select 1
    from public.sys_document_number_rule existing
    where true
      and existing.rule_key = v_scene.rule_key
  );
  get diagnostics v_created = row_count;

  return jsonb_build_object(
    'created', v_created,
    'updated', v_updated,
    'assigned', v_created + v_updated
  );
end;
$function$;

--
-- Name: copy_mdm_business_type; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.copy_mdm_business_type(p_source_id uuid, p_document_type_id uuid, p_business_type_code text, p_business_type_name text, p_is_default boolean, p_source_business_type_id uuid, p_inventory_direction text, p_owner_type text, p_inventory_accounting boolean, p_remark text, p_sort_order integer, p_text_color text, p_tag_style text, p_enabled boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_source public.mdm_business_type%rowtype;
  v_id uuid;
begin
  if auth.uid() is null then
    raise exception '请先登录后再复制业务类型' using errcode='42501';
  end if;
  if not app_private.is_platform_super()
     and not (
       app_private.has_permission('MdmBusinessType:View')
       and app_private.has_permission('MdmBusinessType:Copy')
     ) then
    raise exception '无权复制业务类型' using errcode='42501';
  end if;

  select source.* into v_source
  from public.mdm_business_type source
  where source.id=p_source_id
;

  if not found then
    raise exception '源业务类型不存在或不可用' using errcode='P0002';
  end if;

  insert into public.mdm_business_type (document_type_id,business_type_code,business_type_name,is_default,
    source_business_type_id,inventory_direction,owner_type,inventory_accounting,
    remark,sort_order,text_color,tag_style,enabled
  ) values (p_document_type_id,p_business_type_code,p_business_type_name,p_is_default,
    p_source_business_type_id,p_inventory_direction,p_owner_type,p_inventory_accounting,
    p_remark,p_sort_order,p_text_color,p_tag_style,p_enabled
  ) returning id into v_id;
  return v_id;
end
$function$;

