--
-- Name: create_tms_carrier_payment; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.create_tms_carrier_payment(p_carrier_id uuid, p_transaction_date date, p_amount numeric, p_payment_method text, p_bank_reference text, p_voucher_urls jsonb, p_remark text, p_allocations jsonb, p_transaction_no text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  perform set_config('app.document_number.tms_cash_transaction', coalesce(p_transaction_no, ''), true);
  return public.create_tms_carrier_payment(
    p_carrier_id, p_transaction_date, p_amount, p_payment_method,
    p_bank_reference, p_voucher_urls, p_remark, p_allocations
  );
end;
$function$;

--
-- Name: create_tms_carrier_payment; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.create_tms_carrier_payment(p_carrier_id uuid, p_transaction_date date, p_amount numeric, p_payment_method text, p_bank_reference text DEFAULT NULL::text, p_voucher_urls jsonb DEFAULT '[]'::jsonb, p_remark text DEFAULT NULL::text, p_allocations jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_transaction_id uuid;
  v_allocation_total numeric(14, 2);
  v_statement_id uuid;
begin
  if p_transaction_date is null then raise exception '请选择付款日期'; end if;
  if coalesce(p_amount, 0) <= 0 then raise exception '付款金额必须大于 0'; end if;
  if p_payment_method not in ('bank_transfer', 'cash', 'wechat', 'alipay', 'other') then
    raise exception '请选择正确的付款方式';
  end if;
  if jsonb_typeof(coalesce(p_voucher_urls, '[]'::jsonb)) <> 'array' then raise exception '付款凭证格式不正确'; end if;
  if jsonb_typeof(coalesce(p_allocations, '[]'::jsonb)) <> 'array' then raise exception '核销明细格式不正确'; end if;

  perform 1
  from public.mdm_carrier c where c.id = p_carrier_id and c.enabled;
  if not found then raise exception '付款承运商不存在或已停用'; end if;

  select coalesce(sum(item.amount), 0)::numeric(14, 2)
    into v_allocation_total
  from jsonb_to_recordset(coalesce(p_allocations, '[]'::jsonb)) as item(statement_id uuid, amount numeric);
  if v_allocation_total > p_amount then raise exception '核销合计不能超过付款金额'; end if;

  for v_statement_id in
    select distinct item.statement_id
    from jsonb_to_recordset(coalesce(p_allocations, '[]'::jsonb)) as item(statement_id uuid, amount numeric)
    where item.statement_id is not null order by item.statement_id
  loop
    perform pg_advisory_xact_lock(hashtextextended(v_statement_id::text, 841329));
  end loop;

  insert into public.tms_cash_transaction (
    transaction_no, direction, carrier_id, counterparty_name_snapshot,
    transaction_date, amount, payment_method, bank_reference, voucher_urls, remark
  )
  select    'CP' || to_char(clock_timestamp(), 'YYYYMMDD') || '-' ||
      lpad(nextval('public.tms_cash_transaction_no_seq'::regclass)::text, 6, '0'),
    'payment', c.id, c.company_name, p_transaction_date, round(p_amount, 2),
    p_payment_method, nullif(btrim(p_bank_reference), ''),
    coalesce(p_voucher_urls, '[]'::jsonb), nullif(btrim(p_remark), '')
  from public.mdm_carrier c where c.id = p_carrier_id
  returning id into v_transaction_id;

  insert into public.tms_carrier_cash_allocation (
    transaction_id, statement_id, carrier_id, allocated_amount, remark
  )
  select v_transaction_id, item.statement_id, p_carrier_id,
         round(sum(item.amount), 2), '登记付款时核销'
  from jsonb_to_recordset(coalesce(p_allocations, '[]'::jsonb)) as item(statement_id uuid, amount numeric)
  where item.statement_id is not null
  group by item.statement_id;
  return v_transaction_id;
end;
$function$;

--
-- Name: create_tms_customer_receipt; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.create_tms_customer_receipt(p_customer_id uuid, p_transaction_date date, p_amount numeric, p_payment_method text, p_bank_reference text DEFAULT NULL::text, p_voucher_urls jsonb DEFAULT '[]'::jsonb, p_remark text DEFAULT NULL::text, p_allocations jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_transaction_id uuid;
  v_allocation_total numeric(14, 2);
  v_statement_id uuid;
begin
  if p_transaction_date is null then
    raise exception '请选择收款日期';
  end if;
  if coalesce(p_amount, 0) <= 0 then
    raise exception '收款金额必须大于 0';
  end if;
  if p_payment_method not in ('bank_transfer', 'cash', 'wechat', 'alipay', 'other') then
    raise exception '请选择正确的收款方式';
  end if;
  if jsonb_typeof(coalesce(p_voucher_urls, '[]'::jsonb)) <> 'array' then
    raise exception '收款凭证格式不正确';
  end if;
  if jsonb_typeof(coalesce(p_allocations, '[]'::jsonb)) <> 'array' then
    raise exception '核销明细格式不正确';
  end if;

  perform 1
  from public.mdm_customer c
  where c.id = p_customer_id and c.enabled;

  if not found then
    raise exception '收款客户不存在或已停用';
  end if;


  select coalesce(sum(item.amount), 0)::numeric(14, 2)
    into v_allocation_total
  from jsonb_to_recordset(coalesce(p_allocations, '[]'::jsonb))
    as item(statement_id uuid, amount numeric);

  if v_allocation_total > p_amount then
    raise exception '核销合计不能超过收款金额';
  end if;

  for v_statement_id in
    select distinct item.statement_id
    from jsonb_to_recordset(coalesce(p_allocations, '[]'::jsonb))
      as item(statement_id uuid, amount numeric)
    where item.statement_id is not null
    order by item.statement_id
  loop
    perform pg_advisory_xact_lock(hashtextextended(v_statement_id::text, 841327));
  end loop;

  insert into public.tms_cash_transaction (
    direction, customer_id, counterparty_name_snapshot,
    transaction_date, amount, payment_method, bank_reference, voucher_urls, remark
  )
  select
    'receipt', c.id, c.customer_name,
    p_transaction_date, round(p_amount, 2), p_payment_method,
    nullif(btrim(p_bank_reference), ''), coalesce(p_voucher_urls, '[]'::jsonb),
    nullif(btrim(p_remark), '')
  from public.mdm_customer c
  where c.id = p_customer_id
  returning id into v_transaction_id;

  insert into public.tms_cash_allocation (
    transaction_id, statement_id, customer_id, allocated_amount, remark
  )
  select
    v_transaction_id,
    item.statement_id,
    p_customer_id,
    round(sum(item.amount), 2),
    '登记收款时核销'
  from jsonb_to_recordset(coalesce(p_allocations, '[]'::jsonb))
    as item(statement_id uuid, amount numeric)
  where item.statement_id is not null
  group by item.statement_id;

  return v_transaction_id;
end;
$function$;

--
-- Name: create_tms_customer_receipt; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.create_tms_customer_receipt(p_customer_id uuid, p_transaction_date date, p_amount numeric, p_payment_method text, p_bank_reference text, p_voucher_urls jsonb, p_remark text, p_allocations jsonb, p_transaction_no text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  perform set_config('app.document_number.tms_cash_transaction', coalesce(p_transaction_no, ''), true);
  return public.create_tms_customer_receipt(
    p_customer_id, p_transaction_date, p_amount, p_payment_method,
    p_bank_reference, p_voucher_urls, p_remark, p_allocations
  );
end;
$function$;

