--
-- Name: hr_create_employee_with_driver_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.hr_create_employee_with_driver_secure(p_employee jsonb, p_driver jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_employee public.mdm_employee%rowtype;
  v_employee_id uuid;
begin
  if not app_private.can_execute_business_action(
    'HrEmployeeRoster', 'Hr:Employee:Add', null, false
  ) then
    raise exception 'Missing employee create permission' using errcode = '42501';
  end if;
  if p_employee is null or jsonb_typeof(p_employee) <> 'object' then
    raise exception '员工数据格式不正确';
  end if;
  if p_driver is not null and p_driver <> 'null'::jsonb then
    raise exception '员工档案不再创建司机档案，请前往司机管理从员工花名册选取';
  end if;
  if exists (
    select 1
    from jsonb_object_keys(p_employee) key
    where key <> all(array[
      'organization_id','employee_no','employee_name','avatar_url','position_id',
      'employment_status','employment_type','gender','birth_date','phone','email','id_card_no',
      'ethnicity','education_level','school_name','major_name','marital_status','political_status',
      'native_place','home_address','hire_date','probation_end_date','leave_date',
      'contract_start_date','contract_end_date','emergency_contact_name',
      'emergency_contact_relation','emergency_contact_phone','remark'
    ]::text[])
  ) then
    raise exception '员工数据包含不允许写入的字段';
  end if;

  select * into v_employee
  from jsonb_populate_record(null::public.mdm_employee, p_employee);

  if not exists (
    select 1
    from public.mdm_position position_row
    where position_row.id = v_employee.position_id
      
      and position_row.enabled
  ) then
    raise exception '所选岗位不存在或已停用';
  end if;
  if not exists (
    select 1
    from public.mdm_organization organization_row
    where organization_row.id = v_employee.organization_id
      
      and organization_row.status = '1'
  ) then
    raise exception '所选组织不存在或已停用';
  end if;

  insert into public.mdm_employee ( organization_id, employee_no, employee_name, avatar_url, position_id,
    employment_status, employment_type, gender, birth_date, phone, email, id_card_no,
    ethnicity, education_level, school_name, major_name, marital_status, political_status,
    native_place, home_address, hire_date, probation_end_date, leave_date,
    contract_start_date, contract_end_date, emergency_contact_name,
    emergency_contact_relation, emergency_contact_phone, remark, create_by
  ) values ( v_employee.organization_id, btrim(v_employee.employee_no),
    btrim(v_employee.employee_name), v_employee.avatar_url, v_employee.position_id,
    coalesce(v_employee.employment_status, 'active'),
    coalesce(v_employee.employment_type, 'full_time'), v_employee.gender,
    v_employee.birth_date, v_employee.phone, v_employee.email, v_employee.id_card_no,
    v_employee.ethnicity, v_employee.education_level, v_employee.school_name,
    v_employee.major_name, v_employee.marital_status, v_employee.political_status,
    v_employee.native_place, v_employee.home_address, v_employee.hire_date,
    v_employee.probation_end_date, v_employee.leave_date, v_employee.contract_start_date,
    v_employee.contract_end_date, v_employee.emergency_contact_name,
    v_employee.emergency_contact_relation, v_employee.emergency_contact_phone,
    v_employee.remark, coalesce(auth.uid()::text, 'system')
  ) returning id into v_employee_id;

  return jsonb_build_object('employee_id', v_employee_id, 'driver_id', null);
end;
$function$;

--
-- Name: hr_list_employee_selector_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.hr_list_employee_selector_secure(p_from integer DEFAULT 0, p_to integer DEFAULT 19, p_keyword text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_from integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(
    greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1),
    200
  );
  v_keyword text := nullif(btrim(p_keyword), '');
  v_has_hr_menu boolean := app_private.can_execute_business_action(
    'HrEmployeeRoster', null, null, false
  );
  v_contact_access text := case when v_has_hr_menu then app_private.resolve_field_access(
    'hr.employee', 'contactDetails', null
  ) else 'hidden' end;
  v_identity_access text := case when v_has_hr_menu then app_private.resolve_field_access(
    'hr.employee', 'identityDetails', null
  ) else 'hidden' end;
  v_total bigint;
  v_records jsonb;
begin
  if not (
    app_private.can_execute_business_action(
      'HrEmployeeRoster', 'Hr:Employee:View', null, false
    )
    or app_private.can_execute_business_action('User', 'System:User:Add', null, false)
    or app_private.can_execute_business_action('User', 'System:User:Edit', null, false)
  ) then
    raise exception 'Missing employee selector permission' using errcode = '42501';
  end if;


  with filtered as materialized (
    select
      employee_row.*,
      organization_row.organization_code,
      organization_row.organization_name
    from public.mdm_employee employee_row
    left join public.mdm_organization organization_row
      on organization_row.id = employee_row.organization_id
     
    where true
      and employee_row.employment_status in ('probation', 'active')
      and not exists (
        select 1
        from public.sys_user user_row
        where user_row.hr_employee_id = employee_row.id
          
          and user_row.deleted_at is null
      )
      and (
        v_keyword is null
        or employee_row.employee_no ilike '%' || v_keyword || '%'
        or employee_row.employee_name ilike '%' || v_keyword || '%'
        or employee_row.job_title ilike '%' || v_keyword || '%'
        or (
          v_contact_access in ('read', 'edit')
          and (
            employee_row.phone ilike '%' || v_keyword || '%'
            or employee_row.email ilike '%' || v_keyword || '%'
          )
        )
      )
  ), paged as (
    select *
    from filtered
    order by employee_name, employee_no, id
    offset v_from limit v_limit
  )
  select
    (select count(*) from filtered),
    coalesce((
      select jsonb_agg(
        jsonb_strip_nulls(jsonb_build_object(
          'id', paged.id,
          
          'organization_id', paged.organization_id,
          'employee_no', paged.employee_no,
          'employee_name', paged.employee_name,
          'avatar_url', paged.avatar_url,
          'job_title', paged.job_title,
          'employment_status', paged.employment_status,
          'organization', case when paged.organization_id is null then null else jsonb_build_object(
            'id', paged.organization_id,
            'organization_code', paged.organization_code,
            'organization_name', paged.organization_name
          ) end,
          'gender', case when v_identity_access in ('read', 'edit') then paged.gender else null end,
          'phone', case when v_contact_access in ('read', 'edit') then paged.phone else null end,
          'email', case when v_contact_access in ('read', 'edit') then paged.email else null end
        )) order by paged.employee_name, paged.employee_no, paged.id
      )
      from paged
    ), '[]'::jsonb)
  into v_total, v_records;

  return jsonb_build_object(
    'records', v_records,
    'total', v_total,
    'field_access', case when v_has_hr_menu
      then app_private.field_access_map('hr.employee', null)
      else '{}'::jsonb
    end
  );
end;
$function$;

--
-- Name: list_menu_management_nodes; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.list_menu_management_nodes(p_parent_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_path text DEFAULT NULL::text, p_record_id uuid DEFAULT NULL::uuid, p_root_only boolean DEFAULT false, p_include_child_state boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select coalesce(
    jsonb_agg(
      to_jsonb(menu_row)
      || case
        when p_include_child_state then jsonb_build_object(
          'has_children',
          exists (
            select 1
            from public.sys_menu child_row
            where child_row.parent_id = menu_row.id
          )
        )
        else '{}'::jsonb
      end
      order by menu_row.sort nulls last, menu_row.id
    ),
    '[]'::jsonb
  )
  from public.sys_menu menu_row
  where case
      when p_parent_id is not null then menu_row.parent_id = p_parent_id
      when p_root_only then menu_row.parent_id is null
      else true
    end
    and (
      nullif(btrim(p_name), '') is null
      or coalesce(menu_row.meta ->> 'title', '') ilike '%' || btrim(p_name) || '%'
    )
    and (
      nullif(btrim(p_path), '') is null
      or menu_row.path = btrim(p_path)
    )
    and (p_record_id is null or menu_row.id = p_record_id);
$function$;

