--
-- Name: mdm_delete_bom; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.mdm_delete_bom(p_bom_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_bom public.mdm_bom%rowtype;
begin
  if auth.uid() is null or not app_private.has_permission('MdmBomMaintenance:Delete') then
    raise exception '当前账号没有删除 BOM 的权限' using errcode='42501';
  end if;

  select * into v_bom
  from public.mdm_bom
  where id=p_bom_id
  for update;
  if not found then
    raise exception 'BOM 不存在或无权删除' using errcode='P0002';
  end if;
  if v_bom.status <> 'design' then
    raise exception '仅设计状态的 BOM 可以删除' using errcode='55000';
  end if;
  if exists (
    select 1 from public.mdm_accessory_processing_list
    where bom_id=v_bom.id 
  ) then
    raise exception '该 BOM 已被配件加工清单引用，请先解除关联' using errcode='23503';
  end if;

  -- The item guard reads its parent; remove items while the BOM still exists.
  delete from public.mdm_bom_item
  where bom_id=v_bom.id ;
  delete from public.mdm_bom
  where id=v_bom.id ;
end
$function$;

--
-- Name: mdm_delete_bom_group_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.mdm_delete_bom_group_secure(p_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_count integer;
begin
  if auth.uid() is null then raise exception '请先登录后删除 BOM 分组' using errcode='42501'; end if;
  if not (app_private.is_platform_super() or app_private.has_permission('MdmBomMaintenance:ManageGroup')) then
    raise exception '当前账号无权删除 BOM 分组' using errcode='42501';
  end if;
  perform 1
  from public.mdm_master_group
  where id=p_id and domain='bom'
  for update;
  if not found then raise exception 'BOM 分组不存在或无权访问' using errcode='P0002'; end if;
  if exists(select 1 from public.mdm_master_group where parent_id=p_id ) then
    raise exception '该分组仍有下级分组，请先调整层级' using errcode='23503';
  end if;
  if exists(select 1 from public.mdm_bom where group_id=p_id ) then
    raise exception '该分组仍有 BOM，请先调整 BOM 分组' using errcode='23503';
  end if;
  delete from public.mdm_master_group where id=p_id  and domain='bom';
  get diagnostics v_count=row_count;
  return v_count;
end
$function$;

--
-- Name: mdm_delete_boms; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.mdm_delete_boms(p_bom_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_count integer := 0;
begin
  if coalesce(cardinality(p_bom_ids),0)=0 or array_position(p_bom_ids,null) is not null then
    raise exception '请选择有效的 BOM 后重试' using errcode='22023';
  end if;

  for v_id in
    select distinct selected.id
    from unnest(p_bom_ids) as selected(id)
    order by selected.id
  loop
    perform public.mdm_delete_bom(v_id);
    v_count := v_count+1;
  end loop;
  return v_count;
end
$function$;

--
-- Name: mdm_delete_component_industry_group; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.mdm_delete_component_industry_group(p_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_count integer;
begin
 if auth.uid() is null or not (app_private.is_platform_super() or app_private.has_permission('MdmComponentType:ManageGroup')) then
   raise exception '当前账号无权删除行业分组' using errcode='42501';
 end if;
 perform 1 from public.mdm_master_group
 where id=p_id and domain='component-type' and true for update;
 if not found then raise exception '行业分组不存在或无权访问' using errcode='P0002'; end if;
 if exists(select 1 from public.mdm_master_group where parent_id=p_id )
 or exists(select 1 from public.mdm_component_type where group_id=p_id ) then
   raise exception '该分组仍有下级分组或组件类型' using errcode='23503';
 end if;
 delete from public.mdm_master_group where id=p_id  and domain='component-type';
 get diagnostics v_count=row_count;
 return v_count;
end $function$;

--
-- Name: mdm_delete_esop_category; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.mdm_delete_esop_category(p_category_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
begin
  perform app_private.mdm_require_esop_write('MdmEsop:Delete');

  perform 1
  from public.mdm_esop_category category
  where category.id = p_category_id;

  if not found then
    raise exception '分类不存在或无权删除' using errcode = 'P0002';
  end if;


  if exists (
    select 1
    from public.mdm_esop_category category
    where category.parent_id = p_category_id
      
  ) or exists (
    select 1
    from public.mdm_esop_document document
    where document.category_id = p_category_id
      
  ) then
    raise exception '分类下仍有子分类或文档，无法删除' using errcode = '55000';
  end if;

  delete from public.mdm_esop_category
  where id = p_category_id
    ;
end;
$function$;

--
-- Name: mdm_delete_esop_documents; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.mdm_delete_esop_documents(p_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_count integer;
begin
  perform app_private.mdm_require_esop_write('MdmEsop:Delete');

  if coalesce(array_length(p_ids, 1), 0) > 500 then
    raise exception '单次最多删除 500 份 ESOP' using errcode = '22023';
  end if;

  delete from public.mdm_esop_document document
  where document.id = any(coalesce(p_ids, '{}'::uuid[]))
;

  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

