--
-- Name: mdm_get_my_shift_schedule_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.mdm_get_my_shift_schedule_secure(p_start_date date, p_end_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_profiles jsonb := '[]'::jsonb;
  v_schedules jsonb := '[]'::jsonb;
  v_holiday_dates jsonb := '[]'::jsonb;
begin
  if p_start_date is null or p_end_date is null or p_end_date<p_start_date then
    raise exception '请选择有效的排班日期范围' using errcode='22023';
  end if;
  if p_end_date-p_start_date>62 then
    raise exception '单次最多查看 63 天排班' using errcode='22023';
  end if;
  if (select auth.uid()) is null or not app_private.can_access_business_menu('MdmMyShiftSchedule') then
    raise exception '当前账号没有查看“我的排班”的权限' using errcode='42501';
  end if;

  select coalesce(jsonb_agg(to_jsonb(profile_row) order by profile_row."departmentName",profile_row."employeeNo"),'[]'::jsonb)
  into v_profiles
  from (
    select personnel.id as "personnelId",personnel.employee_id as "employeeId",personnel.name as "employeeName",
      personnel.employee_no as "employeeNo",personnel.job_title as "jobTitle",personnel.avatar_url as "avatarUrl",
      department.id as "departmentId",department.name as "departmentName",department.code as "departmentCode",department.factory
    from public.sys_user account
    join public.mdm_production_personnel personnel on personnel.employee_id=account.hr_employee_id
    join public.mdm_production_department department on department.id=personnel.department_id
    where account.auth_user_id=(select auth.uid())  and account.status='1'
      and account.deleted_at is null and account.hr_employee_id is not null
  ) profile_row;

  select coalesce(jsonb_agg(to_jsonb(schedule_row) order by schedule_row."startDate",schedule_row."shiftStartTime"),'[]'::jsonb)
  into v_schedules
  from (
    select distinct on (schedule.id)
      schedule.id,department.id as "departmentId",department.name as "departmentName",department.code as "departmentCode",
      department.factory,pattern.name as "patternName",pattern.color as "patternColor",schedule.shift_name as "shiftName",
      to_char(schedule.shift_start_time,'HH24:MI') as "shiftStartTime",to_char(schedule.shift_end_time,'HH24:MI') as "shiftEndTime",
      schedule.date_mode as "dateMode",to_char(schedule.start_date,'YYYY-MM-DD') as "startDate",
      case when schedule.end_date is null then null else to_char(schedule.end_date,'YYYY-MM-DD') end as "endDate",
      coalesce(to_jsonb(schedule)->'weekdays','[0,1,2,3,4,5,6]'::jsonb) as weekdays,
      coalesce((to_jsonb(schedule)->>'include_statutory_holidays')::boolean,true) as "includeStatutoryHolidays",schedule.note
    from public.sys_user account
    join public.mdm_production_personnel personnel on personnel.employee_id=account.hr_employee_id
    join public.mdm_shift_schedule_member member on member.personnel_id=personnel.id
    join public.mdm_shift_schedule schedule on schedule.id=member.schedule_id
    join public.mdm_production_department department on department.id=schedule.department_id
    join public.mdm_production_shift_pattern pattern on pattern.id=schedule.pattern_id
    where account.auth_user_id=(select auth.uid())  and account.status='1'
      and account.deleted_at is null and account.hr_employee_id is not null and schedule.deleted_at is null
      and app_private.mdm_shift_schedule_range(schedule.start_date,schedule.end_date) && daterange(p_start_date,p_end_date,'[]')
    order by schedule.id,schedule.start_date,schedule.shift_start_time
  ) schedule_row;

  select coalesce(jsonb_agg(to_char(holiday_row.work_date,'YYYY-MM-DD') order by holiday_row.work_date),'[]'::jsonb)
  into v_holiday_dates
  from (
    select distinct holiday.work_date
    from public.sys_user account
    join public.mdm_production_personnel personnel on personnel.employee_id=account.hr_employee_id
    join public.mdm_production_department department on department.id=personnel.department_id
    cross join lateral app_private.mdm_non_working_statutory_holiday_dates(
      department.id,p_start_date,p_end_date) holiday
    where account.auth_user_id=(select auth.uid())  and account.status='1'
      and account.deleted_at is null and account.hr_employee_id is not null
  ) holiday_row;

  return jsonb_build_object('profiles',v_profiles,'schedules',v_schedules,'holidayDates',v_holiday_dates);
end;
$function$;

--
-- Name: mdm_list_personnel_common_work_centers; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.mdm_list_personnel_common_work_centers(p_department_ids uuid[] DEFAULT NULL::uuid[], p_keyword text DEFAULT NULL::text, p_only_unconfigured boolean DEFAULT false, p_from integer DEFAULT 0, p_to integer DEFAULT 19)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  normalized_keyword text := nullif(btrim(p_keyword), '');
  safe_from integer := greatest(coalesce(p_from, 0), 0);
  safe_to integer;
  result_value jsonb;
begin
  if (select auth.uid()) is null then
    raise exception '请先登录后再查看常用工作中心配置' using errcode = '42501';
  end if;
  if app_private.has_permission('MdmPersonnelWorkCenter:View') is not true then
    raise exception '当前账号没有查看人员工作中心配置的权限' using errcode = '42501';
  end if;

  safe_to := least(greatest(coalesce(p_to, safe_from + 19), safe_from), safe_from + 999);

  with filtered as materialized (
    select person.*
    from public.mdm_production_personnel person
    where true
      and person.enabled is true
      and (
        p_department_ids is null
        or cardinality(p_department_ids) = 0
        or person.department_id = any(p_department_ids)
      )
      and (
        normalized_keyword is null
        or person.name ilike '%' || normalized_keyword || '%'
        or person.employee_no ilike '%' || normalized_keyword || '%'
        or person.phone ilike '%' || normalized_keyword || '%'
      )
      and (
        p_only_unconfigured is not true
        or not exists (
          select 1
          from public.mdm_personnel_common_work_center configured
          where true
            and configured.personnel_id = person.id
        )
      )
  ),
  paged as (
    select person.*
    from filtered person
    order by person.sort, person.employee_no, person.id
    offset safe_from
    limit safe_to - safe_from + 1
  )
  select jsonb_build_object(
    'records', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', person.id,
          'departmentId', person.department_id,
          'department', jsonb_build_object(
            'id', department.id,
            'name', department.name,
            'code', department.code
          ),
          'name', person.name,
          'employeeNo', person.employee_no,
          'phone', person.phone,
          'jobTitle', person.job_title,
          'avatarUrl', person.avatar_url,
          'commonWorkCenters', coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'id', center.id,
                'code', center.code,
                'name', center.name,
                'departmentId', center.department_id,
                'departmentName', center_department.name
              )
              order by center.sort, center.code, center.id
            )
            from public.mdm_personnel_common_work_center configured
            join public.mdm_work_center center
              on center.id = configured.work_center_id
            join public.mdm_production_department center_department
              on center_department.id = center.department_id
            where true
              and configured.personnel_id = person.id
          ), '[]'::jsonb)
        )
        order by person.sort, person.employee_no, person.id
      )
      from paged person
      join public.mdm_production_department department
        on department.id = person.department_id
    ), '[]'::jsonb),
    'total', (select count(*) from filtered)
  ) into result_value;

  return result_value;
end;
$function$;

--
-- Name: mdm_list_production_calendar_day_settings_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.mdm_list_production_calendar_day_settings_secure(p_department_id uuid, p_start_date date, p_end_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;
begin
 if auth.uid() is null or not app_private.has_permission('MdmFactoryCalendar:View') then raise exception '没有工厂日历查看权限' using errcode='42501'; end if;
 if p_start_date is null or p_end_date is null or p_end_date<p_start_date or p_end_date-p_start_date>3660 then raise exception '请选择有效日期区间' using errcode='22023'; end if;
 with recursive production_scope as (
 select d.id,d.parent_id,d.organization_id,0 as depth,array[d.id] as visited from public.mdm_production_department d where d.id=p_department_id 
 union all
 select d.id,d.parent_id,d.organization_id,s.depth+1,s.visited||d.id from public.mdm_production_department d join production_scope s on d.id=s.parent_id where not d.id=any(s.visited)
 ), linked_org as (
 select organization_id from production_scope where organization_id is not null order by depth limit 1
 ), org_scope as (
 select o.id,o.parent_id,0 as depth,array[o.id] as visited from public.mdm_organization o join linked_org l on l.organization_id=o.id where true
 union all
 select o.id,o.parent_id,s.depth+1,s.visited||o.id from public.mdm_organization o join org_scope s on o.id=s.parent_id where not o.id=any(s.visited)
 ), candidates as (
 select s.id,s.work_date,s.day_type,'manual'::text as source,null::uuid as holiday_id,null::text as holiday_name,-1 as priority,s.update_time from public.mdm_production_calendar_day_setting s where s.department_id=p_department_id and s.work_date between p_start_date and p_end_date
 union all
 select h.id,dates.d::date,
 case h.holiday_type when 'compensatory_leave' then 'rest_day' when 'makeup_work' then 'work_day' else 'statutory_holiday' end,
 'statutory_holiday',h.id,
 case h.holiday_type when 'compensatory_leave' then '调休' when 'makeup_work' then '补班' when 'new_year' then '元旦' when 'spring_festival' then '春节' when 'qingming' then '清明节' when 'labor_day' then '劳动节' when 'dragon_boat' then '端午节' when 'mid_autumn' then '中秋节' when 'national_day' then '国庆节' else h.holiday_type end,
 o.depth,h.update_time
 from public.smis_statutory_holiday h join org_scope o on o.id=h.organization_id
 cross join lateral generate_series(greatest(h.start_date,p_start_date)::timestamp,least(h.end_date,p_end_date)::timestamp,interval '1 day') dates(d)
 where h.start_date<=p_end_date and h.end_date>=p_start_date
 ), chosen as (select distinct on(work_date) * from candidates order by work_date,priority,update_time desc,id)
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'departmentId',p_department_id,'workDate',work_date,'dayType',day_type,'source',source,'holidayId',holiday_id,'holidayName',holiday_name) order by work_date),'[]'::jsonb) into v_result from chosen;
 return v_result;
end $function$;

--
-- Name: mdm_list_production_employees; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.mdm_list_production_employees(p_id uuid DEFAULT NULL::uuid, p_from integer DEFAULT 0, p_to integer DEFAULT 9, p_keyword text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select app_private.list_mdm_production_employees(p_id,p_from,p_to,p_keyword);
$function$;

--
-- Name: mdm_list_production_equipment_v2_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.mdm_list_production_equipment_v2_secure(p_from integer DEFAULT 0, p_to integer DEFAULT 19, p_keyword text DEFAULT NULL::text, p_category_id uuid DEFAULT NULL::uuid, p_department_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_from integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1);
  v_keyword text := nullif(btrim(coalesce(p_keyword, '')), '');
  v_records jsonb;
  v_total bigint;
  v_references jsonb;
  v_overview jsonb;
begin
  if auth.uid() is null then raise exception '请先登录后再查看生产设备' using errcode = '42501'; end if;
  if not app_private.has_permission('MdmProductionEquipment:View') then
    raise exception '当前账号没有查看生产设备的权限' using errcode = '42501';
  end if;

  with recursive category_scope as (
    select id from public.mdm_equipment_category
    where id = p_category_id
    union all
    select child.id from public.mdm_equipment_category child
    join category_scope parent on child.parent_id = parent.id
    where true
  ), department_scope as (
    select id from public.mdm_production_department
    where id = p_department_id
    union all
    select child.id from public.mdm_production_department child
    join department_scope parent on child.parent_id = parent.id
    where true
  ), location_scope as (
    select id from public.mdm_storage_location
    where id = p_location_id
    union all
    select child.id from public.mdm_storage_location child
    join location_scope parent on child.parent_id = parent.id
    where true
  ), filtered as (
    select equipment.*
    from public.mdm_equipment equipment
    where true
      and (p_category_id is null or equipment.category_id in (select id from category_scope))
      and (p_department_id is null or equipment.production_department_id in (select id from department_scope))
      and (p_location_id is null or equipment.location_id in (select id from location_scope))
      and (p_status is null or equipment.status = p_status)
      and (
        v_keyword is null
        or equipment.equipment_code ilike '%' || v_keyword || '%'
        or equipment.equipment_name ilike '%' || v_keyword || '%'
        or coalesce(equipment.model, '') ilike '%' || v_keyword || '%'
        or coalesce(equipment.factory_no, '') ilike '%' || v_keyword || '%'
      )
  )
  select count(*) into v_total from filtered;

  with recursive category_scope as (
    select id from public.mdm_equipment_category
    where id = p_category_id
    union all
    select child.id from public.mdm_equipment_category child
    join category_scope parent on child.parent_id = parent.id
    where true
  ), department_scope as (
    select id from public.mdm_production_department
    where id = p_department_id
    union all
    select child.id from public.mdm_production_department child
    join department_scope parent on child.parent_id = parent.id
    where true
  ), location_scope as (
    select id from public.mdm_storage_location
    where id = p_location_id
    union all
    select child.id from public.mdm_storage_location child
    join location_scope parent on child.parent_id = parent.id
    where true
  )
  select coalesce(jsonb_agg(record order by record->>'equipmentName', record->>'equipmentCode'), '[]'::jsonb)
  into v_records
  from (
    select jsonb_build_object(
      'id', e.id,
      'equipmentCode', e.equipment_code, 'equipmentName', e.equipment_name,
      'photoUrl', e.photo_url,
      'categoryId', e.category_id, 'categoryName', category.category_name,
      'productionDepartmentId', e.production_department_id, 'departmentName', department.name,
      'locationId', e.location_id, 'locationName', location.location_name,
      'workCenterId', e.work_center_id, 'workCenterCode', center.code, 'workCenterName', center.name,
      'responsibleEmployeeId', e.responsible_employee_id, 'responsibleName', employee.employee_name,
      'supplierId', e.supplier_id, 'supplierName', supplier.supplier_name,
      'equipmentBrand', e.equipment_brand, 'model', e.model, 'factoryNo', e.factory_no,
      'manufacturer', e.manufacturer, 'fixedAssetNo', e.fixed_asset_no,
      'manufactureDate', e.manufacture_date, 'installationDate', e.installation_date,
      'acceptanceDate', e.acceptance_date, 'enableDate', e.enable_date,
      'trafficLightCardNo', e.traffic_light_card_no, 'andonBoxNo', e.andon_box_no,
      'pulseIntervalSeconds', e.pulse_interval_seconds,
      'standardUtilization', e.standard_utilization,
      'syncWorkCenter', e.sync_work_center, 'operationStatus', e.operation_status,
      'status', e.status, 'remark', e.remark, 'sort', e.sort,
      'createBy', e.create_by, 'createTime', e.create_time,
      'updateBy', e.update_by, 'updateTime', e.update_time
    ) record
    from public.mdm_equipment e
    join public.mdm_equipment_category category
      on category.id = e.category_id 
    left join public.mdm_production_department department
      on department.id = e.production_department_id 
    left join public.mdm_storage_location location
      on location.id = e.location_id 
    left join public.mdm_work_center center
      on center.id = e.work_center_id 
    left join public.mdm_employee employee
      on employee.id = e.responsible_employee_id 
    left join public.mdm_supplier supplier
      on supplier.id = e.supplier_id 
    where true
      and (p_category_id is null or e.category_id in (select id from category_scope))
      and (p_department_id is null or e.production_department_id in (select id from department_scope))
      and (p_location_id is null or e.location_id in (select id from location_scope))
      and (p_status is null or e.status = p_status)
      and (
        v_keyword is null
        or e.equipment_code ilike '%' || v_keyword || '%'
        or e.equipment_name ilike '%' || v_keyword || '%'
        or coalesce(e.model, '') ilike '%' || v_keyword || '%'
        or coalesce(e.factory_no, '') ilike '%' || v_keyword || '%'
      )
    order by e.sort, e.equipment_name, e.equipment_code
    offset v_from limit v_limit
  ) page;

  select jsonb_build_object(
    'categories', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', id, 'parentId', parent_id,
        'code', category_code, 'name', category_name
      ) order by sort, category_name)
      from public.mdm_equipment_category
      where status = 'enabled'
    ), '[]'::jsonb),
    'departments', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', id, 'parentId', parent_id,
        'code', code, 'name', name, 'organizationId', organization_id, 'kind', kind
      ) order by sort, name)
      from public.mdm_production_department
      where enabled
    ), '[]'::jsonb),
    'locations', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', id, 'parentId', parent_id,
        'code', location_code, 'name', location_name
      ) order by location_name)
      from public.mdm_storage_location
      where status = 'enabled'
    ), '[]'::jsonb),
    'workCenters', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', id, 'departmentId', department_id,
        'code', code, 'name', name
      ) order by sort, name)
      from public.mdm_work_center
      where true
    ), '[]'::jsonb),
    'suppliers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', id, 'code', supplier_code, 'name', supplier_name
      ) order by supplier_name)
      from public.mdm_supplier
      where true
    ), '[]'::jsonb)
  ) into v_references;

  select jsonb_build_object(
    'total', count(*),
    'enabled', count(*) filter (where status = 'enabled'),
    'connected', count(*) filter (where traffic_light_card_no is not null or andon_box_no is not null),
    'unassigned', count(*) filter (where production_department_id is null)
  )
  into v_overview
  from public.mdm_equipment
  where  1=1 ;

  return jsonb_build_object(
    'records', v_records, 'total', v_total,
    'references', v_references, 'overview', v_overview
  );
end
$function$;

--
-- Name: mdm_list_shift_schedule_departments_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.mdm_list_shift_schedule_departments_secure()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select case when auth.uid() is null or not app_private.has_permission('MdmShiftScheduling:View') then '[]'::jsonb else coalesce(jsonb_agg(jsonb_build_object('id',d.id,'organizationId',d.organization_id,'parentId',d.parent_id,'name',d.name,'code',d.code,'factory',d.factory,'kind',d.kind,'sort',d.sort,'textColor',d.text_color,'tagType',d.tag_type,'enabled',d.enabled,'remark',d.remark) order by d.sort,d.code),'[]'::jsonb) end from public.mdm_production_department d where true $function$;

--
-- Name: mdm_list_shift_schedule_holiday_dates_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.mdm_list_shift_schedule_holiday_dates_secure(p_department_id uuid, p_start_date date, p_end_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;
begin
  if auth.uid() is null or not app_private.has_permission('MdmShiftScheduling:View') then
    raise exception '没有排班查看权限' using errcode='42501';
  end if;
  if p_start_date is null or p_end_date is null or p_end_date<p_start_date
    or p_end_date-p_start_date>3660 then
    raise exception '请选择有效日期区间' using errcode='22023';
  end if;
  select coalesce(jsonb_agg(to_char(h.work_date,'YYYY-MM-DD') order by h.work_date),'[]'::jsonb)
  into v_result
  from app_private.mdm_non_working_statutory_holiday_dates(
    p_department_id,p_start_date,p_end_date) h;
  return v_result;
end
$function$;

--
-- Name: mdm_list_shift_schedule_patterns_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.mdm_list_shift_schedule_patterns_secure(p_department_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select case when auth.uid() is null or not app_private.has_permission('MdmShiftScheduling:View') then '[]'::jsonb else coalesce(jsonb_agg(jsonb_build_object('id',p.id,'departmentId',p.department_id,'name',p.name,'description',p.description,'sort',p.sort,'color',p.color,'shifts',p.shifts) order by p.sort,p.name),'[]'::jsonb) end from public.mdm_production_shift_pattern p where p.department_id=p_department_id and true $function$;

--
-- Name: mdm_list_shift_schedule_people_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.mdm_list_shift_schedule_people_secure(p_department_id uuid, p_from integer DEFAULT 0, p_to integer DEFAULT 9, p_keyword text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;
begin
 if auth.uid() is null or not app_private.has_permission('MdmShiftScheduling:View') then raise exception '没有排班查看权限' using errcode='42501'; end if;
 if p_from<0 or p_to<p_from or p_to-p_from>199 then raise exception '分页范围无效'; end if;
 with recursive department_scope as (select id from public.mdm_production_department where id=p_department_id  union all select d.id from public.mdm_production_department d join department_scope s on d.parent_id=s.id where true), filtered as (select p.*,d.name department_name,d.code department_code,count(*) over() total from public.mdm_production_personnel p join department_scope scope on scope.id=p.department_id join public.mdm_production_department d on d.id=p.department_id where p.enabled and (p_keyword is null or concat_ws(' ',p.name,p.employee_no,p.job_title) ilike '%'||p_keyword||'%') order by p.employee_no,p.id offset p_from limit p_to-p_from+1)
 select jsonb_build_object('records',coalesce(jsonb_agg(jsonb_build_object('id',f.id,'departmentId',f.department_id,'employeeName',f.name,'employeeNo',f.employee_no,'phone',f.phone,'jobTitle',f.job_title,'avatarUrl',f.avatar_url,'employmentStatus',case when f.enabled then 'active' else 'inactive' end,'organization',jsonb_build_object('id',f.department_id,'organizationCode',f.department_code,'organizationName',f.department_name),'organizationName',f.department_name) order by f.employee_no),'[]'::jsonb),'total',coalesce(max(f.total),0)) into v_result from filtered f;
 return v_result;
end $function$;

--
-- Name: mdm_list_shift_schedules_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.mdm_list_shift_schedules_secure(p_department_id uuid, p_start_date date, p_end_date date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
select case
  when auth.uid() is null or not app_private.has_permission('MdmShiftScheduling:View') then '[]'::jsonb
  else coalesce(jsonb_agg(jsonb_build_object(
    'id',s.id,'departmentId',s.department_id,
    'patternId',s.pattern_id,'patternName',p.name,'patternColor',p.color,
    'shiftIndex',s.shift_index,'shiftName',s.shift_name,
    'shiftStartTime',to_char(s.shift_start_time,'HH24:MI'),
    'shiftEndTime',to_char(s.shift_end_time,'HH24:MI'),
    'dateMode',s.date_mode,'startDate',to_char(s.start_date,'YYYY-MM-DD'),
    'endDate',case when s.end_date is null then null else to_char(s.end_date,'YYYY-MM-DD') end,
    'weekdays',to_jsonb(s.weekdays),
    'includeStatutoryHolidays',s.include_statutory_holidays,
    'note',s.note,'memberCount',coalesce(m.member_count,0),
    'members',coalesce(m.members,'[]'::jsonb),
    'createTime',s.create_time,'updateTime',s.update_time
  ) order by s.start_date,s.shift_index,s.create_time),'[]'::jsonb)
end
from public.mdm_shift_schedule s
join public.mdm_production_shift_pattern p
  on p.id=s.pattern_id 
left join lateral (
  select count(*)::integer member_count,
    jsonb_agg(jsonb_build_object(
      'id',person.id,'departmentId',person.department_id,
      'employeeName',person.name,'employeeNo',person.employee_no,'phone',person.phone,
      'jobTitle',person.job_title,'avatarUrl',person.avatar_url,
      'employmentStatus',case when person.enabled then 'active' else 'inactive' end,
      'organization',jsonb_build_object(
        'id',d.id,'organizationCode',d.code,'organizationName',d.name
      )
    ) order by person.employee_no) members
  from public.mdm_shift_schedule_member sm
  join public.mdm_production_personnel person
    on person.id=sm.personnel_id 
  join public.mdm_production_department d
    on d.id=person.department_id 
  where sm.schedule_id=s.id
) m on true
where s.department_id=p_department_id and s.deleted_at is null

  and p_start_date<=p_end_date
  and app_private.mdm_shift_schedule_range(s.start_date,s.end_date)
      && daterange(p_start_date,p_end_date,'[]')
$function$;

--
-- Name: mdm_list_statutory_holidays_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.mdm_list_statutory_holidays_secure(p_from integer DEFAULT 0, p_to integer DEFAULT 999, p_organization_id uuid DEFAULT NULL::uuid, p_holiday_type text DEFAULT NULL::text, p_year integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_records jsonb;
  v_total bigint;
begin
  if not (app_private.is_platform_super() or app_private.has_permission('MdmStatutoryHoliday:View')) then
    raise exception '当前账号没有查看法定节假日的权限' using errcode = '42501';
  end if;

  select count(*) into v_total
  from public.smis_statutory_holiday holiday
  where (p_organization_id is null or holiday.organization_id = p_organization_id)
    and (p_holiday_type is null or holiday.holiday_type = p_holiday_type)
    and (p_year is null or holiday.start_date <= make_date(p_year, 12, 31)
      and holiday.end_date >= make_date(p_year, 1, 1));

  select coalesce(jsonb_agg(to_jsonb(record_row) order by record_row."startDate", record_row."createTime"), '[]'::jsonb)
  into v_records
  from (
    select holiday.id,
      holiday.organization_id as "organizationId",
      holiday.holiday_type as "holidayType",
      holiday.start_date as "startDate",
      holiday.end_date as "endDate",
      holiday.remark,
      holiday.create_time as "createTime",
      holiday.update_time as "updateTime",
      jsonb_build_object(
        'id', organization.id,
        'organizationCode', organization.organization_code,
        'organizationName', organization.organization_name,
        'organizationType', organization.organization_type
      ) as organization
    from public.smis_statutory_holiday holiday
    join public.mdm_organization organization
      on organization.id = holiday.organization_id 
    where (p_organization_id is null or holiday.organization_id = p_organization_id)
      and (p_holiday_type is null or holiday.holiday_type = p_holiday_type)
      and (p_year is null or holiday.start_date <= make_date(p_year, 12, 31)
        and holiday.end_date >= make_date(p_year, 1, 1))
    order by holiday.start_date, holiday.create_time
    offset greatest(coalesce(p_from, 0), 0)
    limit greatest(coalesce(p_to, 999) - greatest(coalesce(p_from, 0), 0) + 1, 0)
  ) record_row;

  return jsonb_build_object('records', v_records, 'total', v_total);
end;
$function$;

--
-- Name: mdm_process_route_material_options; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.mdm_process_route_material_options(p_keyword text DEFAULT ''::text, p_category_id uuid DEFAULT NULL::uuid, p_from integer DEFAULT 0, p_to integer DEFAULT 9)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
  v_term text := replace(replace(replace(coalesce(p_keyword, ''), '\\', '\\\\'), '%', '\\%'), '_', '\\_');
begin
  if auth.uid() is null or not app_private.has_permission('MdmProcessRoute:View') then
    raise exception '没有查看工艺路线物料参选数据权限' using errcode = '42501';
  end if;
  if p_from < 0 or p_to < p_from or p_to - p_from > 999 then
    raise exception '分页范围无效';
  end if;

  with recursive selected_categories as (
    select category.id
    from public.mdm_material_category category
    where category.id = p_category_id


    union all
    select child.id
    from public.mdm_material_category child
    join selected_categories parent on parent.id = child.parent_id
    where true

  ),
  source as (
    select
      material.material_code,
      jsonb_build_object(
        'id', material.id,
        'categoryId', material.category_id,
        'materialCode', material.material_code,
        'materialName', material.material_name,
        'specificationModel', material.specification_model,
        'drawingNo', material.drawing_no,
        'materialComposition', material.material_composition,
        'brand', material.brand,
        'materialType', material.material_type,
        'materialSource', material.material_source,
        'specialPurchaseType', material.special_purchase_type,
        'productionUnitId', material.production_unit_id,
        'category', jsonb_build_object(
          'id', category.id,
          'categoryCode', category.category_code,
          'categoryName', category.category_name
        ),
        'materialTypeRef', case
          when material_type.id is null then null
          else jsonb_build_object(
            'id', material_type.id,
            'typeCode', material_type.type_code,
            'typeName', material_type.type_name
          )
        end
      ) as record
    from public.mdm_material material
    join public.mdm_material_category category on category.id = material.category_id
    left join public.mdm_material_type material_type on material_type.id = material.material_type_id
    where true

      and (
        p_category_id is null
        or material.category_id in (select id from selected_categories)
      )
      and (
        material.material_code ilike '%' || v_term || '%'
        or material.material_name ilike '%' || v_term || '%'
        or coalesce(material.specification_model, '') ilike '%' || v_term || '%'
        or coalesce(material.drawing_no, '') ilike '%' || v_term || '%'
        or coalesce(material.material_composition, '') ilike '%' || v_term || '%'
        or coalesce(material.brand, '') ilike '%' || v_term || '%'
      )
  ),
  page as (
    select record
    from source
    order by material_code
    limit p_to - p_from + 1
    offset p_from
  )
  select jsonb_build_object(
    'records', coalesce((select jsonb_agg(page.record) from page), '[]'::jsonb),
    'total', (select count(*) from source)
  )
  into v_result;

  return v_result;
end
$function$;

