--
-- Name: save_dict_type_tree_order; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.save_dict_type_tree_order(p_updates jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  item jsonb;
  affected_rows integer;
begin
  if not app_private.is_platform_super() then
    raise exception '仅平台超级管理员可以调整字典目录';
  end if;

  if jsonb_typeof(p_updates) <> 'array' then
    raise exception '字典目录排序参数必须是数组';
  end if;

  for item in
    select value
    from jsonb_array_elements(p_updates)
  loop
    update public.sys_dict_type
    set
      parent_id = nullif(item->>'parentId', '')::uuid,
      sort = greatest(coalesce((item->>'sort')::integer, 0), 0)
    where id = (item->>'id')::uuid;

    get diagnostics affected_rows = row_count;
    if affected_rows <> 1 then
      raise exception '字典目录节点不存在或无权修改: %', item->>'id';
    end if;
  end loop;
end
$function$;

--
-- Name: save_menu_tree_order; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.save_menu_tree_order(p_updates jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  item jsonb;
  target_id uuid;
  target_parent_id uuid;
  target_sort integer;
  current_parent_id uuid;
  current_sort integer;
  affected_rows integer;
  expected_rows integer;
begin
  if jsonb_typeof(p_updates) <> 'array' then
    raise exception '菜单树排序参数必须是数组';
  end if;

  select count(*) into expected_rows from public.sys_menu;

  if jsonb_array_length(p_updates) <> expected_rows then
    raise exception '菜单树排序必须提交完整节点，期望 % 个，实际 % 个',
      expected_rows, jsonb_array_length(p_updates);
  end if;

  if (
    select count(*)
    from jsonb_array_elements(p_updates) value
  ) <> (
    select count(distinct value->>'id')
    from jsonb_array_elements(p_updates) value
  ) then
    raise exception '菜单树排序包含重复节点';
  end if;

  for item in
    select value
    from jsonb_array_elements(p_updates)
  loop
    target_id := (item->>'id')::uuid;
    target_parent_id := nullif(item->>'parentId', '')::uuid;
    target_sort := (item->>'sort')::integer;

    if target_sort is null or target_sort < 1 then
      raise exception '菜单排序必须大于等于 1: %', item->>'id';
    end if;

    if target_parent_id = target_id then
      raise exception '菜单不能成为自己的父级: %', item->>'id';
    end if;

    select parent_id, sort
      into current_parent_id, current_sort
    from public.sys_menu
    where id = target_id;

    if not found then
      raise exception '菜单节点不存在: %', item->>'id';
    end if;

    if current_parent_id is distinct from target_parent_id
       or current_sort is distinct from target_sort then
      update public.sys_menu
      set
        parent_id = target_parent_id,
        sort = target_sort
      where id = target_id;

      get diagnostics affected_rows = row_count;
      if affected_rows <> 1 then
        raise exception '当前账号没有菜单排序权限: %', item->>'id';
      end if;
    end if;
  end loop;

  if exists (
    select 1
    from public.sys_menu child
    left join public.sys_menu parent on parent.id = child.parent_id
    where child.parent_id is not null
      and parent.id is null
  ) then
    raise exception '菜单树包含不存在的父级节点';
  end if;

  if exists (
    with recursive ancestry as (
      select
        menu.id,
        menu.parent_id,
        array[menu.id] as path,
        false as cycle
      from public.sys_menu menu

      union all

      select
        ancestry.id,
        parent.parent_id,
        ancestry.path || parent.id,
        parent.id = any(ancestry.path)
      from ancestry
      join public.sys_menu parent on parent.id = ancestry.parent_id
      where not ancestry.cycle
    )
    select 1
    from ancestry
    where cycle
  ) then
    raise exception '菜单树不能形成循环层级';
  end if;

  if exists (
    select 1
    from public.sys_menu
    group by parent_id, sort
    having count(*) > 1
  ) then
    raise exception '同一父级下存在重复排序值';
  end if;
end
$function$;

--
-- Name: save_notification_channel_config; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.save_notification_channel_config(p_channel_code text, p_provider_code text, p_enabled boolean, p_config jsonb, p_secret jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_secret_id uuid;
  v_result public.sys_notification_channel_config%rowtype;
  v_secret_name text;
begin
  if not app_private.has_permission('System:NotificationReminder:EditChannel') then
    raise exception '缺少编辑通知渠道权限' using errcode = '42501';
  end if;
  if p_channel_code not in ('in_app', 'email', 'sms', 'dingtalk', 'wecom') then
    raise exception '不支持的通知渠道';
  end if;
  if coalesce(jsonb_typeof(p_config), 'null') <> 'object'
     or (p_secret is not null and jsonb_typeof(p_secret) <> 'object') then
    raise exception '渠道配置格式无效';
  end if;

  select vault_secret_id into v_secret_id
  from public.sys_notification_channel_config
  where channel_code = p_channel_code;

  if p_channel_code <> 'in_app' and p_secret is not null and p_secret <> '{}'::jsonb then
    v_secret_name := 'notification_channel_' || p_channel_code;
    if v_secret_id is null then
      select vault.create_secret(p_secret::text, v_secret_name, 'Notification channel credential')
        into v_secret_id;
    else
      perform vault.update_secret(v_secret_id, p_secret::text);
    end if;
  end if;

  insert into public.sys_notification_channel_config ( channel_code, provider_code, enabled, config, vault_secret_id,
    create_by, update_by
  ) values ( p_channel_code, coalesce(nullif(btrim(p_provider_code), ''), 'builtin'),
    case when p_channel_code = 'in_app' then true else coalesce(p_enabled, false) end,
    coalesce(p_config, '{}'::jsonb), v_secret_id,
    coalesce(app_private.current_user_email(), 'system-reminder'),
    coalesce(app_private.current_user_email(), 'system-reminder')
  )
  on conflict (channel_code) do update
  set provider_code = excluded.provider_code,
      enabled = excluded.enabled,
      config = excluded.config,
      vault_secret_id = coalesce(excluded.vault_secret_id, public.sys_notification_channel_config.vault_secret_id),
      last_error = null,
      update_by = excluded.update_by
  returning * into v_result;

  return jsonb_build_object(
    'id', v_result.id,
    'channelCode', v_result.channel_code,
    'providerCode', v_result.provider_code,
    'enabled', v_result.enabled,
    'config', v_result.config,
    'secretConfigured', v_result.channel_code = 'in_app' or v_result.vault_secret_id is not null
  );
end;
$function$;

--
-- Name: save_notification_rule; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.save_notification_rule(p_rule jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rule_id uuid := nullif(p_rule ->> 'id', '')::uuid;
  v_scenario_id uuid := nullif(p_rule ->> 'scenarioId', '')::uuid;
  v_channels text[];
  v_roles text[];
  v_result public.sys_notification_rule%rowtype;
begin
  if v_rule_id is null then
    if not app_private.has_permission('System:NotificationReminder:AddRule') then
      raise exception '缺少新增提醒规则权限' using errcode = '42501';
    end if;
  elsif not app_private.has_permission('System:NotificationReminder:EditRule') then
    raise exception '缺少编辑提醒规则权限' using errcode = '42501';
  end if;

  if not exists (select 1 from public.sys_notification_scenario where id = v_scenario_id and enabled is true) then
    raise exception '提醒场景不存在或已停用';
  end if;
  select array_agg(distinct value order by value) into v_channels
  from jsonb_array_elements_text(coalesce(p_rule -> 'channels', '[]'::jsonb)) value;
  select coalesce(array_agg(distinct value order by value), array[]::text[]) into v_roles
  from jsonb_array_elements_text(coalesce(p_rule -> 'recipientRoleCodes', '[]'::jsonb)) value;
  if coalesce(cardinality(v_channels), 0) = 0 then raise exception '请至少选择一个通知渠道'; end if;

  if v_rule_id is null then
    insert into public.sys_notification_rule ( scenario_id, rule_name, lead_days, repeat_every_days, send_hour,
      recipient_strategy, recipient_role_codes, channels, enabled, create_by, update_by
    ) values ( v_scenario_id, btrim(p_rule ->> 'ruleName'),
      coalesce((p_rule ->> 'leadDays')::integer, 0), nullif(p_rule ->> 'repeatEveryDays', '')::integer,
      coalesce((p_rule ->> 'sendHour')::smallint, 9),
      coalesce(nullif(p_rule ->> 'recipientStrategy', ''), 'owner_then_roles'),
      v_roles, v_channels, coalesce((p_rule ->> 'enabled')::boolean, true),
      coalesce(app_private.current_user_email(), 'system-reminder'),
      coalesce(app_private.current_user_email(), 'system-reminder')
    ) returning * into v_result;
  else
    update public.sys_notification_rule
    set scenario_id = v_scenario_id,
        rule_name = btrim(p_rule ->> 'ruleName'),
        lead_days = coalesce((p_rule ->> 'leadDays')::integer, 0),
        repeat_every_days = nullif(p_rule ->> 'repeatEveryDays', '')::integer,
        send_hour = coalesce((p_rule ->> 'sendHour')::smallint, 9),
        recipient_strategy = coalesce(nullif(p_rule ->> 'recipientStrategy', ''), 'owner_then_roles'),
        recipient_role_codes = v_roles,
        channels = v_channels,
        enabled = coalesce((p_rule ->> 'enabled')::boolean, true),
        update_by = coalesce(app_private.current_user_email(), 'system-reminder')
    where id = v_rule_id 
    returning * into v_result;
    if not found then raise exception '提醒规则不存在或无权编辑'; end if;
  end if;
  return to_jsonb(v_result);
end;
$function$;

