--
-- Name: set_field_permissions; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.set_field_permissions(p_resource_key text, p_subject_type text, p_subject_id uuid, p_permissions jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=app_private.current_app_user_id(); v_resource public.sys_permission_resource%rowtype; v_before jsonb;
begin
 if not app_private.can_manage_field_permissions() then raise exception 'Missing permission: System:FieldPermission:Manage'; end if;
 if p_subject_type not in ('role','user') or p_permissions is null or jsonb_typeof(p_permissions)<>'object' then raise exception 'Invalid permission request'; end if;
 select * into v_resource from public.sys_permission_resource where resource_key=p_resource_key and enabled;
 if not found then raise exception 'Permission resource not found'; end if;
 if p_subject_type='role' then
  if not exists(select 1 from public.sys_role where id=p_subject_id and enabled) then raise exception 'Role not found or access denied'; end if;
  select coalesce(jsonb_object_agg(f.field_key,p.access_level),'{}'::jsonb) into v_before from public.sys_role_field_permission p join public.sys_permission_field f on f.id=p.field_id where p.role_id=p_subject_id and p.resource_id=v_resource.id;
  delete from public.sys_role_field_permission where role_id=p_subject_id and resource_id=v_resource.id;
  insert into public.sys_role_field_permission(role_id,resource_id,field_id,access_level,create_by,update_by) select p_subject_id,v_resource.id,f.id,x.value,'platform-owner@example.com','platform-owner@example.com' from jsonb_each_text(p_permissions) x join public.sys_permission_field f on f.resource_id=v_resource.id and f.field_key=x.key and f.enabled and f.sensitive where x.value in ('hidden','masked','read','edit');
 else
  if not exists(select 1 from public.sys_user where id=p_subject_id and status='1' and deleted_at is null) then raise exception 'User not found or access denied'; end if;
  select coalesce(jsonb_object_agg(f.field_key,p.access_level),'{}'::jsonb) into v_before from public.sys_user_field_permission p join public.sys_permission_field f on f.id=p.field_id where p.user_id=p_subject_id and p.resource_id=v_resource.id;
  delete from public.sys_user_field_permission where user_id=p_subject_id and resource_id=v_resource.id;
  insert into public.sys_user_field_permission(user_id,resource_id,field_id,access_level,create_by,update_by) select p_subject_id,v_resource.id,f.id,x.value,'platform-owner@example.com','platform-owner@example.com' from jsonb_each_text(p_permissions) x join public.sys_permission_field f on f.resource_id=v_resource.id and f.field_key=x.key and f.enabled and f.sensitive where x.value in ('hidden','masked','read','edit');
 end if;
 insert into public.sys_permission_audit_log(actor_user_id,target_type,target_id,resource_id,action,before_value,after_value,create_by) values(v_actor,p_subject_type||'_field',p_subject_id,v_resource.id,case when p_permissions='{}'::jsonb then 'clear' else 'replace' end,v_before,p_permissions,coalesce(auth.jwt()->>'email','unknown'));
end; $function$;

--
-- Name: set_role_menus; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.set_role_menus(p_role_id uuid, p_menu_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'app_private'
AS $function$
declare
  v_role_code text;
begin
  if not app_private.has_permission('System:Role:AssignPermission') then
    raise exception 'Missing permission: System:Role:AssignPermission';
  end if;

  select upper(role.role_code)
    into v_role_code
  from public.sys_role as role
  where role.id = p_role_id;

  if not found then
    raise exception 'Role not found or access denied';
  end if;

  if v_role_code = 'R_SUPER' then
    raise exception 'Super admin role has all permissions and does not support menu allocation';
  end if;

  delete from public.sys_role_menu
  where role_id = p_role_id;

  if coalesce(cardinality(p_menu_ids), 0) > 0 then
    insert into public.sys_role_menu (role_id, menu_id)
    select p_role_id, menu_id
    from (select distinct unnest(p_menu_ids) as menu_id) selected
    where menu_id is not null
    on conflict (role_id, menu_id) do nothing;
  end if;
end;
$function$;

--
-- Name: set_vehicle_parts_category_level; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.set_vehicle_parts_category_level()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  parent_level integer;
begin
  if new.parent_id is null then
    new.category_level := 1;
  else
    select category_level into parent_level
    from public.mdm_part_category
    where id = new.parent_id;

    if parent_level is null then
      raise exception 'Parent category % does not exist', new.parent_id;
    end if;

    new.category_level := parent_level + 1;
  end if;

  return new;
end;
$function$;

