      select transaction_row.id, transaction_row.direction, transaction_row.bank_reference
      from public.tms_cash_transaction transaction_row
      where transaction_row.bank_reference is not null
        and app_private.resolve_field_access(
          'tms.cash_transaction', 'bankDetails', transaction_row.created_by_user_id
        ) in ('read', 'edit')
      order by transaction_row.id
      limit least(5000, greatest(coalesce(p_limit, 5000), 1))
    ) permitted
  ), '[]'::jsonb);
end;
$function$;

--
-- Name: tms_list_customer_options_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.tms_list_customer_options_secure(p_exclude_id uuid DEFAULT NULL::uuid, p_include_disabled boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
begin
  if not app_private.can_access_tms_customer_reference_data() then
    raise exception 'Missing customer reference data permission' using errcode = '42501';
  end if;


  return coalesce((
    select jsonb_agg(
      app_private.tms_customer_option_to_secure_json(customer_row)
