--
-- Name: tms_list_customer_selector_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.tms_list_customer_selector_secure(p_from integer DEFAULT 0, p_to integer DEFAULT 9, p_keyword text DEFAULT NULL::text, p_address_type text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_customer_access jsonb;
  v_can_search_phone boolean;
  v_can_search_address boolean;
  v_limit integer := least(
    200,
    greatest(coalesce(p_to, 9) - greatest(coalesce(p_from, 0), 0) + 1, 1)
  );
  v_result jsonb;
begin
  if not app_private.can_access_tms_customer_reference_data() then
    raise exception 'Missing customer reference data permission' using errcode = '42501';
  end if;
  if p_address_type is not null and p_address_type not in ('shipping', 'receiving') then
    raise exception 'Invalid customer address type';
  end if;

  v_customer_access := app_private.field_access_map('tms.customer', null);
  v_can_search_phone := coalesce(v_customer_access->>'contactPhone', 'hidden') in ('read', 'edit');
  v_can_search_address := coalesce(v_customer_access->>'addressDetail', 'hidden') in ('read', 'edit');

  with filtered as materialized (
    select customer_row as customer_record
    from public.mdm_customer customer_row
    where customer_row.enabled
      and (
        nullif(btrim(p_keyword), '') is null
        or customer_row.customer_name ilike '%' || btrim(p_keyword) || '%'
        or customer_row.customer_code ilike '%' || btrim(p_keyword) || '%'
        or customer_row.contact_name ilike '%' || btrim(p_keyword) || '%'
        or (v_can_search_phone and customer_row.contact_phone ilike '%' || btrim(p_keyword) || '%')
        or (v_can_search_address and customer_row.address_detail ilike '%' || btrim(p_keyword) || '%')
      )
  ), paged as (
    select filtered.customer_record
    from filtered
    order by (filtered.customer_record).create_time desc, (filtered.customer_record).id
    offset greatest(coalesce(p_from, 0), 0)
    limit v_limit
  ), shaped as (
    select
      app_private.tms_customer_option_to_secure_json(paged.customer_record) as customer_json,
      address_pick.address_record
    from paged
    left join lateral (
      select address_row as address_record
      from public.mdm_customer_address address_row
      where p_address_type is not null
        and address_row.customer_id = (paged.customer_record).id
        and address_row.address_type = p_address_type
      order by address_row.is_default desc, address_row.update_time desc nulls last,
               address_row.create_time desc, address_row.id
      limit 1
    ) address_pick on true
  )
  select jsonb_build_object(
    'records', coalesce((
      select jsonb_agg(
        case when shaped.address_record is null then shaped.customer_json
        else (
          shaped.customer_json
          || jsonb_build_object(
            'address_id', (shaped.address_record).id,
            'address_type', (shaped.address_record).address_type
          )
          || (
            app_private.tms_customer_address_to_secure_json(shaped.address_record, null)
            - 'id' - 'customer_id' - 'customer' - 'field_access' - 'is_record_owner'
          )
          || jsonb_build_object(
            'field_access', app_private.field_access_map(
              'tms.customer_address',
              (shaped.address_record).created_by_user_id
            ),
            'is_record_owner',
              (shaped.address_record).created_by_user_id = app_private.current_app_user_id()
          )
        ) end
      ) from shaped
    ), '[]'::jsonb),
    'total', (select count(*) from filtered)
  ) into v_result;

  return v_result;
end;
$function$;

--
-- Name: tms_list_customer_statement_allocatable_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.tms_list_customer_statement_allocatable_secure(p_customer_id uuid, p_keyword text DEFAULT NULL::text, p_from integer DEFAULT 0, p_to integer DEFAULT 9)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_limit integer := least(
    500,
    greatest(coalesce(p_to, 9) - greatest(coalesce(p_from, 0), 0) + 1, 1)
  );
begin
  if not (
    app_private.can_execute_business_action(
      'FinanceCashTransaction', 'FinanceCashTransaction:Add', null, false
    )
    or app_private.can_execute_business_action(
      'FinanceCashTransaction', 'FinanceCashTransaction:Allocate', null, false
    )
    or app_private.can_execute_business_action(
      'FinanceCashTransaction', 'FinanceCashTransaction:Import', null, false
    )
  ) then
    raise exception 'Missing customer receipt allocation permission' using errcode = '42501';
  end if;

  return (
    with filtered as materialized (
      select allocatable_row
      from public.tms_customer_statement_allocatable allocatable_row
      join public.tms_customer_statement statement_row
        on statement_row.id = allocatable_row.id
       
      where (p_customer_id is null or allocatable_row.customer_id = p_customer_id)
        and app_private.resolve_field_access(
          'tms.customer_statement', 'statementAmounts', statement_row.created_by_user_id
        ) in ('read', 'edit')
        and app_private.resolve_field_access(
          'tms.customer_statement', 'settlementAmounts', statement_row.created_by_user_id
        ) in ('read', 'edit')
        and (
          nullif(btrim(p_keyword), '') is null
          or allocatable_row.statement_no ilike '%' || btrim(p_keyword) || '%'
          or allocatable_row.customer_name ilike '%' || btrim(p_keyword) || '%'
        )
    ), paged as (
      select filtered.allocatable_row
      from filtered
      order by (filtered.allocatable_row).period_end,
               (filtered.allocatable_row).create_time,
               (filtered.allocatable_row).id
      offset greatest(coalesce(p_from, 0), 0)
      limit v_limit
    )
    select jsonb_build_object(
      'records', coalesce((
        select jsonb_agg(
          to_jsonb(paged.allocatable_row)
          order by (paged.allocatable_row).period_end,
                   (paged.allocatable_row).create_time,
                   (paged.allocatable_row).id
        ) from paged
      ), '[]'::jsonb),
      'total', (select count(*) from filtered)
    )
  );
end;
$function$;

--
-- Name: tms_list_customer_statements_receivables_ai_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.tms_list_customer_statements_receivables_ai_secure(p_limit integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_limit integer := least(500, greatest(coalesce(p_limit, 300), 1));
begin
  if not app_private.can_execute_business_action('FinanceWorkbench', null, null, false) then
    raise exception 'Missing finance workbench permission' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'records', coalesce((
      select jsonb_agg(
        (to_jsonb(permitted.statement_record))
        || jsonb_build_object(
          'invoiced_amount', permitted.invoiced_amount,
          'uninvoiced_amount', permitted.uninvoiced_amount
        )
        order by (permitted.statement_record).period_end,
                 (permitted.statement_record).id
      )
      from (
        select
          summary_row as statement_record,
          coalesce(invoiceable_row.invoiced_amount, 0::numeric) as invoiced_amount,
          coalesce(invoiceable_row.uninvoiced_amount, 0::numeric) as uninvoiced_amount
        from public.tms_customer_statement_summary summary_row
        join public.tms_customer_statement statement_row
          on statement_row.id = summary_row.id
         
        left join public.tms_invoiceable_statement invoiceable_row
          on invoiceable_row.direction = 'output'
         and invoiceable_row.statement_id = summary_row.id
         
        where summary_row.status not in ('settled', 'voided')
          and app_private.resolve_field_access(
            'tms.customer_statement', 'statementAmounts', statement_row.created_by_user_id
          ) in ('read', 'edit')
          and app_private.resolve_field_access(
            'tms.customer_statement', 'settlementAmounts', statement_row.created_by_user_id
          ) in ('read', 'edit')
        order by summary_row.period_end, summary_row.id
        limit v_limit
      ) permitted
    ), '[]'::jsonb)
  );
end;
$function$;

--
-- Name: tms_save_geofence_config; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.tms_save_geofence_config(p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare
  normalized jsonb;
  param_record public.sys_param%rowtype;
begin
  if not (
    app_private.is_platform_super()
    or app_private.has_permission('System:GeofenceConfig:Edit')
  ) then
    raise exception '无权修改电子围栏配置' using errcode = '42501';
  end if;

  normalized := jsonb_build_object(
    'enabled', coalesce((p_config ->> 'enabled')::boolean, true),
    'loadingRadiusM', coalesce((p_config ->> 'loadingRadiusM')::integer, 1000),
    'unloadingRadiusM', coalesce((p_config ->> 'unloadingRadiusM')::integer, 1000),
    'loadingAllowOutsideCheckIn', coalesce((p_config ->> 'loadingAllowOutsideCheckIn')::boolean, false),
    'unloadingAllowOutsideCheckIn', coalesce((p_config ->> 'unloadingAllowOutsideCheckIn')::boolean, false),
    'autoConfirmLoading', coalesce((p_config ->> 'autoConfirmLoading')::boolean, false),
    'autoConfirmUnloading', coalesce((p_config ->> 'autoConfirmUnloading')::boolean, false)
  );

  if (normalized ->> 'loadingRadiusM')::integer not between 50 and 50000
    or (normalized ->> 'unloadingRadiusM')::integer not between 50 and 50000 then
    raise exception '围栏半径应在 50 至 50000 米之间' using errcode = '23514';
  end if;

  update public.sys_param
  set param_value = normalized::text
  where param_key = 'tms.geofence.config'
  returning * into param_record;

  if param_record.id is null then
    raise exception '电子围栏系统参数不存在' using errcode = 'P0002';
  end if;

  return jsonb_build_object(
    'id', param_record.id,
    'enabled', (normalized ->> 'enabled')::boolean,
    'loadingRadiusM', (normalized ->> 'loadingRadiusM')::integer,
    'unloadingRadiusM', (normalized ->> 'unloadingRadiusM')::integer,
    'loadingAllowOutsideCheckIn', (normalized ->> 'loadingAllowOutsideCheckIn')::boolean,
    'unloadingAllowOutsideCheckIn', (normalized ->> 'unloadingAllowOutsideCheckIn')::boolean,
    'autoConfirmLoading', (normalized ->> 'autoConfirmLoading')::boolean,
    'autoConfirmUnloading', (normalized ->> 'autoConfirmUnloading')::boolean,
    'updateBy', param_record.update_by,
    'updateTime', param_record.update_time
  );
end;
$function$;

--
-- Name: transfer_workflow_task; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.transfer_workflow_task(p_task_id uuid, p_assignee_user_id uuid, p_reason text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  select app_private.transfer_workflow_task(
    p_task_id, p_assignee_user_id, p_reason, p_idempotency_key
  )
$function$;

--
-- Name: trg_guard_sys_user_authorization_fields; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.trg_guard_sys_user_authorization_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_is_service_role boolean := current_user in ('postgres', 'service_role')
    or coalesce(auth.jwt() ->> 'role', '') = 'service_role';
  v_is_self boolean := old.auth_user_id = auth.uid();
  v_roles_changed boolean := new.user_roles is distinct from old.user_roles;
  v_authorization_changed boolean :=
    new.organization_id is distinct from old.organization_id
    or new.user_type is distinct from old.user_type
    or new.status is distinct from old.status
    or new.auth_user_id is distinct from old.auth_user_id;
  v_profile_changed boolean :=
    new.user_name is distinct from old.user_name
    or new.nick_name is distinct from old.nick_name
    or new.user_gender is distinct from old.user_gender
    or new.user_phone is distinct from old.user_phone
    or new.user_email is distinct from old.user_email
    or new.extra is distinct from old.extra
    or new.remark is distinct from old.remark
    or new.avatar is distinct from old.avatar;
begin
  if v_is_service_role then
    return new;
  end if;

  if new.id is distinct from old.id
    or new.create_by is distinct from old.create_by
    or new.create_time is distinct from old.create_time
  then
    raise exception '用户主键和创建信息不可修改';
  end if;

  if v_roles_changed then
    if v_is_self then
      raise exception '不能为当前账号分配角色';
    end if;
    if not app_private.has_permission('System:User:AssignRole') then
      raise exception '缺少用户角色分配权限';
    end if;
  end if;

  if v_authorization_changed
    and not app_private.has_permission('System:User:Edit')
  then
    raise exception '缺少用户管理权限，不能修改组织、类型或账号状态';
  end if;

  if v_profile_changed
    and not v_is_self
    and not app_private.has_permission('System:User:Edit')
  then
    raise exception '缺少用户编辑权限';
  end if;

  return new;
end;
$function$;

--
-- Name: trg_guard_system_organization; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.trg_guard_system_organization()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
begin


  if tg_op = 'UPDATE' and old.is_system and (
    new.parent_id is distinct from old.parent_id
    or new.organization_code is distinct from old.organization_code
    or new.organization_type is distinct from old.organization_type
    or new.status is distinct from old.status
    or not new.is_system
  ) then
    raise exception '正式组织根节点的编码、类型、层级和状态受系统保护';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$;

--
-- Name: trg_set_create_time_and_by; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.trg_set_create_time_and_by()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  -- set create_time if column exists and is null
  IF TG_ARGV[0] = 'true' THEN
    BEGIN
      IF NEW.create_time IS NULL THEN
        NEW.create_time := now();
      END IF;
    EXCEPTION WHEN undefined_column THEN
      NULL;
    END;
  END IF;

  -- set create_by if column exists and is null
  -- Use auth.jwt() ->> 'email' as the source of truth
  IF TG_ARGV[1] = 'true' THEN
    BEGIN
      IF NEW.create_by IS NULL OR NEW.create_by = '' THEN
        -- prefer JWT email; fallback to 'unknown' if not present
        NEW.create_by := COALESCE((auth.jwt() ->> 'email'), 'unknown');
      END IF;
    EXCEPTION WHEN undefined_column THEN
      NULL;
    END;
  END IF;

  RETURN NEW;
END;
$function$;

--
-- Name: trg_set_update_time_and_by; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.trg_set_update_time_and_by()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  begin
    new.update_time := now();
  exception when undefined_column then
    null;
  end;

  begin
    new.update_by := coalesce(
      nullif(public.get_app_user_display_name(), ''),
      nullif(auth.jwt() ->> 'email', ''),
      nullif(old.update_by, ''),
      'unknown'
    );
  exception when undefined_column then
    null;
  end;

  return new;
end
$function$;

--
-- Name: trg_validate_sys_organization; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.trg_validate_sys_organization()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.parent_id = new.id then
    raise exception '组织不能将自身设置为上级组织';
  end if;

  if new.leader_user_id is not null and not exists (
    select 1
    from public.sys_user u
    where u.id = new.leader_user_id
      
  ) then
    raise exception '组织负责人必须属于同一组织';
  end if;

  if new.parent_id is not null and exists (
    with recursive ancestors as (
      select o.id, o.parent_id
      from public.mdm_organization o
      where o.id = new.parent_id

      union all

      select parent.id, parent.parent_id
      from public.mdm_organization parent
      join ancestors child on child.parent_id = parent.id
    )
    select 1 from ancestors where id = new.id
  ) then
    raise exception '组织层级不能形成循环';
  end if;

  return new;
end;
$function$;

--
-- Name: validate_tms_carrier_payment_application_submission; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.validate_tms_carrier_payment_application_submission(p_application_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_app record;
  v_item record;
  v_item_count integer;
  v_total numeric(14,2);
  v_outstanding numeric(14,2);
  v_reserved numeric(14,2);
begin
  select * into v_app from public.tms_carrier_payment_application
  where id=p_application_id for update;
  if not found then raise exception '付款申请不存在'; end if;
  if v_app.status not in ('draft','rejected') then raise exception '只有草稿或已驳回申请可以提交审批'; end if;
  select count(*)::integer, coalesce(sum(applied_amount),0)::numeric(14,2)
  into v_item_count, v_total
  from public.tms_carrier_payment_application_item where application_id=p_application_id;
  if v_item_count < 1 then raise exception '请至少选择一份待付款对账单'; end if;
  if v_total is distinct from v_app.amount then raise exception '付款分配合计必须等于申请金额'; end if;

  for v_item in
    select i.*, s.status statement_status, s.settled_amount,
      coalesce((select sum(si.line_amount) from public.tms_carrier_statement_item si
                where si.statement_id=s.id and si.is_active),0)::numeric(14,2) statement_amount
    from public.tms_carrier_payment_application_item i
    join public.tms_carrier_statement s on s.id=i.statement_id
    where i.application_id=p_application_id order by i.statement_id
  loop
    perform pg_advisory_xact_lock(hashtextextended(v_item.statement_id::text, 841329));
    if v_item.statement_status not in ('confirmed','partially_settled') then
      raise exception '对账单 % 当前状态不允许付款', v_item.statement_no_snapshot;
    end if;
    v_outstanding := greatest(v_item.statement_amount-v_item.settled_amount,0)::numeric(14,2);
    select coalesce(sum(i.applied_amount),0)::numeric(14,2) into v_reserved
    from public.tms_carrier_payment_application_item i
    join public.tms_carrier_payment_application a on a.id=i.application_id
    where i.statement_id=v_item.statement_id
      and a.status in ('pending_review','approved')
      and a.id<>p_application_id;
    if v_item.applied_amount > v_outstanding-v_reserved then
      raise exception '对账单 % 可申请余额不足，当前可申请 %',
        v_item.statement_no_snapshot, greatest(v_outstanding-v_reserved,0);
    end if;
  end loop;
  return true;
end;
$function$;

--
-- Name: validate_tms_expense_reimbursement_submission_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.validate_tms_expense_reimbursement_submission_secure(p_reimbursement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_reimbursement public.tms_expense_reimbursement%rowtype;
  v_access jsonb;
begin
  select reimbursement_row.*
  into v_reimbursement
  from public.tms_expense_reimbursement reimbursement_row
  where reimbursement_row.id = p_reimbursement_id
    ;
  if not found then raise exception '费用报销单不存在或无权访问'; end if;
  if v_reimbursement.status not in ('draft', 'rejected') then
    raise exception '当前费用报销单状态不允许提交审批';
  end if;
  v_access := app_private.field_access_map(
    'tms.expense_reimbursement', v_reimbursement.created_by_user_id
  );
  if coalesce(v_access->>'reimbursementAmounts', 'hidden') not in ('read', 'edit') then
    raise exception '当前字段权限不足，无法读取报销金额并提交审批'
      using errcode = '42501';
  end if;
  if coalesce(v_access->>'payeeDetails', 'hidden') not in ('read', 'edit') then
    raise exception '当前字段权限不足，无法读取收款信息并提交审批'
      using errcode = '42501';
  end if;
  return jsonb_build_object(
    'amount', v_reimbursement.total_amount,
    'reimbursementNo', v_reimbursement.reimbursement_no,
    'paymentMethod', v_reimbursement.payment_method,
    'plannedPaymentDate', v_reimbursement.planned_payment_date,
    'itemCount', (
      select count(*)::integer
      from public.tms_expense_reimbursement_item item_row
      where item_row.reimbursement_id = v_reimbursement.id
        
    ),
    'waybillCount', (
      select count(distinct item_row.waybill_id)::integer
      from public.tms_expense_reimbursement_item item_row
      where item_row.reimbursement_id = v_reimbursement.id
        
    )
  );
end;
$function$;

--
-- Name: validate_tms_waybill_cost_submission_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.validate_tms_waybill_cost_submission_secure(p_cost_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cost public.tms_waybill_cost%rowtype;
begin
  if not app_private.can_execute_business_action(
    'FinanceWaybillCost', 'FinanceWaybillCost:Submit', null, false
  ) then
    raise exception 'Missing waybill cost submit permission' using errcode = '42501';
  end if;
  select cost_row.* into v_cost
  from public.tms_waybill_cost cost_row
  where cost_row.id = p_cost_id ;
  if not found then raise exception '运单费用不存在或无权访问'; end if;
  if v_cost.audit_status not in ('draft', 'rejected') then
    raise exception '当前运单费用状态不允许提交审批';
  end if;
  if app_private.resolve_field_access(
    'tms.waybill_cost', 'costAmounts', v_cost.created_by_user_id
  ) not in ('read', 'edit') then
    raise exception '当前字段权限不足，无法读取费用金额并提交审批'
      using errcode = '42501';
  end if;
  return true;
end;
$function$;

--
-- Name: verify_notification_dispatch_token; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.verify_notification_dispatch_token(p_token text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce((select auth.jwt() ->> 'role'), '') = 'service_role'
    and exists (
      select 1 from vault.decrypted_secrets
      where name = 'notification_dispatch_cron_token'
        and decrypted_secret = p_token
    );
$function$;

--
-- Name: withdraw_workflow; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.withdraw_workflow(p_instance_id uuid, p_comment text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE sql
 SET search_path TO ''
AS $function$ select app_private.withdraw_workflow(p_instance_id,p_comment) $function$;

--
-- Name: wms_recommend_bin_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.wms_recommend_bin_secure(p_warehouse_id uuid, p_material_id uuid, p_quantity numeric, p_area_sqm numeric DEFAULT NULL::numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_locations boolean;
  v_status text;
  v_serial boolean;
  v_category_id uuid;
  v_bin record;
begin
  if (select auth.uid()) is null then
    raise exception '请先登录后再推荐库位' using errcode='42501';
  end if;
  if p_quantity is null or p_quantity <= 0 or (p_area_sqm is not null and p_area_sqm < 0) then
    raise exception '推荐库位需要有效的入库数量和面积' using errcode='22023';
  end if;
  select enable_locations,status into v_locations,v_status
  from public.mdm_warehouse where id=p_warehouse_id;
  if not found or v_status<>'enabled' then
    raise exception '当前账号不可读取该仓库' using errcode='42501';
  end if;
  select serial_management_enabled,category_id into v_serial,v_category_id
  from public.mdm_material
  where id=p_material_id  and status='enabled';
  if not found then
    raise exception '该仓库下无有效物料' using errcode='23514';
  end if;
  if not v_locations then return null; end if;
  for v_bin in
    select b.id
    from public.mdm_warehouse_bin b
    left join public.mdm_warehouse_zone z
      on z.id=b.zone_id 
    where true
      and b.warehouse_id=p_warehouse_id
      and b.status='available'
      and (b.zone_id is null or
        (z.id is not null and z.status='enabled' and not coalesce(z.abnormal,false)
         and (z.category_id is null or z.category_id=v_category_id)))
      and (b.fixed_material_id is null or b.fixed_material_id=p_material_id)
      and (not coalesce(v_serial,false) or coalesce(b.supports_serial,false))
    order by
      case when b.fixed_material_id=p_material_id then 0 else 1 end,
      case when not coalesce(v_serial,false) and b.supports_serial then 1 else 0 end,
      case
        when b.fixed_material_id=p_material_id then 0
        when exists(
          select 1 from public.wms_inventory_batch stock
          where stock.bin_id=b.id
            and stock.material_id=p_material_id and stock.quantity>0
        ) then 1
        when not exists(
          select 1 from public.wms_inventory_batch stock
          where stock.bin_id=b.id and stock.quantity>0
        ) then 2
        else 3
      end,
      b.sort nulls last,b.bin_code,b.id
  loop
    begin
      perform app_private.assert_wms_destination(p_warehouse_id,v_bin.id,p_material_id,p_quantity,p_area_sqm);
      return v_bin.id;
    exception when check_violation then
      continue;
    end;
  end loop;
  return null;
end
$function$;

--
-- Name: wms_set_receipt_line_bin_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.wms_set_receipt_line_bin_secure(p_line_id uuid, p_bin_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_doc public.scm_receipt_target_document%rowtype;
  v_line public.scm_receipt_target_line%rowtype;
  v_warehouse_id uuid;
  v_material_id uuid;
  v_quantity numeric;
  v_bin_name text;
begin
  if auth.uid() is null then
    raise exception '请先登录' using errcode='42501';
  end if;
  if not (app_private.is_platform_super() or app_private.has_permission('WmsReceiptInbound:AssignBin')) then
    raise exception '无指定入库库位权限' using errcode='42501';
  end if;
  select d.* into v_doc
  from public.scm_receipt_target_document d
  join public.scm_receipt_target_line l on l.target_document_id=d.id
  where l.id=p_line_id
  for update of d;
  if not found then
    raise exception '入库明细不存在' using errcode='22023';
  end if;  if v_doc.target_kind<>'inbound' or v_doc.status<>'draft' then
    raise exception '只能修改草稿收料入库的库位' using errcode='23514';
  end if;
  select * into v_line from public.scm_receipt_target_line
  where id=p_line_id and target_document_id=v_doc.id for update;
  v_warehouse_id:=nullif(v_line.line_snapshot->>'warehouse_id','')::uuid;
  v_material_id:=nullif(v_line.line_snapshot->>'material_id','')::uuid;
  if v_warehouse_id is null or v_material_id is null then
    raise exception '收料明细缺少仓库或物料' using errcode='23514';
  end if;
  v_quantity:=app_private.scm_receipt_stock_quantity(v_material_id,coalesce((v_line.line_snapshot->>'quantity')::numeric,0)
  );
  perform app_private.assert_wms_destination(v_warehouse_id,p_bin_id,v_material_id,v_quantity,null
  );
  if p_bin_id is not null then
    select bin_name into v_bin_name from public.mdm_warehouse_bin
    where id=p_bin_id  and warehouse_id=v_warehouse_id;
  end if;
  update public.scm_receipt_target_line
  set line_snapshot=jsonb_set(
    jsonb_set(v_line.line_snapshot,'{bin_id}',coalesce(to_jsonb(p_bin_id),'null'::jsonb),true),
    '{location}',to_jsonb(coalesce(v_bin_name,'')),true
  )
  where id=v_line.id;
  update public.scm_receipt_target_document set updated_at=now() where id=v_doc.id;
end
$function$;

--
-- Name: wms_set_receipt_line_serials_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.wms_set_receipt_line_serials_secure(p_line_id uuid, p_serial_nos text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_doc public.scm_receipt_target_document%rowtype;v_line public.scm_receipt_target_line%rowtype;
 v_material_id uuid;v_qty numeric;v_enabled boolean;
begin
 if auth.uid() is null then raise exception '请先登录' using errcode='42501'; end if;
 if not (app_private.is_platform_super() or app_private.has_permission('WmsReceiptInbound:CaptureSN')) then
  raise exception '无权录入收料 SN' using errcode='42501'; end if;
 if p_line_id is null or p_serial_nos is null or cardinality(p_serial_nos)>5000 then
  raise exception '序列号清单格式无效' using errcode='22023'; end if;
 select d.* into v_doc from public.scm_receipt_target_document d
 join public.scm_receipt_target_line l on l.target_document_id=d.id where l.id=p_line_id for update of d;
 if not found then raise exception '收料入库单不存在' using errcode='P0002'; end if; if v_doc.target_kind<>'inbound' or v_doc.status<>'draft' then
  raise exception '仅收料入库草稿可录入 SN' using errcode='23514'; end if;
 select * into v_line from public.scm_receipt_target_line
 where id=p_line_id and target_document_id=v_doc.id for update;
 v_material_id:=nullif(v_line.line_snapshot->>'material_id','')::uuid;
 if v_material_id is null then raise exception '收料明细未关联物料' using errcode='23514'; end if;
 select serial_management_enabled into v_enabled from public.mdm_material
 where id=v_material_id ;
 if not coalesce(v_enabled,false) then raise exception '该物料未启用序列号管理' using errcode='23514'; end if;
 v_qty:=app_private.scm_receipt_stock_quantity(v_material_id,
   coalesce((v_line.line_snapshot->>'quantity')::numeric,0));
 if v_qty<>trunc(v_qty) or
   (cardinality(p_serial_nos)>0 and cardinality(p_serial_nos)<>v_qty) or
   exists(select 1 from unnest(p_serial_nos) sn where btrim(sn)='' or length(sn)>100) or
   (select count(distinct sn) from unnest(p_serial_nos) sn)<>cardinality(p_serial_nos) then
  raise exception 'SN 编码须逐件唯一录入，件数应等于库存数量' using errcode='23514'; end if;
 update public.scm_receipt_target_line set serial_nos=p_serial_nos where id=p_line_id;
end $function$;

--
-- Name: wms_set_receipt_scope_secure; Type: FUNCTION; Schema: public
--

CREATE OR REPLACE FUNCTION public.wms_set_receipt_scope_secure(p_target_id uuid, p_construction_no text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_doc public.scm_receipt_target_document%rowtype;v_no text:=nullif(btrim(coalesce(p_construction_no,'')),'');
begin
 if auth.uid() is null then raise exception '请先登录' using errcode='42501'; end if;
 if not (app_private.is_platform_super() or app_private.has_permission('WmsReceiptInbound:AssignScope')) then
   raise exception '没有设置入库施工号权限' using errcode='42501'; end if;
 select * into v_doc from public.scm_receipt_target_document where id=p_target_id for update;
 if not found or v_doc.target_kind<>'inbound' or v_doc.status<>'draft' then
   raise exception '仅收料入库草稿可设置施工号' using errcode='23514'; end if; perform app_private.wms_assert_project_section(v_doc.project_id,v_no,false);
 update public.scm_receipt_target_document set construction_no=v_no,updated_at=now() where id=v_doc.id;
end $function$;

--
-- Name: ai_artifact_review; Type: TABLE; Schema: public
--

CREATE TABLE public.ai_artifact_review (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ai_run_id uuid NOT NULL,
    auth_user_id uuid NOT NULL,
    feature text NOT NULL,
    artifact_type text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    proposed_payload jsonb NOT NULL,
    final_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    confidence numeric(5,4),
    field_confidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    warnings text[] DEFAULT '{}'::text[] NOT NULL,
    accepted_fields text[] DEFAULT '{}'::text[] NOT NULL,
    corrected_fields text[] DEFAULT '{}'::text[] NOT NULL,
    entity_type text,
    entity_id uuid,
    review_note text,
    reviewed_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    create_by text,
    create_time timestamp with time zone DEFAULT now() NOT NULL,
    update_by text,
    update_time timestamp with time zone DEFAULT now() NOT NULL,
    raw_ocr_text text DEFAULT ''::text NOT NULL
);

--
-- Name: ai_conversation; Type: TABLE; Schema: public
--

CREATE TABLE public.ai_conversation (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
