CREATE VIEW public.sys_organization (id, parent_id, organization_code, organization_name, organization_type, leader_user_id, status, sort, phone, email, address, description, is_system, create_by, create_time, update_by, update_time) AS
 SELECT id,
    parent_id,
    organization_code,
    organization_name,
    organization_type,
    leader_user_id,
    status,
    sort,
    phone,
    email,
    address,
    description,
    is_system,
    create_by,
    create_time,
    update_by,
    update_time
   FROM mdm_organization;;

