--
-- Name: ai_artifact_review ai_artifact_review_applied_entity_check; Type: CONSTRAINT; Schema: public
--

DO $already_exists$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint c
     WHERE c.conname = 'ai_artifact_review_applied_entity_check'
       AND c.conrelid = 'public.ai_artifact_review'::regclass
  ) THEN
ALTER TABLE ONLY public.ai_artifact_review
    ADD CONSTRAINT ai_artifact_review_applied_entity_check CHECK (((status <> 'applied'::text) OR ((entity_type IS NOT NULL) AND (entity_id IS NOT NULL) AND (final_payload <> '{}'::jsonb))));
  END IF;
END
$already_exists$;

--
-- Name: ai_artifact_review ai_artifact_review_confidence_check; Type: CONSTRAINT; Schema: public
--

DO $already_exists$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint c
     WHERE c.conname = 'ai_artifact_review_confidence_check'
       AND c.conrelid = 'public.ai_artifact_review'::regclass
  ) THEN
ALTER TABLE ONLY public.ai_artifact_review
    ADD CONSTRAINT ai_artifact_review_confidence_check CHECK (((confidence IS NULL) OR ((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))));
  END IF;
END
$already_exists$;

